/* =========================================================================
   DATA — People of the Old Testament  (data-ot.js)
   Mapped from the NIV text on bible.com, Genesis to Malachi in the Christian
   order. Uses lk(), LG and UNSURE_RE from data-nt.js, which loads first.
   ========================================================================= */
const OT_CAT = {
  prim:  {label:"Creation & Flood",      color:"var(--prim)"},
  line:  {label:"Genealogies",           color:"var(--line)"},
  patri: {label:"Patriarchs & Matriarchs", color:"var(--patri)"},
  tribe: {label:"House of Jacob",        color:"var(--tribe)"},
  kin:   {label:"Wider Family & Kin",    color:"var(--kin)"},
  exod:  {label:"Exodus & Wilderness",   color:"var(--exod)"},
  priest:{label:"Priests & Levites",     color:"var(--priest)"},
  lead:  {label:"Tribal Leaders",        color:"var(--lead)"},
  judg:  {label:"Conquest & Judges",     color:"var(--judg)"},
  king:  {label:"Kings of Israel & Judah",color:"var(--king)"},
  proph: {label:"The Prophets",          color:"var(--proph)"},
  exile: {label:"Exile & Return",        color:"var(--exile)"},
  wis:   {label:"Wisdom & Poetry",       color:"var(--wis)"},
  natn:  {label:"Foreign Nations",       color:"var(--natn)"},
  angels:{label:"Angels",                color:"var(--angel)", ring:"angel"},
  devil: {label:"The devil",             color:"var(--devil)", ring:"devil"},
};

const OT_PEOPLE = [
 // ================= GENESIS =================
 // Sourced chapter-by-chapter from the NIV on bible.com (Genesis 1–50).
 // Lifespans in `dates` are the figures Genesis itself gives; absolute BC dates
 // for the patriarchs are traditional estimates only.

 // ---------------- CREATION & FLOOD (Genesis 1–11) ----------------
 {id:"adam", name:"Adam", short:"Adam", cat:"prim", w:13,
  aliases:"the man formed from the dust",
  dates:"primeval · lived 930 years (Genesis 5:5) · c. 4174 – 3244 BC* by a straight count of Genesis 5 & 11 (estimate)",
  desc:`The first man, formed by the LORD God "from the dust of the ground" and put in the Garden of Eden "to work it and take care of it." He names the animals, and God makes the woman from his rib. When he eats from the tree of the knowledge of good and evil, the ground is cursed because of him and he is banished from Eden. Father of Cain, Abel and Seth, and of "other sons and daughters."`,
  refs:["Genesis 1:26–31","Genesis 2","Genesis 3","Genesis 4:1–2","Genesis 4:25","Genesis 5:1–5"]},

 {id:"eve", name:"Eve", short:"Eve", cat:"prim", w:11,
  aliases:"the woman · mother of all the living",
  dates:"primeval",
  desc:`The first woman, made by the LORD God from the man's rib as "a helper suitable for him." Deceived by the serpent, she eats from the forbidden tree and gives some to her husband. Adam names her Eve "because she would become the mother of all the living." She bears Cain, then Abel, and later Seth: "God has granted me another child in place of Abel."`,
  refs:["Genesis 2:18–25","Genesis 3","Genesis 4:1–2","Genesis 4:25"]},

 {id:"cain", name:"Cain", short:"Cain", cat:"prim", w:9,
  dates:"primeval",
  desc:`The firstborn of Adam and Eve, who worked the soil. When the LORD looked with favor on Abel's offering but not on his, Cain was very angry; he attacked his brother in the field and killed him — "Am I my brother's keeper?" Driven out as "a restless wanderer," he is given a mark so that no one will kill him, settles in the land of Nod, east of Eden, and builds a city named after his son Enoch.`,
  refs:["Genesis 4:1–17"]},

 {id:"abel", name:"Abel", short:"Abel", cat:"prim", w:8,
  dates:"primeval",
  desc:`The second son of Adam and Eve, who kept flocks. The LORD looked with favor on his offering of "fat portions from some of the firstborn of his flock." His brother Cain killed him in the field, and the LORD says, "Your brother's blood cries out to me from the ground."`,
  refs:["Genesis 4:2–11","Genesis 4:25"]},

 {id:"seth", name:"Seth", short:"Seth", cat:"prim", w:8,
  dates:"primeval · lived 912 years (Genesis 5:8) · c. 4044 – 3132 BC* by a straight count of Genesis 5 & 11 (estimate)",
  desc:`Born to Adam and Eve after Abel's death, when Adam was 130 — "in his own likeness, in his own image." Father of Enosh; "at that time people began to call on the name of the LORD." The family line from Adam to Noah in Genesis 5 runs through him.`,
  refs:["Genesis 4:25–26","Genesis 5:3–8"]},

 {id:"enoch", name:"Enoch son of Jared", short:"Enoch", cat:"prim", w:7,
  clash:"Enoch", clashtag:"Son of Jared in Seth's line, who 'walked faithfully with God' and was taken away by God at 365.",
  dates:"primeval · 365 years (Genesis 5:23) · c. 3552 – 3187 BC* by a straight count of Genesis 5 & 11 (estimate)",
  desc:`A descendant of Seth and father of Methuselah. Genesis twice says he "walked faithfully with God," and instead of the usual "and then he died" records: "then he was no more, because God took him away."`,
  notconfused:`Enoch son of Cain, after whom Cain named the city he was building (Genesis 4:17).`,
  refs:["Genesis 5:18–24"]},

 {id:"noah", name:"Noah", short:"Noah", cat:"prim", w:14, halo:1,
  clash:"Noah", clashtag:"The righteous man who built the ark and survived the flood with his family.",
  notconfused:`Noah daughter of Zelophehad, of the tribe of Manasseh (Numbers 27:1).`,
  dates:"primeval · lived 950 years (Genesis 9:29) · c. 3118 – 2168 BC* by a straight count of Genesis 5 & 11 (estimate)",
  desc:`"A righteous man, blameless among the people of his time," who "walked faithfully with God" when the earth was "full of violence." Warned of the flood, he builds the ark and enters it with his wife, his sons Shem, Ham and Japheth and their wives, and the animals. Afterward he builds an altar, and God establishes his covenant with him and every living creature, setting the rainbow as its sign. Later he plants a vineyard, becomes drunk, and curses Canaan. Ezekiel names him with Daniel and Job as men whose righteousness "could save only themselves."`,
  refs:["Genesis 5:28–32","Genesis 6–9","Isaiah 54:9","Ezekiel 14:14","Ezekiel 14:20"]},

 {id:"shem", name:"Shem", short:"Shem", cat:"prim", w:9,
  dates:"primeval · lived 600 years (100 + 500, Genesis 11:10–11) · c. 2616 – 2016 BC* by a straight count of Genesis 5 & 11 (estimate)",
  desc:`A son of Noah, who with Japheth walks in backward to cover their father's nakedness and receives Noah's blessing: "Praise be to the LORD, the God of Shem!" Genesis calls him "the ancestor of all the sons of Eber," and his family line in Genesis 11 runs to Terah and Abram.`,
  refs:["Genesis 9:18–27","Genesis 10:21–31","Genesis 11:10–26"]},

 {id:"ham", name:"Ham", short:"Ham", cat:"prim", w:8,
  dates:"primeval",
  desc:`A son of Noah and "the father of Canaan." He sees his father lying drunk and uncovered and tells his two brothers; when Noah learns "what his youngest son had done to him," he curses Canaan. In the Table of Nations his sons are Cush, Egypt, Put and Canaan — the line that includes Nimrod and the Canaanite clans.`,
  refs:["Genesis 9:18–27","Genesis 10:6–20"]},

 {id:"japheth", name:"Japheth", short:"Japheth", cat:"prim", w:7,
  dates:"primeval",
  desc:`A son of Noah and, per Genesis 10:21, Shem's older brother. With Shem he covers their father, and Noah blesses him: "May God extend Japheth's territory." His sons were Gomer, Magog, Madai, Javan, Tubal, Meshek and Tiras; from them "the maritime peoples spread out into their territories."`,
  refs:["Genesis 9:18–27","Genesis 10:2–5","Genesis 10:21"]},

 {id:"canaan_p", name:"Canaan son of Ham", short:"Canaan", cat:"prim", w:6,
  dates:"primeval",
  desc:`A son of Ham, on whom Noah's curse falls: "Cursed be Canaan! The lowest of slaves will he be to his brothers." He is the father of Sidon his firstborn and of the Hittites, Jebusites, Amorites, Girgashites, Hivites and other clans whose borders reached from Sidon toward Gaza and Sodom.`,
  notconfused:`The land of Canaan, named for the clans descended from him and later promised to Abram's offspring (Genesis 12:7).`,
  refs:["Genesis 9:18–27","Genesis 10:15–19"]},

 {id:"nimrod", name:"Nimrod", short:"Nimrod", cat:"prim", w:7,
  dates:"primeval",
  desc:`A son of Cush, son of Ham, "who became a mighty warrior on the earth" — "a mighty hunter before the LORD." The first centers of his kingdom were Babylon, Uruk, Akkad and Kalneh in Shinar; from there he went to Assyria and built Nineveh, Rehoboth Ir, Calah and Resen. Micah 5:6 calls Assyria "the land of Nimrod."`,
  refs:["Genesis 10:8–12","Micah 5:6"]},

 // ---------------- GENEALOGIES (names known only from the family lists) ----------------
 // Cain's line (Genesis 4)
 {id:"enoch_cain", name:"Enoch son of Cain", short:"Enoch (Cain's son)", cat:"line", w:5,
  clash:"Enoch", clashtag:"Cain's son, after whom Cain named the city he was building.",
  dates:"primeval",
  desc:`Cain's son, after whom Cain named the city he was building. Through Irad, Mehujael and Methushael his line leads to Lamech.`,
  notconfused:`Enoch son of Jared, in Seth's line, who "walked faithfully with God" and was taken away by God (Genesis 5:24).`,
  refs:["Genesis 4:17–18"]},

 {id:"lamech_cain", name:"Lamech son of Methushael", short:"Lamech (Cain's line)", cat:"line", w:6,
  clash:"Lamech", clashtag:"A descendant of Cain who married Adah and Zillah and boasted to them of killing a man.",
  dates:"primeval",
  desc:`A descendant of Cain who married two women, Adah and Zillah. He boasts to them: "I have killed a man for wounding me, a young man for injuring me. If Cain is avenged seven times, then Lamech seventy-seven times."`,
  notconfused:`Lamech son of Methuselah, in Seth's line, the father of Noah (Genesis 5:25–31).`,
  refs:["Genesis 4:18–24"]},

 {id:"adah", name:"Adah wife of Lamech", short:"Adah", cat:"line", w:4,
  dates:"primeval",
  desc:`One of Lamech's two wives; mother of Jabal and Jubal.`,
  notconfused:`Adah daughter of Elon the Hittite, named as a wife of Esau in Genesis 36:2.`,
  refs:["Genesis 4:19–23"]},

 {id:"zillah", name:"Zillah", short:"Zillah", cat:"line", w:4,
  dates:"primeval",
  desc:`Lamech's other wife; mother of Tubal-Cain.`,
  refs:["Genesis 4:19–23"]},

 {id:"jabal", name:"Jabal", short:"Jabal", cat:"line", w:4,
  dates:"primeval",
  desc:`Son of Adah and Lamech: "the father of those who live in tents and raise livestock."`,
  refs:["Genesis 4:20"]},

 {id:"jubal", name:"Jubal", short:"Jubal", cat:"line", w:4,
  dates:"primeval",
  desc:`Jabal's brother: "the father of all who play stringed instruments and pipes."`,
  refs:["Genesis 4:21"]},

 {id:"tubalcain", name:"Tubal-Cain", short:"Tubal-Cain", cat:"line", w:4,
  dates:"primeval",
  desc:`Son of Zillah, "who forged all kinds of tools out of bronze and iron."`,
  refs:["Genesis 4:22"]},

 {id:"naamah", name:"Naamah", short:"Naamah", cat:"line", w:4,
  clash:"Naamah", clashtag:"Tubal-Cain's sister in Cain's line.",
  dates:"primeval",
  desc:`"Tubal-Cain's sister was Naamah" — the only detail Genesis gives.`,
  refs:["Genesis 4:22"]},

 // Seth's line to Noah (Genesis 5)
 {id:"enosh", name:"Enosh", short:"Enosh", cat:"line", w:5,
  dates:"primeval · lived 905 years (Genesis 5:11) · c. 3939 – 3034 BC* by a straight count of Genesis 5 & 11 (estimate)",
  desc:`Son of Seth and father of Kenan. At his birth Genesis notes, "At that time people began to call on the name of the LORD."`,
  refs:["Genesis 4:26","Genesis 5:6–11"]},

 {id:"kenan", name:"Kenan", short:"Kenan", cat:"line", w:4,
  dates:"primeval · lived 910 years (Genesis 5:14) · c. 3849 – 2939 BC* by a straight count of Genesis 5 & 11 (estimate)",
  desc:`Son of Enosh and father of Mahalalel, in the line from Adam to Noah.`,
  refs:["Genesis 5:9–14"]},

 {id:"mahalalel", name:"Mahalalel", short:"Mahalalel", cat:"line", w:4,
  dates:"primeval · lived 895 years (Genesis 5:17) · c. 3779 – 2884 BC* by a straight count of Genesis 5 & 11 (estimate)",
  desc:`Son of Kenan and father of Jared, in the line from Adam to Noah.`,
  refs:["Genesis 5:12–17"]},

 {id:"jared", name:"Jared", short:"Jared", cat:"line", w:4,
  dates:"primeval · lived 962 years (Genesis 5:20) · c. 3714 – 2752 BC* by a straight count of Genesis 5 & 11 (estimate)",
  desc:`Son of Mahalalel and father of Enoch, in the line from Adam to Noah.`,
  refs:["Genesis 5:15–20"]},

 {id:"methuselah", name:"Methuselah", short:"Methuselah", cat:"line", w:5,
  dates:"primeval · lived 969 years (Genesis 5:27) · c. 3487 – 2518 BC* by a straight count of Genesis 5 & 11 (estimate)",
  desc:`Son of Enoch and father of Lamech, in the line from Adam to Noah. His 969 years are the longest lifespan recorded in Scripture.`,
  refs:["Genesis 5:21–27"]},

 {id:"lamech_noah", name:"Lamech son of Methuselah", short:"Lamech", cat:"line", w:5,
  clash:"Lamech", clashtag:"Son of Methuselah and father of Noah, who hoped his son would 'comfort us' in their toil on the cursed ground.",
  dates:"primeval · lived 777 years (Genesis 5:31) · c. 3300 – 2523 BC* by a straight count of Genesis 5 & 11 (estimate)",
  desc:`Son of Methuselah. At 182 he has a son and names him Noah, saying, "He will comfort us in the labor and painful toil of our hands caused by the ground the LORD has cursed."`,
  notconfused:`Lamech son of Methushael, in Cain's line, who boasted of killing a man (Genesis 4:18–24).`,
  refs:["Genesis 5:25–31"]},

 // Shem's line to Abram (Genesis 10–11)
 {id:"arphaxad", name:"Arphaxad", short:"Arphaxad", cat:"line", w:4,
  dates:"primeval · lived 438 years (35 + 403, Genesis 11:12–13) · c. 2516 – 2078 BC* by a straight count of Genesis 5 & 11 (estimate)",
  desc:`Son of Shem, born "two years after the flood," and father of Shelah.`,
  refs:["Genesis 10:22–24","Genesis 11:10–13"]},

 {id:"shelah_a", name:"Shelah son of Arphaxad", short:"Shelah", cat:"line", w:4,
  clash:"Shelah", clashtag:"Son of Arphaxad and father of Eber, in Shem's line to Abram.",
  dates:"primeval · lived 433 years (30 + 403, Genesis 11:14–15) · c. 2481 – 2048 BC* by a straight count of Genesis 5 & 11 (estimate)",
  desc:`Son of Arphaxad and father of Eber, in Shem's line to Abram.`,
  notconfused:`Shelah son of Judah, the son Judah withheld from Tamar (Genesis 38).`,
  refs:["Genesis 10:24","Genesis 11:12–15"]},

 {id:"eber", name:"Eber", short:"Eber", cat:"line", w:5,
  dates:"primeval · lived 464 years (34 + 430, Genesis 11:16–17) · c. 2451 – 1987 BC* by a straight count of Genesis 5 & 11 (estimate)",
  desc:`Son of Shelah; Genesis calls Shem "the ancestor of all the sons of Eber." He had two sons: Peleg, through whom the line continues to Abram, and Joktan, whose thirteen sons lived "in the eastern hill country."`,
  refs:["Genesis 10:21","Genesis 10:24–30","Genesis 11:14–17"]},

 {id:"peleg", name:"Peleg", short:"Peleg", cat:"line", w:4,
  dates:"primeval · lived 239 years (30 + 209, Genesis 11:18–19) · c. 2417 – 2178 BC* by a straight count of Genesis 5 & 11 (estimate)",
  desc:`Son of Eber, "named Peleg, because in his time the earth was divided." Father of Reu.`,
  refs:["Genesis 10:25","Genesis 11:16–19"]},

 {id:"reu", name:"Reu", short:"Reu", cat:"line", w:4,
  dates:"primeval · lived 239 years (32 + 207, Genesis 11:20–21) · c. 2387 – 2148 BC* by a straight count of Genesis 5 & 11 (estimate)",
  desc:`Son of Peleg and father of Serug, in Shem's line to Abram.`,
  refs:["Genesis 11:18–21"]},

 {id:"serug", name:"Serug", short:"Serug", cat:"line", w:4,
  dates:"primeval · lived 230 years (30 + 200, Genesis 11:22–23) · c. 2355 – 2125 BC* by a straight count of Genesis 5 & 11 (estimate)",
  desc:`Son of Reu and father of Nahor, in Shem's line to Abram.`,
  refs:["Genesis 11:20–23"]},

 {id:"nahor_elder", name:"Nahor son of Serug", short:"Nahor (Terah's father)", cat:"line", w:4,
  clash:"Nahor", clashtag:"Son of Serug and father of Terah — Abram's grandfather.",
  dates:"primeval · lived 148 years (29 + 119, Genesis 11:24–25) · c. 2325 – 2177 BC* by a straight count of Genesis 5 & 11 (estimate)",
  desc:`Son of Serug and father of Terah, which makes him Abram's grandfather. Abram's brother bears the same name.`,
  notconfused:`Nahor son of Terah, Abraham's brother and Rebekah's grandfather (Genesis 11:26–29).`,
  refs:["Genesis 11:22–25"]},

 // ---------------- PATRIARCHS & MATRIARCHS (Genesis 12–50) ----------------
 {id:"abraham", name:"Abraham", short:"Abraham", cat:"patri", w:16, halo:1,
  aliases:"Abram · father of many nations",
  dates:"c. 2166 – 1991 BC* (estimate) · lived 175 years (Genesis 25:7)",
  desc:`Son of Terah, brought by the LORD "out of Ur of the Chaldeans" and told to go "to the land I will show you," with the promise: "I will make you into a great nation … and all peoples on earth will be blessed through you." He "believed the LORD, and he credited it to him as righteousness." Renamed Abraham at the covenant of circumcision, he fathers Ishmael by Hagar and, at a hundred, Isaac by Sarah — then is tested when God tells him to sacrifice Isaac in the region of Moriah. He is buried with Sarah in the cave of Machpelah. Isaiah 41:8 calls Israel the "descendants of Abraham my friend."`,
  refs:["Genesis 11:26–32","Genesis 12","Genesis 15","Genesis 17","Genesis 22","Genesis 25:1–11","Psalm 105:9","Isaiah 41:8","Isaiah 51:2","Ezekiel 33:24"]},

 {id:"sarah", name:"Sarah", short:"Sarah", cat:"patri", w:12,
  aliases:"Sarai",
  dates:"c. 2156 – 2029 BC* (estimate) · 90 at Isaac's birth (Genesis 17:17); lived 127 years (Genesis 23:1)",
  desc:`Abraham's wife — and, he tells Abimelek, "the daughter of my father though not of my mother." Childless, she gives her Egyptian slave Hagar to Abram to build a family through her. Twice passed off as Abraham's sister — to Pharaoh and to Abimelek — she laughs at the promise of a son in her old age, then bears Isaac: "God has brought me laughter." She dies at Hebron and is buried in the cave of Machpelah.`,
  refs:["Genesis 11:29–31","Genesis 12:10–20","Genesis 16","Genesis 17:15–21","Genesis 18:1–15","Genesis 20","Genesis 21:1–12","Genesis 23","Isaiah 51:2"]},

 {id:"isaac", name:"Isaac", short:"Isaac", cat:"patri", w:13,
  dates:"c. 2066 – 1886 BC* (estimate) · lived 180 years (Genesis 35:28)",
  desc:`The son born to Abraham at a hundred and to Sarah in her old age. Bound on the altar in the region of Moriah, he is spared when God provides a ram. At forty he marries Rebekah, and at sixty becomes father of the twins Esau and Jacob. Like his father he calls his wife his sister at Gerar and makes a treaty with Abimelek; in old age, his eyes weak, he is deceived into blessing Jacob instead of Esau. His sons Esau and Jacob bury him.`,
  refs:["Genesis 21:1–8","Genesis 22","Genesis 24","Genesis 25:19–28","Genesis 26","Genesis 27","Genesis 35:27–29","Psalm 105:9"]},

 {id:"rebekah", name:"Rebekah", short:"Rebekah", cat:"patri", w:11,
  dates:"c. 21st – 20th c. BC* (estimate) · married Isaac when he was 40 (Genesis 25:20)",
  desc:`Daughter of Bethuel and granddaughter of Abraham's brother Nahor. At the spring she offers Abraham's servant, "I'll draw water for your camels too," and when asked to go with him answers, "I will go." She becomes Isaac's wife; childless until Isaac prays, she is told "the older will serve the younger" and bears Esau and Jacob. She loves Jacob, helps him take Esau's blessing, and sends him to her brother Laban.`,
  refs:["Genesis 22:23","Genesis 24","Genesis 25:19–28","Genesis 26:7–11","Genesis 27","Genesis 49:31"]},

 {id:"jacob", name:"Jacob", short:"Jacob", cat:"patri", w:15, halo:1,
  aliases:"Israel",
  dates:"c. 2006 – 1859 BC* (estimate) · lived 147 years (Genesis 47:28)",
  desc:`Esau's younger twin, born "with his hand grasping Esau's heel." He buys Esau's birthright for stew and, with Rebekah's help, takes his blessing. Fleeing to Laban, he dreams of a stairway to heaven at Bethel, serves fourteen years for Leah and Rachel, and fathers twelve sons and a daughter. At the Jabbok a man wrestles with him till daybreak and renames him Israel, "because you have struggled with God and with humans and have overcome." In old age he goes down to Egypt, blesses his sons — "the twelve tribes of Israel" — and is buried at Machpelah. Hosea recalls him: "In the womb he grasped his brother's heel; as a man he struggled with God. He struggled with the angel and overcame him; he wept and begged for his favor. He found him at Bethel," and "Jacob fled to the country of Aram; Israel served to get a wife, and to pay for her he tended sheep." Malachi 1:2–3: "Was not Esau Jacob's brother?" declares the LORD. "Yet I have loved Jacob, but Esau I have hated."`,
  refs:["Genesis 25:19–34","Genesis 27–35","Genesis 46–50","Hosea 12:3–4","Hosea 12:12","Malachi 1:2–3"]},

 {id:"leah", name:"Leah", short:"Leah", cat:"patri", w:10,
  dates:"c. 20th c. BC* (estimate)",
  desc:`Laban's older daughter, who "had weak eyes," given to Jacob by her father's deception in place of Rachel. "When the LORD saw that Leah was not loved, he enabled her to conceive": she bears Reuben, Simeon, Levi, Judah, Issachar and Zebulun, and a daughter, Dinah. She also gives her servant Zilpah to Jacob. She is buried in the cave of Machpelah.`,
  refs:["Genesis 29:16–35","Genesis 30:9–21","Genesis 49:31"]},

 {id:"rachel", name:"Rachel", short:"Rachel", cat:"patri", w:11,
  dates:"c. 20th c. BC* (estimate)",
  desc:`Laban's younger daughter, a shepherd, for whom Jacob served seven years that "seemed like only a few days to him because of his love for her." Long childless, she gives her servant Bilhah to Jacob, then bears Joseph: "God has taken away my disgrace." She steals her father's household gods, and dies giving birth to Benjamin on the way to Ephrath (Bethlehem), where Jacob sets a pillar over her tomb. Jeremiah 31:15: "Rachel weeping for her children and refusing to be comforted, because they are no more."`,
  refs:["Genesis 29:6–30","Genesis 30:1–8","Genesis 30:22–24","Genesis 31:19–35","Genesis 35:16–20","Jeremiah 31:15"]},

 {id:"joseph_ot", name:"Joseph", short:"Joseph", cat:"patri", w:14, halo:1,
  aliases:"Zaphenath-Paneah · \"that dreamer\"",
  dates:"c. 1915 – 1805 BC* (estimate) · lived 110 years (Genesis 50:26)",
  desc:`Rachel's firstborn and Jacob's favorite, given an ornate robe. His dreams of his family bowing to him stir his brothers' hatred, and they sell him to traders bound for Egypt. There he serves Potiphar, is falsely accused by Potiphar's wife and imprisoned, and interprets the dreams of Pharaoh's cupbearer and baker — then Pharaoh's own. Put in charge of the whole land of Egypt, he stores grain for the famine, tests and finally reveals himself to his brothers, and settles Jacob's family in Goshen: "You intended to harm me, but God intended it for good." Psalm 105: "Joseph, sold as a slave. They bruised his feet with shackles, his neck was put in irons, till what he foretold came to pass."`,
  notconfused:`Joseph the husband of Mary, the father-figure of Jesus in the New Testament — a different man, over a thousand years later.`,
  refs:["Genesis 30:22–24","Genesis 37","Genesis 39–45","Genesis 47–48","Genesis 50","Exodus 13:19","Joshua 24:32","Psalm 105:16–22"]},

 // ---------------- HOUSE OF JACOB ----------------
 {id:"reuben", name:"Reuben", short:"Reuben", cat:"tribe", w:9,
  dates:"c. 18th c. BC (traditional)",
  desc:`Jacob's firstborn, by Leah. He sleeps with his father's concubine Bilhah. When his brothers plot to kill Joseph he says, "Don't shed any blood," meaning to rescue him, and later offers his own two sons as surety for Benjamin. Jacob's blessing: "Turbulent as the waters, you will no longer excel." His sons were Hanok, Pallu, Hezron and Karmi.`,
  refs:["Genesis 29:32","Genesis 35:22","Genesis 37:21–30","Genesis 42:22","Genesis 42:37","Genesis 46:8–9","Genesis 49:3–4"]},

 {id:"simeon", name:"Simeon", short:"Simeon", cat:"tribe", w:8,
  dates:"c. 18th c. BC (traditional)",
  desc:`Leah's second son. With Levi he avenges Dinah by attacking the city of Shechem and killing every male. In Egypt Joseph has him bound and held until the brothers return with Benjamin. Jacob says of Simeon and Levi, "their swords are weapons of violence."`,
  notconfused:`Simeon who took the infant Jesus in his arms at the temple (Luke 2), and Simon Peter, in the New Testament.`,
  refs:["Genesis 29:33","Genesis 34:25–31","Genesis 42:24","Genesis 43:23","Genesis 46:10","Genesis 49:5–7"]},

 {id:"levi", name:"Levi", short:"Levi", cat:"tribe", w:8,
  dates:"c. 18th c. BC (traditional) · lived 137 years (Exodus 6:16)",
  desc:`Leah's third son: "Now at last my husband will become attached to me." With Simeon he takes revenge on Shechem for Dinah, and Jacob's last words condemn their anger: "I will scatter them in Jacob." His sons were Gershon, Kohath and Merari; Moses and Aaron later come from his tribe. Malachi 2:4–6 speaks of "my covenant with Levi… a covenant of life and peace… True instruction was in his mouth and nothing false was found on his lips."`,
  notconfused:`Levi the tax collector (Matthew) in the New Testament.`,
  refs:["Genesis 29:34","Genesis 34:25–31","Genesis 46:11","Genesis 49:5–7","Exodus 6:16–20","Malachi 2:4–8"]},

 {id:"judah", name:"Judah", short:"Judah", cat:"tribe", w:11,
  dates:"c. 18th c. BC (traditional)",
  desc:`Leah's fourth son: "This time I will praise the LORD." He proposes selling Joseph to the Ishmaelites rather than killing him. Through Tamar, his daughter-in-law, he fathers the twins Perez and Zerah, admitting, "She is more righteous than I." He pledges himself for Benjamin and offers to stay as a slave in the boy's place. Jacob blesses him: "The scepter will not depart from Judah."`,
  notconfused:`Judas — the same name in Greek — including Judas Iscariot and Jude, in the New Testament.`,
  refs:["Genesis 29:35","Genesis 37:26–27","Genesis 38","Genesis 43:3–10","Genesis 44:14–34","Genesis 49:8–12"]},

 {id:"dan", name:"Dan", short:"Dan", cat:"tribe", w:6,
  dates:"c. 18th c. BC (traditional)",
  desc:`Bilhah's first son, born for Rachel: "God has vindicated me." Jacob: "Dan will provide justice for his people … Dan will be a snake by the roadside." His son was Hushim.`,
  notconfused:`The town of Dan, to which Abram pursued Lot's captors (Genesis 14:14).`,
  refs:["Genesis 30:3–6","Genesis 46:23","Genesis 49:16–17"]},

 {id:"naphtali", name:"Naphtali", short:"Naphtali", cat:"tribe", w:6,
  dates:"c. 18th c. BC (traditional)",
  desc:`Bilhah's second son: "I have had a great struggle with my sister, and I have won." Jacob: "Naphtali is a doe set free that bears beautiful fawns."`,
  refs:["Genesis 30:7–8","Genesis 46:24","Genesis 49:21"]},

 {id:"gad", name:"Gad", short:"Gad", cat:"tribe", w:6,
  clash:"Gad", clashtag:"Jacob's son by Zilpah, ancestor of the tribe of Gad.",
  dates:"c. 18th c. BC (traditional)",
  desc:`Zilpah's first son, born for Leah: "What good fortune!" Jacob: "Gad will be attacked by a band of raiders, but he will attack them at their heels."`,
  refs:["Genesis 30:9–11","Genesis 46:16","Genesis 49:19"]},

 {id:"asher", name:"Asher", short:"Asher", cat:"tribe", w:6,
  dates:"c. 18th c. BC (traditional)",
  desc:`Zilpah's second son: "How happy I am!" Jacob: "Asher's food will be rich; he will provide delicacies fit for a king." His daughter was Serah.`,
  refs:["Genesis 30:12–13","Genesis 46:17","Genesis 49:20"]},

 {id:"issachar", name:"Issachar", short:"Issachar", cat:"tribe", w:6,
  dates:"c. 18th c. BC (traditional)",
  desc:`Leah's fifth son, conceived after she traded Reuben's mandrakes to Rachel for a night with Jacob: "God has rewarded me." Jacob: "Issachar is a rawboned donkey lying down among the sheep pens."`,
  refs:["Genesis 30:14–18","Genesis 46:13","Genesis 49:14–15"]},

 {id:"zebulun", name:"Zebulun", short:"Zebulun", cat:"tribe", w:6,
  dates:"c. 18th c. BC (traditional)",
  desc:`Leah's sixth son: "God has presented me with a precious gift." Jacob: "Zebulun will live by the seashore and become a haven for ships."`,
  refs:["Genesis 30:19–20","Genesis 46:14","Genesis 49:13"]},

 {id:"benjamin", name:"Benjamin", short:"Benjamin", cat:"tribe", w:9,
  aliases:"Ben-Oni",
  dates:"c. 18th c. BC (traditional)",
  desc:`Jacob's youngest son and Rachel's second, born as she died; she named him Ben-Oni, "but his father named him Benjamin." Jacob keeps him home on the first journey to Egypt; on the second, Joseph's silver cup is planted in his sack. Joseph weeps on him, and gives him five times the portion and five sets of clothes. Jacob: "Benjamin is a ravenous wolf."`,
  refs:["Genesis 35:16–18","Genesis 42–45","Genesis 46:21","Genesis 49:27"]},

 {id:"dinah", name:"Dinah", short:"Dinah", cat:"tribe", w:7,
  dates:"c. 18th c. BC (traditional)",
  desc:`Jacob's daughter by Leah. When she goes out to visit the women of the land, Shechem son of Hamor "took her and raped her," then asks to marry her. Her brothers answer deceitfully, and Simeon and Levi kill the city's men and take her from Shechem's house.`,
  refs:["Genesis 30:21","Genesis 34","Genesis 46:15"]},

 {id:"bilhah", name:"Bilhah", short:"Bilhah", cat:"tribe", w:7,
  dates:"c. 18th c. BC (traditional)",
  desc:`The servant Laban gave to Rachel, who gives her to Jacob "as a wife" so she can build a family through her. She bears Dan and Naphtali. Reuben later sleeps with her.`,
  refs:["Genesis 29:29","Genesis 30:3–8","Genesis 35:22","Genesis 35:25"]},

 {id:"zilpah", name:"Zilpah", short:"Zilpah", cat:"tribe", w:6,
  dates:"c. 18th c. BC (traditional)",
  desc:`The servant Laban gave to Leah, who gives her to Jacob as a wife when she stops having children. She bears Gad and Asher.`,
  refs:["Genesis 29:24","Genesis 30:9–13","Genesis 35:26"]},

 {id:"tamar_g", name:"Tamar, Judah's daughter-in-law", short:"Tamar", cat:"tribe", w:8,
  clash:"Tamar", clashtag:"Judah's daughter-in-law, mother of Perez and Zerah.",
  dates:"c. 18th c. BC (traditional)",
  desc:`Widow of Judah's sons Er and then Onan. When Judah withholds his third son Shelah from her, she disguises herself with a veil by the road to Timnah and conceives by Judah himself, keeping his seal, cord and staff as a pledge. Accused of prostitution, she produces them, and Judah admits, "She is more righteous than I." She bears twins, Perez and Zerah.`,
  notconfused:`Tamar daughter of David (2 Samuel 13), a different woman centuries later.`,
  refs:["Genesis 38","Matthew 1:3"]},

 {id:"er", name:"Er", short:"Er", cat:"tribe", w:5,
  dates:"c. 18th c. BC (traditional)",
  desc:`Judah's firstborn, married to Tamar. He "was wicked in the LORD's sight; so the LORD put him to death."`,
  refs:["Genesis 38:3–7","Genesis 46:12"]},

 {id:"onan", name:"Onan", short:"Onan", cat:"tribe", w:5,
  dates:"c. 18th c. BC (traditional)",
  desc:`Judah's second son, told to fulfill his duty as a brother-in-law and raise offspring for Er. He refuses to provide offspring for his brother, and the LORD puts him to death also.`,
  refs:["Genesis 38:4–10","Genesis 46:12"]},

 {id:"shelah_j", name:"Shelah son of Judah", short:"Shelah (Judah's son)", cat:"tribe", w:5,
  clash:"Shelah", clashtag:"Judah's third son, whom Judah withheld from Tamar, fearing he would die like his brothers.",
  dates:"c. 18th c. BC (traditional)",
  desc:`Judah's third son, born at Kezib. Judah tells Tamar to wait until Shelah grows up, but withholds him, thinking, "He may die too, just like his brothers."`,
  notconfused:`Shelah son of Arphaxad, in Shem's line to Abram (Genesis 11:12–15).`,
  refs:["Genesis 38:5","Genesis 38:11–14","Genesis 38:26","Genesis 46:12"]},

 {id:"perez", name:"Perez", short:"Perez", cat:"tribe", w:6,
  dates:"c. 18th c. BC (traditional)",
  desc:`Twin son of Judah and Tamar who came out ahead of his brother — "So this is how you have broken out!" His sons were Hezron and Hamul. The book of Ruth traces David's line from him.`,
  refs:["Genesis 38:27–30","Genesis 46:12","Ruth 4:18–22"]},

 {id:"zerah_j", name:"Zerah son of Judah", short:"Zerah", cat:"tribe", w:5,
  clash:"Zerah", clashtag:"Son of Judah and Tamar, twin brother of Perez.",
  dates:"c. 18th c. BC (traditional)",
  desc:`Perez's twin, who first put out his hand and had a scarlet thread tied on his wrist by the midwife, but was born second.`,
  notconfused:`Zerah son of Reuel, a grandson of Esau (Genesis 36:13), and Zerah of Bozrah, father of the Edomite king Jobab (36:33).`,
  refs:["Genesis 38:27–30","Genesis 46:12"]},

 {id:"manasseh_j", name:"Manasseh son of Joseph", short:"Manasseh", cat:"tribe", w:7,
  clash:"Manasseh", clashtag:"Joseph's firstborn, claimed by Jacob as his own son but blessed second to his younger brother Ephraim.",
  dates:"c. 18th c. BC (traditional)",
  desc:`Joseph's firstborn by Asenath in Egypt: "It is because God has made me forget all my trouble and all my father's household." Jacob claims him and Ephraim as his own sons, but crosses his hands to put his right hand on the younger. Joseph lives to see the children of Manasseh's son Makir.`,
  notconfused:`King Manasseh of Judah, centuries later (2 Kings 21).`,
  refs:["Genesis 41:50–51","Genesis 46:20","Genesis 48","Genesis 50:23"]},

 {id:"ephraim", name:"Ephraim", short:"Ephraim", cat:"tribe", w:8,
  dates:"c. 18th c. BC (traditional)",
  desc:`Joseph's second son: "It is because God has made me fruitful in the land of my suffering." Though younger, he receives Jacob's right hand — "his younger brother will be greater than he" — and Israel is to bless by saying, "May God make you like Ephraim and Manasseh."`,
  refs:["Genesis 41:52","Genesis 46:20","Genesis 48","Genesis 50:23"]},

 // ---------------- WIDER FAMILY & KIN ----------------
 {id:"terah", name:"Terah", short:"Terah", cat:"kin", w:8,
  dates:"c. 2296 – 2091 BC* (estimate) · lived 205 years (Genesis 11:32)",
  desc:`Son of Nahor and father of Abram, Nahor and Haran. He sets out from Ur of the Chaldeans with Abram, Sarai and his grandson Lot to go to Canaan, but they settle in Harran, where he dies. Abraham later calls Sarah "the daughter of my father though not of my mother." Joshua recalls that Terah and his family "lived beyond the Euphrates River and worshiped other gods."`,
  refs:["Genesis 11:24–32","Genesis 20:12","Joshua 24:2"]},

 {id:"haran_t", name:"Haran son of Terah", short:"Haran", cat:"kin", w:5,
  dates:"c. 21st c. BC (traditional)",
  desc:`Abram's brother and the father of Lot, Milkah and Iskah. He died in Ur of the Chaldeans while his father Terah was still alive.`,
  notconfused:`Harran, the city where Terah's family settled (Genesis 11:31) — spelled differently in the NIV.`,
  refs:["Genesis 11:26–31"]},

 {id:"nahor_b", name:"Nahor brother of Abraham", short:"Nahor", cat:"kin", w:7,
  clash:"Nahor", clashtag:"Abraham's brother, husband of Milkah and grandfather of Rebekah and Laban.",
  dates:"c. 21st c. BC (traditional)",
  desc:`Abram's brother, who married Milkah. Milkah bore him eight sons — Uz, Buz, Kemuel, Kesed, Hazo, Pildash, Jidlaph and Bethuel — and his concubine Reumah bore Tebah, Gaham, Tahash and Maakah. Abraham's servant finds Rebekah at "the town of Nahor," and Laban swears by "the God of Abraham and the God of Nahor."`,
  notconfused:`Nahor son of Serug, his grandfather (Genesis 11:22–25).`,
  refs:["Genesis 11:26–29","Genesis 22:20–24","Genesis 24:10","Genesis 31:53"]},

 {id:"milkah", name:"Milkah wife of Nahor", short:"Milkah", cat:"kin", w:5,
  clash:"Milkah", clashtag:"Daughter of Haran and wife of Abraham's brother Nahor; Rebekah's grandmother.",
  notconfused:`Milkah daughter of Zelophehad, of the tribe of Manasseh (Numbers 27:1).`,
  dates:"c. 21st c. BC (traditional)",
  desc:`Daughter of Haran and wife of Abram's brother Nahor; mother of eight sons, including Bethuel, Rebekah's father.`,
  refs:["Genesis 11:29","Genesis 22:20–23","Genesis 24:15"]},

 {id:"bethuel", name:"Bethuel", short:"Bethuel", cat:"kin", w:6,
  aliases:"Bethuel the Aramean",
  dates:"c. 20th c. BC (traditional)",
  desc:`Son of Nahor and Milkah, "the Aramean from Paddan Aram"; father of Rebekah and Laban. With Laban he answers Abraham's servant: "This is from the LORD."`,
  refs:["Genesis 22:22–23","Genesis 24:15","Genesis 24:50","Genesis 25:20","Genesis 28:2–5"]},

 {id:"laban", name:"Laban", short:"Laban", cat:"kin", w:10,
  aliases:"Laban the Aramean",
  dates:"c. 19th c. BC (traditional)",
  desc:`Rebekah's brother in Harran. He welcomes Abraham's servant, later takes in his nephew Jacob, and on the wedding night gives him Leah instead of Rachel: "It is not our custom here to give the younger daughter in marriage before the older one." Jacob says Laban changed his wages "ten times." He pursues Jacob when he flees, searches in vain for his stolen household gods, and the two make a covenant at Galeed (Mizpah).`,
  refs:["Genesis 24:29–60","Genesis 29","Genesis 30:25–43","Genesis 31"]},

 {id:"lot", name:"Lot", short:"Lot", cat:"kin", w:10,
  dates:"c. 2000 BC (traditional)",
  desc:`Son of Abram's brother Haran, who travels with Abram from Harran. When their herders quarrel he chooses the well-watered plain of the Jordan and pitches his tents near Sodom. Carried off in the war of the kings, he is rescued by Abram. Two angels later lead him, his wife and two daughters out before Sodom and Gomorrah are destroyed. Through his daughters he becomes the father of Moab and Ben-Ammi.`,
  refs:["Genesis 11:27–31","Genesis 12:4–5","Genesis 13","Genesis 14:12–16","Genesis 19"]},

 {id:"lotwife", name:"Lot's wife", short:"Lot's wife", cat:"kin", w:6,
  dates:"c. 2000 BC (traditional)",
  desc:`Led out of Sodom by the angels with Lot and their two daughters, with the warning "Don't look back." "But Lot's wife looked back, and she became a pillar of salt." Genesis does not give her name.`,
  refs:["Genesis 19:15–26","Luke 17:32"]},

 {id:"moab", name:"Moab", short:"Moab", cat:"kin", w:5,
  dates:"c. 2000 BC (traditional)",
  desc:`Son of Lot by his older daughter, born after they fled Zoar to live in a cave; "he is the father of the Moabites of today."`,
  refs:["Genesis 19:30–37"]},

 {id:"benammi", name:"Ben-Ammi", short:"Ben-Ammi", cat:"kin", w:5,
  dates:"c. 2000 BC (traditional)",
  desc:`Son of Lot by his younger daughter; "he is the father of the Ammonites of today."`,
  refs:["Genesis 19:36–38"]},

 {id:"hagar", name:"Hagar", short:"Hagar", cat:"kin", w:9,
  aliases:"Hagar the Egyptian",
  dates:"c. 2000 BC (traditional)",
  desc:`Sarai's Egyptian slave, given to Abram "to be his wife." When she conceives she despises her mistress, and flees when Sarai mistreats her. The angel of the LORD finds her by a spring and tells her to name her son Ishmael; she calls the LORD "the God who sees me." After Isaac is weaned she is sent away and wanders in the Desert of Beersheba, until God opens her eyes to a well. She later gets Ishmael a wife from Egypt.`,
  refs:["Genesis 16","Genesis 21:8–21","Genesis 25:12"]},

 {id:"ishmael", name:"Ishmael", short:"Ishmael", cat:"kin", w:9,
  clash:"Ishmael", clashtag:"Son of Abraham and Hagar, father of twelve tribal rulers.",
  dates:"c. 2080 – 1943 BC* (estimate) · born when Abram was 86 (Genesis 16:16); lived 137 years (Genesis 25:17)",
  desc:`Son of Abram and Hagar, born when Abram was eighty-six; named by the angel "for the LORD has heard of your misery." Circumcised at thirteen, he is promised to become "a great nation" and "the father of twelve rulers," though God's covenant is established with Isaac. Sent away with his mother, he grows up in the desert and becomes an archer. With Isaac he buries Abraham. His twelve sons, from Nebaioth to Kedemah, became tribal rulers. By tradition, ancestor of the Arab peoples.`,
  notconfused:`Ishmael son of Nethaniah, who assassinated Gedaliah after the fall of Jerusalem (Jeremiah 41).`,
  refs:["Genesis 16","Genesis 17:18–26","Genesis 21:8–21","Genesis 25:9","Genesis 25:12–18"]},

 {id:"keturah", name:"Keturah", short:"Keturah", cat:"kin", w:6,
  dates:"c. 2000 BC (traditional)",
  desc:`Another wife of Abraham, who bore him Zimran, Jokshan, Medan, Midian, Ishbak and Shuah. Abraham left everything to Isaac, but gave gifts to the sons of his concubines and sent them away to the land of the east.`,
  refs:["Genesis 25:1–6"]},

 {id:"esau", name:"Esau", short:"Esau", cat:"kin", w:10,
  aliases:"Edom",
  dates:"born c. 2006 BC* (estimate), Jacob's twin (Genesis 25:24–26)",
  desc:`Isaac's firstborn twin — red, hairy, "a skillful hunter" and his father's favorite. Famished, he sells his birthright to Jacob for bread and lentil stew; when Jacob also takes his blessing, he plans to kill him. Twenty years later he runs to meet Jacob, embraces him and weeps. He settles in the hill country of Seir as father of the Edomites. Genesis lists his wives two ways — Judith, Basemath daughter of Elon and Mahalath daughter of Ishmael (26:34; 28:9), and Adah daughter of Elon, Oholibamah and Basemath daughter of Ishmael (36:2–3) — and his sons as Eliphaz, Reuel, Jeush, Jalam and Korah. Obadiah's vision against Edom speaks of "the mountains of Esau" and "the violence against your brother Jacob": "Jacob will be a fire and Joseph a flame; Esau will be stubble." Amos condemns Edom "because he pursued his brother with a sword."`,
  refs:["Genesis 25:24–34","Genesis 26:34–35","Genesis 27","Genesis 28:6–9","Genesis 32–33","Genesis 36","Obadiah 1","Amos 1:11–12","Malachi 1:2–4"]},

 {id:"deborah_n", name:"Deborah, Rebekah's nurse", short:"Deborah (nurse)", cat:"kin", w:5,
  clash:"Deborah", clashtag:"Rebekah's nurse, who died while Jacob's household was at Bethel and was buried under the oak outside it.",
  dates:"c. 19th c. BC (traditional)",
  desc:`Rebekah's nurse. A nurse went with Rebekah when she left home to marry Isaac (24:59); Genesis 35:8 records that "Deborah, Rebekah's nurse, died and was buried under the oak outside Bethel," at the place named Allon Bakuth.`,
  notconfused:`Deborah the prophetess and judge, who led Israel with Barak (Judges 4–5).`,
  refs:["Genesis 24:59","Genesis 35:8"]},

 {id:"abr_servant", name:"Abraham's senior servant", short:"Abraham's servant", cat:"kin", w:7,
  dates:"c. 1900 BC (traditional)",
  desc:`"The senior servant in his household, the one in charge of all that he had," sent under oath to Aram Naharaim to find a wife for Isaac among Abraham's relatives. He prays for a sign at the spring outside the town of Nahor, recognises it in Rebekah, and brings her back to Isaac.`,
  notconfused:`Eliezer of Damascus, whom the childless Abram expected to be his heir (15:2). Genesis 24 never names the servant, so identifying him as Eliezer is an assumption, not the text.`,
  refs:["Genesis 24"]},

 {id:"eliezer", name:"Eliezer of Damascus", short:"Eliezer", cat:"kin", w:5,
  clash:"Eliezer", clashtag:"The servant Abram named as his heir while he was still childless.",
  dates:"c. 2000 BC (traditional)",
  desc:`Named by the childless Abram as "the one who will inherit my estate" — "a servant in my household will be my heir." The LORD answers, "This man will not be your heir."`,
  notconfused:`Abraham's unnamed senior servant of Genesis 24, often assumed to be Eliezer — the text does not say so.`,
  refs:["Genesis 15:2–4"]},

 // ---------------- PATRIARCHAL ERA (outside Genesis) ----------------
 {id:"job", name:"Job", short:"Job", cat:"wis", w:12,
  aliases:"the man from Uz · \"my servant Job\"",
  dates:"undated — the book gives no date",
  desc:`"In the land of Uz there lived a man whose name was Job," "blameless and upright," with seven sons, three daughters and great flocks — "the greatest man among all the people of the East." When the LORD points to "my servant Job," Satan answers, "Does Job fear God for nothing?" and is allowed to strike everything he has — his herds and servants are lost to Sabeans, Chaldeans and fire, and his children die when a wind brings the house down — and then his body, with painful sores. Job worships: "The LORD gave and the LORD has taken away; may the name of the LORD be praised." His wife says, "Curse God and die!"; he answers, "Shall we accept good from God, and not trouble?" After seven silent days with his three friends he curses the day of his birth, and through long cycles of debate he maintains his innocence against them — "Though he slay me, yet will I hope in him"; "I know that my redeemer lives." The LORD answers him "out of the storm" — "Where were you when I laid the earth's foundation?" — and Job replies, "My ears had heard of you but now my eyes have seen you." The LORD tells the friends, "you have not spoken the truth about me, as my servant Job has," accepts Job's prayer for them, and gives him twice as much as before; he again has seven sons and three daughters and lives another 140 years. Ezekiel names him with Noah and Daniel as men whose righteousness "could save only themselves."`,
  refs:["Job 1–2","Job 3","Job 13:15","Job 19:25–27","Job 38–42","Ezekiel 14:14","Ezekiel 14:20"]},

 // ================= EXODUS =================
 // Sourced chapter-by-chapter from the NIV on bible.com (Exodus 1–40).

 // ---------------- EXODUS & WILDERNESS ----------------
 {id:"moses", name:"Moses", short:"Moses", cat:"exod", w:16, halo:1,
  aliases:"\"Moses the servant of the LORD\" · \"Moses the man of God\"",
  dates:"c. 1526 – 1406 BC* (early-date estimate) · 80 before Pharaoh (Exodus 7:7); died at 120 (Deuteronomy 34:7)",
  desc:`Born to Levite parents, Amram and Jochebed, when Pharaoh had ordered every Hebrew boy thrown into the Nile; hidden, set in a papyrus basket, and raised as the son of Pharaoh's daughter, who named him: "I drew him out of the water." After killing an Egyptian he flees to Midian and marries Zipporah. At the burning bush God sends him to Pharaoh — "I am who I am." He leads Israel out through the plagues, the Passover and the sea, receives the Ten Commandments at Sinai, pleads for the people after the golden calf, ordains Aaron and builds the tabernacle; "The LORD would speak to Moses face to face, as one speaks to a friend." In the wilderness — "a very humble man, more humble than anyone else on the face of the earth" — he bears the people's complaints, the spies' bad report and Korah's revolt. At Meribah, told to speak to the rock, he strikes it twice, and because he and Aaron "did not trust in me enough to honor me as holy," he may not enter the land. On the plains of Moab he sets the law before Israel again (Deuteronomy), commissions Joshua, teaches the people his song and blesses the tribes, then dies on Mount Nebo at 120, "yet his eyes were not weak nor his strength gone." Psalm 90 is "A prayer of Moses the man of God": "Teach us to number our days, that we may gain a heart of wisdom." Psalm 106 recalls that Moses "stood in the breach" to keep God's wrath from destroying the people, and that at Meribah "rash words came from Moses' lips." Jeremiah 15:1: "Even if Moses and Samuel were to stand before me, my heart would not go out to this people." Micah 6:4: "I sent Moses to lead you, also Aaron and Miriam." Malachi closes the prophets with "Remember the law of my servant Moses, the decrees and laws I gave him at Horeb for all Israel."`,
  notconfused:`Deuteronomy 18:15 promises "a prophet like me"; Deuteronomy 34:10 adds that "no prophet has risen in Israel like Moses, whom the LORD knew face to face."`,
  refs:["Exodus 2–4","Exodus 14","Exodus 19–20","Exodus 32–34","Leviticus 8","Numbers 12","Numbers 20:1–13","Numbers 27:12–23","Deuteronomy 31–34","Psalm 90","Psalm 106:23","Psalm 106:32–33","Isaiah 63:11–12","Jeremiah 15:1","Daniel 9:11–13","Micah 6:4","Malachi 4:4"]},

 {id:"miriam", name:"Miriam", short:"Miriam", cat:"exod", w:9,
  aliases:"Miriam the prophet",
  dates:"c. 15th c. BC (traditional)",
  desc:`"Miriam the prophet, Aaron's sister," who after the crossing of the sea takes a timbrel and leads the women in song: "Sing to the LORD, for he is highly exalted." Exodus 2 does not name the sister who watched the infant Moses in the reeds; Miriam is the only sister of Moses and Aaron named in Scripture (Numbers 26:59). She and Aaron speak against Moses because of his Cushite wife — "Has the LORD spoken only through Moses?" — and her skin becomes leprous, "as white as snow." Moses cries, "Please, God, heal her!" and she is confined outside the camp seven days before being brought back. She dies and is buried at Kadesh. Deuteronomy 24:9: "Remember what the LORD your God did to Miriam along the way." Micah 6:4 names her with her brothers: "I sent Moses to lead you, also Aaron and Miriam."`,
  refs:["Exodus 2:4–8","Exodus 15:20–21","Numbers 12","Numbers 20:1","Numbers 26:59","Deuteronomy 24:9","Micah 6:4"]},

 {id:"amram", name:"Amram", short:"Amram", cat:"exod", w:6,
  dates:"c. 16th c. BC (traditional) · lived 137 years (Exodus 6:20)",
  desc:`A son of Kohath, son of Levi. "Amram married his father's sister Jochebed, who bore him Aaron and Moses." Exodus 2 calls him simply "a man of the tribe of Levi."`,
  refs:["Exodus 2:1","Exodus 6:18–20","Numbers 26:59"]},

 {id:"jochebed", name:"Jochebed", short:"Jochebed", cat:"exod", w:7,
  dates:"c. 16th c. BC (traditional)",
  desc:`Amram's wife — his father's sister — and the mother of Aaron and Moses (and, per Numbers 26:59, Miriam). As Moses' mother she is the "Levite woman" of Exodus 2 who hides her baby for three months, places him in a papyrus basket among the reeds, and is then paid by Pharaoh's daughter to nurse him.`,
  refs:["Exodus 2:1–10","Exodus 6:20","Numbers 26:59"]},

 {id:"zipporah", name:"Zipporah", short:"Zipporah", cat:"exod", w:8,
  dates:"c. 15th c. BC (traditional)",
  desc:`One of the seven daughters of Reuel (Jethro), the priest of Midian, given to Moses in marriage after he rescues them at the well. She bears Gershom and Eliezer. On the way back to Egypt, when the LORD is about to kill Moses, she circumcises her son with a flint knife: "Surely you are a bridegroom of blood to me." Moses later sends her away, and Jethro brings her and her sons back to him in the wilderness.`,
  refs:["Exodus 2:16–22","Exodus 4:20–26","Exodus 18:2–6"]},

 {id:"gershom", name:"Gershom", short:"Gershom", cat:"exod", w:6,
  dates:"c. 15th c. BC (traditional)",
  desc:`Moses' son by Zipporah, born in Midian. Moses named him Gershom, saying, "I have become a foreigner in a foreign land."`,
  notconfused:`Gershon son of Levi, Moses' great-uncle, whose name differs by one letter (Exodus 6:16–17).`,
  refs:["Exodus 2:22","Exodus 18:3"]},

 {id:"eliezer_m", name:"Eliezer son of Moses", short:"Eliezer (Moses' son)", cat:"exod", w:5,
  clash:"Eliezer", clashtag:"Moses' second son by Zipporah: 'My father's God was my helper.'",
  dates:"c. 15th c. BC (traditional)",
  desc:`Moses' second son by Zipporah. Moses named him Eliezer, saying, "My father's God was my helper; he saved me from the sword of Pharaoh."`,
  notconfused:`Eliezer of Damascus, whom the childless Abram expected to be his heir (Genesis 15:2).`,
  refs:["Exodus 4:20","Exodus 18:4–6"]},

 {id:"jethro", name:"Jethro", short:"Jethro", cat:"exod", w:8,
  aliases:"Reuel · priest of Midian",
  dates:"c. 15th c. BC (traditional)",
  desc:`The priest of Midian — called Reuel when Moses first meets his seven daughters at the well — who takes Moses in and gives him his daughter Zipporah. He sends Moses back to Egypt with "Go, and I wish you well." Hearing of the exodus, he brings Zipporah and her sons to Moses, declares, "Now I know that the LORD is greater than all other gods," and offers sacrifices. Seeing Moses judge the people from morning till evening, he advises him to appoint capable officials "over thousands, hundreds, fifties and tens." Numbers 10:29 names "Hobab son of Reuel the Midianite, Moses' father-in-law."`,
  notconfused:`Reuel son of Esau (Genesis 36:4), an Edomite.`,
  refs:["Exodus 2:15–22","Exodus 3:1","Exodus 4:18","Exodus 18","Numbers 10:29"]},

 {id:"hur", name:"Hur", short:"Hur", cat:"exod", w:6,
  dates:"c. 15th c. BC (traditional)",
  desc:`With Aaron, he holds up Moses' hands on the hilltop "one on one side, one on the other" until sunset, while Joshua defeats the Amalekites. When Moses goes up Sinai he tells the elders, "Aaron and Hur are with you, and anyone involved in a dispute can go to them."`,
  notconfused:`Hur the grandfather of Bezalel, of the tribe of Judah (Exodus 31:2) — 1 Chronicles 2:19–20 makes that Hur the son of Caleb son of Hezron by Ephrath — whom neither book identifies with this Hur; and Hur, one of the five kings of Midian killed in Numbers 31:8.`,
  refs:["Exodus 17:10–12","Exodus 24:14"]},

 {id:"bezalel", name:"Bezalel", short:"Bezalel", cat:"exod", w:8,
  dates:"c. 15th c. BC (traditional)",
  desc:`"Bezalel son of Uri, the son of Hur, of the tribe of Judah," chosen by the LORD and filled "with the Spirit of God, with wisdom, with understanding, with knowledge and with all kinds of skills" to make the tabernacle and its furnishings. With Oholiab he is given "the ability to teach others"; he makes the ark, the table, the lampstand and the altars. 1 Chronicles traces his line through Hur, son of Caleb son of Hezron and Ephrath; Solomon inquires of the LORD at "the bronze altar that Bezalel son of Uri, the son of Hur, had made."`,
  refs:["Exodus 31:1–11","Exodus 35:30–36:2","Exodus 37–38","1 Chronicles 2:18–20","2 Chronicles 1:5"]},

 {id:"oholiab", name:"Oholiab", short:"Oholiab", cat:"exod", w:6,
  dates:"c. 15th c. BC (traditional)",
  desc:`"Oholiab son of Ahisamak, of the tribe of Dan," appointed to help Bezalel build the tabernacle — "an engraver and designer, and an embroiderer in blue, purple and scarlet yarn and fine linen."`,
  refs:["Exodus 31:6","Exodus 35:34–36:2","Exodus 38:23"]},

 {id:"shiphrah", name:"Shiphrah", short:"Shiphrah", cat:"exod", w:6,
  dates:"c. 16th c. BC (traditional)",
  desc:`One of the two Hebrew midwives ordered by the king of Egypt to kill every newborn Hebrew boy. "The midwives, however, feared God" and let the boys live; God was kind to them and "gave them families of their own."`,
  refs:["Exodus 1:15–21"]},

 {id:"puah", name:"Puah", short:"Puah", cat:"exod", w:6,
  dates:"c. 16th c. BC (traditional)",
  desc:`The other Hebrew midwife who defied the king's order to kill the Hebrew boys. Questioned, the midwives answered, "Hebrew women are not like Egyptian women; they are vigorous and give birth before the midwives arrive."`,
  notconfused:`Puah son of Issachar (Genesis 46:13), a man of the same name.`,
  refs:["Exodus 1:15–21"]},

 {id:"korah", name:"Korah", short:"Korah", cat:"exod", w:8,
  dates:"c. 15th c. BC (traditional)",
  desc:`"Korah son of Izhar, the son of Kohath, the son of Levi," who with the Reubenites Dathan, Abiram and On and 250 council leaders rises against Moses and Aaron: "The whole community is holy … Why then do you set yourselves above the LORD's assembly?" Moses answers, "now you are trying to get the priesthood too." The earth opens and swallows the rebels' households, fire consumes the 250 offering incense, and their bronze censers are hammered into a covering for the altar. Yet "the line of Korah, however, did not die out"; his sons were Assir, Elkanah and Abiasaph. Eleven psalms are headed "of the Sons of Korah" (42, 44–49, 84–85, 87–88).`,
  notconfused:`Korah son of Esau, an Edomite chief (Genesis 36:5).`,
  refs:["Exodus 6:21","Exodus 6:24","Numbers 16","Numbers 26:9–11","Psalm 42","Psalms 44–49","Psalms 84–85","Psalms 87–88"]},

 // ---------------- PRIESTS & LEVITES ----------------
 {id:"aaron", name:"Aaron", short:"Aaron", cat:"priest", w:13, halo:1,
  aliases:"\"Aaron the Levite\" · the first priest of Israel",
  dates:"c. 1529 – 1407 BC* (early-date estimate) · 83 before Pharaoh (Exodus 7:7); died at 123 (Numbers 33:39)",
  desc:`Moses' elder brother, son of Amram and Jochebed, made his spokesman — "it will be as if he were your mouth." He stretches out his staff for the first plagues, holds up Moses' hands against the Amalekites, and sees the God of Israel on Sinai; left in charge below, he makes the golden calf — "out came this calf!" Ordained by Moses in the sacred garments, he offers the first sacrifices and blesses the people, and fire from the LORD consumes the offering; when Nadab and Abihu die for their unauthorized fire, "Aaron remained silent." He alone may enter the Most Holy Place, once a year on the Day of Atonement. In Numbers he joins Miriam in speaking against Moses; his staff alone "sprouted … budded, blossomed and produced almonds"; and with incense he "stood between the living and the dead, and the plague stopped." Barred from the land after Meribah, he dies on Mount Hor in the fortieth year, aged 123, and his garments are put on Eleazar; Deuteronomy 10:6 records his death at Moserah. The Psalms remember him beside Moses — "You led your people like a flock by the hand of Moses and Aaron" — and picture unity as precious oil "running down on Aaron's beard."`,
  refs:["Exodus 4:14–16","Exodus 28–29","Exodus 32","Leviticus 8–10","Leviticus 16","Numbers 12","Numbers 16:46–50","Numbers 17","Numbers 20:22–29","Numbers 33:38–39","Deuteronomy 10:6","Psalm 77:20","Psalm 99:6","Psalm 105:26","Psalm 133:2","Micah 6:4"]},

 {id:"elisheba", name:"Elisheba", short:"Elisheba", cat:"priest", w:6,
  dates:"c. 15th c. BC (traditional)",
  desc:`Aaron's wife, "daughter of Amminadab and sister of Nahshon" of the line of Judah, who bore him Nadab and Abihu, Eleazar and Ithamar — the first priestly family.`,
  refs:["Exodus 6:23"]},

 {id:"nadab", name:"Nadab son of Aaron", short:"Nadab", cat:"priest", w:6,
  clash:"Nadab", clashtag:"Aaron's firstborn, consumed by fire for offering unauthorized fire.",
  dates:"c. 15th c. BC (traditional)",
  desc:`Aaron's firstborn. With his father, his brother Abihu and seventy elders he goes up Sinai and they "saw the God of Israel … and they ate and drank." Consecrated as a priest, he and Abihu "took their censers … and they offered unauthorized fire before the LORD, contrary to his command. So fire came out from the presence of the LORD and consumed them." Their cousins Mishael and Elzaphan carry them out of the camp. "They had no sons."`,
  notconfused:`Nadab son of Jeroboam, a later king of Israel (1 Kings 15).`,
  refs:["Exodus 6:23","Exodus 24:1","Exodus 24:9–11","Leviticus 10:1–5","Numbers 3:2–4"]},

 {id:"abihu", name:"Abihu", short:"Abihu", cat:"priest", w:6,
  dates:"c. 15th c. BC (traditional)",
  desc:`Aaron's second son, who went up Sinai with Nadab and the seventy elders and saw the God of Israel. Consecrated as a priest, he died with Nadab when fire from the LORD consumed them for offering unauthorized fire; they left no sons.`,
  refs:["Exodus 6:23","Exodus 24:1","Exodus 24:9–11","Leviticus 10:1–5","Numbers 3:2–4"]},

 {id:"eleazar", name:"Eleazar son of Aaron", short:"Eleazar", cat:"priest", w:9,
  clash:"Eleazar", clashtag:"Aaron's son, who succeeded him as priest and helped Joshua divide the land.",
  dates:"c. 15th c. BC (traditional)",
  desc:`Aaron's third son, who with Ithamar serves as priest after Nadab and Abihu die. Numbers calls him "the chief leader of the Levites"; he hammers the rebels' censers into a covering for the altar and oversees the red heifer. On Mount Hor Moses puts Aaron's garments on him and he succeeds his father as priest. Joshua is commissioned standing before him, and he will "obtain decisions for him by inquiring of the Urim." In Joshua he and Joshua allot the land by lot at Shiloh, hear the claim of Zelophehad's daughters and the Levites' request for towns. He dies and is buried at Gibeah, which had been allotted to his son Phinehas.`,
  refs:["Exodus 6:23–25","Leviticus 10:6–20","Numbers 3:32","Numbers 20:25–28","Numbers 27:18–23","Numbers 34:17","Joshua 14:1","Joshua 17:4","Joshua 19:51","Joshua 21:1","Joshua 24:33"]},

 {id:"ithamar", name:"Ithamar", short:"Ithamar", cat:"priest", w:6,
  dates:"c. 15th c. BC (traditional)",
  desc:`Aaron's youngest son, consecrated as a priest, who serves with Eleazar after Nadab and Abihu die. The tabernacle's materials "were recorded at Moses' command by the Levites under the direction of Ithamar son of Aaron," and in Numbers the Gershonite and Merarite clans work "under the direction of Ithamar son of Aaron, the priest."`,
  refs:["Exodus 6:23","Exodus 38:21","Leviticus 10:6–20","Numbers 3:4","Numbers 4:28","Numbers 4:33","Numbers 7:8"]},

 {id:"phinehas", name:"Phinehas son of Eleazar", short:"Phinehas", cat:"priest", w:8,
  clash:"Phinehas", clashtag:"Eleazar's son, Aaron's grandson, given 'a covenant of a lasting priesthood' for his zeal at Peor.",
  dates:"c. 15th – 14th c. BC (traditional)",
  desc:`Son of Eleazar and grandson of Aaron. At Peor, when Zimri brings the Midianite woman Kozbi into the camp, Phinehas kills them both with a spear and the plague stops; the LORD gives him "my covenant of peace" — "a covenant of a lasting priesthood." He goes with the army against Midian. In Joshua he leads the delegation to Reuben, Gad and half Manasseh over their altar by the Jordan, and on hearing their answer declares, "Today we know that the LORD is with us." Gibeah in the hill country of Ephraim was allotted to him. In the war against Benjamin he is still "ministering before" the ark at Bethel. 1 Chronicles 6 runs the line of high priests through him down to Zadok, and recalls that he "was the official in charge of the gatekeepers, and the LORD was with him." Psalm 106: "Phinehas stood up and intervened, and the plague was checked. This was credited to him as righteousness for endless generations to come."`,
  notconfused:`Phinehas son of Eli, the priest at Shiloh, centuries later (1 Samuel 1–4).`,
  refs:["Exodus 6:25","Numbers 25:7–13","Numbers 31:6","Joshua 22:10–34","Joshua 24:33","Judges 20:27–28","1 Chronicles 6:4–8","1 Chronicles 9:20","Psalm 106:30–31"]},

 // ---------------- GENEALOGIES (Exodus 6) ----------------
 {id:"gershon", name:"Gershon son of Levi", short:"Gershon", cat:"line", w:4,
  dates:"c. 17th c. BC (traditional)",
  desc:`Levi's first-listed son; his sons, "by clans, were Libni and Shimei."`,
  notconfused:`Gershom son of Moses (Exodus 2:22).`,
  refs:["Genesis 46:11","Exodus 6:16–17"]},

 {id:"kohath", name:"Kohath", short:"Kohath", cat:"line", w:5,
  dates:"c. 17th c. BC (traditional) · lived 133 years (Exodus 6:18)",
  desc:`A son of Levi and grandfather of Moses and Aaron. His sons were Amram, Izhar, Hebron and Uzziel.`,
  refs:["Genesis 46:11","Exodus 6:16–18"]},

 {id:"merari", name:"Merari", short:"Merari", cat:"line", w:4,
  dates:"c. 17th c. BC (traditional)",
  desc:`A son of Levi; his sons were Mahli and Mushi.`,
  refs:["Genesis 46:11","Exodus 6:16","Exodus 6:19"]},

 {id:"izhar", name:"Izhar", short:"Izhar", cat:"line", w:4,
  dates:"c. 16th c. BC (traditional)",
  desc:`A son of Kohath; his sons were Korah, Nepheg and Zikri.`,
  refs:["Exodus 6:18","Exodus 6:21"]},

 {id:"uzziel", name:"Uzziel son of Kohath", short:"Uzziel", cat:"line", w:4,
  dates:"c. 16th c. BC (traditional)",
  desc:`A son of Kohath; his sons were Mishael, Elzaphan and Sithri.`,
  refs:["Exodus 6:18","Exodus 6:22"]},

 {id:"amminadab", name:"Amminadab", short:"Amminadab", cat:"line", w:4,
  dates:"c. 16th–15th c. BC (traditional)",
  desc:`Father of Aaron's wife Elisheba and of Nahshon. Ruth 4 places him in the line of Perez: "Ram the father of Amminadab, Amminadab the father of Nahshon."`,
  refs:["Exodus 6:23","Ruth 4:19–20"]},

 {id:"putiel", name:"Putiel", short:"Putiel", cat:"line", w:4,
  dates:"c. 15th c. BC (traditional)",
  desc:`Father of the wife of Eleazar son of Aaron, and so grandfather of Phinehas. Nothing else is recorded of him.`,
  refs:["Exodus 6:25"]},

 // ================= LEVITICUS · NUMBERS · DEUTERONOMY =================
 // Sourced chapter-by-chapter from the NIV on bible.com.
 // ----- Leviticus · Numbers · Deuteronomy (wilderness figures) -----
 {id:"dathan", name:"Dathan", short:"Dathan", cat:"exod", w:6,
  dates:"c. 15th c. BC (traditional)",
  desc:`A Reubenite, son of Eliab, who with his brother Abiram joins Korah's revolt. Summoned by Moses he refuses: "We will not come! … you have brought us up out of a land flowing with milk and honey to kill us in the wilderness." The earth opens and swallows them with their households; Deuteronomy 11:6 recalls it. Psalm 106: "The earth opened up and swallowed Dathan; it buried the company of Abiram."`,
  refs:["Numbers 16","Numbers 26:8–10","Deuteronomy 11:6","Psalm 106:17"]},

 {id:"abiram", name:"Abiram", short:"Abiram", cat:"exod", w:6,
  dates:"c. 15th c. BC (traditional)",
  desc:`Dathan's brother, a son of Eliab the Reubenite and one of "the community officials who rebelled against Moses and Aaron." He refuses Moses' summons and is swallowed by the earth with his household.`,
  refs:["Numbers 16","Numbers 26:8–10","Deuteronomy 11:6","Psalm 106:17"]},

 {id:"on_p", name:"On son of Peleth", short:"On", cat:"exod", w:4,
  dates:"c. 15th c. BC (traditional)",
  desc:`A Reubenite named with Korah, Dathan and Abiram among those who "became insolent and rose up against Moses." Nothing more is said of him.`,
  refs:["Numbers 16:1"]},

 {id:"eldad", name:"Eldad", short:"Eldad", cat:"exod", w:4,
  dates:"c. 15th c. BC (traditional)",
  desc:`One of the seventy elders, who stayed in the camp instead of going to the tent — yet "the Spirit also rested on them, and they prophesied in the camp." When Joshua urges Moses to stop him and Medad, Moses replies, "I wish that all the LORD's people were prophets."`,
  notconfused:`Elidad son of Kislon, the Benjamite leader named to help assign the land (Numbers 34:21).`,
  refs:["Numbers 11:24–29"]},

 {id:"medad", name:"Medad", short:"Medad", cat:"exod", w:4,
  dates:"c. 15th c. BC (traditional)",
  desc:`With Eldad, one of the elders listed for the tent who remained in the camp and prophesied there when the Spirit rested on them.`,
  refs:["Numbers 11:26–29"]},

 {id:"cushite_wife", name:"Moses' Cushite wife", short:"Cushite wife", cat:"exod", w:5,
  dates:"c. 15th c. BC (traditional; unnamed)",
  desc:`"Miriam and Aaron began to talk against Moses because of his Cushite wife, for he had married a Cushite." Numbers does not name her, and Scripture does not say whether she is Zipporah the Midianite or another wife.`,
  refs:["Numbers 12:1"]},

 {id:"hobab", name:"Hobab", short:"Hobab", cat:"exod", w:5,
  dates:"c. 15th c. BC (traditional)",
  desc:`"Hobab son of Reuel the Midianite, Moses' father-in-law" — the NIV wording leaves open whether "father-in-law" refers to Hobab or to Reuel. Moses urges him to come with Israel: "You know where we should camp in the wilderness, and you can be our eyes." He first answers, "No, I will not go"; Numbers does not record his final decision. Judges 4:11 later speaks of "the descendants of Hobab, Moses' brother-in-law," among the Kenites.`,
  refs:["Numbers 10:29–32","Judges 1:16","Judges 4:11"]},

 {id:"shelomith", name:"Shelomith", short:"Shelomith", cat:"exod", w:4,
  dates:"c. 15th c. BC (traditional)",
  desc:`"The daughter of Dibri the Danite," an Israelite woman whose son by an Egyptian father blasphemed the Name during a fight in the camp.`,
  refs:["Leviticus 24:10–11"]},

 {id:"blasphemer", name:"Son of Shelomith (the blasphemer)", short:"The blasphemer", cat:"exod", w:4,
  dates:"c. 15th c. BC (traditional; unnamed)",
  desc:`"The son of an Israelite mother and an Egyptian father," who in a fight in the camp "blasphemed the Name with a curse." Held in custody until the LORD's will was clear, he is taken outside the camp and stoned, and the law is given: "anyone who blasphemes the name of the LORD is to be put to death."`,
  refs:["Leviticus 24:10–23"]},

 {id:"zimri", name:"Zimri son of Salu", short:"Zimri", cat:"exod", w:5,
  clash:"Zimri", clashtag:"A Simeonite family leader killed by Phinehas at Peor with the Midianite woman Kozbi.",
  notconfused:`Zimri son of Zerah, of Judah, the grandfather of Achan (Joshua 7:1).`,
  dates:"c. 15th c. BC (traditional)",
  desc:`"The leader of a Simeonite family," who during the Baal of Peor apostasy brought the Midianite woman Kozbi into the camp before Moses and the assembly. Phinehas killed them both with a spear, and the plague stopped.`,
  refs:["Numbers 25:6–14"]},

 {id:"mahlah", name:"Mahlah daughter of Zelophehad", short:"Mahlah", cat:"exod", w:5,
  dates:"c. 15th c. BC (traditional)",
  desc:`The first-named of Zelophehad's five daughters, who stand before Moses, Eleazar and the assembly: "Why should our father's name disappear from his clan because he had no son?" The LORD answers, "What Zelophehad's daughters are saying is right," and a law of inheritance follows. They later marry cousins within Manasseh so the land stays in the tribe, and in Joshua they remind Eleazar and Joshua of the command and receive their inheritance "along with the brothers of their father."`,
  refs:["Numbers 26:33","Numbers 27:1–11","Numbers 36","Joshua 17:3–6"]},

 {id:"noah_z", name:"Noah daughter of Zelophehad", short:"Noah (Zelophehad's daughter)", cat:"exod", w:4,
  clash:"Noah", clashtag:"One of the five daughters of Zelophehad who won the right to inherit their father's land.",
  dates:"c. 15th c. BC (traditional)",
  desc:`One of Zelophehad's five daughters — Mahlah, Noah, Hoglah, Milkah and Tirzah — who successfully asked for their father's inheritance.`,
  notconfused:`Noah of the flood (Genesis 6–9).`,
  refs:["Numbers 26:33","Numbers 27:1–11","Numbers 36:11"]},

 {id:"hoglah", name:"Hoglah", short:"Hoglah", cat:"exod", w:4,
  dates:"c. 15th c. BC (traditional)",
  desc:`One of Zelophehad's five daughters who asked for, and received, their father's inheritance.`,
  refs:["Numbers 26:33","Numbers 27:1–11","Numbers 36:11"]},

 {id:"milkah_z", name:"Milkah daughter of Zelophehad", short:"Milkah (Zelophehad's daughter)", cat:"exod", w:4,
  clash:"Milkah", clashtag:"One of the five daughters of Zelophehad who received their father's inheritance.",
  dates:"c. 15th c. BC (traditional)",
  desc:`One of Zelophehad's five daughters who asked for, and received, their father's inheritance.`,
  notconfused:`Milkah wife of Nahor, Rebekah's grandmother (Genesis 11:29).`,
  refs:["Numbers 26:33","Numbers 27:1–11","Numbers 36:11"]},

 {id:"tirzah", name:"Tirzah", short:"Tirzah", cat:"exod", w:4,
  dates:"c. 15th c. BC (traditional)",
  desc:`One of Zelophehad's five daughters who asked for, and received, their father's inheritance.`,
  notconfused:`The town of Tirzah, later a royal city of the northern kingdom.`,
  refs:["Numbers 26:33","Numbers 27:1–11","Numbers 36:11"]},

 {id:"mishael", name:"Mishael son of Uzziel", short:"Mishael", cat:"priest", w:4,
  clash:"Mishael", clashtag:"Son of Uzziel, Aaron's cousin, who carried Nadab and Abihu's bodies out of the camp.",
  dates:"c. 15th c. BC (traditional)",
  desc:`A son of Aaron's uncle Uzziel. When Nadab and Abihu die before the LORD, Moses summons Mishael and Elzaphan: "carry your cousins outside the camp," and they carry them out "still in their tunics."`,
  refs:["Exodus 6:22","Leviticus 10:4–5"]},

 {id:"elzaphan", name:"Elzaphan son of Uzziel", short:"Elzaphan", cat:"priest", w:5,
  aliases:"Elizaphan son of Uzziel",
  clash:"Elizaphan", clashtag:"Son of Uzziel, Aaron's cousin; carried out Nadab and Abihu and led the Kohathite clans.",
  dates:"c. 15th c. BC (traditional)",
  desc:`A son of Uzziel and cousin of Aaron's sons, who with Mishael carries the bodies of Nadab and Abihu outside the camp. Numbers 3:30 names "Elizaphan son of Uzziel" as "the leader of the families of the Kohathite clans," responsible for the ark, the table, the lampstand and the altars.`,
  notconfused:`Elizaphan son of Parnak, the Zebulunite leader named to help assign the land (Numbers 34:25).`,
  refs:["Exodus 6:22","Leviticus 10:4–5","Numbers 3:30–31"]},

 {id:"eliasaph_l", name:"Eliasaph son of Lael", short:"Eliasaph (Gershonites)", cat:"priest", w:4,
  clash:"Eliasaph", clashtag:"Leader of the Levite families of the Gershonites, who cared for the tabernacle's curtains and coverings.",
  dates:"c. 15th c. BC (traditional)",
  desc:`"The leader of the families of the Gershonites," whose clans camped west of the tabernacle and cared for its tent, coverings, curtains and ropes.`,
  notconfused:`Eliasaph son of Deuel, leader of the tribe of Gad (Numbers 1:14).`,
  refs:["Numbers 3:23–26"]},

 {id:"zuriel", name:"Zuriel son of Abihail", short:"Zuriel", cat:"priest", w:4,
  dates:"c. 15th c. BC (traditional)",
  desc:`"The leader of the families of the Merarite clans," who camped north of the tabernacle and cared for its frames, crossbars, posts and bases.`,
  refs:["Numbers 3:35–37"]},

 // ---------------- GENEALOGIES (Numbers 26–27) ----------------
 {id:"eliab_p", name:"Eliab son of Pallu", short:"Eliab (Reubenite)", cat:"line", w:4,
  clash:"Eliab", clashtag:"A Reubenite, grandson of Reuben through Pallu, and father of the rebels Dathan and Abiram.",
  dates:"c. 16th–15th c. BC (traditional)",
  desc:`"The son of Pallu was Eliab, and the sons of Eliab were Nemuel, Dathan and Abiram." Deuteronomy calls him "Eliab the Reubenite."`,
  notconfused:`Eliab son of Helon, leader of the tribe of Zebulun (Numbers 1:9).`,
  refs:["Numbers 16:1","Numbers 26:8–9","Deuteronomy 11:6"]},

 {id:"makir", name:"Makir son of Manasseh", short:"Makir", cat:"line", w:5,
  clash:"Makir", clashtag:"Son of Manasseh and grandson of Joseph; ancestor of the Gileadites.",
  dates:"c. 17th c. BC (traditional)",
  desc:`Joseph's grandson, whose children "were placed at birth on Joseph's knees." "Makir was the father of Gilead." His descendants "went to Gilead, captured it and drove out the Amorites," and Moses gave Gilead to the Makirites; Jair and Nobah, also of Manasseh, took further settlements. Joshua calls him "Manasseh's firstborn" and says the Makirites received Gilead and Bashan "because the Makirites were great soldiers."`,
  refs:["Genesis 50:23","Numbers 26:29","Numbers 32:39–42","Deuteronomy 3:13–15","Joshua 17:1"]},

 {id:"gilead_p", name:"Gilead son of Makir", short:"Gilead", cat:"line", w:4,
  clash:"Gilead", clashtag:"Son of Makir and clan father of the Gileadites of Manasseh.",
  dates:"c. 17th–16th c. BC (traditional)",
  desc:`Son of Makir and head of the Gileadite clan of Manasseh, whose sons were Iezer, Helek, Asriel, Shechem, Shemida and Hepher.`,
  notconfused:`The region of Gilead east of the Jordan, which Moses gave to the Makirites (Numbers 32:40).`,
  refs:["Numbers 26:29–32","Numbers 27:1"]},

 {id:"hepher", name:"Hepher", short:"Hepher", cat:"line", w:4,
  dates:"c. 16th c. BC (traditional)",
  desc:`A son of Gilead and head of the Hepherite clan of Manasseh; father of Zelophehad.`,
  refs:["Numbers 26:32–33","Numbers 27:1"]},

 {id:"zelophehad", name:"Zelophehad", short:"Zelophehad", cat:"line", w:5,
  dates:"c. 15th c. BC (traditional)",
  desc:`"Zelophehad son of Hepher had no sons; he had only daughters." His daughters say he "died in the wilderness. He was not among Korah's followers … but he died for his own sin and left no sons" — and win the right to his inheritance.`,
  refs:["Numbers 26:33","Numbers 27:1–7","Numbers 36"]},

 // ---------------- TRIBAL LEADERS (Numbers) ----------------
 {id:"nahshon", name:"Nahshon son of Amminadab", short:"Nahshon", cat:"lead", w:6,
  dates:"c. 15th c. BC (traditional)",
  desc:`"From Judah, Nahshon son of Amminadab" — the leader of the tribe of Judah chosen to help Moses and Aaron take the census. He commanded Judah's camp on the east, which set out first, and on the first day of the altar's dedication he brought Judah's offering. Brother of Aaron's wife Elisheba (Exodus 6:23); Ruth 4:20 makes him "the father of Salmon," the father of Boaz.`,
  refs:["Numbers 1:7","Numbers 2","Numbers 7","Numbers 10:14–27","Exodus 6:23","Ruth 4:20"]},

 {id:"nethanel", name:"Nethanel son of Zuar", short:"Nethanel", cat:"lead", w:4,
  dates:"c. 15th c. BC (traditional)",
  desc:`"From Issachar, Nethanel son of Zuar" — the leader of the tribe of Issachar chosen to help Moses and Aaron take the census. His division marched in Judah's camp on the east, which set out first, and on the second day of the altar's dedication he brought Issachar's offering.`,
  refs:["Numbers 1:8","Numbers 2","Numbers 7","Numbers 10:14–27"]},

 {id:"eliab_h", name:"Eliab son of Helon", short:"Eliab", cat:"lead", w:4,
  clash:"Eliab", clashtag:"Son of Helon, leader of the tribe of Zebulun at the census and dedication of the altar.",
  dates:"c. 15th c. BC (traditional)",
  desc:`"From Zebulun, Eliab son of Helon" — the leader of the tribe of Zebulun chosen to help Moses and Aaron take the census. His division marched in Judah's camp on the east, which set out first, and on the third day of the altar's dedication he brought Zebulun's offering.`,
  notconfused:`Eliab son of Pallu, the Reubenite father of Dathan and Abiram (Numbers 26:8–9).`,
  refs:["Numbers 1:9","Numbers 2","Numbers 7","Numbers 10:14–27"]},

 {id:"elizur", name:"Elizur son of Shedeur", short:"Elizur", cat:"lead", w:4,
  dates:"c. 15th c. BC (traditional)",
  desc:`"From Reuben, Elizur son of Shedeur" — the leader of the tribe of Reuben chosen to help Moses and Aaron take the census. He commanded Reuben's camp on the south, and on the fourth day of the altar's dedication he brought Reuben's offering.`,
  refs:["Numbers 1:5","Numbers 2","Numbers 7","Numbers 10:14–27"]},

 {id:"shelumiel", name:"Shelumiel son of Zurishaddai", short:"Shelumiel", cat:"lead", w:4,
  dates:"c. 15th c. BC (traditional)",
  desc:`"From Simeon, Shelumiel son of Zurishaddai" — the leader of the tribe of Simeon chosen to help Moses and Aaron take the census. His division marched in Reuben's camp on the south, and on the fifth day of the altar's dedication he brought Simeon's offering.`,
  refs:["Numbers 1:6","Numbers 2","Numbers 7","Numbers 10:14–27"]},

 {id:"eliasaph_d", name:"Eliasaph son of Deuel", short:"Eliasaph", cat:"lead", w:4,
  clash:"Eliasaph", clashtag:"Son of Deuel, leader of the tribe of Gad at the census and dedication of the altar.",
  dates:"c. 15th c. BC (traditional)",
  desc:`"From Gad, Eliasaph son of Deuel" — the leader of the tribe of Gad chosen to help Moses and Aaron take the census. His division marched in Reuben's camp on the south, and on the sixth day of the altar's dedication he brought Gad's offering.`,
  notconfused:`Eliasaph son of Lael, leader of the Gershonite Levites (Numbers 3:24).`,
  refs:["Numbers 1:14","Numbers 2","Numbers 7","Numbers 10:14–27"]},

 {id:"elishama", name:"Elishama son of Ammihud", short:"Elishama", cat:"lead", w:4,
  clash:"Elishama", clashtag:"Son of Ammihud, leader of Ephraim in the wilderness.",
  dates:"c. 15th c. BC (traditional)",
  desc:`"From Ephraim, Elishama son of Ammihud" — the leader of the tribe of Ephraim chosen to help Moses and Aaron take the census. He commanded Ephraim's camp on the west, and on the seventh day of the altar's dedication he brought Ephraim's offering. 1 Chronicles 7:26–27 places him in Ephraim's line as Joshua's grandfather: "Ammihud his son, Elishama his son, Nun his son and Joshua his son."`,
  refs:["Numbers 1:10","Numbers 2","Numbers 7","Numbers 10:14–27","1 Chronicles 7:26–27"]},

 {id:"gamaliel", name:"Gamaliel son of Pedahzur", short:"Gamaliel", cat:"lead", w:4,
  dates:"c. 15th c. BC (traditional)",
  desc:`"From Manasseh, Gamaliel son of Pedahzur" — the leader of the tribe of Manasseh chosen to help Moses and Aaron take the census. His division marched in Ephraim's camp on the west, and on the eighth day of the altar's dedication he brought Manasseh's offering.`,
  notconfused:`Gamaliel the Pharisee and teacher of the law in Acts 5 — a New Testament figure many centuries later.`,
  refs:["Numbers 1:10","Numbers 2","Numbers 7","Numbers 10:14–27"]},

 {id:"abidan", name:"Abidan son of Gideoni", short:"Abidan", cat:"lead", w:4,
  dates:"c. 15th c. BC (traditional)",
  desc:`"From Benjamin, Abidan son of Gideoni" — the leader of the tribe of Benjamin chosen to help Moses and Aaron take the census. His division marched in Ephraim's camp on the west, and on the ninth day of the altar's dedication he brought Benjamin's offering.`,
  refs:["Numbers 1:11","Numbers 2","Numbers 7","Numbers 10:14–27"]},

 {id:"ahiezer", name:"Ahiezer son of Ammishaddai", short:"Ahiezer", cat:"lead", w:4,
  dates:"c. 15th c. BC (traditional)",
  desc:`"From Dan, Ahiezer son of Ammishaddai" — the leader of the tribe of Dan chosen to help Moses and Aaron take the census. He commanded Dan's camp on the north, the rear guard, and on the tenth day of the altar's dedication he brought Dan's offering.`,
  refs:["Numbers 1:12","Numbers 2","Numbers 7","Numbers 10:14–27"]},

 {id:"pagiel", name:"Pagiel son of Okran", short:"Pagiel", cat:"lead", w:4,
  dates:"c. 15th c. BC (traditional)",
  desc:`"From Asher, Pagiel son of Okran" — the leader of the tribe of Asher chosen to help Moses and Aaron take the census. His division marched in Dan's camp on the north, the rear guard, and on the eleventh day of the altar's dedication he brought Asher's offering.`,
  refs:["Numbers 1:13","Numbers 2","Numbers 7","Numbers 10:14–27"]},

 {id:"ahira", name:"Ahira son of Enan", short:"Ahira", cat:"lead", w:4,
  dates:"c. 15th c. BC (traditional)",
  desc:`"From Naphtali, Ahira son of Enan" — the leader of the tribe of Naphtali chosen to help Moses and Aaron take the census. His division marched in Dan's camp on the north, the rear guard, and on the twelfth day of the altar's dedication he brought Naphtali's offering.`,
  refs:["Numbers 1:15","Numbers 2","Numbers 7","Numbers 10:14–27"]},

 {id:"shammua", name:"Shammua son of Zakkur", short:"Shammua", cat:"lead", w:4,
  dates:"c. 15th c. BC (traditional)",
  desc:`"From the tribe of Reuben, Shammua son of Zakkur" — one of the twelve leaders Moses sent from the Desert of Paran to explore Canaan. With all the spies except Joshua and Caleb he spread "a bad report about the land," and those men "were struck down and died of a plague before the LORD."`,
  refs:["Numbers 13:4–16","Numbers 13:31–33","Numbers 14:36–38"]},

 {id:"shaphat", name:"Shaphat son of Hori", short:"Shaphat", cat:"lead", w:4,
  dates:"c. 15th c. BC (traditional)",
  desc:`"From the tribe of Simeon, Shaphat son of Hori" — one of the twelve leaders Moses sent from the Desert of Paran to explore Canaan. With all the spies except Joshua and Caleb he spread "a bad report about the land," and those men "were struck down and died of a plague before the LORD."`,
  refs:["Numbers 13:4–16","Numbers 13:31–33","Numbers 14:36–38"]},

 {id:"igal", name:"Igal son of Joseph", short:"Igal", cat:"lead", w:4,
  dates:"c. 15th c. BC (traditional)",
  desc:`"From the tribe of Issachar, Igal son of Joseph" — one of the twelve leaders Moses sent from the Desert of Paran to explore Canaan. With all the spies except Joshua and Caleb he spread "a bad report about the land," and those men "were struck down and died of a plague before the LORD."`,
  notconfused:`Joseph son of Jacob — Igal's father Joseph, of Issachar, is a different man.`,
  refs:["Numbers 13:4–16","Numbers 13:31–33","Numbers 14:36–38"]},

 {id:"palti", name:"Palti son of Raphu", short:"Palti", cat:"lead", w:4,
  dates:"c. 15th c. BC (traditional)",
  desc:`"From the tribe of Benjamin, Palti son of Raphu" — one of the twelve leaders Moses sent from the Desert of Paran to explore Canaan. With all the spies except Joshua and Caleb he spread "a bad report about the land," and those men "were struck down and died of a plague before the LORD."`,
  notconfused:`Paltiel son of Azzan, the Issacharite leader named to assign the land (Numbers 34:26).`,
  refs:["Numbers 13:4–16","Numbers 13:31–33","Numbers 14:36–38"]},

 {id:"gaddiel", name:"Gaddiel son of Sodi", short:"Gaddiel", cat:"lead", w:4,
  dates:"c. 15th c. BC (traditional)",
  desc:`"From the tribe of Zebulun, Gaddiel son of Sodi" — one of the twelve leaders Moses sent from the Desert of Paran to explore Canaan. With all the spies except Joshua and Caleb he spread "a bad report about the land," and those men "were struck down and died of a plague before the LORD."`,
  refs:["Numbers 13:4–16","Numbers 13:31–33","Numbers 14:36–38"]},

 {id:"gaddi", name:"Gaddi son of Susi", short:"Gaddi", cat:"lead", w:4,
  dates:"c. 15th c. BC (traditional)",
  desc:`"From the tribe of Manasseh, Gaddi son of Susi" — one of the twelve leaders Moses sent from the Desert of Paran to explore Canaan. With all the spies except Joshua and Caleb he spread "a bad report about the land," and those men "were struck down and died of a plague before the LORD."`,
  refs:["Numbers 13:4–16","Numbers 13:31–33","Numbers 14:36–38"]},

 {id:"ammiel", name:"Ammiel son of Gemalli", short:"Ammiel", cat:"lead", w:4,
  dates:"c. 15th c. BC (traditional)",
  desc:`"From the tribe of Dan, Ammiel son of Gemalli" — one of the twelve leaders Moses sent from the Desert of Paran to explore Canaan. With all the spies except Joshua and Caleb he spread "a bad report about the land," and those men "were struck down and died of a plague before the LORD."`,
  refs:["Numbers 13:4–16","Numbers 13:31–33","Numbers 14:36–38"]},

 {id:"sethur", name:"Sethur son of Michael", short:"Sethur", cat:"lead", w:4,
  dates:"c. 15th c. BC (traditional)",
  desc:`"From the tribe of Asher, Sethur son of Michael" — one of the twelve leaders Moses sent from the Desert of Paran to explore Canaan. With all the spies except Joshua and Caleb he spread "a bad report about the land," and those men "were struck down and died of a plague before the LORD."`,
  refs:["Numbers 13:4–16","Numbers 13:31–33","Numbers 14:36–38"]},

 {id:"nahbi", name:"Nahbi son of Vophsi", short:"Nahbi", cat:"lead", w:4,
  dates:"c. 15th c. BC (traditional)",
  desc:`"From the tribe of Naphtali, Nahbi son of Vophsi" — one of the twelve leaders Moses sent from the Desert of Paran to explore Canaan. With all the spies except Joshua and Caleb he spread "a bad report about the land," and those men "were struck down and died of a plague before the LORD."`,
  refs:["Numbers 13:4–16","Numbers 13:31–33","Numbers 14:36–38"]},

 {id:"geuel", name:"Geuel son of Maki", short:"Geuel", cat:"lead", w:4,
  dates:"c. 15th c. BC (traditional)",
  desc:`"From the tribe of Gad, Geuel son of Maki" — one of the twelve leaders Moses sent from the Desert of Paran to explore Canaan. With all the spies except Joshua and Caleb he spread "a bad report about the land," and those men "were struck down and died of a plague before the LORD."`,
  refs:["Numbers 13:4–16","Numbers 13:31–33","Numbers 14:36–38"]},

 {id:"shemuel", name:"Shemuel son of Ammihud", short:"Shemuel", cat:"lead", w:4,
  dates:"c. 15th c. BC (traditional)",
  desc:`"Shemuel son of Ammihud," the leader from the tribe of Simeon named to help Eleazar the priest and Joshua son of Nun assign the land of Canaan as an inheritance.`,
  refs:["Numbers 34:16–29"]},

 {id:"elidad", name:"Elidad son of Kislon", short:"Elidad", cat:"lead", w:4,
  dates:"c. 15th c. BC (traditional)",
  desc:`"Elidad son of Kislon," the leader from the tribe of Benjamin named to help Eleazar the priest and Joshua son of Nun assign the land of Canaan as an inheritance.`,
  notconfused:`Eldad, the elder who prophesied in the camp (Numbers 11:26).`,
  refs:["Numbers 34:16–29"]},

 {id:"bukki", name:"Bukki son of Jogli", short:"Bukki", cat:"lead", w:4,
  dates:"c. 15th c. BC (traditional)",
  desc:`"Bukki son of Jogli," the leader from the tribe of Dan named to help Eleazar the priest and Joshua son of Nun assign the land of Canaan as an inheritance.`,
  refs:["Numbers 34:16–29"]},

 {id:"hanniel", name:"Hanniel son of Ephod", short:"Hanniel", cat:"lead", w:4,
  dates:"c. 15th c. BC (traditional)",
  desc:`"Hanniel son of Ephod," the leader from the tribe of Manasseh named to help Eleazar the priest and Joshua son of Nun assign the land of Canaan as an inheritance.`,
  refs:["Numbers 34:16–29"]},

 {id:"kemuel", name:"Kemuel son of Shiphtan", short:"Kemuel", cat:"lead", w:4,
  dates:"c. 15th c. BC (traditional)",
  desc:`"Kemuel son of Shiphtan," the leader from the tribe of Ephraim named to help Eleazar the priest and Joshua son of Nun assign the land of Canaan as an inheritance.`,
  notconfused:`Kemuel son of Nahor, Abraham's nephew (Genesis 22:21).`,
  refs:["Numbers 34:16–29"]},

 {id:"elizaphan_p", name:"Elizaphan son of Parnak", short:"Elizaphan", cat:"lead", w:4,
  clash:"Elizaphan", clashtag:"Son of Parnak, the Zebulunite leader named to help assign the land.",
  dates:"c. 15th c. BC (traditional)",
  desc:`"Elizaphan son of Parnak," the leader from the tribe of Zebulun named to help Eleazar the priest and Joshua son of Nun assign the land of Canaan as an inheritance.`,
  notconfused:`Elizaphan (Elzaphan) son of Uzziel, leader of the Kohathite Levites (Numbers 3:30).`,
  refs:["Numbers 34:16–29"]},

 {id:"paltiel", name:"Paltiel son of Azzan", short:"Paltiel", cat:"lead", w:4,
  clash:"Paltiel", clashtag:"Son of Azzan, the Issacharite leader named to help assign the land.",
  dates:"c. 15th c. BC (traditional)",
  desc:`"Paltiel son of Azzan," the leader from the tribe of Issachar named to help Eleazar the priest and Joshua son of Nun assign the land of Canaan as an inheritance.`,
  notconfused:`Palti son of Raphu, the Benjamite spy (Numbers 13:9).`,
  refs:["Numbers 34:16–29"]},

 {id:"ahihud", name:"Ahihud son of Shelomi", short:"Ahihud", cat:"lead", w:4,
  dates:"c. 15th c. BC (traditional)",
  desc:`"Ahihud son of Shelomi," the leader from the tribe of Asher named to help Eleazar the priest and Joshua son of Nun assign the land of Canaan as an inheritance.`,
  refs:["Numbers 34:16–29"]},

 {id:"pedahel", name:"Pedahel son of Ammihud", short:"Pedahel", cat:"lead", w:4,
  dates:"c. 15th c. BC (traditional)",
  desc:`"Pedahel son of Ammihud," the leader from the tribe of Naphtali named to help Eleazar the priest and Joshua son of Nun assign the land of Canaan as an inheritance.`,
  refs:["Numbers 34:16–29"]},

 // ---------------- CONQUEST & JUDGES ----------------
 {id:"joshua_ot", name:"Joshua son of Nun", short:"Joshua", cat:"judg", w:14, halo:1,
  aliases:"Hoshea · Moses' aide · \"the servant of the LORD\"",
  clash:"Joshua", clashtag:"Moses' successor who led Israel across the Jordan and conquered Canaan.",
  dates:"c. 1485 – 1375 BC* (estimate) · died at 110 (Joshua 24:29)",
  desc:`An Ephraimite, "Hoshea son of Nun," renamed by Moses; he defeats the Amalekites, serves as Moses' aide on Sinai and at the tent of meeting, and with Caleb is one of only two spies who trust the LORD. Commissioned by Moses, he hears: "Be strong and courageous… I will never leave you nor forsake you." He sends spies to Rahab in Jericho, leads Israel across the Jordan on dry ground and sets up twelve stones at Gilgal, and meets "the commander of the army of the LORD." Jericho's walls collapse; after Achan's sin is exposed Ai falls; he renews the covenant at Mount Ebal, is tricked into a treaty with the Gibeonites, and at Gibeon prays "Sun, stand still." In southern and northern campaigns thirty-one kings are defeated. With Eleazar he allots the land by lot at Shiloh and receives Timnath Serah. In his farewell at Shechem he charges Israel: "choose for yourselves this day whom you will serve … But as for me and my household, we will serve the LORD." He dies at 110 and is buried at Timnath Serah (called Timnath Heres in Judges 2:9). 1 Chronicles traces his descent from Ephraim through Elishama son of Ammihud and Nun.`,
  notconfused:`Jeshua (Joshua) the high priest, who rebuilt the temple a thousand years later after the exile.`,
  refs:["Exodus 17:8–14","Numbers 13–14","Numbers 27:18–23","Deuteronomy 34:9","Joshua 1","Joshua 3–4","Joshua 6","Joshua 10","Joshua 24","Judges 2:6–9","1 Chronicles 7:20–27"]},

 {id:"caleb", name:"Caleb son of Jephunneh", short:"Caleb", cat:"judg", w:10,
  clash:"Caleb", clashtag:"Son of Jephunneh, the faithful spy who took Hebron.",
  aliases:"the Kenizzite",
  dates:"c. 1485 – after 1400 BC* (early-date estimate) · 40 when sent from Kadesh Barnea, 85 when he claimed Hebron (Joshua 14:7, 10)",
  desc:`"Caleb son of Jephunneh the Kenizzite," the spy from the tribe of Judah, who told the frightened people, "We should go up and take possession of the land, for we can certainly do it." The LORD says, "my servant Caleb has a different spirit and follows me wholeheartedly," and he and Joshua alone of the counted generation enter the land. At 85 — "I am still as strong today as the day Moses sent me out" — he asks Joshua for the hill country promised him, receives Hebron, drives out the three sons of Anak, and offers his daughter Aksah to whoever captures Kiriath Sepher; Othniel takes it.`,
  notconfused:`Caleb son of Hezron in Judah's genealogy (1 Chronicles 2:18–50), whose daughter was also called Aksah; 1 Chronicles 4:15 lists "the sons of Caleb son of Jephunneh" separately.`,
  refs:["Numbers 13:6","Numbers 13:30","Numbers 14:24","Numbers 34:19","Deuteronomy 1:36","Joshua 14:6–15","Joshua 15:13–19","Joshua 21:12","Judges 1:12–20","1 Chronicles 4:15","1 Chronicles 6:56"]},

 // ================= JOSHUA =================
 // Sourced chapter-by-chapter from the NIV on bible.com (Joshua 1–24).
 {id:"achan", name:"Achan son of Karmi", short:"Achan", cat:"judg", w:7,
  aliases:"Achar (1 Chronicles 2:7)",
  dates:"c. 1400 BC (early-date tradition; disputed)",
  desc:`"Achan son of Karmi, the son of Zimri, the son of Zerah, of the tribe of Judah," who takes some of the devoted things from Jericho. Israel is routed at Ai until the lot falls on him; he confesses, "I coveted them and took them" — "a beautiful robe from Babylonia, two hundred shekels of silver and a bar of gold weighing fifty shekels," hidden in his tent. All Israel stones him in the Valley of Achor and raises a pile of rocks over him. Joshua 22:20 recalls that "He was not the only one who died for his sin." 1 Chronicles 2:7 calls him Achar, "who brought trouble on Israel by violating the ban on taking devoted things."`,
  refs:["Joshua 7","Joshua 22:20","1 Chronicles 2:7"]},

 {id:"othniel", name:"Othniel son of Kenaz", short:"Othniel", cat:"judg", w:8,
  dates:"c. 1374 – 1334 BC* (estimate; disputed) · the land had peace 40 years (Judges 3:11)",
  desc:`"Othniel son of Kenaz, Caleb's younger brother" (Judges 1:13; Joshua 15:17 says "Caleb's brother"), who captures Kiriath Sepher (Debir) and so wins Caleb's daughter Aksah. He is the first deliverer in Judges: after eight years under Cushan-Rishathaim king of Aram Naharaim, "the Spirit of the LORD came on him, so that he became Israel's judge," and "the land had peace for forty years."`,
  refs:["Joshua 15:15–19","Judges 1:12–15","Judges 3:7–11"]},

 {id:"aksah", name:"Aksah daughter of Caleb", short:"Aksah", cat:"judg", w:5,
  dates:"c. 14th c. BC (traditional; disputed)",
  desc:`Caleb's daughter, promised "to the man who attacks and captures Kiriath Sepher" and given to Othniel. She urges him to ask her father for a field, then asks Caleb herself: "Since you have given me land in the Negev, give me also springs of water." He gives her the upper and lower springs.`,
  refs:["Joshua 15:16–19"]},

 // genealogy
 {id:"zimri_j", name:"Zimri son of Zerah", short:"Zimri (Achan's grandfather)", cat:"line", w:4,
  clash:"Zimri", clashtag:"Of the Zerahite clan of Judah; grandfather of Achan.",
  dates:"c. 15th c. BC (traditional)",
  desc:`Named in Achan's line — "Achan son of Karmi, the son of Zimri, the son of Zerah." When lots are cast, "the clan of the Zerahites … and Zimri was chosen."`,
  notconfused:`Zimri son of Salu, the Simeonite killed by Phinehas at Peor (Numbers 25:14).`,
  refs:["Joshua 7:1","Joshua 7:17–18"]},

 {id:"karmi", name:"Karmi son of Zimri", short:"Karmi", cat:"line", w:4,
  dates:"c. 15th c. BC (traditional)",
  desc:`Achan's father, of the Zerahite clan of Judah.`,
  notconfused:`Karmi son of Reuben (Genesis 46:9).`,
  refs:["Joshua 7:1","Joshua 7:18"]},

 {id:"kenaz_o", name:"Kenaz, father of Othniel", short:"Kenaz", cat:"line", w:4,
  dates:"c. 15th c. BC (traditional)",
  desc:`Father of Othniel. Joshua 15:17 reads "Othniel son of Kenaz, Caleb's brother"; Caleb himself is called "the Kenizzite" (14:6).`,
  notconfused:`Kenaz grandson of Esau, an Edomite chief (Genesis 36:11).`,
  refs:["Joshua 15:17"]},

 {id:"arba", name:"Arba", short:"Arba", cat:"line", w:4,
  dates:"before the conquest (undated)",
  desc:`"The greatest man among the Anakites" and "the forefather of Anak," after whom Hebron was formerly called Kiriath Arba.`,
  refs:["Joshua 14:15","Joshua 15:13","Joshua 21:11"]},

 {id:"rahab", name:"Rahab", short:"Rahab", cat:"judg", w:9,
  aliases:"Rahab the prostitute",
  dates:"c. 1406 BC (early-date tradition; disputed)",
  desc:`"A prostitute named Rahab" in Jericho, whose house was part of the city wall. She hides Joshua's two spies under stalks of flax and sends the king's men the wrong way, confessing, "the LORD your God is God in heaven above and on the earth below." She lets the spies down by a rope and ties a scarlet cord in her window as the sign. When Jericho falls, "Joshua spared Rahab the prostitute, with her family and all who belonged to her … and she lives among the Israelites to this day." Matthew's genealogy names her as the mother of Boaz.`,
  refs:["Joshua 2","Joshua 6:17–25","Matthew 1:5"]},

 // ================= JUDGES =================
 // Sourced chapter-by-chapter from the NIV on bible.com (Judges 1–21).
 {id:"ehud", name:"Ehud son of Gera", short:"Ehud", cat:"judg", w:8,
  dates:"c. 1316 BC* (estimate; disputed) · the land had peace 80 years (Judges 3:30)",
  desc:`"A left-handed man, the son of Gera the Benjamite," raised up as a deliverer after eighteen years under Eglon king of Moab. Bringing Israel's tribute, he tells the king, "I have a message from God for you," and drives his double-edged sword into Eglon's belly, then escapes and leads Israel to seize the fords of the Jordan. "The land had peace for eighty years."`,
  refs:["Judges 3:12–30","Judges 4:1"]},

 {id:"shamgar", name:"Shamgar son of Anath", short:"Shamgar", cat:"judg", w:5,
  dates:"c. 13th–12th c. BC (traditional; disputed)",
  desc:`"After Ehud came Shamgar son of Anath, who struck down six hundred Philistines with an oxgoad. He too saved Israel." Deborah's song recalls "the days of Shamgar," when "the highways were abandoned."`,
  refs:["Judges 3:31","Judges 5:6"]},

 {id:"barak", name:"Barak son of Abinoam", short:"Barak", cat:"judg", w:8,
  dates:"c. 12th c. BC (traditional; disputed)",
  desc:`Of Kedesh in Naphtali, summoned by Deborah to lead ten thousand men of Naphtali and Zebulun to Mount Tabor. He answers, "If you go with me, I will go," and she warns him that "the honor will not be yours, for the LORD will deliver Sisera into the hands of a woman." He routs Sisera's chariots and finds Sisera dead in Jael's tent; he and Deborah sing the victory song.`,
  refs:["Judges 4","Judges 5:1","Judges 5:12"]},

 {id:"jael", name:"Jael wife of Heber", short:"Jael", cat:"judg", w:8,
  dates:"c. 12th c. BC (traditional; disputed)",
  desc:`"The wife of Heber the Kenite," to whose tent Sisera flees because of an alliance between Jabin and Heber's family. She gives him milk, covers him, and while he sleeps drives a tent peg through his temple. Deborah's song: "Most blessed of women be Jael."`,
  refs:["Judges 4:17–22","Judges 5:6","Judges 5:24–27"]},

 {id:"heber_k", name:"Heber the Kenite", short:"Heber", cat:"judg", w:5,
  dates:"c. 12th c. BC (traditional; disputed)",
  desc:`A Kenite who "had left the other Kenites, the descendants of Hobab, Moses' brother-in-law," and camped near Kedesh; his family had an alliance with Jabin king of Hazor. Husband of Jael.`,
  refs:["Judges 4:11","Judges 4:17","Judges 5:24"]},

 {id:"lappidoth", name:"Lappidoth", short:"Lappidoth", cat:"line", w:4,
  dates:"c. 12th c. BC (traditional; disputed)",
  desc:`Deborah's husband — "Deborah, a prophet, the wife of Lappidoth." Nothing more is recorded.`,
  refs:["Judges 4:4"]},

 {id:"joash_ab", name:"Joash the Abiezrite", short:"Joash (Gideon's father)", cat:"judg", w:5,
  clash:"Joash", clashtag:"Gideon's father, of the Abiezrite clan of Manasseh, who defended his son against the worshipers of Baal.",
  dates:"c. 12th c. BC (traditional; disputed)",
  desc:`Gideon's father, whose oak at Ophrah shelters the angel of the LORD and whose altar to Baal Gideon tears down. When the town demands his son's death he answers, "If Baal really is a god, he can defend himself." Gideon is buried in his tomb.`,
  notconfused:`Joash king of Judah and Jehoash (Joash) king of Israel, centuries later.`,
  refs:["Judges 6:11","Judges 6:29–32","Judges 8:32"]},

 {id:"purah", name:"Purah", short:"Purah", cat:"judg", w:4,
  dates:"c. 12th c. BC (traditional; disputed)",
  desc:`Gideon's servant, who goes down with him at night to the Midianite camp, where they overhear the dream of the barley loaf.`,
  refs:["Judges 7:10–11"]},

 {id:"jether_g", name:"Jether son of Gideon", short:"Jether", cat:"judg", w:4,
  dates:"c. 12th c. BC (traditional; disputed)",
  desc:`Gideon's oldest son, told to kill Zebah and Zalmunna, "but Jether did not draw his sword, because he was only a boy and was afraid."`,
  refs:["Judges 8:20"]},

 {id:"abimelek_g", name:"Abimelek son of Gideon", short:"Abimelek (Gideon's son)", cat:"judg", w:8,
  clash:"Abimelek", clashtag:"Gideon's son by his concubine at Shechem, who murdered his seventy brothers and was crowned king.",
  dates:"c. 12th c. BC (traditional; disputed)",
  desc:`Gideon's son by "his concubine, who lived in Shechem." Backed by his mother's clan, he murders his seventy brothers "on one stone" — only Jotham escapes — and is crowned king at Shechem. After three years God stirs up animosity between him and Shechem; he destroys the city and burns the tower of El-Berith, but at Thebez "a woman dropped an upper millstone on his head," and he has his armor-bearer kill him. "Thus God repaid the wickedness that Abimelek had done."`,
  notconfused:`Abimelek king of Gerar in the days of Abraham and Isaac (Genesis 20; 26).`,
  refs:["Judges 8:31","Judges 9"]},

 {id:"jotham_g", name:"Jotham son of Gideon", short:"Jotham (Gideon's son)", cat:"judg", w:6,
  clash:"Jotham", clashtag:"Gideon's youngest son, who escaped Abimelek and told the parable of the trees.",
  dates:"c. 12th c. BC (traditional; disputed)",
  desc:`Gideon's youngest son, the only one to escape Abimelek's massacre. From the top of Mount Gerizim he tells the parable of the trees who make the thornbush their king, then flees to Beer. "The curse of Jotham son of Jerub-Baal came on" the people of Shechem.`,
  notconfused:`Jotham king of Judah, son of Uzziah, centuries later (2 Kings 15).`,
  refs:["Judges 9:5–21","Judges 9:57"]},

 {id:"gaal", name:"Gaal son of Ebed", short:"Gaal", cat:"judg", w:4,
  dates:"c. 12th c. BC (traditional; disputed)",
  desc:`A newcomer to Shechem who stirs up its citizens against Abimelek — "Who is Abimelek …?" — and is defeated and driven out of the city by Zebul.`,
  refs:["Judges 9:26–41"]},

 {id:"zebul", name:"Zebul", short:"Zebul", cat:"judg", w:4,
  dates:"c. 12th c. BC (traditional; disputed)",
  desc:`"The governor of the city" of Shechem and Abimelek's deputy, who secretly warns Abimelek about Gaal and then drives Gaal and his clan out.`,
  refs:["Judges 9:28–41"]},

 {id:"tola", name:"Tola son of Puah", short:"Tola", cat:"judg", w:5,
  dates:"c. 12th c. BC (traditional; disputed)",
  desc:`"A man of Issachar named Tola son of Puah, the son of Dodo," who rose to save Israel after Abimelek; he lived in Shamir and "led Israel twenty-three years."`,
  notconfused:`Tola son of Issachar (Genesis 46:13); and Tola's father Puah is not the midwife Puah of Exodus 1.`,
  refs:["Judges 10:1–2"]},

 {id:"jair_g", name:"Jair of Gilead", short:"Jair", cat:"judg", w:5,
  dates:"c. 12th c. BC (traditional; disputed)",
  desc:`A judge who "led Israel twenty-two years." "He had thirty sons, who rode thirty donkeys. They controlled thirty towns in Gilead, which to this day are called Havvoth Jair."`,
  notconfused:`Jair the descendant of Manasseh in Moses' day, after whom Havvoth Jair was first named (Numbers 32:41; Deuteronomy 3:14).`,
  refs:["Judges 10:3–5"]},

 {id:"gilead_j", name:"Gilead, father of Jephthah", short:"Gilead (Jephthah's father)", cat:"line", w:4,
  clash:"Gilead", clashtag:"Jephthah's father, whose sons by his wife drove Jephthah away.",
  dates:"c. 11th c. BC (traditional; disputed)",
  desc:`"His father was Gilead; his mother was a prostitute." Gilead's sons by his wife drove Jephthah out: "You are not going to get any inheritance in our family."`,
  notconfused:`Gilead son of Makir, the clan father of the Gileadites in Moses' day (Numbers 26:29).`,
  refs:["Judges 11:1–2"]},

 {id:"jephthah_dau", name:"Jephthah's daughter", short:"Jephthah's daughter", cat:"judg", w:6,
  dates:"c. 11th c. BC (traditional; disputed)",
  desc:`Jephthah's only child, who comes out "dancing to the sound of timbrels" to meet him after his vow. She answers, "Do to me just as you promised," asks two months to weep with her friends in the hills "because I will never marry," then returns, "and he did to her as he had vowed." Each year the young women of Israel "commemorate the daughter of Jephthah." Scripture does not give her name.`,
  refs:["Judges 11:34–40"]},

 {id:"ibzan", name:"Ibzan of Bethlehem", short:"Ibzan", cat:"judg", w:4,
  dates:"c. 11th c. BC (traditional; disputed)",
  desc:`A judge who "led Israel seven years"; he had thirty sons and thirty daughters and arranged their marriages outside his clan.`,
  refs:["Judges 12:8–10"]},

 {id:"elon_z", name:"Elon the Zebulunite", short:"Elon", cat:"judg", w:4,
  dates:"c. 11th c. BC (traditional; disputed)",
  desc:`A judge who "led Israel ten years" and was buried in Aijalon in Zebulun.`,
  notconfused:`Elon son of Zebulun (Genesis 46:14) and Elon the Hittite, father-in-law of Esau (Genesis 26:34).`,
  refs:["Judges 12:11–12"]},

 {id:"abdon", name:"Abdon son of Hillel", short:"Abdon", cat:"judg", w:4,
  dates:"c. 11th c. BC (traditional; disputed)",
  desc:`A judge from Pirathon in Ephraim who "led Israel eight years"; "he had forty sons and thirty grandsons, who rode on seventy donkeys."`,
  refs:["Judges 12:13–15"]},

 {id:"manoah", name:"Manoah", short:"Manoah", cat:"judg", w:6,
  dates:"c. 11th c. BC (traditional; disputed)",
  desc:`"A certain man of Zorah, named Manoah, from the clan of the Danites," father of Samson. He prays for the man of God to return, asks his name — "It is beyond understanding" — and sees the angel of the LORD ascend in the altar's flame: "We are doomed to die! … We have seen God!" Samson is buried in his tomb.`,
  refs:["Judges 13","Judges 14:2–10","Judges 16:31"]},

 {id:"manoah_wife", name:"Manoah's wife", short:"Samson's mother", cat:"judg", w:6,
  dates:"c. 11th c. BC (traditional; disputed)",
  desc:`Childless until the angel of the LORD tells her she will bear a son who will be "a Nazirite, dedicated to God from the womb." When Manoah fears they will die, she reasons, "If the LORD had meant to kill us, he would not have accepted a burnt offering." She names her son Samson. Scripture does not give her name.`,
  refs:["Judges 13"]},

 {id:"samson_wife", name:"Samson's Timnite wife", short:"Samson's wife", cat:"judg", w:5,
  dates:"c. 11th c. BC (traditional; disputed)",
  desc:`A Philistine woman of Timnah whom Samson insists on marrying. Threatened by her people, she weeps for seven days until he tells her his riddle; she is then given to his companion, and after Samson burns their fields the Philistines "burned her and her father to death." Unnamed in Scripture.`,
  refs:["Judges 14","Judges 15:1–6"]},

 {id:"micah_e", name:"Micah of Ephraim", short:"Micah (Ephraim)", cat:"judg", w:6,
  clash:"Micah", clashtag:"An Ephraimite of the judges' era who set up a household shrine with an idol and hired a Levite priest.",
  dates:"c. 12th–11th c. BC (traditional; disputed)",
  desc:`A man from the hill country of Ephraim who returns eleven hundred shekels he took from his mother; she has an idol made from it. He sets up a shrine with an ephod and household gods and hires a young Levite: "Now I know that the LORD will be good to me." The Danites take his idol and his priest — "You took the gods I made, and my priest … What else do I have?" "In those days Israel had no king; everyone did as they saw fit."`,
  notconfused:`Micah the prophet of Moresheth, centuries later (Micah 1).`,
  refs:["Judges 17–18"]},

 {id:"jonathan_g", name:"Jonathan son of Gershom", short:"Jonathan (Gershom's son)", cat:"priest", w:5,
  clash:"Jonathan", clashtag:"A Levite, 'son of Gershom, the son of Moses,' who served as priest for the Danites' idol.",
  dates:"c. 12th–11th c. BC (traditional; disputed)",
  desc:`"Jonathan son of Gershom, the son of Moses, and his sons were priests for the tribe of Dan until the time of the captivity of the land," serving the idol taken from Micah. Judges 17–18 calls Micah's priest only "a young Levite from Bethlehem"; the text implies but does not state outright that he is this Jonathan.`,
  notconfused:`Jonathan son of Saul, David's friend (1 Samuel 18–20).`,
  refs:["Judges 17:7–13","Judges 18:30"]},

 {id:"levite_j", name:"The Levite of Ephraim", short:"The Levite (Judges 19)", cat:"judg", w:5,
  dates:"c. 12th–11th c. BC (traditional; disputed)",
  desc:`A Levite from the hill country of Ephraim whose concubine is raped and killed by men of Gibeah after he sends her out to them. He cuts her body into twelve parts and sends them through Israel, and the tribes go to war against Benjamin. Unnamed in Scripture.`,
  refs:["Judges 19","Judges 20:4–7"]},

 {id:"concubine_j", name:"The Levite's concubine", short:"The concubine (Judges 19)", cat:"judg", w:5,
  dates:"c. 12th–11th c. BC (traditional; disputed)",
  desc:`A woman from Bethlehem in Judah, concubine of a Levite. At Gibeah she is sent out to the men of the city, who "raped her and abused her throughout the night"; at dawn she falls at the door "with her hands on the threshold." Her death leads to civil war against Benjamin. Unnamed in Scripture.`,
  refs:["Judges 19:1–30","Judges 20:4–6"]},

 // ================= RUTH =================
 // Ruth 1:1 — "In the days when the judges ruled."
 {id:"elimelek", name:"Elimelek", short:"Elimelek", cat:"judg", w:5,
  dates:"c. 12th–11th c. BC (traditional; 'when the judges ruled')",
  desc:`An Ephrathite from Bethlehem in Judah who goes to Moab in a famine with his wife Naomi and sons Mahlon and Kilion, and dies there. Boaz is "from the clan of Elimelek," and later buys his property.`,
  refs:["Ruth 1:1–3","Ruth 2:1–3","Ruth 4:3","Ruth 4:9"]},

 {id:"mahlon", name:"Mahlon", short:"Mahlon", cat:"judg", w:5,
  dates:"c. 12th–11th c. BC (traditional)",
  desc:`Son of Elimelek and Naomi, who marries in Moab and dies there; Boaz acquires "Ruth the Moabite, Mahlon's widow," to maintain his name.`,
  refs:["Ruth 1:2–5","Ruth 4:9–10"]},

 {id:"kilion", name:"Kilion", short:"Kilion", cat:"judg", w:4,
  dates:"c. 12th–11th c. BC (traditional)",
  desc:`Son of Elimelek and Naomi, who marries in Moab and dies there. Ruth 1:4 names the brothers' Moabite wives as Orpah and Ruth, and Ruth 4:10 makes Ruth "Mahlon's widow"; the text does not pair Orpah with Kilion by name.`,
  refs:["Ruth 1:2–5","Ruth 4:9"]},

 {id:"orpah", name:"Orpah", short:"Orpah", cat:"judg", w:5,
  dates:"c. 12th–11th c. BC (traditional)",
  desc:`A Moabite daughter-in-law of Naomi. Urged to go home, "Orpah kissed her mother-in-law goodbye, but Ruth clung to her"; Naomi says she is "going back to her people and her gods."`,
  refs:["Ruth 1:4–15"]},

 {id:"redeemer", name:"The nearer guardian-redeemer", short:"The other redeemer", cat:"judg", w:4,
  dates:"c. 12th–11th c. BC (traditional)",
  desc:`A relative of Elimelek "more closely related" than Boaz. He is willing to buy Naomi's land, but when told he must also acquire Ruth, he says, "I cannot redeem it because I might endanger my own estate," and gives Boaz his sandal. Ruth does not give his name.`,
  refs:["Ruth 3:12–13","Ruth 4:1–8"]},

 {id:"obed", name:"Obed", short:"Obed", cat:"judg", w:6,
  dates:"c. 11th c. BC (traditional)",
  desc:`Son of Boaz and Ruth, whom Naomi takes in her arms; the women of the town say, "Naomi has a son!" and name him Obed. "He was the father of Jesse, the father of David."`,
  refs:["Ruth 4:13–22","Matthew 1:5"]},

 {id:"salmon", name:"Salmon", short:"Salmon", cat:"line", w:4,
  dates:"c. 14th–12th c. BC (traditional)",
  desc:`In Ruth's genealogy, "Nahshon the father of Salmon, Salmon the father of Boaz." Matthew 1:5 names Rahab as Boaz's mother.`,
  refs:["Ruth 4:20–21","Matthew 1:4–5"]},

 {id:"hezron_j", name:"Hezron son of Perez", short:"Hezron", cat:"line", w:4,
  dates:"c. 17th c. BC (traditional)",
  desc:`Son of Perez and grandson of Judah, head of the Hezronite clan; "Hezron the father of Ram."`,
  notconfused:`Hezron son of Reuben (Genesis 46:9).`,
  refs:["Genesis 46:12","Numbers 26:21","Ruth 4:18–19"]},

 {id:"ram_j", name:"Ram son of Hezron", short:"Ram", cat:"line", w:4,
  dates:"c. 16th c. BC (traditional)",
  desc:`In Ruth's genealogy, "Hezron the father of Ram, Ram the father of Amminadab."`,
  refs:["Ruth 4:19","Matthew 1:3–4"]},

 {id:"deborah", name:"Deborah", short:"Deborah", cat:"judg", w:11,
  aliases:"\"Deborah, a prophet\" · \"a mother in Israel\"",
  clash:"Deborah", clashtag:"Prophet and judge who summoned Barak and, with him, defeated Sisera.",
  dates:"c. 1235 BC* (estimate; disputed) · the land had peace 40 years (Judges 5:31)",
  desc:`"Deborah, a prophet, the wife of Lappidoth, was leading Israel at that time." She holds court under the Palm of Deborah, summons Barak to fight Jabin's commander Sisera, and goes with him, warning that "the LORD will deliver Sisera into the hands of a woman." Her song with Barak (Judges 5) celebrates the victory: "until I, Deborah, arose, until I arose, a mother in Israel." "Then the land had peace forty years."`,
  notconfused:`Deborah, Rebekah's nurse, buried near Bethel in Jacob's day (Genesis 35:8).`,
  refs:["Judges 4–5"]},

 {id:"gideon", name:"Gideon", short:"Gideon", cat:"judg", w:11,
  aliases:"Jerub-Baal",
  dates:"c. 1169 BC* (estimate; disputed) · the land had peace 40 years in his lifetime (Judges 8:28)",
  desc:`Son of Joash the Abiezrite, threshing wheat in a winepress when the angel of the LORD greets him: "The LORD is with you, mighty warrior." He tears down his father's altar to Baal — and is named Jerub-Baal, "Let Baal contend with him" — and tests God with the fleece. The LORD cuts his army to three hundred men, who rout Midian with trumpets, jars and torches: "A sword for the LORD and for Gideon!" He captures the kings Zebah and Zalmunna and refuses to rule — "The LORD will rule over you" — but makes a gold ephod that "became a snare to Gideon and his family." He has seventy sons and, by a concubine in Shechem, Abimelek; "the land had peace forty years."`,
  refs:["Judges 6–8","Judges 9:1–5"]},

 {id:"jephthah", name:"Jephthah", short:"Jephthah", cat:"judg", w:9,
  aliases:"Jephthah the Gileadite",
  dates:"led Israel 6 years, c. 1096 – 1090 BC* (estimate; disputed) (Judges 12:7)",
  desc:`"A mighty warrior," son of Gilead by a prostitute, driven out by his half-brothers to the land of Tob, then called back by the elders of Gilead to fight the Ammonites. He argues Israel's claim to the land, the Spirit of the LORD comes on him, and he vows that "whatever comes out of the door of my house to meet me" will be a burnt offering — and his only daughter comes out dancing. He later fights Ephraim, whose survivors are exposed at the Jordan by "Shibboleth." "Jephthah led Israel six years."`,
  refs:["Judges 10:17–12:7"]},

 {id:"samson", name:"Samson", short:"Samson", cat:"judg", w:11,
  aliases:"\"a Nazirite, dedicated to God from the womb\"",
  dates:"led Israel 20 years, c. 1075 – 1055 BC* (estimate; disputed) (Judges 16:31)",
  desc:`Son of Manoah of Zorah, announced by the angel of the LORD as a Nazirite who would "take the lead in delivering Israel from the hands of the Philistines." The Spirit of the LORD comes on him: he tears a lion apart, poses a riddle at his wedding feast in Timnah, burns the Philistines' grain with three hundred foxes, kills a thousand men with a donkey's jawbone, and carries off the gates of Gaza. Delilah coaxes out the secret of his uncut hair; shaved, captured, blinded and set to grinding grain, he prays "strengthen me just once more" and pulls down the temple of Dagon — "he killed many more when he died than while he lived." "He had led Israel twenty years."`,
  refs:["Judges 13–16"]},

 {id:"delilah", name:"Delilah", short:"Delilah", cat:"judg", w:7,
  dates:"c. 11th c. BC (traditional; disputed)",
  desc:`A woman "in the Valley of Sorek" whom Samson loves. The rulers of the Philistines each offer her eleven hundred shekels of silver to learn the secret of his strength; after three false answers he tells her of his uncut hair, and while he sleeps on her lap she has his seven braids shaved: "Samson, the Philistines are upon you!"`,
  refs:["Judges 16:4–21"]},

 {id:"ruth", name:"Ruth", short:"Ruth", cat:"judg", w:11,
  aliases:"Ruth the Moabite",
  dates:"c. 12th–11th c. BC (traditional; 'when the judges ruled')",
  desc:`A Moabite, widow of Naomi's son Mahlon, who refuses to leave her mother-in-law: "Where you go I will go, and where you stay I will stay. Your people will be my people and your God my God." In Bethlehem she gleans in the field of Boaz, a relative of Elimelek, who praises what she has done; at the threshing floor she asks him, as a guardian-redeemer, to "spread the corner of your garment over me." Boaz marries her and she bears Obed, the grandfather of David; the women say she is "better to you than seven sons."`,
  refs:["Ruth 1–4","Matthew 1:5"]},

 {id:"boaz", name:"Boaz", short:"Boaz", cat:"judg", w:9,
  dates:"c. 12th–11th c. BC (traditional)",
  desc:`"A man of standing from the clan of Elimelek" in Bethlehem, son of Salmon (and, per Matthew 1:5, of Rahab). He protects and provides for Ruth as she gleans, and when she comes to him at the threshing floor he promises to act as guardian-redeemer. At the town gate the nearer relative declines, and Boaz buys Elimelek's property and acquires "Ruth the Moabite, Mahlon's widow, as my wife." He becomes the father of Obed, the grandfather of David.`,
  refs:["Ruth 2–4","Matthew 1:5"]},

 {id:"naomi", name:"Naomi", short:"Naomi", cat:"judg", w:9,
  aliases:"Mara",
  dates:"c. 12th–11th c. BC (traditional)",
  desc:`Wife of Elimelek of Bethlehem, who goes to Moab in a famine and loses her husband and both sons. Returning with Ruth she says, "Call me Mara, because the Almighty has made my life very bitter… I went away full, but the LORD has brought me back empty." She guides Ruth to Boaz, and when Obed is born she takes him in her arms: "Naomi has a son!"`,
  refs:["Ruth 1–4"]},

 {id:"eli", name:"Eli", short:"Eli", cat:"judg", w:8,
  dates:"led Israel 40 years, c. 1110 – 1070 BC* (estimate) · died at 98 (1 Samuel 4:15, 18)",
  desc:`The priest at Shiloh, sitting "by the doorpost of the LORD's house," who mistakes Hannah's silent prayer for drunkenness and then blesses her. He raises the boy Samuel and teaches him to answer, "Speak, LORD, for your servant is listening." His sons Hophni and Phinehas are scoundrels he fails to restrain, and the LORD announces judgment on his house. Hearing that the ark is captured and his sons are dead, he falls backward and breaks his neck at ninety-eight. "He had led Israel forty years."`,
  refs:["1 Samuel 1:9–17","1 Samuel 2:11–36","1 Samuel 3","1 Samuel 4:12–18"]},

 {id:"hannah", name:"Hannah", short:"Hannah", cat:"judg", w:8,
  dates:"c. 11th c. BC (traditional)",
  desc:`Elkanah's beloved wife, childless and provoked by her rival Peninnah. At Shiloh she weeps and vows that if the LORD gives her a son "I will give him to the LORD for all the days of his life." She names her son Samuel, "Because I asked the LORD for him," brings him to Eli once he is weaned, and prays, "My heart rejoices in the LORD… He raises the poor from the dust." She later bears three more sons and two daughters.`,
  refs:["1 Samuel 1–2"]},

 {id:"samuel", name:"Samuel", short:"Samuel", cat:"judg", w:13, halo:1,
  aliases:"the seer · prophet of the LORD",
  dates:"c. 1100 – 1011 BC* (estimate)",
  desc:`Son of Elkanah and Hannah, given to the LORD and raised by Eli at Shiloh. Called by name in the night — "Speak, for your servant is listening" — he is "attested as a prophet of the LORD" from Dan to Beersheba. He leads Israel to put away their idols, intercedes at Mizpah as the LORD routs the Philistines, and sets up the stone Ebenezer: "Thus far the LORD has helped us." He judges Israel on a circuit from Ramah. When the people demand a king he warns them, then anoints Saul; when Saul disobeys he declares, "To obey is better than sacrifice," and anoints David in Bethlehem. He dies and is buried at Ramah, and is called up by the medium at Endor to pronounce Saul's end. 1 Chronicles 6 lists him in the Levite line of Kohath through Korah, calls him "Samuel the seer," and names his grandson Heman the musician. Psalm 99: "Samuel was among those who called on his name; they called on the LORD and he answered them." Jeremiah 15:1: "Even if Moses and Samuel were to stand before me, my heart would not go out to this people."`,
  refs:["1 Samuel 1–3","1 Samuel 7–10","1 Samuel 12","1 Samuel 15–16","1 Samuel 25:1","1 Samuel 28:11–19","1 Chronicles 6:26–28","1 Chronicles 6:33–34","1 Chronicles 9:22","1 Chronicles 29:29","Psalm 99:6","Jeremiah 15:1"]},

 // ---------------- KINGS OF ISRAEL & JUDAH ----------------
 {id:"jesse", name:"Jesse", short:"Jesse", cat:"king", w:8,
  dates:"c. 11th c. BC (traditional)",
  desc:`Son of Obed and grandson of Boaz and Ruth — "Obed the father of Jesse, and Jesse the father of David." 1 Chronicles lists his sons in order — Eliab, Abinadab, Shimea, Nethanel, Raddai, Ozem and "the seventh David" — though 1 Samuel 17:12 says "Jesse had eight sons." His daughters were Zeruiah and Abigail. Isaiah 11:1: "A shoot will come up from the stump of Jesse; from his roots a Branch will bear fruit."`,
  refs:["Ruth 4:17–22","Matthew 1:5–6","1 Chronicles 2:12–17","1 Samuel 16:1–13","1 Samuel 17:12","Psalm 72:20","Isaiah 11:1","Isaiah 11:10"]},

 // ================= 1 SAMUEL =================
 // Sourced chapter-by-chapter from the NIV on bible.com (1 Samuel 1–31).
 {id:"elkanah", name:"Elkanah son of Jeroham", short:"Elkanah", cat:"judg", w:6,
  dates:"c. 11th c. BC (traditional)",
  desc:`"A Zuphite from the hill country of Ephraim," of Ramathaim, with two wives, Hannah and Peninnah. He goes up yearly to sacrifice at Shiloh and gives Hannah a double portion "because he loved her": "Don't I mean more to you than ten sons?" Father of Samuel. 1 Chronicles 6 lists him in the Levite line of Kohath, through Korah.`,
  refs:["1 Samuel 1–2","1 Chronicles 6:22–28","1 Chronicles 6:33–38"]},

 {id:"peninnah", name:"Peninnah", short:"Peninnah", cat:"judg", w:5,
  dates:"c. 11th c. BC (traditional)",
  desc:`Elkanah's other wife, who had children while Hannah had none; "her rival kept provoking her in order to irritate her" year after year at Shiloh.`,
  refs:["1 Samuel 1:2–7"]},

 {id:"hophni", name:"Hophni son of Eli", short:"Hophni", cat:"priest", w:6,
  dates:"c. 11th c. BC (traditional)",
  desc:`With his brother Phinehas, a priest at Shiloh. "Eli's sons were scoundrels; they had no regard for the LORD," taking the people's offerings by force and sleeping with the women who served at the tent of meeting. A man of God foretells that both will die on the same day; they are killed when the Philistines capture the ark.`,
  refs:["1 Samuel 1:3","1 Samuel 2:12–36","1 Samuel 4:4–17"]},

 {id:"phinehas_eli", name:"Phinehas son of Eli", short:"Phinehas (Eli's son)", cat:"priest", w:6,
  clash:"Phinehas", clashtag:"Eli's corrupt son, a priest at Shiloh, killed when the ark was captured.",
  dates:"c. 11th c. BC (traditional)",
  desc:`With his brother Hophni, a priest at Shiloh who treated "the LORD's offering with contempt." Both die the day the Philistines capture the ark; his wife, giving birth at the news, names the child Ichabod. Through his son Ahitub his line continues in the priests Ahijah and Ahimelek.`,
  notconfused:`Phinehas son of Eleazar, Aaron's grandson, whose zeal at Peor won "a covenant of a lasting priesthood" (Numbers 25).`,
  refs:["1 Samuel 1:3","1 Samuel 2:12–34","1 Samuel 4:11–22","1 Samuel 14:3"]},

 {id:"ichabod", name:"Ichabod", short:"Ichabod", cat:"priest", w:5,
  dates:"c. 11th c. BC (traditional)",
  desc:`Son of Phinehas, born as his mother died on hearing that the ark was captured and her husband and father-in-law were dead. She named him Ichabod, saying, "The Glory has departed from Israel."`,
  refs:["1 Samuel 4:19–22","1 Samuel 14:3"]},

 {id:"ahitub", name:"Ahitub son of Phinehas", short:"Ahitub", cat:"line", w:4,
  dates:"c. 11th c. BC (traditional)",
  desc:`"Ichabod's brother Ahitub son of Phinehas, the son of Eli"; father of the priests Ahijah (1 Samuel 14:3) and Ahimelek (22:9, 11).`,
  notconfused:`Ahitub the father of Zadok, whom 1 Chronicles 6:7–8 places in Eleazar's priestly line.`,
  refs:["1 Samuel 14:3","1 Samuel 22:9–12"]},

 {id:"ahijah_p", name:"Ahijah son of Ahitub", short:"Ahijah (priest)", cat:"priest", w:5,
  clash:"Ahijah", clashtag:"Son of Ahitub, the priest who wore the ephod with Saul's army.",
  dates:"c. 11th c. BC (traditional)",
  desc:`The priest "wearing an ephod" with Saul's men at Gibeah when Jonathan attacks the Philistine outpost; Saul tells him, "Bring the ark of God," then, "Withdraw your hand."`,
  refs:["1 Samuel 14:3","1 Samuel 14:18–19"]},

 {id:"ahimelek_p", name:"Ahimelek son of Ahitub", short:"Ahimelek (priest)", cat:"priest", w:6,
  clash:"Ahimelek", clashtag:"The priest at Nob who gave David the consecrated bread and Goliath's sword, and was killed on Saul's orders.",
  dates:"c. 11th c. BC (traditional)",
  desc:`The priest at Nob who trembles when David arrives alone, gives him the consecrated bread and "the sword of Goliath the Philistine." Accused by Doeg, he tells Saul, "Who of all your servants is as loyal as David?" — and Saul has Doeg kill him with eighty-five priests. Only his son Abiathar escapes.`,
  refs:["1 Samuel 21:1–9","1 Samuel 22:9–20","Psalm 52"]},

 {id:"abiathar", name:"Abiathar son of Ahimelek", short:"Abiathar", cat:"priest", w:8,
  dates:"c. 11th–10th c. BC (traditional)",
  desc:`The only son of Ahimelek to escape the massacre at Nob; he flees to David, who says, "I am responsible for the death of your whole family. Stay with me." He brings the ephod, through which David inquires of the LORD at Keilah and after the raid on Ziklag. Solomon removes him from the priesthood and sends him to Anathoth, fulfilling the word spoken about Eli's house. Chronicles names him with Zadok when the ark is brought up and as a counselor after Ahithophel; it also lists "Ahimelek son of Abiathar" as priest under David.`,
  refs:["1 Samuel 22:20–23","1 Samuel 23:6–12","1 Samuel 30:7–8","1 Kings 2:26–27","1 Chronicles 15:11","1 Chronicles 27:34"]},

 {id:"abinadab_k", name:"Abinadab of Kiriath Jearim", short:"Abinadab (ark keeper)", cat:"judg", w:4,
  clash:"Abinadab", clashtag:"The man of Kiriath Jearim in whose house on the hill the ark stayed for twenty years.",
  dates:"c. 11th c. BC (traditional)",
  desc:`When the ark is returned by the Philistines, the men of Kiriath Jearim bring it "to Abinadab's house on the hill and consecrated Eleazar his son to guard the ark." It remains there twenty years.`,
  refs:["1 Samuel 7:1–2"]},

 {id:"eleazar_ab", name:"Eleazar son of Abinadab", short:"Eleazar (ark guard)", cat:"judg", w:4,
  clash:"Eleazar", clashtag:"Abinadab's son, consecrated to guard the ark at Kiriath Jearim.",
  dates:"c. 11th c. BC (traditional)",
  desc:`Consecrated by the men of Kiriath Jearim "to guard the ark of the LORD" in his father Abinadab's house.`,
  notconfused:`Eleazar son of Aaron, the high priest who succeeded his father (Numbers 20).`,
  refs:["1 Samuel 7:1"]},

 {id:"joel_s", name:"Joel son of Samuel", short:"Joel (Samuel's son)", cat:"judg", w:4,
  clash:"Joel", clashtag:"Samuel's firstborn, who took bribes at Beersheba.",
  dates:"c. 11th c. BC (traditional)",
  desc:`Samuel's firstborn, appointed with his brother Abijah as a leader at Beersheba; they "turned aside after dishonest gain and accepted bribes and perverted justice," and the elders asked for a king. 1 Chronicles 6:33 makes him the father of Heman the musician.`,
  notconfused:`Joel the prophet (Joel 1).`,
  refs:["1 Samuel 8:1–5","1 Chronicles 6:28","1 Chronicles 6:33"]},

 {id:"abijah_s", name:"Abijah son of Samuel", short:"Abijah (Samuel's son)", cat:"judg", w:4,
  clash:"Abijah", clashtag:"Samuel's second son, who took bribes at Beersheba.",
  dates:"c. 11th c. BC (traditional)",
  desc:`Samuel's second son, who with Joel "did not follow his ways" at Beersheba.`,
  refs:["1 Samuel 8:1–3"]},

 // Saul's house
 {id:"kish", name:"Kish son of Abiel", short:"Kish", cat:"king", w:6,
  dates:"c. 11th c. BC (traditional)",
  desc:`"A Benjamite, a man of standing," father of Saul. Saul is out looking for his father's lost donkeys when Samuel anoints him; "What is this that has happened to the son of Kish?" 1 Chronicles 8:33 calls him the son of Ner, where 1 Samuel 9:1 has "Kish son of Abiel."`,
  refs:["1 Samuel 9:1–3","1 Samuel 10:11","1 Samuel 14:51","1 Chronicles 8:33","1 Chronicles 9:39"]},

 {id:"abiel", name:"Abiel", short:"Abiel", cat:"line", w:4,
  dates:"c. 11th c. BC (traditional)",
  desc:`A Benjamite, "son of Zeror"; "Saul's father Kish and Abner's father Ner were sons of Abiel."`,
  refs:["1 Samuel 9:1","1 Samuel 14:51"]},

 {id:"ner", name:"Ner son of Abiel", short:"Ner", cat:"line", w:4,
  dates:"c. 11th c. BC (traditional)",
  desc:`"Ner was Saul's uncle," and father of Abner, the commander of Saul's army. 1 Chronicles 8:33 and 9:39 instead say "Ner was the father of Kish, Kish the father of Saul," and list a Ner among the sons of Jeiel the father of Gibeon; the text does not reconcile the two accounts.`,
  refs:["1 Samuel 14:50–51","1 Chronicles 8:29–33","1 Chronicles 9:35–39"]},

 {id:"abner", name:"Abner son of Ner", short:"Abner", cat:"king", w:9,
  dates:"c. 11th c. BC (traditional)",
  desc:`Saul's cousin and "the commander of Saul's army." After Saul's death he makes Ish-Bosheth king over Israel and kills Asahel at Gibeon. When Ish-Bosheth accuses him over Saul's concubine Rizpah, he goes over to David and brings Michal back, but Joab, avenging his brother, stabs him at Hebron. David walks behind his bier: "a commander and a great man has fallen in Israel this day."`,
  refs:["1 Samuel 14:50–51","1 Samuel 17:55–57","1 Samuel 26:5–16","2 Samuel 2:8–32","2 Samuel 3"]},

 {id:"ahinoam_s", name:"Ahinoam daughter of Ahimaaz", short:"Ahinoam (Saul's wife)", cat:"king", w:4,
  clash:"Ahinoam", clashtag:"Saul's wife, daughter of Ahimaaz.",
  dates:"c. 11th c. BC (traditional)",
  desc:`"His wife's name was Ahinoam daughter of Ahimaaz" — Saul's wife, the only one named in 1 Samuel.`,
  refs:["1 Samuel 14:50"]},

 {id:"ishvi", name:"Ishvi son of Saul", short:"Ishvi", cat:"king", w:4,
  dates:"c. 11th c. BC (traditional)",
  desc:`Named among Saul's sons with Jonathan and Malki-Shua.`,
  refs:["1 Samuel 14:49"]},

 {id:"malkishua", name:"Malki-Shua son of Saul", short:"Malki-Shua", cat:"king", w:5,
  dates:"c. 11th c. BC (traditional)",
  desc:`A son of Saul killed with Jonathan and Abinadab by the Philistines on Mount Gilboa.`,
  refs:["1 Samuel 14:49","1 Samuel 31:2"]},

 {id:"abinadab_s", name:"Abinadab son of Saul", short:"Abinadab (Saul's son)", cat:"king", w:4,
  clash:"Abinadab", clashtag:"A son of Saul killed with Jonathan on Mount Gilboa.",
  dates:"c. 11th c. BC (traditional)",
  desc:`A son of Saul killed with Jonathan and Malki-Shua on Mount Gilboa.`,
  refs:["1 Samuel 31:2"]},

 {id:"merab", name:"Merab daughter of Saul", short:"Merab", cat:"king", w:5,
  dates:"c. 11th c. BC (traditional)",
  desc:`Saul's older daughter, promised to David — "only serve me bravely" — but "given in marriage to Adriel of Meholah."`,
  refs:["1 Samuel 14:49","1 Samuel 18:17–19"]},

 {id:"adriel", name:"Adriel of Meholah", short:"Adriel", cat:"king", w:4,
  dates:"c. 11th c. BC (traditional)",
  desc:`The man to whom Merab, Saul's daughter promised to David, was given in marriage instead.`,
  refs:["1 Samuel 18:19"]},

 {id:"michal", name:"Michal daughter of Saul", short:"Michal", cat:"king", w:8,
  dates:"c. 11th–10th c. BC (traditional)",
  desc:`Saul's younger daughter, who "was in love with David." She becomes his wife for a bride-price of Philistine foreskins and saves him by letting him down through a window. Saul gives her to Paltiel, but David demands her back, and Paltiel follows "weeping behind her all the way to Bahurim." When David dances before the ark she "despised him in her heart," and she "had no children to the day of her death."`,
  refs:["1 Samuel 18:20–28","1 Samuel 19:11–17","1 Samuel 25:44","2 Samuel 3:13–16","2 Samuel 6:16–23"]},

 {id:"paltiel_l", name:"Paltiel son of Laish", short:"Paltiel (Michal's husband)", cat:"king", w:4,
  clash:"Paltiel", clashtag:"The man of Gallim to whom Saul gave Michal, David's wife.",
  dates:"c. 11th c. BC (traditional)",
  desc:`"Saul had given his daughter Michal, David's wife, to Paltiel son of Laish, who was from Gallim."`,
  notconfused:`Paltiel son of Azzan, the Issacharite leader named in Numbers 34:26.`,
  refs:["1 Samuel 25:44"]},

 {id:"endor_medium", name:"The medium at Endor", short:"Medium of Endor", cat:"king", w:6,
  dates:"c. 1010 BC (traditional)",
  desc:`A woman "who is a medium" at Endor, whom Saul, after expelling the mediums, consults in disguise when the LORD will not answer him. She sees "a ghostly figure coming up out of the earth" — Samuel, who foretells Saul's death — then urges the shaken king to eat. Unnamed in Scripture.`,
  refs:["1 Samuel 28:3–25"]},

 // Jesse's sons and David's early circle
 {id:"eliab_j", name:"Eliab son of Jesse", short:"Eliab (David's brother)", cat:"king", w:5,
  clash:"Eliab", clashtag:"Jesse's firstborn, whom Samuel thought must be the LORD's anointed.",
  dates:"c. 11th c. BC (traditional)",
  desc:`Jesse's firstborn. Seeing him, Samuel thinks, "Surely the LORD's anointed stands here," but the LORD says, "People look at the outward appearance, but the LORD looks at the heart." At the Valley of Elah he scolds David: "I know how conceited you are."`,
  refs:["1 Samuel 16:6–7","1 Samuel 17:13","1 Samuel 17:28"]},

 {id:"abinadab_j", name:"Abinadab son of Jesse", short:"Abinadab (David's brother)", cat:"king", w:4,
  clash:"Abinadab", clashtag:"Jesse's second son, passed over when Samuel came to anoint a king.",
  dates:"c. 11th c. BC (traditional)",
  desc:`Jesse's second son, passed over by Samuel and later in Saul's army at the Valley of Elah.`,
  refs:["1 Samuel 16:8","1 Samuel 17:13"]},

 {id:"shammah_j", name:"Shammah son of Jesse", short:"Shammah (David's brother)", cat:"king", w:4,
  aliases:"Shimea (1 Chronicles 2:13)",
  clash:"Shammah", clashtag:"Jesse's third son, David's brother.",
  dates:"c. 11th c. BC (traditional)",
  desc:`Jesse's third son, passed over by Samuel and in Saul's army when David faced Goliath. 1 Chronicles calls him Shimea; his son Jonathan killed a six-fingered giant at Gath.`,
  refs:["1 Samuel 16:9","1 Samuel 17:13","1 Chronicles 2:13","1 Chronicles 20:7"]},

 {id:"abigail", name:"Abigail", short:"Abigail", cat:"king", w:8,
  clash:"Abigail", clashtag:"Nabal's widow from Carmel, who became David's wife.",
  aliases:"Abigail of Carmel",
  dates:"c. 11th–10th c. BC (traditional)",
  desc:`"An intelligent and beautiful woman," wife of the surly Nabal. When Nabal insults David's men she rides out with food and turns David from bloodshed: "the life of my lord will be bound securely in the bundle of the living." After the LORD strikes Nabal she becomes David's wife; she is captured at Ziklag and rescued.`,
  refs:["1 Samuel 25","1 Samuel 27:3","1 Samuel 30:5–18"]},

 {id:"nabal", name:"Nabal", short:"Nabal", cat:"king", w:6,
  dates:"c. 11th c. BC (traditional)",
  desc:`A wealthy Calebite of Maon who refuses David's men — "Who is this David?" Abigail says, "He is just like his name — his name means Fool." When he learns what she has done, "his heart failed him and he became like a stone"; ten days later "the LORD struck Nabal and he died."`,
  refs:["1 Samuel 25"]},

 {id:"ahinoam_j", name:"Ahinoam of Jezreel", short:"Ahinoam (David's wife)", cat:"king", w:6,
  clash:"Ahinoam", clashtag:"David's wife from Jezreel, who shared his exile among the Philistines.",
  dates:"c. 11th–10th c. BC (traditional)",
  desc:`"David had also married Ahinoam of Jezreel"; with Abigail she lives with David at Gath and Ziklag and is captured and rescued from the Amalekites.`,
  refs:["1 Samuel 25:43","1 Samuel 27:3","1 Samuel 30:5"]},

 {id:"ahimelek_h", name:"Ahimelek the Hittite", short:"Ahimelek the Hittite", cat:"king", w:4,
  clash:"Ahimelek", clashtag:"A Hittite with David in the wilderness, asked to go down into Saul's camp.",
  dates:"c. 11th c. BC (traditional)",
  desc:`One of the two men David asks, "Who will go down into the camp with me to Saul?" (Abishai volunteers).`,
  refs:["1 Samuel 26:6"]},

 {id:"gad_p", name:"Gad the prophet", short:"Gad (prophet)", cat:"proph", w:7,
  clash:"Gad", clashtag:"'David's seer,' who advised him in the wilderness and gave the LORD's word after the census.",
  dates:"c. 11th–10th c. BC (traditional)",
  desc:`"The prophet Gad," who tells the fugitive David, "Go into the land of Judah." Called "David's seer," after the census he brings David the LORD's three options — famine, flight or plague — and then tells him to build an altar on the threshing floor of Araunah. Chronicles cites "the records of Gad the seer" for David's reign; the temple music was arranged "in the way prescribed by David and Gad the king's seer and Nathan the prophet."`,
  notconfused:`Gad son of Jacob and Zilpah, ancestor of the tribe of Gad (Genesis 30:11).`,
  refs:["1 Samuel 22:5","2 Samuel 24:11–19","1 Chronicles 21:9–19","1 Chronicles 29:29","2 Chronicles 29:25"]},


 {id:"saul", name:"Saul son of Kish", short:"Saul", cat:"king", w:13,
  aliases:"first king of Israel",
  dates:"reigned c. 1050 – 1010 BC (1 Samuel 13:1's figures are uncertain in the text)",
  desc:`A Benjamite, "as handsome a young man as could be found anywhere in Israel, and he was a head taller than anyone else." Out looking for his father's donkeys, he is anointed by Samuel, prophesies — "Is Saul also among the prophets?" — and is chosen by lot at Mizpah, hiding among the supplies. He rescues Jabesh Gilead from Nahash, but offers the burnt offering at Gilgal without Samuel and spares Agag and the best of the plunder, and the LORD rejects him as king. Tormented by an evil spirit and jealous of David — "Saul has slain his thousands, and David his tens of thousands" — he hurls his spear at him, hunts him through the wilderness, and has the priests of Nob killed. Twice spared by David, he admits, "You are more righteous than I." Facing the Philistines at Gilboa he consults the medium at Endor, and the next day, critically wounded, he falls on his own sword; the men of Jabesh Gilead bury him. Psalm titles recall David's escapes from him (Psalms 18, 52, 54, 57, 59).`,
  notconfused:`Saul of Tarsus (the apostle Paul), named after this king — a different man in the New Testament.`,
  refs:["1 Samuel 9–11","1 Samuel 13–15","1 Samuel 18–19","1 Samuel 24","1 Samuel 26","1 Samuel 28","1 Samuel 31","Psalm 18","Psalm 57","Psalm 59"]},

 {id:"jonathan", name:"Jonathan son of Saul", short:"Jonathan", cat:"king", w:10,
  clash:"Jonathan", clashtag:"Saul's son, David's close friend, killed with Saul at Gilboa.",
  dates:"c. 11th c. BC (traditional)",
  desc:`Saul's son, who with only his armor-bearer climbs to the Philistine outpost — "Nothing can hinder the LORD from saving, whether by many or by few" — and is spared from his father's rash oath by the army. After David kills Goliath, "Jonathan became one in spirit with David, and he loved him as himself"; he gives David his robe, sword and bow, warns him with the arrows in the field, and in the wilderness tells him, "You will be king over Israel, and I will be second to you." He falls with Saul at Gilboa.`,
  refs:["1 Samuel 13–14","1 Samuel 18:1–4","1 Samuel 19:1–7","1 Samuel 20","1 Samuel 23:16–18","1 Samuel 31:2"]},

 {id:"david", name:"David son of Jesse", short:"David", cat:"king", w:16, halo:1,
  aliases:"\"a man after his own heart\" (1 Samuel 13:14) · \"the hero of Israel's songs\"",
  dates:"reigned c. 1010 – 970 BC · 30 when he became king; reigned 40 years (2 Samuel 5:4)",
  desc:`The youngest son of Jesse of Bethlehem, a shepherd anointed by Samuel — "the LORD looks at the heart." He plays the lyre for Saul, kills Goliath "in the name of the LORD Almighty," and is loved by Jonathan; hunted by Saul, he twice spares "the LORD's anointed." Made king over Judah at Hebron and then over all Israel, he takes Jerusalem, brings up the ark dancing "with all his might," and receives the LORD's promise through Nathan: "your throne will be established forever." He takes Bathsheba and has Uriah killed; confronted — "You are the man!" — he confesses, "I have sinned against the LORD." The sword does not depart from his house: Amnon rapes Tamar, Absalom kills Amnon and rebels, and David weeps, "O my son Absalom!" He sings of the LORD as "my rock, my fortress and my deliverer," and after the census buys Araunah's threshing floor to stop the plague. Chronicles adds his organizing of the priests, Levites, musicians and gatekeepers and his preparations for the temple, which he was not to build "because you are a warrior and have shed blood"; he charges Solomon, "Be strong and courageous, and do the work." Chronicles says "Satan rose up against Israel and incited David" to take the census (2 Samuel 24:1 says the LORD's anger "incited David"). The titles of seventy-three psalms are "of David," several tied to moments in his life — fleeing Absalom (Psalm 3), delivered from Saul (18, 57, 59), pretending to be insane "before Abimelek" (34), Nathan's rebuke after Bathsheba (51: "Create in me a pure heart, O God"), Doeg (52), the Ziphites (54), Gath (56), Joab's victory over Edom (60) and the cave (142). Psalm 72 closes, "This concludes the prayers of David son of Jesse," and Psalm 78 says God "chose David his servant and took him from the sheep pens." Isaiah promises one who "will reign on David's throne," Jeremiah "a righteous Branch" from "David's line," and Ezekiel "one shepherd, my servant David," who "will be their prince forever." Hosea foretells that the Israelites "will return and seek the LORD their God and David their king"; Amos rebukes those who "strum away on your harps like David" and promises, "I will restore David's fallen shelter."`,
  refs:["1 Samuel 16–17","1 Samuel 24","1 Samuel 26","2 Samuel 2:4","2 Samuel 5–7","2 Samuel 11–12","2 Samuel 15–19","2 Samuel 22–24","Psalms","1 Chronicles 11–29","Psalm 3","Psalm 23","Psalm 51","Psalm 72:20","Psalm 78:70–72","Psalm 89:3–4","Isaiah 9:7","Jeremiah 33:15","Ezekiel 34:23–24","Ezekiel 37:24–25","Hosea 3:5","Amos 6:5","Amos 9:11"]},

 {id:"bathsheba", name:"Bathsheba", short:"Bathsheba", cat:"king", w:9,
  dates:"c. 10th c. BC (traditional)",
  desc:`"The daughter of Eliam and the wife of Uriah the Hittite," whom David sees bathing, sends for and sleeps with; when she is pregnant David arranges Uriah's death and marries her. Their first son dies; she then bears Solomon, whom the LORD loved and named Jedidiah through Nathan. 1 Chronicles 3:5 calls her "Bathsheba daughter of Ammiel" and names her four sons: Shammua, Shobab, Nathan and Solomon.`,
  refs:["2 Samuel 11–12","1 Kings 1–2","1 Chronicles 3:5","Psalm 51"]},

 {id:"absalom", name:"Absalom son of David", short:"Absalom", cat:"king", w:10,
  dates:"c. 10th c. BC (traditional)",
  desc:`David's third son, by Maakah daughter of Talmai king of Geshur; "in all Israel there was not a man so highly praised for his handsome appearance." After Amnon rapes his sister Tamar he has Amnon killed and flees to Geshur; brought back by Joab's scheme, he "stole the hearts of the people of Israel," proclaims himself king in Hebron, takes Jerusalem and sleeps with his father's concubines. Following Hushai's advice over Ahithophel's, he is defeated in the forest of Ephraim; his hair catches in an oak, and Joab kills him against David's order. He had set up "Absalom's Monument" because "I have no son to carry on the memory of my name." Psalm 3 is headed, "A psalm of David. When he fled from his son Absalom."`,
  refs:["2 Samuel 3:3","2 Samuel 13–18","Psalm 3"]},

 // ================= 2 SAMUEL =================
 // Sourced chapter-by-chapter from the NIV on bible.com (2 Samuel 1–24).
 {id:"ishbosheth", name:"Ish-Bosheth son of Saul", short:"Ish-Bosheth", cat:"king", w:7,
  dates:"reigned 2 years, c. 1010 BC (2 Samuel 2:10)",
  desc:`Saul's son, made king over Israel by Abner at Mahanaim at forty while Judah followed David; "he reigned two years." When he accuses Abner over Saul's concubine Rizpah, Abner goes over to David. After Abner's death he loses courage and is murdered in his bed by Rekab and Baanah; David executes the killers and buries his head in Abner's tomb.`,
  refs:["2 Samuel 2:8–10","2 Samuel 3:6–11","2 Samuel 4"]},

 {id:"joab", name:"Joab son of Zeruiah", short:"Joab", cat:"king", w:11,
  dates:"c. 11th–10th c. BC (traditional)",
  desc:`Commander of David's army, the eldest of "the three sons of Zeruiah." He murders Abner to avenge his brother Asahel; takes Rabbah; carries David's letter that sends Uriah to his death; brings Absalom home through the wise woman of Tekoa — and later drives three javelins into Absalom's heart against David's order. He stabs Amasa, ends Sheba's revolt at Abel Beth Maakah, and objects to David's census. David laments, "these sons of Zeruiah are too strong for me." Psalm 60's title recalls "when Joab returned and struck down twelve thousand Edomites in the Valley of Salt."`,
  refs:["2 Samuel 2:13–32","2 Samuel 3:22–39","2 Samuel 11–12","2 Samuel 14","2 Samuel 18–20","2 Samuel 24:1–9","Psalm 60"]},

 {id:"abishai", name:"Abishai son of Zeruiah", short:"Abishai", cat:"king", w:8,
  dates:"c. 11th–10th c. BC (traditional)",
  desc:`Joab's brother, who goes down with David into Saul's camp and urges, "let me pin him to the ground." He joins Joab in killing Abner, offers to cut off Shimei's head, commands a third of the army against Absalom, and saves David from the giant Ishbi-Benob. "Chief of the Three," he once killed three hundred men.`,
  refs:["1 Samuel 26:6–9","2 Samuel 3:30","2 Samuel 16:9–11","2 Samuel 18:2","2 Samuel 21:16–17","2 Samuel 23:18–19"]},

 {id:"asahel", name:"Asahel son of Zeruiah", short:"Asahel", cat:"king", w:6,
  dates:"c. 1010 BC (traditional)",
  desc:`Joab's brother, "as fleet-footed as a wild gazelle," who chases Abner at Gibeon and will not turn aside; Abner kills him with the butt of his spear. He is buried in his father's tomb at Bethlehem and listed among the Thirty.`,
  refs:["2 Samuel 2:18–23","2 Samuel 3:27–30","2 Samuel 23:24"]},

 {id:"zeruiah", name:"Zeruiah", short:"Zeruiah", cat:"king", w:5,
  dates:"c. 11th c. BC (traditional)",
  desc:`Mother of Joab, Abishai and Asahel — "the three sons of Zeruiah." 2 Samuel 17:25 calls Amasa's mother Abigail "sister of Zeruiah the mother of Joab." 1 Chronicles 2:16 names Zeruiah and Abigail as the sisters of Jesse's sons.`,
  refs:["2 Samuel 2:18","2 Samuel 17:25","1 Chronicles 2:16"]},

 {id:"amnon", name:"Amnon son of David", short:"Amnon", cat:"king", w:7,
  dates:"c. 10th c. BC (traditional)",
  desc:`David's firstborn, by Ahinoam of Jezreel. Advised by Jonadab, he feigns illness and rapes his half-sister Tamar, then "hated her with intense hatred." Two years later Absalom has him killed at the sheepshearing at Baal Hazor.`,
  refs:["2 Samuel 3:2","2 Samuel 13"]},

 {id:"kileab", name:"Kileab son of David", short:"Kileab", cat:"king", w:4,
  aliases:"Daniel (1 Chronicles 3:1)",
  dates:"c. 10th c. BC (traditional)",
  desc:`David's second son, born in Hebron to Abigail, the widow of Nabal. 1 Chronicles 3:1 names this son "Daniel the son of Abigail of Carmel."`,
  refs:["2 Samuel 3:3","1 Chronicles 3:1"]},

 {id:"maakah_g", name:"Maakah daughter of Talmai", short:"Maakah (Absalom's mother)", cat:"king", w:5,
  clash:"Maakah", clashtag:"Daughter of Talmai king of Geshur, David's wife and Absalom's mother.",
  dates:"c. 10th c. BC (traditional)",
  desc:`Mother of Absalom (and so of Tamar), "daughter of Talmai king of Geshur" — the grandfather to whom Absalom flees after killing Amnon.`,
  refs:["2 Samuel 3:3","2 Samuel 13:37"]},

 {id:"haggith", name:"Haggith", short:"Haggith", cat:"king", w:4,
  dates:"c. 10th c. BC (traditional)",
  desc:`One of David's wives in Hebron; mother of Adonijah, his fourth son.`,
  refs:["2 Samuel 3:4","1 Kings 1:5"]},

 {id:"nathan_s", name:"Nathan son of David", short:"Nathan (David's son)", cat:"king", w:4,
  clash:"Nathan", clashtag:"A son born to David in Jerusalem, named alongside Solomon.",
  dates:"c. 10th c. BC (traditional)",
  desc:`One of the sons born to David in Jerusalem — "Shammua, Shobab, Nathan, Solomon," with Ibhar, Elishua, Nepheg, Japhia, Elishama, Eliada and Eliphelet.`,
  notconfused:`Nathan the prophet, who confronted David over Bathsheba (2 Samuel 12).`,
  refs:["2 Samuel 5:14"]},

 {id:"tamar_d", name:"Tamar daughter of David", short:"Tamar (David's daughter)", cat:"king", w:7,
  clash:"Tamar", clashtag:"David's daughter, Absalom's sister, raped by her half-brother Amnon.",
  dates:"c. 10th c. BC (traditional)",
  desc:`"The beautiful sister of Absalom," whom Amnon lures into his room and rapes despite her plea, "Don't do this wicked thing." Sent away, she tears her ornate robe and lives "in her brother Absalom's house, a desolate woman." Absalom names his own daughter Tamar.`,
  notconfused:`Tamar, Judah's daughter-in-law (Genesis 38).`,
  refs:["2 Samuel 13:1–22","2 Samuel 13:32","2 Samuel 14:27"]},

 {id:"jonadab", name:"Jonadab son of Shimeah", short:"Jonadab", cat:"king", w:5,
  dates:"c. 10th c. BC (traditional)",
  desc:`Amnon's adviser, "son of Shimeah, David's brother" — "a very shrewd man" — who suggests the ruse that lets Amnon get Tamar alone, and later assures David that "only Amnon is dead."`,
  refs:["2 Samuel 13:3–5","2 Samuel 13:32–35"]},

 {id:"rizpah", name:"Rizpah daughter of Aiah", short:"Rizpah", cat:"king", w:6,
  dates:"c. 10th c. BC (traditional)",
  desc:`Saul's concubine, over whom Ish-Bosheth accuses Abner. When her two sons Armoni and Mephibosheth are handed to the Gibeonites and killed, she spreads sackcloth on a rock and guards their bodies "from the beginning of the harvest till the rain poured down"; moved by this, David gives Saul and Jonathan an honorable burial.`,
  refs:["2 Samuel 3:7","2 Samuel 21:8–14"]},

 {id:"armoni", name:"Armoni son of Saul", short:"Armoni", cat:"king", w:4,
  dates:"c. 10th c. BC (traditional)",
  desc:`A son of Saul by Rizpah, handed over to the Gibeonites with six others and put to death at the start of the barley harvest.`,
  refs:["2 Samuel 21:8–9"]},

 {id:"mephibosheth_r", name:"Mephibosheth son of Saul", short:"Mephibosheth (Rizpah's son)", cat:"king", w:4,
  clash:"Mephibosheth", clashtag:"Saul's son by Rizpah, put to death by the Gibeonites.",
  dates:"c. 10th c. BC (traditional)",
  desc:`A son of Saul by Rizpah, given to the Gibeonites and killed; David spared the other Mephibosheth, Jonathan's son.`,
  notconfused:`Mephibosheth son of Jonathan, who ate at David's table (2 Samuel 9).`,
  refs:["2 Samuel 21:8–9"]},

 {id:"mephibosheth", name:"Mephibosheth son of Jonathan", short:"Mephibosheth", cat:"king", w:7,
  clash:"Mephibosheth", clashtag:"Jonathan's lame son, who ate at David's table.",
  dates:"c. 10th c. BC (traditional)",
  desc:`Jonathan's son, lamed at five when his nurse fled with him at news of Gilboa. David shows him kindness "for the sake of your father Jonathan," restores Saul's land and has him eat at the king's table: "What is your servant, that you should notice a dead dog like me?" During Absalom's revolt Ziba accuses him; when David returns, Mephibosheth says Ziba betrayed him, and David divides the land between them. David spares him when the Gibeonites demand Saul's descendants. His son was Mika.`,
  notconfused:`Mephibosheth son of Saul by Rizpah (2 Samuel 21:8).`,
  refs:["2 Samuel 4:4","2 Samuel 9","2 Samuel 16:1–4","2 Samuel 19:24–30","2 Samuel 21:7"]},

 {id:"ziba", name:"Ziba", short:"Ziba", cat:"king", w:6,
  dates:"c. 10th c. BC (traditional)",
  desc:`"A servant of Saul's household" with fifteen sons and twenty servants, who tells David of Mephibosheth and is ordered to farm Saul's land for him. When David flees Absalom, Ziba meets him with provisions and claims Mephibosheth hopes to regain Saul's kingdom; David later orders the land divided between them.`,
  refs:["2 Samuel 9","2 Samuel 16:1–4","2 Samuel 19:17","2 Samuel 19:26–29"]},

 {id:"makir_a", name:"Makir son of Ammiel", short:"Makir (Lo Debar)", cat:"king", w:4,
  clash:"Makir", clashtag:"The man of Lo Debar who sheltered Mephibosheth and later supplied David at Mahanaim.",
  dates:"c. 10th c. BC (traditional)",
  desc:`Of Lo Debar, in whose house Mephibosheth was living; later he brings bedding and food to David at Mahanaim.`,
  notconfused:`Makir son of Manasseh, Joseph's grandson (Numbers 26:29).`,
  refs:["2 Samuel 9:4–5","2 Samuel 17:27–29"]},

 {id:"zadok", name:"Zadok son of Ahitub", short:"Zadok", cat:"priest", w:8,
  dates:"c. 10th c. BC (traditional)",
  desc:`A priest with Abiathar under David. When David flees Absalom he sends Zadok back with the ark — "If I find favor in the LORD's eyes, he will bring me back" — and Zadok's son Ahimaaz carries Hushai's warnings to David. He anoints Solomon at Gihon and replaces Abiathar. 1 Chronicles traces his line from Aaron's son Eleazar through Phinehas to Ahitub, stations him "before the tabernacle of the LORD at the high place in Gibeon," and records him anointed "to be priest" when Solomon is acknowledged king. Ezekiel's vision of the new temple gives the altar service to "the Levitical priests, who are descendants of Zadok and who guarded my sanctuary when the Israelites went astray."`,
  notconfused:`Ahitub son of Phinehas, of Eli's house, is a different Ahitub: 1 Chronicles 6:7–8 places Zadok's father in Eleazar's line.`,
  refs:["2 Samuel 8:17","2 Samuel 15:24–36","2 Samuel 17:15","2 Samuel 19:11","2 Samuel 20:25","1 Kings 1:32–45","1 Kings 2:35","1 Chronicles 6:3–8","1 Chronicles 16:39","1 Chronicles 24:3","1 Chronicles 29:22","Ezekiel 40:46","Ezekiel 44:15","Ezekiel 48:11"]},

 {id:"ahimaaz_z", name:"Ahimaaz son of Zadok", short:"Ahimaaz", cat:"priest", w:6,
  dates:"c. 10th c. BC (traditional)",
  desc:`Zadok's son, who with Jonathan son of Abiathar hides in a well at Bahurim and brings David Hushai's warning. After the battle he outruns the Cushite to David but cannot bring himself to say that Absalom is dead.`,
  notconfused:`Ahimaaz the father of Saul's wife Ahinoam (1 Samuel 14:50).`,
  refs:["2 Samuel 15:27–36","2 Samuel 17:17–21","2 Samuel 18:19–30"]},

 {id:"jonathan_a", name:"Jonathan son of Abiathar", short:"Jonathan (Abiathar's son)", cat:"priest", w:5,
  clash:"Jonathan", clashtag:"Abiathar's son, a messenger for David during Absalom's revolt.",
  dates:"c. 10th c. BC (traditional)",
  desc:`With Ahimaaz son of Zadok, a messenger who hides in a well at Bahurim and carries Hushai's warning to David.`,
  refs:["2 Samuel 15:27","2 Samuel 15:36","2 Samuel 17:17–21"]},

 {id:"uzzah", name:"Uzzah son of Abinadab", short:"Uzzah", cat:"judg", w:5,
  dates:"c. 10th c. BC (traditional)",
  desc:`With his brother Ahio, he guides the new cart bringing the ark from Abinadab's house. When the oxen stumble he takes hold of the ark, and "God struck him down, and he died there beside the ark of God"; the place is called Perez Uzzah.`,
  refs:["2 Samuel 6:3–8"]},

 {id:"ahio", name:"Ahio son of Abinadab", short:"Ahio", cat:"judg", w:4,
  dates:"c. 10th c. BC (traditional)",
  desc:`Uzzah's brother, who walked in front of the ark on the new cart.`,
  refs:["2 Samuel 6:3–4"]},

 {id:"obededom", name:"Obed-Edom the Gittite", short:"Obed-Edom", cat:"king", w:5,
  dates:"c. 10th c. BC (traditional)",
  desc:`In whose house David leaves the ark for three months after Uzzah's death; "the LORD blessed him and his entire household," and David then brings the ark up to the City of David. Chronicles also lists an Obed-Edom among the Levite musicians and gatekeepers — "Obed-Edom son of Jeduthun" — whose sons were many, "for God had blessed Obed-Edom"; it does not say outright whether he is the Gittite.`,
  refs:["2 Samuel 6:10–12","1 Chronicles 13:13–14","1 Chronicles 15:18–25","1 Chronicles 16:38","1 Chronicles 26:4–8"]},

 {id:"ittai", name:"Ittai the Gittite", short:"Ittai", cat:"king", w:6,
  dates:"c. 10th c. BC (traditional)",
  desc:`A foreigner from Gath who refuses to leave David when he flees: "wherever my lord the king may be, whether it means life or death, there will your servant be." He commands a third of David's army against Absalom.`,
  refs:["2 Samuel 15:18–22","2 Samuel 18:2–5"]},

 {id:"hushai", name:"Hushai the Arkite", short:"Hushai", cat:"king", w:7,
  dates:"c. 10th c. BC (traditional)",
  desc:`"David's confidant," sent back to Jerusalem to serve Absalom and frustrate Ahithophel's advice. His counsel to wait and gather all Israel prevails — "the LORD had determined to frustrate the good advice of Ahithophel" — and he warns David through the priests.`,
  refs:["2 Samuel 15:32–37","2 Samuel 16:16–19","2 Samuel 17:5–16"]},

 {id:"ahithophel", name:"Ahithophel the Gilonite", short:"Ahithophel", cat:"king", w:7,
  dates:"c. 10th c. BC (traditional)",
  desc:`David's counselor, whose advice "was like that of one who inquires of God," who joins Absalom's conspiracy. He tells Absalom to sleep with his father's concubines and to strike David at once; when Hushai's advice is chosen instead, he goes home, puts his house in order and hangs himself. Eliam son of Ahithophel is listed among David's Thirty.`,
  refs:["2 Samuel 15:12","2 Samuel 15:31","2 Samuel 16:20–23","2 Samuel 17:1–23","2 Samuel 23:34"]},

 {id:"shimei", name:"Shimei son of Gera", short:"Shimei", cat:"king", w:6,
  dates:"c. 10th c. BC (traditional)",
  desc:`A Benjamite of Saul's clan who pelts the fleeing David with stones and curses — "Get out, get out, you murderer!" David restrains Abishai: "let him curse, for the LORD has told him to." On David's return Shimei falls before him, and David swears, "You shall not die."`,
  refs:["2 Samuel 16:5–13","2 Samuel 19:16–23"]},

 {id:"amasa", name:"Amasa son of Jether", short:"Amasa", cat:"king", w:6,
  dates:"c. 10th c. BC (traditional)",
  desc:`Absalom's commander "in place of Joab," son of Jether, an Ishmaelite, and of "Abigail, the daughter of Nahash and sister of Zeruiah." David later promises him command of his army, but when he is slow to summon Judah against Sheba, Joab greets him — "How are you, my brother?" — and stabs him. 1 Chronicles 2:17 names his parents as Abigail, David's sister, and "Jether the Ishmaelite."`,
  refs:["2 Samuel 17:25","2 Samuel 19:13","2 Samuel 20:4–12","1 Chronicles 2:16–17"]},

 {id:"barzillai", name:"Barzillai the Gileadite", short:"Barzillai", cat:"king", w:6,
  dates:"c. 10th c. BC (traditional)",
  desc:`"A very wealthy man" of Rogelim, eighty years old, who provides for David at Mahanaim. Invited to Jerusalem, he declines — "Can your servant taste what he eats and drinks?" — and sends his servant Kimham instead.`,
  refs:["2 Samuel 17:27–29","2 Samuel 19:31–39"]},

 {id:"sheba_b", name:"Sheba son of Bikri", short:"Sheba", cat:"king", w:6,
  dates:"c. 10th c. BC (traditional)",
  desc:`"A troublemaker," a Benjamite who sounds the trumpet — "We have no share in David… Every man to his tent, Israel!" — and leads Israel away. Besieged in Abel Beth Maakah, he is beheaded by the townspeople on the advice of a wise woman, and his head is thrown to Joab.`,
  refs:["2 Samuel 20:1–22"]},

 {id:"wisewoman_tekoa", name:"The wise woman of Tekoa", short:"Wise woman of Tekoa", cat:"king", w:5,
  dates:"c. 10th c. BC (traditional)",
  desc:`Brought by Joab to tell David a story of two sons, one of whom killed the other, so that he would bring the banished Absalom home: "God… devises ways so that a banished person does not remain banished from him." Unnamed in Scripture.`,
  refs:["2 Samuel 14:1–20"]},

 {id:"wisewoman_abel", name:"The wise woman of Abel", short:"Wise woman of Abel", cat:"king", w:5,
  dates:"c. 10th c. BC (traditional)",
  desc:`A woman of Abel Beth Maakah who calls to Joab from the wall — "You are trying to destroy a city that is a mother in Israel" — and persuades her town to throw Sheba's head to him. Unnamed in Scripture.`,
  refs:["2 Samuel 20:16–22"]},

 {id:"benaiah", name:"Benaiah son of Jehoiada", short:"Benaiah", cat:"king", w:8,
  dates:"c. 10th c. BC (traditional)",
  desc:`"A valiant fighter from Kabzeel," over David's Kerethites and Pelethites and in charge of his bodyguard. He struck down Moab's two mightiest warriors, "went down into a pit on a snowy day and killed a lion," and killed a huge Egyptian with his own spear. He executes Adonijah, Joab and Shimei for Solomon and replaces Joab over the army. 1 Chronicles 27:5 calls him "son of Jehoiada the priest," commander for the third month.`,
  refs:["2 Samuel 8:18","2 Samuel 20:23","2 Samuel 23:20–23","1 Kings 2:25–46","1 Chronicles 11:22–25","1 Chronicles 27:5–6"]},

 {id:"jehoshaphat_r", name:"Jehoshaphat son of Ahilud", short:"Jehoshaphat (recorder)", cat:"king", w:4,
  clash:"Jehoshaphat", clashtag:"David's (and Solomon's) recorder.",
  dates:"c. 10th c. BC (traditional)",
  desc:`David's recorder, listed among his officials.`,
  refs:["2 Samuel 8:16","2 Samuel 20:24","1 Kings 4:3"]},

 {id:"uriah", name:"Uriah the Hittite", short:"Uriah", cat:"king", w:7,
  clash:"Uriah", clashtag:"The Hittite, Bathsheba's husband, whom David had killed.",
  dates:"c. 10th c. BC (traditional)",
  desc:`Husband of Bathsheba and one of David's Thirty. Called home from the siege of Rabbah, he will not go to his house: "How could I go to my house to eat and drink and make love to my wife?" He carries David's own letter to Joab — "Put Uriah out in front where the fighting is fiercest" — and is killed.`,
  refs:["2 Samuel 11","2 Samuel 12:9–10","2 Samuel 23:39"]},

 {id:"josheb", name:"Josheb-Basshebeth", short:"Josheb-Basshebeth", cat:"king", w:5,
  aliases:"Jashobeam (1 Chronicles 11:11)",
  dates:"c. 10th c. BC (traditional)",
  desc:`"A Tahkemonite," chief of the Three among David's mighty warriors, who "raised his spear against eight hundred men, whom he killed in one encounter." The parallel list in 1 Chronicles 11:11 names the chief "Jashobeam, a Hakmonite," who "raised his spear against three hundred men."`,
  refs:["2 Samuel 23:8","1 Chronicles 11:11"]},

 {id:"eleazar_d", name:"Eleazar son of Dodai", short:"Eleazar (mighty man)", cat:"king", w:5,
  clash:"Eleazar", clashtag:"One of David's Three, who fought until his hand froze to his sword.",
  dates:"c. 10th c. BC (traditional)",
  desc:`"The Ahohite," one of the Three, who stood his ground against the Philistines "till his hand grew tired and froze to the sword."`,
  refs:["2 Samuel 23:9–10"]},

 {id:"shammah_a", name:"Shammah son of Agee", short:"Shammah (mighty man)", cat:"king", w:5,
  clash:"Shammah", clashtag:"One of David's Three, who defended a field of lentils alone.",
  dates:"c. 10th c. BC (traditional)",
  desc:`"The Hararite," one of the Three, who took his stand in a field full of lentils when Israel fled, "and the LORD brought about a great victory."`,
  notconfused:`Shammah son of Jesse, David's brother (1 Samuel 16:9).`,
  refs:["2 Samuel 23:11–12"]},

 {id:"adonijah", name:"Adonijah son of David", short:"Adonijah", cat:"king", w:7,
  dates:"c. 10th c. BC (traditional)",
  desc:`David's fourth son, by Haggith, "born next after Absalom" and "very handsome"; his father "had never rebuked him." As David lies old he declares, "I will be king," backed by Joab and Abiathar, and holds a feast at En Rogel. When Nathan and Bathsheba secure Solomon's anointing, he clings to the horns of the altar and is spared — until he asks for Abishag as his wife, and Solomon has Benaiah strike him down.`,
  refs:["2 Samuel 3:4","1 Kings 1:5–53","1 Kings 2:13–25"]},


 {id:"solomon", name:"Solomon son of David", short:"Solomon", cat:"king", w:14, halo:1,
  aliases:"Jedidiah",
  dates:"reigned 40 years, c. 970 – 931 BC (1 Kings 11:42)",
  desc:`Son of David and Bathsheba, named Jedidiah because "the LORD loved him." Anointed at Gihon by Zadok and Nathan when Adonijah claims the throne, he secures his rule by executing Adonijah, Joab and Shimei and banishing Abiathar. At Gibeon he asks for "a discerning heart to govern your people," and God adds wealth and honor; his ruling between two mothers shows "wisdom from God to administer justice." He speaks three thousand proverbs and 1,005 songs, builds the temple in seven years — begun "in the four hundred and eightieth year after the Israelites came out of Egypt" — and prays at its dedication, "will God really dwell on earth?" The queen of Sheba finds that "not even half was told me." But his many foreign wives "turned his heart after other gods," and the LORD tears ten tribes from his son, raising up Hadad, Rezon and Jeroboam against him. 2 Chronicles places the temple "on Mount Moriah… on the threshing floor of Araunah"; at its dedication "fire came down from heaven," and the LORD answers, "if my people, who are called by my name, will humble themselves and pray… then I will hear from heaven." Psalms 72 and 127 are headed "Of Solomon." Proverbs opens, "The proverbs of Solomon son of David, king of Israel," and adds "more proverbs of Solomon, compiled by the men of Hezekiah king of Judah." The Song of Songs is titled "Solomon's Song of Songs" and pictures "King Solomon wearing a crown, the crown with which his mother crowned him on the day of his wedding."`,
  notconfused:`The "Teacher, son of David, king in Jerusalem" of Ecclesiastes, traditionally identified with him; the book itself does not name Solomon.`,
  refs:["2 Samuel 12:24–25","1 Kings 1–11","1 Chronicles 22","1 Chronicles 28–29","2 Chronicles 1–9","Psalm 72","Psalm 127","Proverbs 1:1","Proverbs 10:1","Proverbs 25:1","Song of Songs 1:1","Song of Songs 3:6–11"]},

 {id:"rehoboam", name:"Rehoboam son of Solomon", short:"Rehoboam", cat:"king", w:8,
  dates:"reigned 17 years, c. 931 – 913 BC (Judah)",
  desc:`Solomon's son by Naamah the Ammonite. At Shechem he rejects the elders' advice and answers Israel harshly — "My father scourged you with whips; I will scourge you with scorpions" — and the northern tribes cry, "To your tents, Israel!" and make Jeroboam king. Shemaiah stops him from going to war. In his fifth year Shishak of Egypt plunders Jerusalem; he replaces Solomon's gold shields with bronze. "There was continual warfare between Rehoboam and Jeroboam."`,
  refs:["1 Kings 11:43","1 Kings 12:1–24","1 Kings 14:21–31"]},

 {id:"jeroboam1", name:"Jeroboam son of Nebat", short:"Jeroboam I", cat:"king", w:9,
  clash:"Jeroboam", clashtag:"The official who led the northern tribes away and made the first king of divided Israel; set up the golden calves.",
  dates:"reigned 22 years, c. 931 – 910 BC (Israel)",
  desc:`"An Ephraimite from Zeredah," whose mother was a widow named Zeruah; put in charge of the labor force of the tribes of Joseph. Ahijah tears his cloak and gives him ten pieces — ten tribes. He flees from Solomon to Shishak in Egypt, returns, and is made king of Israel. Fearing his people will turn back to Jerusalem, he sets up golden calves at Bethel and Dan — "Here are your gods, Israel" — appoints non-Levite priests and a festival of his own choosing. A man of God from Judah denounces his altar; Ahijah foretells the end of his house. "This was the sin of the house of Jeroboam."`,
  notconfused:`Jeroboam II, a later and more prosperous king of the same northern kingdom.`,
  refs:["1 Kings 11:26–40","1 Kings 12–14"]},

 // ================= 1 KINGS =================
 // Sourced chapter-by-chapter from the NIV on bible.com (1 Kings 1–22).
 {id:"abishag", name:"Abishag the Shunammite", short:"Abishag", cat:"king", w:6,
  dates:"c. 970 BC (traditional)",
  desc:`"A beautiful young woman" brought to care for the aged David, "but the king had no sexual relations with her." When Adonijah asks for her as his wife, Solomon replies, "You might as well request the kingdom for him," and has him killed.`,
  refs:["1 Kings 1:1–4","1 Kings 1:15","1 Kings 2:13–25"]},

 {id:"adoniram", name:"Adoniram son of Abda", short:"Adoniram", cat:"king", w:5,
  dates:"c. 10th c. BC (traditional)",
  desc:`In charge of forced labor under David and Solomon. When Rehoboam sends him out to the rebellious northern tribes, "all Israel stoned him to death."`,
  refs:["2 Samuel 20:24","1 Kings 4:6","1 Kings 5:14","1 Kings 12:18"]},

 {id:"ahijah_sh", name:"Ahijah the Shilonite", short:"Ahijah (prophet)", cat:"proph", w:7,
  clash:"Ahijah", clashtag:"The prophet of Shiloh who tore his cloak into twelve pieces and gave Jeroboam ten.",
  dates:"c. 10th c. BC",
  desc:`"The prophet of Shiloh," who meets Jeroboam on the road, tears his new cloak into twelve pieces and tells him, "Take ten pieces for yourself… I am going to tear the kingdom out of Solomon's hand." Years later, old and blind, he recognizes Jeroboam's disguised wife and announces disaster on Jeroboam's house and the death of their son.`,
  notconfused:`Ahijah son of Ahitub, the priest with Saul's army (1 Samuel 14:3).`,
  refs:["1 Kings 11:29–39","1 Kings 12:15","1 Kings 14:1–18","1 Kings 15:29"]},

 {id:"shemaiah", name:"Shemaiah the man of God", short:"Shemaiah", cat:"proph", w:5,
  clash:"Shemaiah", clashtag:"The man of God who stopped Rehoboam's war and warned him about Shishak.",
  dates:"c. 10th c. BC",
  desc:`"The man of God" who tells Rehoboam and the army of Judah and Benjamin, "Do not go up to fight against your brothers, the Israelites… this is my doing" — and they go home. In 2 Chronicles he also tells Rehoboam, "You have abandoned me; therefore, I now abandon you to Shishak," and when they humble themselves, that Jerusalem will not be destroyed. His records cover Rehoboam's reign.`,
  notconfused:`Shemaiah son of Delaiah, the prophet hired to frighten Nehemiah (Nehemiah 6:10).`,
  refs:["1 Kings 12:21–24","2 Chronicles 11:2–4","2 Chronicles 12:5–8","2 Chronicles 12:15"]},

 {id:"manofgod_judah", name:"The man of God from Judah", short:"Man of God from Judah", cat:"proph", w:6,
  dates:"c. 10th c. BC",
  desc:`Sent to Bethel, he cries out against Jeroboam's altar that "a son named Josiah will be born to the house of David" who will burn the priests' bones on it; the altar splits and Jeroboam's hand shrivels. Deceived by an old prophet into eating in Bethel against the LORD's command, he is killed by a lion on the road. Unnamed in Scripture.`,
  refs:["1 Kings 13"]},

 {id:"oldprophet_bethel", name:"The old prophet of Bethel", short:"Old prophet of Bethel", cat:"proph", w:5,
  dates:"c. 10th c. BC",
  desc:`A prophet living in Bethel who lies to the man of God from Judah — "an angel said to me…" — and brings him home to eat, then pronounces his doom. He buries him in his own tomb and asks to be buried beside him. Unnamed in Scripture.`,
  refs:["1 Kings 13:11–32"]},

 {id:"abijah_j", name:"Abijah son of Jeroboam", short:"Abijah (Jeroboam's son)", cat:"king", w:4,
  clash:"Abijah", clashtag:"Jeroboam's son who died as a boy — 'the only one in the house of Jeroboam in whom the LORD… found anything good.'",
  dates:"c. 10th c. BC",
  desc:`Jeroboam's son, whose illness sends his disguised mother to Ahijah; he dies as she steps over her threshold, "the only one in the house of Jeroboam in whom the LORD, the God of Israel, has found anything good."`,
  refs:["1 Kings 14:1–18"]},

 {id:"naamah_a", name:"Naamah the Ammonite", short:"Naamah (Rehoboam's mother)", cat:"king", w:4,
  clash:"Naamah", clashtag:"Rehoboam's mother, an Ammonite.",
  dates:"c. 10th c. BC",
  desc:`"His mother's name was Naamah; she was an Ammonite" — the mother of Rehoboam, named twice in his reign summary.`,
  notconfused:`Naamah, Tubal-Cain's sister in Cain's line (Genesis 4:22).`,
  refs:["1 Kings 14:21","1 Kings 14:31"]},

 {id:"abijah_k", name:"Abijah king of Judah", short:"Abijah (king)", cat:"king", w:6,
  clash:"Abijah", clashtag:"Rehoboam's son and successor, king of Judah for three years.",
  dates:"reigned 3 years, c. 913 – 910 BC (Judah)",
  desc:`Son of Rehoboam, king of Judah three years; "he committed all the sins his father had done." Yet "for David's sake the LORD his God gave him a lamp in Jerusalem." There was war between him and Jeroboam. 2 Chronicles gives his speech on Mount Zemaraim — "God is with us; he is our leader" — and Judah's victory over Jeroboam, who "did not regain power during the time of Abijah." He married fourteen wives.`,
  refs:["1 Kings 14:31","1 Kings 15:1–8","2 Chronicles 13"]},

 {id:"maakah_ab", name:"Maakah daughter of Abishalom", short:"Maakah (queen mother)", cat:"king", w:5,
  clash:"Maakah", clashtag:"Mother of King Abijah and grandmother of Asa, deposed as queen mother for an Asherah image.",
  dates:"c. 10th c. BC",
  desc:`Mother of Abijah and "grandmother" of Asa, who "deposed his grandmother Maakah from her position as queen mother, because she had made a repulsive image for the worship of Asherah." 2 Chronicles calls her "Maakah daughter of Absalom," the wife Rehoboam "loved… more than any of his other wives," and also "Maakah, a daughter of Uriel of Gibeah"; the text does not reconcile the two.`,
  refs:["1 Kings 15:2","1 Kings 15:10–13","2 Chronicles 11:20–22","2 Chronicles 13:2","2 Chronicles 15:16"]},

 {id:"asa", name:"Asa king of Judah", short:"Asa", cat:"king", w:8,
  dates:"reigned 41 years, c. 910 – 869 BC (Judah)",
  desc:`Abijah's son, who "did what was right in the eyes of the LORD, as his father David had done": he expels the shrine prostitutes, removes the idols and deposes Maakah. At war with Baasha, he sends the temple treasure to Ben-Hadad of Aram to break his treaty with Israel. "In his old age, however, his feet became diseased." 2 Chronicles adds his defeat of Zerah the Cushite after the prayer "Help us, LORD our God, for we rely on you," and a covenant to seek the LORD after Azariah son of Oded's prophecy. When he later relies on Aram, Hanani the seer rebukes him and is put in prison; in his foot disease "he did not seek help from the LORD, but only from the physicians." Jeremiah 41:9 says the cistern at Mizpah that Ishmael son of Nethaniah filled with the dead "was the one King Asa had made as part of his defense against Baasha king of Israel."`,
  refs:["1 Kings 15:8–24","2 Chronicles 14–16","Jeremiah 41:9"]},

 {id:"jehoshaphat_j", name:"Jehoshaphat king of Judah", short:"Jehoshaphat (king)", cat:"king", w:8,
  clash:"Jehoshaphat", clashtag:"Asa's son, a king of Judah who 'did what was right' and allied with Ahab at Ramoth Gilead.",
  dates:"reigned 25 years, c. 872 – 848 BC (Judah)",
  desc:`Son of Asa and Azubah, who "did what was right in the eyes of the LORD." At peace with Israel, he joins Ahab against Ramoth Gilead but insists, "First seek the counsel of the LORD," and asks for a true prophet, Micaiah. His trading fleet is wrecked at Ezion Geber. He marches with Joram of Israel against Moab, and Elisha helps for his sake. 2 Chronicles adds that he sent officials and Levites to teach the Book of the Law, appointed judges — "you are not judging for mere mortals but for the LORD" — and was rebuked by Jehu son of Hanani for helping Ahab. Facing Moab, Ammon and Edom he prayed, "We do not know what to do, but our eyes are on you," and through Jahaziel came the answer, "the battle is not yours, but God's." Eliezer son of Dodavahu foretold the wreck of the fleet he built with Ahaziah of Israel.`,
  notconfused:`Jehoshaphat son of Ahilud, recorder under David and Solomon (2 Samuel 8:16).`,
  refs:["1 Kings 15:24","1 Kings 22:1–50","2 Kings 3","2 Chronicles 17–20"]},

 {id:"nadab_k", name:"Nadab king of Israel", short:"Nadab (king)", cat:"king", w:5,
  clash:"Nadab", clashtag:"Jeroboam's son, who reigned two years before Baasha killed him.",
  dates:"reigned 2 years, c. 910 – 909 BC (Israel)",
  desc:`Son of Jeroboam, king of Israel two years; he "did evil," and Baasha strikes him down at Gibbethon and destroys Jeroboam's whole family, "according to the word of the LORD given through… Ahijah."`,
  notconfused:`Nadab son of Aaron, consumed by fire for offering unauthorized fire (Leviticus 10).`,
  refs:["1 Kings 14:20","1 Kings 15:25–31"]},

 {id:"baasha", name:"Baasha king of Israel", short:"Baasha", cat:"king", w:7,
  dates:"reigned 24 years, c. 909 – 886 BC (Israel)",
  desc:`"Baasha son of Ahijah from the tribe of Issachar," who kills Nadab and wipes out Jeroboam's house, then follows Jeroboam's ways. He fortifies Ramah against Asa until Ben-Hadad attacks Israel. The prophet Jehu son of Hanani announces that his house will be like Jeroboam's.`,
  refs:["1 Kings 15:16–34","1 Kings 16:1–7","Jeremiah 41:9"]},

 {id:"jehu_h", name:"Jehu son of Hanani", short:"Jehu (prophet)", cat:"proph", w:5,
  clash:"Jehu", clashtag:"The prophet who announced the end of Baasha's house.",
  dates:"c. 9th c. BC",
  desc:`The prophet through whom "the word of the LORD came… concerning Baasha": "I lifted you up from the dust… So I am about to wipe out Baasha and his house." Zimri fulfills it. "Jehu the seer, the son of Hanani" also rebukes Jehoshaphat — "Should you help the wicked?" — and writes the annals of his reign.`,
  notconfused:`Jehu son of Nimshi, the army commander anointed to destroy Ahab's dynasty (2 Kings 9).`,
  refs:["1 Kings 16:1–7","1 Kings 16:12","2 Chronicles 19:2–3","2 Chronicles 20:34"]},

 {id:"elah", name:"Elah king of Israel", short:"Elah", cat:"king", w:5,
  dates:"reigned 2 years, c. 886 – 885 BC (Israel)",
  desc:`Son of Baasha, king two years, killed while "getting drunk in the home of Arza, the palace administrator at Tirzah" by Zimri, one of his chariot commanders.`,
  refs:["1 Kings 16:6–14"]},

 {id:"zimri_k", name:"Zimri king of Israel", short:"Zimri (king)", cat:"king", w:5,
  clash:"Zimri", clashtag:"The chariot commander who killed Elah and reigned seven days before burning the palace around himself.",
  dates:"reigned 7 days, c. 885 BC (Israel)",
  desc:`A chariot commander who kills Elah and wipes out Baasha's family. He "reigned in Tirzah seven days"; when Omri besieges the city, he sets the palace on fire around himself and dies.`,
  refs:["1 Kings 16:9–20"]},

 {id:"tibni", name:"Tibni son of Ginath", short:"Tibni", cat:"king", w:4,
  dates:"c. 885 BC (Israel)",
  desc:`After Zimri's death "half supported Tibni son of Ginath for king, and the other half supported Omri. But Omri's followers proved stronger… So Tibni died and Omri became king."`,
  refs:["1 Kings 16:21–22"]},

 {id:"omri", name:"Omri king of Israel", short:"Omri", cat:"king", w:8,
  dates:"reigned 12 years, c. 885 – 874 BC (Israel)",
  desc:`Commander of Israel's army, proclaimed king in the camp when Zimri murders Elah. He buys the hill of Samaria from Shemer and builds the city of Samaria, but "sinned more than all those before him." Father of Ahab. Micah 6:16 condemns Judah: "You have observed the statutes of Omri and all the practices of Ahab's house."`,
  refs:["1 Kings 16:16–28","Micah 6:16"]},

 {id:"hiel", name:"Hiel of Bethel", short:"Hiel", cat:"king", w:4,
  dates:"c. 9th c. BC (Israel)",
  desc:`In Ahab's time he rebuilt Jericho, laying its foundations "at the cost of his firstborn son Abiram" and setting up its gates "at the cost of his youngest son Segub, in accordance with the word of the LORD spoken by Joshua son of Nun."`,
  refs:["1 Kings 16:34","Joshua 6:26"]},

 {id:"obadiah_a", name:"Obadiah, Ahab's palace administrator", short:"Obadiah (Ahab's steward)", cat:"king", w:6,
  clash:"Obadiah", clashtag:"Ahab's palace administrator, 'a devout believer in the LORD,' who hid a hundred prophets.",
  dates:"c. 9th c. BC (Israel)",
  desc:`Ahab's palace administrator, "a devout believer in the LORD," who hid a hundred of the LORD's prophets in two caves while Jezebel was killing them. Meeting Elijah, he fears to report him to Ahab, but carries the message.`,
  notconfused:`Obadiah the prophet, author of the short book against Edom.`,
  refs:["1 Kings 18:3–16"]},

 {id:"widow_zarephath", name:"The widow of Zarephath", short:"Widow of Zarephath", cat:"proph", w:6,
  dates:"c. 9th c. BC",
  desc:`A widow in Sidonian Zarephath who, with only a handful of flour and a little oil, bakes bread first for Elijah: "The jar of flour will not be used up and the jug of oil will not run dry." When her son dies, Elijah stretches himself on him and he lives — "Now I know that you are a man of God." Unnamed in Scripture.`,
  refs:["1 Kings 17:8–24"]},

 {id:"naboth", name:"Naboth the Jezreelite", short:"Naboth", cat:"king", w:6,
  dates:"c. 9th c. BC (Israel)",
  desc:`Owner of a vineyard next to Ahab's palace in Jezreel, who refuses to sell it: "The LORD forbid that I should give you the inheritance of my ancestors." Jezebel has two scoundrels accuse him of cursing God and the king, and he is stoned; Elijah announces that dogs will lick up Ahab's blood in the same place.`,
  refs:["1 Kings 21","2 Kings 9:21–26"]},

 {id:"micaiah", name:"Micaiah son of Imlah", short:"Micaiah", cat:"proph", w:7,
  clash:"Micaiah", clashtag:"Son of Imlah, the prophet who foretold Ahab's death.",
  dates:"c. 9th c. BC",
  desc:`The prophet Ahab hates "because he never prophesies anything good about me." Summoned before Ahab and Jehoshaphat, he says, "I can tell him only what the LORD tells me," and describes Israel "scattered on the hills like sheep without a shepherd" and a deceiving spirit in the mouths of Ahab's prophets. Slapped by Zedekiah and imprisoned, he declares, "If you ever return safely, the LORD has not spoken through me." Ahab dies at Ramoth Gilead.`,
  refs:["1 Kings 22:7–28"]},

 {id:"zedekiah_k", name:"Zedekiah son of Kenaanah", short:"Zedekiah (prophet)", cat:"proph", w:5,
  clash:"Zedekiah", clashtag:"One of Ahab's prophets, who made iron horns and slapped Micaiah.",
  dates:"c. 9th c. BC",
  desc:`One of Ahab's four hundred prophets, who makes iron horns — "With these you will gore the Arameans" — and slaps Micaiah in the face.`,
  notconfused:`Zedekiah the last king of Judah (2 Kings 24–25).`,
  refs:["1 Kings 22:11","1 Kings 22:24–25"]},


 {id:"ahab", name:"Ahab son of Omri", short:"Ahab", cat:"king", w:11,
  clash:"Ahab", clashtag:"Son of Omri, king of Israel, husband of Jezebel.",
  dates:"reigned 22 years, c. 874 – 853 BC (Israel)",
  desc:`King of Israel in Samaria, who "did more evil in the eyes of the LORD than any of those before him": he marries Jezebel daughter of Ethbaal, builds a temple of Baal and an Asherah pole. Elijah announces a drought and calls down fire on Mount Carmel — "Is that you, you troubler of Israel?" He defeats Ben-Hadad twice but lets him go. When Jezebel has Naboth killed for his vineyard, Elijah says dogs will lick up his blood; Ahab humbles himself in sackcloth and the disaster is delayed to his son's days. Ignoring Micaiah, he goes in disguise to Ramoth Gilead, is hit by a random arrow, and dies; dogs lick his blood from the chariot.`,
  refs:["1 Kings 16:28–34","1 Kings 18","1 Kings 20–22","Micah 6:16"]},

 {id:"jezebel", name:"Jezebel daughter of Ethbaal", short:"Jezebel", cat:"king", w:9,
  dates:"c. 9th c. BC (Israel)",
  desc:`"Jezebel daughter of Ethbaal king of the Sidonians," whose marriage to Ahab comes with his turn to "serve Baal." She kills off the LORD's prophets, feeds the prophets of Baal and Asherah "at Jezebel's table," and after Carmel vows to take Elijah's life. She has Naboth falsely accused and stoned so Ahab can take his vineyard; Elijah foretells that dogs will devour her at Jezreel. Mother of King Joram, she is thrown from a window when Jehu enters Jezreel — "you Zimri, you murderer of your master" — and only her skull, feet and hands are found.`,
  refs:["1 Kings 16:31","1 Kings 18:4","1 Kings 18:19","1 Kings 19:1–2","1 Kings 21","2 Kings 9:22","2 Kings 9:30–37"]},

 {id:"jehu", name:"Jehu son of Nimshi", short:"Jehu", cat:"king", w:9,
  clash:"Jehu", clashtag:"Son of Jehoshaphat, son of Nimshi: the commander anointed to destroy Ahab's house.",
  dates:"reigned 28 years, c. 841 – 814 BC (Israel)",
  desc:`An army commander at Ramoth Gilead — "Jehu son of Jehoshaphat, the son of Nimshi" — anointed by a young prophet sent by Elisha: "You are to destroy the house of Ahab." Driving "like a maniac" to Jezreel, he shoots Joram, has Ahaziah of Judah struck down and Jezebel thrown from a window. He has Ahab's seventy sons killed, takes Jehonadab son of Rekab into his chariot, then calls a great sacrifice for Baal and slaughters its servants: "So Jehu destroyed Baal worship in Israel." Yet he keeps the golden calves of Bethel and Dan. The LORD promises his descendants the throne "to the fourth generation," while Hazael begins to take Israel's land. A century later Hosea names his first son Jezreel, "because I will soon punish the house of Jehu for the massacre at Jezreel."`,
  notconfused:`Jehu son of Hanani, the prophet who denounced Baasha. His father Jehoshaphat son of Nimshi is not Jehoshaphat king of Judah.`,
  refs:["1 Kings 19:16–17","2 Kings 9–10","2 Kings 15:12","Hosea 1:4"]},

 {id:"athaliah", name:"Athaliah", short:"Athaliah", cat:"king", w:8,
  dates:"ruled 6 years, c. 841 – 835 BC (Judah)",
  desc:`Mother of King Ahaziah of Judah, "a granddaughter of Omri king of Israel." When her son is killed, "she proceeded to destroy the whole royal family" and rules the land six years — but the infant Joash is hidden in the temple by Jehosheba. In the seventh year the priest Jehoiada crowns Joash; Athaliah tears her robes crying "Treason! Treason!" and is put to death where the horses enter the palace grounds.`,
  notconfused:`2 Kings 8:18 says her husband Jehoram "married a daughter of Ahab." She is the only wife of his named, but the text does not state the identification outright.`,
  refs:["2 Kings 8:18","2 Kings 8:26","2 Kings 11"]},

 {id:"jehoram_judah", name:"Jehoram son of Jehoshaphat", short:"Jehoram (Judah)", cat:"king", w:7,
  aliases:"Joram of Judah",
  clash:"Joram", clashtag:"King of Judah, son of Jehoshaphat, who 'married a daughter of Ahab.'",
  dates:"reigned 8 years, c. 848 – 841 BC (Judah)",
  desc:`King of Judah at 32. "He followed the ways of the kings of Israel… for he married a daughter of Ahab," yet for David's sake the LORD will not destroy Judah, having promised "to maintain a lamp for David." In his time Edom rebels and sets up its own king, and Libnah revolts. His son Ahaziah succeeds him; his daughter Jehosheba later saves the infant Joash. 2 Chronicles adds that he put all his brothers to the sword, built high places, received a letter of judgment from Elijah, lost his wives and all his sons but Ahaziah to Philistine and Arab raiders, and died of a disease of the bowels, "to no one's regret."`,
  notconfused:`Joram (Jehoram) of Israel, son of Ahab, reigning at the same time in the north.`,
  refs:["1 Kings 22:50","2 Kings 8:16–24","2 Kings 11:2","2 Chronicles 21"]},

 {id:"joram_israel", name:"Joram son of Ahab", short:"Joram (Israel)", cat:"king", w:7,
  aliases:"Jehoram of Israel",
  clash:"Joram", clashtag:"King of Israel, son of Ahab and Jezebel; shot by Jehu at Jezreel.",
  dates:"reigned 12 years, c. 852 – 841 BC (Israel)",
  desc:`Son of Ahab who does evil, "but not as his father and mother had done": he removes Baal's sacred stone yet clings to Jeroboam's sins. With Jehoshaphat of Judah and the king of Edom he marches against Mesha of Moab; Elisha helps only out of respect for Jehoshaphat. Wounded by Hazael's Arameans at Ramoth Gilead, he recovers at Jezreel, where Jehu shoots him "between the shoulders," and his body is thrown on Naboth's field. The "king of Israel" in the Naaman and Samaria-siege stories (2 Kings 5–7) is not named.`,
  notconfused:`Jehoram (Joram) of Judah, son of Jehoshaphat, reigning at the same time in the south.`,
  refs:["2 Kings 1:17","2 Kings 3","2 Kings 8:28–29","2 Kings 9:14–26"]},

 {id:"ahaziah_israel", name:"Ahaziah son of Ahab", short:"Ahaziah (Israel)", cat:"king", w:6,
  clash:"Ahaziah", clashtag:"Short-reigning king of Israel, son of Ahab; injured in a fall, he consulted Baal-Zebub and was rebuked by Elijah.",
  dates:"reigned 2 years, c. 853 – 852 BC (Israel)",
  desc:`Son of Ahab, who "reigned over Israel two years," following "the ways of his father and mother" and serving Baal. Injured in a fall "through the lattice of his upper room in Samaria," he sends to consult Baal-Zebub, the god of Ekron. Elijah intercepts the messengers — "Is it because there is no God in Israel?" — and, after fire consumes two companies sent to seize him, tells the king to his face he will die. He has no son, and Joram succeeds him.`,
  notconfused:`Ahaziah of Judah, son of Jehoram, killed by Jehu about a decade later.`,
  refs:["1 Kings 22:51–53","2 Kings 1"]},

 {id:"ahaziah_judah", name:"Ahaziah son of Jehoram", short:"Ahaziah (Judah)", cat:"king", w:6,
  clash:"Ahaziah", clashtag:"King of Judah for one year, son of Jehoram and Athaliah; killed in Jehu's revolt.",
  dates:"reigned 1 year, c. 841 BC (Judah)",
  desc:`King of Judah at 22; "his mother's name was Athaliah, a granddaughter of Omri," and he "was related by marriage to Ahab's family." He fights beside Joram of Israel against Hazael at Ramoth Gilead and visits the wounded Joram at Jezreel. When Jehu strikes he flees, is wounded near Ibleam and dies at Megiddo, and is buried in the City of David. Jehu later kills forty-two of his relatives at Beth Eked. 2 Chronicles says his mother "encouraged him to act wickedly," and that he was captured "hiding in Samaria" and brought to Jehu; he was buried because "He was a son of Jehoshaphat."`,
  notconfused:`Ahaziah of Israel, son of Ahab.`,
  refs:["2 Kings 8:24–29","2 Kings 9:16–29","2 Kings 10:12–14","2 Chronicles 22:1–9"]},

 {id:"joash_judah", name:"Joash son of Ahaziah", short:"Joash (Judah)", cat:"king", w:7,
  aliases:"Jehoash of Judah",
  clash:"Joash", clashtag:"The boy-king of Judah hidden from Athaliah and crowned by the priest Jehoiada; repaired the temple.",
  dates:"reigned 40 years, c. 835 – 796 BC (Judah)",
  desc:`Rescued as a baby by his aunt Jehosheba when Athaliah kills the royal family, and hidden "at the temple of the LORD for six years." At seven he is crowned by the priest Jehoiada. His mother was Zibiah of Beersheba. He "did what was right… all the years Jehoiada the priest instructed him," and repairs the temple with money from a collection chest. He strips the temple treasuries to buy off Hazael, and is assassinated by his officials Jozabad and Jehozabad at Beth Millo. 2 Chronicles adds that after Jehoiada's death he turned to idols and had Jehoiada's son Zechariah stoned.`,
  notconfused:`Jehoash (Joash) of Israel, son of Jehoahaz, who reigned a generation later; and Joash the Abiezrite, Gideon's father.`,
  refs:["2 Kings 11–12","2 Chronicles 24"]},

 {id:"jehoash_israel", name:"Jehoash son of Jehoahaz", short:"Jehoash (Israel)", cat:"king", w:7,
  aliases:"Joash of Israel",
  clash:"Joash", clashtag:"King of Israel, grandson of Jehu, who wept at Elisha's deathbed and defeated Amaziah.",
  dates:"reigned 16 years, c. 798 – 782 BC (Israel)",
  desc:`Grandson of Jehu, who "did evil in the eyes of the LORD." He weeps at the dying Elisha's bedside — "My father! My father! The chariots and horsemen of Israel!" — and shoots "the LORD's arrow of victory," but strikes the ground only three times; so he defeats Ben-Hadad son of Hazael three times and recovers Israel's towns. Challenged by Amaziah of Judah, he answers with the parable of the thistle and the cedar, captures Amaziah at Beth Shemesh, breaks down Jerusalem's wall and carries off the temple's gold and silver.`,
  notconfused:`Joash of Judah, son of Ahaziah, the earlier boy-king of the same name.`,
  refs:["2 Kings 13:9–25","2 Kings 14:8–16"]},

 {id:"jeroboam2", name:"Jeroboam son of Jehoash", short:"Jeroboam II", cat:"king", w:8,
  clash:"Jeroboam", clashtag:"Jeroboam son of Jehoash, who restored Israel's borders; Amos and Hosea prophesied in his reign.",
  dates:"reigned 41 years, c. 793 – 753 BC (Israel)",
  desc:`King in Samaria, who "did evil in the eyes of the LORD." Even so, "he restored the boundaries of Israel from Lebo Hamath to the Dead Sea," as the LORD had spoken "through his servant Jonah son of Amittai," because the LORD "had seen how bitterly everyone in Israel… was suffering." He recovers Damascus and Hamath. The prophets Amos and Hosea date their ministries to his reign. Amos is shown a plumb line — "with my sword I will rise against the house of Jeroboam" — and Amaziah the priest of Bethel reports to the king that Amos is saying, "Jeroboam will die by the sword."`,
  notconfused:`Jeroboam son of Nebat (Jeroboam I), the first king of the northern kingdom.`,
  refs:["2 Kings 14:16","2 Kings 14:23–29","Amos 1:1","Hosea 1:1","Amos 7:9–11"]},

 {id:"zechariah_k", name:"Zechariah son of Jeroboam", short:"Zechariah (King)", cat:"king", w:6,
  clash:"Zechariah", clashtag:"Son of Jeroboam II and last king of Jehu's dynasty; reigned six months before he was assassinated.",
  dates:"reigned 6 months, c. 753 BC (Israel)",
  desc:`King in Samaria for six months, who does evil "as his predecessors had done." Shallum son of Jabesh assassinates him "in front of the people," and so the word to Jehu is fulfilled: "Your descendants will sit on the throne of Israel to the fourth generation."`,
  notconfused:`Zechariah the post-exilic prophet, and Zechariah the father of John the Baptist in the New Testament.`,
  refs:["2 Kings 14:29","2 Kings 15:8–12"]},

 {id:"uzziah", name:"Azariah (Uzziah) son of Amaziah", short:"Uzziah", cat:"king", w:8,
  clash:"Azariah", clashtag:"King of Judah, called Azariah in most of 2 Kings and Uzziah elsewhere.",
  aliases:"Azariah",
  dates:"reigned 52 years, c. 792 – 740 BC (Judah)",
  desc:`Called Azariah in most of 2 Kings and Uzziah in 2 Kings 15:13 and 15:30–34. Made king at sixteen by "all the people of Judah" after his father's murder, he rebuilds Elath and does "what was right in the eyes of the LORD," though the high places remain. "The LORD afflicted the king with leprosy until the day he died"; he lives in a separate house while his son Jotham governs. 2 Chronicles explains that "his pride led to his downfall" when he burned incense in the temple. Isaiah's vision is dated "in the year that King Uzziah died." He "sought God during the days of Zechariah, who instructed him"; Azariah the chief priest and eighty priests confronted him in the temple. Amos dates his vision "two years before the earthquake, when Uzziah was king of Judah"; Hosea's ministry also begins in his reign. Zechariah 14:5 recalls the same event: "You will flee as you fled from the earthquake in the days of Uzziah king of Judah."`,
  refs:["2 Kings 14:21–22","2 Kings 15:1–7","2 Chronicles 26","Isaiah 6:1","Isaiah 1:1","Hosea 1:1","Amos 1:1","Zechariah 14:5"]},

 {id:"hezekiah", name:"Hezekiah son of Ahaz", short:"Hezekiah", cat:"king", w:11,
  dates:"reigned 29 years, c. 715 – 686 BC (Judah) — start date disputed",
  desc:`He removes the high places and breaks up Moses' bronze snake, Nehushtan, to which Israel had burned incense: "There was no one like him among all the kings of Judah." He rebels against Assyria. When Sennacherib takes Judah's fortified cities he pays tribute, but when the field commander mocks the LORD he spreads the Assyrian letter "before the LORD" and prays. Through Isaiah the LORD promises deliverance, and the angel of the LORD strikes the Assyrian camp. Healed of a deadly illness with fifteen years added, he is given the sign of the shadow going back ten steps — then shows all his treasures to envoys from Babylon, and Isaiah foretells they will be carried there. He made the pool and tunnel that brought water into the city. 2 Chronicles adds that in his first month he reopened and purified the temple, invited all Israel to a Passover unlike any "since the days of Solomon," and "blocked the upper outlet of the Gihon spring." After his healing "his heart was proud," but he repented. Proverbs 25:1 records "more proverbs of Solomon, compiled by the men of Hezekiah king of Judah." Isaiah 38 preserves "a writing of Hezekiah king of Judah after his illness and recovery," ending, "The LORD will save me, and we will sing with stringed instruments all the days of our lives in the temple of the LORD." A century later, elders defending Jeremiah recall that Hezekiah did not put the prophet Micah to death but feared the LORD, and the LORD relented.`,
  refs:["2 Kings 16:20","2 Kings 18–20","Isaiah 36–39","2 Chronicles 29–32","Proverbs 25:1","Isaiah 38:9–20","Jeremiah 26:18–19","Hosea 1:1","Micah 1:1"]},

 {id:"manasseh_k", name:"Manasseh son of Hezekiah", short:"Manasseh (King)", cat:"king", w:7,
  clash:"Manasseh", clashtag:"Judah's longest-reigning king (55 years), whose sins 2 Kings names as the cause of Judah's fall.",
  dates:"reigned 55 years, c. 697 – 642 BC (Judah)",
  desc:`King at twelve. He rebuilds the high places, sets up altars to Baal and to the starry hosts in the temple courts, puts a carved Asherah pole in the temple, sacrifices his own son, consults mediums, and "shed so much innocent blood that he filled Jerusalem from end to end." The LORD declares a disaster on Jerusalem so great "that the ears of everyone who hears of it will tingle," and 2 Kings later names his sins as the reason Judah fell. 2 Chronicles adds that Assyria's commanders took him prisoner to Babylon, where he humbled himself and was restored.`,
  notconfused:`Manasseh son of Joseph, ancestor of the tribe of Manasseh.`,
  refs:["2 Kings 21:1–18","2 Kings 23:26","2 Kings 24:3–4","2 Chronicles 33","Jeremiah 15:4"]},

 {id:"josiah", name:"Josiah son of Amon", short:"Josiah", cat:"king", w:10,
  clash:"Josiah", clashtag:"Son of Amon, king of Judah, who found the Book of the Law.",
  dates:"reigned 31 years, c. 640 – 609 BC (Judah)",
  desc:`King at eight after his father Amon's assassination. In his eighteenth year Hilkiah the high priest finds "the Book of the Law" in the temple; when Shaphan reads it to him, Josiah tears his robes and sends to the prophet Huldah. He renews the covenant, purges the temple of Baal and Asherah, desecrates Topheth and the high places Solomon built, and tears down Jeroboam's altar at Bethel, as the man of God from Judah had foretold. He keeps a Passover unlike any since "the days of the judges." "Neither before nor after Josiah was there a king like him." He is killed by Pharaoh Necho at Megiddo. 2 Chronicles adds that he began to seek God in his eighth year and to purge Judah in his twelfth. Necho warned him, "stop opposing God," but he went out in disguise, was shot by archers at Megiddo, and died in Jerusalem; "Jeremiah composed laments for Josiah." Jeremiah's call came "in the thirteenth year of the reign of Josiah," and Jeremiah later holds him up against his son Jehoiakim: "He defended the cause of the poor and needy… Is that not what it means to know me?"`,
  notconfused:`Josiah son of Zephaniah, at whose house the crown for Joshua the high priest was made (Zechariah 6:10).`,
  refs:["1 Kings 13:2","2 Kings 21:24–26","2 Kings 22–23","2 Chronicles 34–35","Jeremiah 1:2","Jeremiah 22:15–16","Jeremiah 25:3"]},

 {id:"zedekiah", name:"Zedekiah son of Josiah", short:"Zedekiah", cat:"king", w:8,
  aliases:"Mattaniah",
  clash:"Zedekiah", clashtag:"The last king of Judah (born Mattaniah), blinded and taken to Babylon.",
  dates:"reigned 11 years, c. 597 – 586 BC (Judah)",
  desc:`Born Mattaniah, the uncle of Jehoiachin; Nebuchadnezzar makes him king and renames him Zedekiah. His mother is Hamutal of Libnah. He "did evil in the eyes of the LORD" and rebels against Babylon, which besieges Jerusalem from his ninth year to his eleventh. When the wall is breached he flees toward the Arabah, is captured in the plains of Jericho, and at Riblah his sons are killed before his eyes; then "they put out his eyes" and take him in bronze shackles to Babylon. 1 Chronicles 3:15 names him Josiah's third son. 2 Chronicles adds that he "did not humble himself before Jeremiah the prophet" and rebelled against Nebuchadnezzar, "who had made him take an oath in God's name." In Jeremiah he sends Pashhur son of Malkijah and the priest Zephaniah to ask Jeremiah to inquire of the LORD, confines him in the courtyard of the guard, and lets his officials put him in a cistern — "The king can do nothing to oppose you" — then orders Ebed-Melek to lift him out. He questions Jeremiah secretly, afraid of "the Jews who have gone over to the Babylonians." He makes a covenant to free the slaves, but the people "changed their minds and took back the slaves." Lachish and Azekah are the last fortified cities holding out.`,
  notconfused:`Zedekiah son of Kenaanah, the false prophet in Ahab's day. 2 Kings calls him Jehoiachin's uncle and gives his mother as Hamutal, also mother of Jehoahaz son of Josiah.`,
  refs:["2 Kings 24:17–20","2 Kings 25:1–7","Jeremiah 52","1 Chronicles 3:15","2 Chronicles 36:10–13","Jeremiah 21","Jeremiah 32:1–5","Jeremiah 34","Jeremiah 37–39","Jeremiah 51:59"]},

 // ---------------- THE PROPHETS ----------------
 // ================= 2 KINGS =================
 // --- Elisha's circle ---
 {id:"widow_oil", name:"The prophet's widow", short:"Widow (olive oil)", cat:"proph", w:5,
  dates:"c. 9th c. BC (unnamed)",
  desc:`"The wife of a man from the company of the prophets," whose husband "revered the LORD." When his creditor comes to take her two boys as slaves, Elisha has her borrow empty jars and pour from her one small jar of olive oil until "there is not a jar left"; she sells the oil and pays her debts.`,
  refs:["2 Kings 4:1–7"]},

 {id:"shunammite", name:"The Shunammite woman", short:"Shunammite", cat:"proph", w:7,
  dates:"c. 9th c. BC (unnamed)",
  desc:`"A well-to-do woman" of Shunem who builds Elisha a small room on her roof. Childless with an old husband, she bears a son "about this time next year," as Elisha foretold. When the boy dies she lays him on the prophet's bed and rides to Mount Carmel — "I will not leave you" — and Elisha raises him. Warned of a seven-year famine, she lives among the Philistines; on her return, as Gehazi is telling the king about her, the king restores her house, land and income.`,
  notconfused:`Abishag the Shunammite, who cared for King David in his old age (1 Kings 1).`,
  refs:["2 Kings 4:8–37","2 Kings 8:1–6"]},

 {id:"gehazi", name:"Gehazi", short:"Gehazi", cat:"proph", w:6,
  dates:"c. 9th c. BC",
  desc:`Elisha's servant. He points out that the Shunammite "has no son," and runs ahead with Elisha's staff, but "the boy has not awakened." After Naaman is healed he runs after him, lies that Elisha wants silver and clothing, and hides two talents; Elisha says, "Naaman's leprosy will cling to you," and he leaves "as white as snow." Later he is found telling the king "about all the great things Elisha has done."`,
  refs:["2 Kings 4:12–36","2 Kings 5:20–27","2 Kings 8:4–5"]},

 {id:"naaman_girl", name:"The young girl from Israel", short:"Naaman's servant girl", cat:"proph", w:5,
  dates:"c. 9th c. BC (unnamed)",
  desc:`Taken captive by Aramean raiders, she serves Naaman's wife and says, "If only my master would see the prophet who is in Samaria! He would cure him of his leprosy."`,
  refs:["2 Kings 5:2–4"]},

 // --- Jehu's revolt and Athaliah ---
 {id:"bidkar", name:"Bidkar", short:"Bidkar", cat:"king", w:4,
  dates:"c. 841 BC",
  desc:`Jehu's chariot officer, told to throw Joram's body on Naboth's field. Jehu reminds him how "you and I were riding together in chariots behind Ahab his father" when the LORD spoke against Ahab.`,
  refs:["2 Kings 9:25–26"]},

 {id:"jehonadab", name:"Jehonadab son of Rekab", short:"Jehonadab", cat:"king", w:5,
  dates:"c. 841 BC",
  desc:`Met by Jehu on the road to Samaria — "Are you in accord with me?" "I am." Jehu takes him into his chariot: "Come with me and see my zeal for the LORD." He goes with Jehu into the temple of Baal before the slaughter of its servants. In Jehoiakim's reign his descendants the Rekabites still keep his command: "Neither you nor your descendants must ever drink wine," living in tents and planting no vineyards. When Jeremiah sets wine before them they refuse, and the LORD promises, "Jehonadab son of Rekab will never fail to have a descendant to serve me."`,
  notconfused:`Rekab son of Rimmon, who murdered Ish-Bosheth (2 Samuel 4), and Jonadab son of Shimeah, David's nephew (2 Samuel 13).`,
  refs:["2 Kings 10:15–17","2 Kings 10:23","Jeremiah 35"]},

 {id:"jehosheba", name:"Jehosheba daughter of Jehoram", short:"Jehosheba", cat:"king", w:6,
  dates:"c. 841 BC",
  desc:`"The daughter of King Jehoram and sister of Ahaziah." When Athaliah sets out to destroy the royal family, she steals the infant Joash "away from among the royal princes" and hides him and his nurse, so "he was not killed." 2 Chronicles 22:11 adds that she was "wife of the priest Jehoiada."`,
  refs:["2 Kings 11:2–3","2 Chronicles 22:11"]},

 {id:"zibiah", name:"Zibiah of Beersheba", short:"Zibiah", cat:"king", w:3,
  dates:"c. 9th c. BC",
  desc:`Mother of King Joash of Judah — "his mother's name was Zibiah; she was from Beersheba."`,
  refs:["2 Kings 12:1"]},

 {id:"jozabad", name:"Jozabad son of Shimeath", short:"Jozabad", cat:"king", w:4,
  aliases:"Zabad (2 Chronicles 24:26)",
  dates:"c. 796 BC",
  desc:`One of the officials who conspired against King Joash and murdered him "at Beth Millo, on the road down to Silla." Amaziah later executed his father's murderers. 2 Chronicles calls him "Zabad, son of Shimeath an Ammonite woman," and says the officials killed Joash "for murdering the son of Jehoiada."`,
  refs:["2 Kings 12:20–21","2 Kings 14:5","2 Chronicles 24:25–26"]},

 {id:"jehozabad", name:"Jehozabad son of Shomer", short:"Jehozabad", cat:"king", w:4,
  dates:"c. 796 BC",
  desc:`With Jozabad son of Shimeath, one of the officials who assassinated King Joash; executed by Amaziah once the kingdom was "firmly in his grasp." 2 Chronicles calls him "son of Shimrith a Moabite woman."`,
  refs:["2 Kings 12:21","2 Kings 14:5","2 Chronicles 24:26"]},

 // --- Jehu's dynasty ---
 {id:"jehoahaz_i", name:"Jehoahaz son of Jehu", short:"Jehoahaz (Israel)", cat:"king", w:5,
  clash:"Jehoahaz", clashtag:"King of Israel, son of Jehu, who reigned 17 years under Aramean oppression.",
  dates:"reigned 17 years, c. 814 – 798 BC (Israel)",
  desc:`Jehu's son, who reigns in Samaria and follows "the sins of Jeroboam son of Nebat." The LORD keeps Israel "under the power of Hazael king of Aram and Ben-Hadad his son" until Jehoahaz "sought the LORD's favor," and the LORD provides "a deliverer." His army is left with only fifty horsemen, ten chariots and ten thousand foot soldiers.`,
  notconfused:`Jehoahaz son of Josiah, who reigned three months in Judah about two centuries later.`,
  refs:["2 Kings 10:35","2 Kings 13:1–9","2 Kings 13:22–25"]},

 // --- Judah: Amaziah to Ahaz ---
 {id:"amaziah", name:"Amaziah son of Joash", short:"Amaziah", cat:"king", w:7,
  clash:"Amaziah", clashtag:"Son of Joash, king of Judah, father of Uzziah.",
  dates:"reigned 29 years, c. 796 – 767 BC (Judah)",
  desc:`King of Judah at 25, who does right, "but not as his father David had done." He executes his father's assassins but spares their children, following the Law of Moses. He defeats ten thousand Edomites in the Valley of Salt, then challenges Jehoash of Israel, who warns him with the parable of the thistle and the cedar. Routed and captured at Beth Shemesh, he sees Jerusalem's wall broken down. He outlives Jehoash by fifteen years but is killed by conspirators at Lachish. 2 Chronicles adds that he hired 100,000 Israelite troops but sent them home at a man of God's word, then brought back the gods of Seir and bowed down to them, silencing the prophet who rebuked him.`,
  notconfused:`Amaziah the priest of Bethel, who opposed Amos in Jeroboam II's reign (Amos 7:10–17).`,
  refs:["2 Kings 12:21","2 Kings 14:1–22","2 Chronicles 25"]},

 {id:"jehoaddan", name:"Jehoaddan of Jerusalem", short:"Jehoaddan", cat:"king", w:3,
  dates:"c. 9th–8th c. BC",
  desc:`Mother of King Amaziah — "his mother's name was Jehoaddan; she was from Jerusalem."`,
  refs:["2 Kings 14:2"]},

 {id:"jekoliah", name:"Jekoliah of Jerusalem", short:"Jekoliah", cat:"king", w:3,
  dates:"c. 8th c. BC",
  desc:`Mother of King Azariah (Uzziah) — "his mother's name was Jekoliah; she was from Jerusalem."`,
  refs:["2 Kings 15:2"]},

 {id:"jotham_k", name:"Jotham son of Uzziah", short:"Jotham (king)", cat:"king", w:6,
  clash:"Jotham", clashtag:"King of Judah, son of Uzziah, who governed while his father had leprosy and rebuilt the temple's Upper Gate.",
  dates:"reigned 16 years, c. 750 – 732 BC (Judah) — includes a co-regency; disputed",
  desc:`While his father has leprosy, "Jotham the king's son had charge of the palace and governed the people of the land." King at 25, he does "what was right in the eyes of the LORD" and rebuilds "the Upper Gate of the temple of the LORD." In his days the LORD begins to send Rezin of Aram and Pekah of Israel against Judah. 2 Chronicles adds that "unlike him he did not enter the temple of the LORD," and that he conquered the Ammonites.`,
  notconfused:`Jotham son of Gideon, who told the parable of the trees from Mount Gerizim (Judges 9).`,
  refs:["2 Kings 15:5–7","2 Kings 15:32–38","2 Chronicles 27","Isaiah 1:1","Isaiah 7:1","Hosea 1:1","Micah 1:1"]},

 {id:"jerusha", name:"Jerusha daughter of Zadok", short:"Jerusha", cat:"king", w:3,
  dates:"c. 8th c. BC",
  desc:`Mother of King Jotham — "his mother's name was Jerusha daughter of Zadok." The text does not say whether this Zadok is of the priestly line.`,
  refs:["2 Kings 15:33"]},

 {id:"ahaz", name:"Ahaz son of Jotham", short:"Ahaz", cat:"king", w:8,
  dates:"reigned 16 years, c. 735 – 715 BC (Judah) — dates disputed",
  desc:`King at twenty who, "unlike David his father," follows "the ways of the kings of Israel" and "even sacrificed his son in the fire." Besieged by Rezin and Pekah, he sends temple silver and gold to Tiglath-Pileser — "I am your servant and vassal." Assyria takes Damascus. Visiting Tiglath-Pileser there, he sends a sketch of an altar to Uriah the priest, sets the new altar in the temple, moves the bronze altar aside and dismantles temple furnishings "in deference to the king of Assyria." 2 Chronicles adds that Aram and Pekah defeated him — 120,000 killed in Judah in one day — and that the prophet Oded persuaded Samaria to free the captives. He shut the doors of the temple and set up altars "at every street corner in Jerusalem"; Tiglath-Pileser "gave him trouble instead of help." In Isaiah 7, as Rezin and Pekah plan to "make the son of Tabeel king" over Judah, Isaiah tells him to ask the LORD for a sign; he refuses — "I will not ask; I will not put the LORD to the test" — and Isaiah gives him the sign of Immanuel. An oracle against Philistia is dated "in the year King Ahaz died."`,
  refs:["2 Kings 15:38","2 Kings 16","2 Kings 20:11","2 Chronicles 28","Isaiah 7","Isaiah 14:28","Isaiah 38:8","Hosea 1:1","Micah 1:1"]},

 {id:"uriah_p", name:"Uriah the priest", short:"Uriah (priest)", cat:"priest", w:5,
  clash:"Uriah", clashtag:"The priest who built King Ahaz's altar from a Damascus pattern.",
  dates:"c. 8th c. BC",
  desc:`Priest in Jerusalem under Ahaz. From the king's sketch he builds an altar copied from one in Damascus, finishes it before Ahaz returns, and offers the daily sacrifices on it: "Uriah the priest did just as King Ahaz had ordered." Isaiah 8:2, also in Ahaz's reign, calls "Uriah the priest and Zechariah son of Jeberekiah" as "reliable witnesses" when Isaiah writes "Maher-Shalal-Hash-Baz" on a scroll; the text does not say whether this is the same Uriah.`,
  notconfused:`Uriah the Hittite, Bathsheba's husband, whom David had killed (2 Samuel 11).`,
  refs:["2 Kings 16:10–16","Isaiah 8:2"]},

 // --- Israel's last kings ---
 {id:"shallum_k", name:"Shallum son of Jabesh", short:"Shallum (king)", cat:"king", w:4,
  clash:"Shallum", clashtag:"King of Israel for one month after assassinating Zechariah; killed by Menahem.",
  dates:"reigned 1 month, c. 752 BC (Israel)",
  desc:`He "conspired against Zechariah," assassinates him "in front of the people" and becomes king, ending Jehu's dynasty. He reigns one month in Samaria before Menahem son of Gadi kills him.`,
  notconfused:`Shallum son of Tikvah, husband of the prophet Huldah, a century later in Judah.`,
  refs:["2 Kings 15:10–15"]},

 {id:"menahem", name:"Menahem son of Gadi", short:"Menahem", cat:"king", w:5,
  dates:"reigned 10 years, c. 752 – 742 BC (Israel)",
  desc:`Comes from Tirzah, assassinates Shallum and takes the throne, then sacks Tiphsah with great cruelty "because they refused to open their gates." When Pul king of Assyria invades, he pays him a thousand talents of silver, taxing every wealthy man fifty shekels, "to strengthen his own hold on the kingdom."`,
  refs:["2 Kings 15:14–22"]},

 {id:"pekahiah", name:"Pekahiah son of Menahem", short:"Pekahiah", cat:"king", w:4,
  dates:"reigned 2 years, c. 742 – 740 BC (Israel)",
  desc:`Menahem's son, who does evil in the LORD's eyes. His chief officer Pekah son of Remaliah, with fifty men of Gilead, assassinates him in the citadel of the palace at Samaria, together with Argob and Arieh.`,
  refs:["2 Kings 15:22–26"]},

 {id:"pekah", name:"Pekah son of Remaliah", short:"Pekah", cat:"king", w:6,
  dates:"reigned 20 years (2 Kings 15:27), c. 752 – 732 BC (Israel) — how the 20 years are counted is disputed",
  desc:`An officer of Pekahiah who assassinates him and takes the throne. In his time Tiglath-Pileser takes Gilead and Galilee, "including all the land of Naphtali," and deports the people. With Rezin of Aram he marches against Jerusalem and besieges Ahaz. Hoshea son of Elah assassinates him. In Isaiah 7 he and Rezin plot to "tear apart" Judah; Isaiah mostly calls him "the son of Remaliah" — "the head of Samaria is only Remaliah's son."`,
  refs:["2 Kings 15:25–31","2 Kings 15:37","2 Kings 16:5","Isaiah 7:1–9","Isaiah 8:6"]},

 {id:"hoshea_k", name:"Hoshea son of Elah", short:"Hoshea (king)", cat:"king", w:7,
  dates:"reigned 9 years, c. 732 – 722 BC (Israel)",
  desc:`The last king of Israel. He assassinates Pekah and reigns in Samaria, doing evil, "but not like the kings of Israel who preceded him." A vassal of Shalmaneser, he sends envoys to So king of Egypt and stops paying tribute; Shalmaneser imprisons him, besieges Samaria for three years, and "in the ninth year of Hoshea" deports Israel to Assyria. 2 Kings 17 explains the exile: Israel "would not listen."`,
  notconfused:`Hoshea son of Nun, renamed Joshua by Moses (Numbers 13:16); the prophet Hosea; and Elah king of Israel, son of Baasha, who is not said to be his father.`,
  refs:["2 Kings 15:30","2 Kings 17:1–23","2 Kings 18:9–12"]},

 // --- Hezekiah's household and court ---
 {id:"abijah_h", name:"Abijah daughter of Zechariah", short:"Abijah (Hezekiah's mother)", cat:"king", w:4,
  clash:"Abijah", clashtag:"Mother of King Hezekiah.",
  dates:"c. 8th c. BC",
  desc:`Mother of King Hezekiah — "his mother's name was Abijah daughter of Zechariah."`,
  refs:["2 Kings 18:2"]},

 {id:"eliakim_h", name:"Eliakim son of Hilkiah", short:"Eliakim (palace)", cat:"king", w:5,
  clash:"Eliakim", clashtag:"Hezekiah's palace administrator, who met Sennacherib's commanders at Jerusalem's wall.",
  dates:"c. 701 BC",
  desc:`Hezekiah's palace administrator. With Shebna and Joah he goes out to Sennacherib's field commander and begs, "Please speak to your servants in Aramaic… Don't speak to us in Hebrew in the hearing of the people on the wall." He reports to Hezekiah with his clothes torn and is sent in sackcloth to the prophet Isaiah. Isaiah 22 foretells his rise in Shebna's place: "I will place on his shoulder the key to the house of David; what he opens no one can shut, and what he shuts no one can open."`,
  notconfused:`Eliakim son of Josiah, renamed Jehoiakim by Pharaoh Necho. His father Hilkiah is not said to be Hilkiah the high priest of Josiah's day.`,
  refs:["2 Kings 18:18","2 Kings 18:26","2 Kings 18:37","2 Kings 19:2","Isaiah 22:20–25","Isaiah 36:3","Isaiah 37:2"]},

 {id:"shebna", name:"Shebna the secretary", short:"Shebna", cat:"king", w:5,
  dates:"c. 701 BC",
  desc:`Hezekiah's secretary, who goes out with Eliakim and Joah to the Assyrian field commander, returns to the king with torn clothes, and is sent in sackcloth to Isaiah. Isaiah 22 calls him "Shebna the palace administrator" and rebukes him for cutting out a grave for himself "on the height": "I will depose you from your office," and his robe, sash and authority will pass to "my servant, Eliakim son of Hilkiah."`,
  refs:["2 Kings 18:18","2 Kings 18:26","2 Kings 18:37","2 Kings 19:2","Isaiah 22:15–25","Isaiah 36:3","Isaiah 37:2"]},

 {id:"joah_a", name:"Joah son of Asaph", short:"Joah", cat:"king", w:4,
  dates:"c. 701 BC",
  desc:`Hezekiah's recorder, one of the three officials who hear the Assyrian field commander's threats and report them to the king.`,
  refs:["2 Kings 18:18","2 Kings 18:26","2 Kings 18:37","Isaiah 36:3","Isaiah 36:22"]},

 // --- Manasseh to Josiah ---
 {id:"hephzibah", name:"Hephzibah", short:"Hephzibah", cat:"king", w:3,
  dates:"c. 7th c. BC",
  desc:`Mother of King Manasseh — "his mother's name was Hephzibah."`,
  refs:["2 Kings 21:1"]},

 {id:"amon", name:"Amon son of Manasseh", short:"Amon", cat:"king", w:5,
  dates:"reigned 2 years, c. 642 – 640 BC (Judah)",
  desc:`King at 22, who "followed completely the ways of his father," worshiping his father's idols and forsaking the LORD. His officials assassinate him in his palace; "the people of the land" kill the plotters and make his son Josiah king. He is buried in the garden of Uzza. Chronicles adds that "unlike his father Manasseh, he did not humble himself before the LORD."`,
  refs:["2 Kings 21:18–26","2 Chronicles 33:21–25"]},

 {id:"meshullemeth", name:"Meshullemeth daughter of Haruz", short:"Meshullemeth", cat:"king", w:3,
  dates:"c. 7th c. BC",
  desc:`Mother of King Amon — "Meshullemeth daughter of Haruz; she was from Jotbah."`,
  refs:["2 Kings 21:19"]},

 {id:"jedidah", name:"Jedidah daughter of Adaiah", short:"Jedidah", cat:"king", w:3,
  dates:"c. 7th c. BC",
  desc:`Mother of King Josiah — "Jedidah daughter of Adaiah; she was from Bozkath."`,
  refs:["2 Kings 22:1"]},

 {id:"shaphan", name:"Shaphan son of Azaliah", short:"Shaphan", cat:"king", w:6,
  dates:"c. 622 BC",
  desc:`"The secretary, Shaphan son of Azaliah, the son of Meshullam," sent by Josiah to the temple about the repair money. Hilkiah gives him the newly found Book of the Law; he reads it, then reads it "in the presence of the king," and goes with the delegation to the prophet Huldah. His son Ahikam and grandson Gedaliah follow him in royal service. Jeremiah names his son Gemariah, from whose room Baruch read Jeremiah's scroll, and his grandson Micaiah son of Gemariah.`,
  refs:["2 Kings 22:3–14","2 Kings 25:22","Jeremiah 26:24","Jeremiah 36:10–12"]},

 {id:"ahikam", name:"Ahikam son of Shaphan", short:"Ahikam", cat:"king", w:5,
  dates:"c. 622 BC",
  desc:`One of the five Josiah sends to "inquire of the LORD" about the Book of the Law, who consult the prophet Huldah. Father of Gedaliah, later appointed governor of Judah by Nebuchadnezzar. "Ahikam son of Shaphan supported Jeremiah, and so he was not handed over to the people to be put to death."`,
  refs:["2 Kings 22:12–14","2 Kings 25:22","Jeremiah 26:24"]},

 {id:"akbor", name:"Akbor son of Micaiah", short:"Akbor", cat:"king", w:3,
  dates:"c. 622 BC",
  desc:`A member of Josiah's delegation to the prophet Huldah. His father Micaiah is not said to be Micaiah son of Imlah of Ahab's day. His son Elnathan served Jehoiakim (Jeremiah 26:22; 36:12).`,
  refs:["2 Kings 22:12–14","Jeremiah 26:22","Jeremiah 36:12"]},

 {id:"asaiah", name:"Asaiah the king's attendant", short:"Asaiah", cat:"king", w:3,
  dates:"c. 622 BC",
  desc:`"Asaiah the king's attendant," one of the five Josiah sends to inquire of the LORD, who go to the prophet Huldah.`,
  refs:["2 Kings 22:12–14"]},

 {id:"shallum_t", name:"Shallum son of Tikvah", short:"Shallum (Huldah's husband)", cat:"king", w:4,
  clash:"Shallum", clashtag:"Husband of the prophet Huldah, keeper of the wardrobe in Josiah's day.",
  dates:"c. 622 BC",
  desc:`"Shallum son of Tikvah, the son of Harhas, keeper of the wardrobe" — husband of the prophet Huldah.`,
  notconfused:`Shallum son of Jabesh, who reigned one month over Israel.`,
  refs:["2 Kings 22:14"]},

 // --- the last kings of Judah ---
 {id:"jehoahaz_j", name:"Jehoahaz son of Josiah", short:"Jehoahaz (Judah)", cat:"king", w:5,
  aliases:"Shallum",
  clash:"Jehoahaz", clashtag:"King of Judah for three months after Josiah; taken to Egypt by Pharaoh Necho.",
  dates:"reigned 3 months, c. 609 BC (Judah)",
  desc:`After Josiah's death "the people of the land took Jehoahaz son of Josiah and anointed him." King at 23, he does evil and reigns three months before Pharaoh Necho puts him in chains at Riblah, places Judah under a levy, and carries him off to Egypt, "and there he died." 1 Chronicles 3:15 lists Josiah's sons as Johanan, Jehoiakim, Zedekiah and Shallum, without the name Jehoahaz; the text does not explain the difference. Jeremiah 22:11 speaks of "Shallum son of Josiah, who succeeded his father as king of Judah but has gone from this place: 'He will never return'" — the NIV footnote reads "Also called Jehoahaz."`,
  notconfused:`Jehoahaz son of Jehu, king of Israel two centuries earlier.`,
  refs:["2 Kings 23:30–34","1 Chronicles 3:15","2 Chronicles 36:1–4","Jeremiah 22:10–12"]},

 {id:"hamutal", name:"Hamutal daughter of Jeremiah", short:"Hamutal", cat:"king", w:4,
  dates:"c. 7th–6th c. BC",
  desc:`"Hamutal daughter of Jeremiah; she was from Libnah" — named as the mother of two kings of Judah, Jehoahaz and Zedekiah. Her father is not said to be the prophet Jeremiah.`,
  refs:["2 Kings 23:31","2 Kings 24:18","Jeremiah 52:1"]},

 {id:"jehoiakim", name:"Jehoiakim son of Josiah", short:"Jehoiakim", cat:"king", w:7,
  clash:"Eliakim", clashtag:"Born Eliakim son of Josiah; renamed Jehoiakim when Pharaoh Necho made him king.",
  aliases:"Eliakim",
  dates:"reigned 11 years, c. 609 – 598 BC (Judah)",
  desc:`"Pharaoh Necho made Eliakim son of Josiah king in place of his father Josiah and changed Eliakim's name to Jehoiakim." King at 25, he taxes the land to pay Necho and does evil. Nebuchadnezzar invades and Jehoiakim is his vassal three years, then rebels; the LORD sends Babylonian, Aramean, Moabite and Ammonite raiders against Judah "because of the sins of Manasseh." His son Jehoiachin succeeds him. 2 Chronicles 36:6 says Nebuchadnezzar "bound him with bronze shackles to take him to Babylon." Jeremiah condemns him for building his palace "by unrighteousness": "He will have the burial of a donkey." He has the prophet Uriah son of Shemaiah brought back from Egypt and killed. In his fifth year, as Jehudi reads Jeremiah's scroll to him by the fire, he cuts off columns "with a scribe's knife" and burns the whole scroll, then orders Baruch and Jeremiah arrested, "but the LORD had hidden them." Daniel 1 dates the siege in which Daniel was taken to "the third year of the reign of Jehoiakim"; Jeremiah 25:1 makes his fourth year "the first year of Nebuchadnezzar."`,
  notconfused:`Eliakim son of Hilkiah, Hezekiah's palace administrator.`,
  refs:["2 Kings 23:34–24:6","2 Chronicles 36:4–8","Jeremiah 22:13–19","Jeremiah 26:20–23","Jeremiah 36","Daniel 1:1–2"]},

 {id:"zebidah", name:"Zebidah daughter of Pedaiah", short:"Zebidah", cat:"king", w:3,
  dates:"c. 7th c. BC",
  desc:`Mother of King Jehoiakim — "Zebidah daughter of Pedaiah; she was from Rumah."`,
  refs:["2 Kings 23:36"]},

 {id:"jehoiachin", name:"Jehoiachin son of Jehoiakim", short:"Jehoiachin", cat:"king", w:7,
  dates:"reigned 3 months, c. 598 – 597 BC (Judah); released c. 562 BC",
  desc:`King at eighteen for three months. When Nebuchadnezzar besieges Jerusalem, he surrenders with his mother, attendants, nobles and officials, and is taken captive to Babylon "in the eighth year" of Nebuchadnezzar, with ten thousand of Jerusalem's people and the temple treasures. His uncle Mattaniah is made king as Zedekiah. In the thirty-seventh year of his exile Awel-Marduk releases him, gives him "a seat of honor," and he eats "at the king's table" for the rest of his life — the last scene of Kings. 2 Chronicles gives his reign as "three months and ten days." 1 Chronicles 3:17–18 lists his sons, among them Shealtiel and Pedaiah. Jeremiah: "even if you, Jehoiachin… were a signet ring on my right hand, I would still pull you off," and "Record this man as if childless… none will sit on the throne of David." The prophet Hananiah falsely promises his return within two years. Ezekiel dates his visions by "the exile of King Jehoiachin."`,
  refs:["2 Kings 24:6–17","2 Kings 25:27–30","1 Chronicles 3:16–18","2 Chronicles 36:9–10","Jeremiah 22:24–30","Jeremiah 24:1","Jeremiah 28:4","Jeremiah 29:2","Jeremiah 52:31–34","Ezekiel 1:2"]},

 {id:"nehushta", name:"Nehushta daughter of Elnathan", short:"Nehushta", cat:"king", w:4,
  dates:"c. 6th c. BC",
  desc:`Mother of King Jehoiachin — "Nehushta daughter of Elnathan; she was from Jerusalem." She surrenders with her son and is taken to Babylon as "the king's mother."`,
  refs:["2 Kings 24:8","2 Kings 24:12","2 Kings 24:15"]},

 // --- priests ---
 {id:"jehoiada", name:"Jehoiada the priest", short:"Jehoiada", cat:"priest", w:8,
  clash:"Jehoiada", clashtag:"The priest who hid the boy Joash, crowned him, and had Athaliah put to death.",
  dates:"c. 9th c. BC",
  desc:`Priest at the temple, who hides the boy Joash for six years. In the seventh year he puts the commanders and guards under oath, arms them with King David's spears and shields, crowns Joash and proclaims him king, and orders Athaliah put to death outside the temple. He makes a covenant "that they would be the LORD's people." Joash does right "all the years Jehoiada the priest instructed him"; Jehoiada sets up the collection chest for the temple repairs. 2 Chronicles adds that he chose two wives for Joash and died "at the age of a hundred and thirty," buried with the kings "because of the good he had done in Israel." His wife was Jehosheba; his son Zechariah was stoned on Joash's order.`,
  notconfused:`Jehoiada the priest, father of Benaiah, in David's day (1 Chronicles 27:5).`,
  refs:["2 Kings 11:4–20","2 Kings 12:2–10","2 Chronicles 22:11–24:16"]},

 {id:"hilkiah", name:"Hilkiah the high priest", short:"Hilkiah", cat:"priest", w:7,
  clash:"Hilkiah", clashtag:"The high priest who found the Book of the Law in Josiah's eighteenth year.",
  dates:"c. 622 BC",
  desc:`High priest in Josiah's eighteenth year, who tells Shaphan, "I have found the Book of the Law in the temple of the LORD." He leads the delegation to Huldah and, at the king's order, removes from the temple "all the articles made for Baal and Asherah and all the starry hosts."`,
  notconfused:`Hilkiah the father of Eliakim, Hezekiah's palace administrator; Hilkiah the priest of Anathoth, father of Jeremiah; and Hilkiah father of Gemariah (Jeremiah 29:3) — the text does not say any of them is the high priest.`,
  refs:["2 Kings 22:4–14","2 Kings 23:4","2 Kings 23:24"]},

 {id:"seraiah", name:"Seraiah the chief priest", short:"Seraiah", cat:"priest", w:4,
  clash:"Seraiah", clashtag:"The chief priest when Jerusalem fell, executed at Riblah.",
  dates:"c. 586 BC",
  desc:`Chief priest when Jerusalem fell. Nebuzaradan takes him prisoner with Zephaniah and the three doorkeepers and brings them to Nebuchadnezzar at Riblah, where they are executed.`,
  refs:["2 Kings 25:18–21","Jeremiah 52:24–27"]},

 {id:"zephaniah_p", name:"Zephaniah the priest", short:"Zephaniah (priest)", cat:"priest", w:4,
  aliases:"Zephaniah son of Maaseiah",
  clash:"Zephaniah", clashtag:"The priest next in rank to Seraiah, executed at Riblah after Jerusalem fell.",
  dates:"c. 586 BC",
  desc:`"The priest next in rank" to Seraiah. Taken prisoner by Nebuzaradan and executed at Riblah. Jeremiah names "the priest Zephaniah son of Maaseiah" in Zedekiah's reign, sent with Pashhur son of Malkijah and later with Jehukal to ask Jeremiah to pray. Shemaiah the Nehelamite writes from Babylon urging him, as the priest "in charge of the house of the LORD," to put Jeremiah in the stocks, but he reads the letter to Jeremiah. The text does not say outright that this is the "priest next in rank" taken to Riblah, though both are "Zephaniah the priest" in Zedekiah's last years.`,
  notconfused:`Zephaniah the prophet of Josiah's day.`,
  refs:["2 Kings 25:18–21","Jeremiah 21:1","Jeremiah 29:25–29","Jeremiah 37:3","Jeremiah 52:24–27"]},

 // --- after the fall ---
 {id:"gedaliah", name:"Gedaliah son of Ahikam", short:"Gedaliah", cat:"exile", w:6,
  clash:"Gedaliah", clashtag:"Son of Ahikam, appointed governor of Judah by Nebuchadnezzar and murdered at Mizpah.",
  dates:"c. 586 BC",
  desc:`"Gedaliah son of Ahikam, the son of Shaphan," appointed by Nebuchadnezzar over the people left in Judah. At Mizpah he reassures the army officers, "Do not be afraid of the Babylonian officials… serve the king of Babylon, and it will go well with you." In the seventh month Ishmael son of Nethaniah assassinates him, and the people flee to Egypt. Jeremiah adds that the Babylonian officers hand Jeremiah over to him and Jeremiah stays with him at Mizpah. Johanan son of Kareah warns him that "Baalis king of the Ammonites has sent Ishmael son of Nethaniah to take your life" and offers to kill Ishmael, but Gedaliah does not believe it.`,
  refs:["2 Kings 25:22–26","Jeremiah 39:14","Jeremiah 40–41"]},

 {id:"ishmael_n", name:"Ishmael son of Nethaniah", short:"Ishmael (Gedaliah's killer)", cat:"exile", w:5,
  clash:"Ishmael", clashtag:"Of royal blood, he assassinated Gedaliah the governor at Mizpah.",
  dates:"c. 586 BC",
  desc:`"Ishmael son of Nethaniah, the son of Elishama, who was of royal blood." One of the army officers who come to Gedaliah at Mizpah, he returns with ten men and kills Gedaliah and the Judeans and Babylonians with him. Jeremiah 40–41 adds that Baalis king of the Ammonites sent him. The day after the murder he slaughters the men coming with offerings from Shechem, Shiloh and Samaria — sparing ten who promise him hidden stores of food — and fills Asa's cistern with the dead, takes the king's daughters and the people of Mizpah captive, and when Johanan catches him at the great pool in Gibeon escapes with eight men to the Ammonites.`,
  notconfused:`Ishmael son of Abraham and Hagar (Genesis 16).`,
  refs:["2 Kings 25:23–25","Jeremiah 40:7–41:18"]},

 {id:"johanan", name:"Johanan son of Kareah", short:"Johanan", cat:"exile", w:4,
  dates:"c. 586 BC",
  desc:`One of the army officers who come with their men to Gedaliah at Mizpah, with Ishmael, Seraiah son of Tanhumeth and Jaazaniah. He warns Gedaliah of Ishmael's plot, rescues Ishmael's captives at Gibeon, then asks Jeremiah to pray for guidance — "we will obey the LORD our God" — but when told to stay in Judah says, "You are lying!" and leads the remnant, with Jeremiah and Baruch, to Tahpanhes in Egypt.`,
  refs:["2 Kings 25:23","Jeremiah 40–43"]},


 // ================= 1–2 CHRONICLES =================
 // --- genealogies (1 Chronicles 1–9) ---
 {id:"caleb_h", name:"Caleb son of Hezron", short:"Caleb (Hezron's son)", cat:"line", w:4,
  clash:"Caleb", clashtag:"Son of Hezron in Judah's genealogy; through Ephrath, ancestor of Hur and Bezalel.",
  dates:"genealogy (undated)",
  desc:`"Caleb son of Hezron," brother of Jerahmeel and Ram. By Azubah he had Jesher, Shobab and Ardon; "when Azubah died, Caleb married Ephrath, who bore him Hur. Hur was the father of Uri, and Uri the father of Bezalel." His concubines Ephah and Maakah also bore him sons, and "Caleb's daughter was Aksah."`,
  notconfused:`Caleb son of Jephunneh, the faithful spy, whose daughter was also named Aksah (Joshua 15:16). 1 Chronicles 4:15 lists "the sons of Caleb son of Jephunneh" separately; the text does not say how the two relate.`,
  refs:["1 Chronicles 2:9","1 Chronicles 2:18–20","1 Chronicles 2:42–50"]},

 {id:"jabez", name:"Jabez", short:"Jabez", cat:"line", w:5,
  dates:"genealogy (undated)",
  desc:`Named among the clans of Judah: "Jabez was more honorable than his brothers. His mother had named him Jabez, saying, 'I gave birth to him in pain.'" He prayed, "Oh, that you would bless me and enlarge my territory! Let your hand be with me, and keep me from harm so that I will be free from pain." "And God granted his request."`,
  refs:["1 Chronicles 4:9–10"]},

 {id:"bithiah", name:"Bithiah, Pharaoh's daughter", short:"Bithiah", cat:"line", w:4,
  dates:"genealogy (undated)",
  desc:`Listed in Judah's genealogy as "Pharaoh's daughter Bithiah, whom Mered had married," the mother of Miriam, Shammai and Ishbah the father of Eshtemoa.`,
  notconfused:`The Pharaoh's daughter who drew Moses from the Nile (Exodus 2), and the Pharaoh's daughter whom Solomon married (1 Kings 3:1).`,
  refs:["1 Chronicles 4:17–18"]},

 {id:"sheerah", name:"Sheerah daughter of Ephraim", short:"Sheerah", cat:"line", w:4,
  dates:"genealogy (undated)",
  desc:`A daughter in Ephraim's line, "who built Lower and Upper Beth Horon as well as Uzzen Sheerah."`,
  refs:["1 Chronicles 7:24"]},

 {id:"abigail_s", name:"Abigail sister of David", short:"Abigail (David's sister)", cat:"king", w:4,
  clash:"Abigail", clashtag:"Jesse's daughter, David's sister, and mother of Amasa.",
  dates:"c. 11th c. BC (traditional)",
  desc:`One of David's two sisters: "Their sisters were Zeruiah and Abigail." She was "the mother of Amasa, whose father was Jether the Ishmaelite." 2 Samuel 17:25 calls her "the daughter of Nahash and sister of Zeruiah."`,
  notconfused:`Abigail of Carmel, the widow of Nabal, who became David's wife (1 Samuel 25).`,
  refs:["1 Chronicles 2:16–17","2 Samuel 17:25"]},

 {id:"shealtiel", name:"Shealtiel son of Jehoiachin", short:"Shealtiel", cat:"exile", w:4,
  dates:"6th c. BC",
  desc:`First named of "the descendants of Jehoiachin the captive: Shealtiel his son, Malkiram, Pedaiah, Shenazzar, Jekamiah, Hoshama and Nedabiah." Ezra and Nehemiah call Zerubbabel "son of Shealtiel."`,
  refs:["1 Chronicles 3:17–18","Ezra 3:2","Nehemiah 12:1","Haggai 1:1","Haggai 2:23"]},

 {id:"pedaiah_j", name:"Pedaiah son of Jehoiachin", short:"Pedaiah", cat:"exile", w:3,
  dates:"6th c. BC",
  desc:`A son of Jehoiachin; "the sons of Pedaiah: Zerubbabel and Shimei." Elsewhere Zerubbabel is called "son of Shealtiel"; 1 Chronicles does not explain the difference.`,
  refs:["1 Chronicles 3:18–19"]},

 // --- Levite musicians and priests ---
 {id:"heman", name:"Heman the musician", short:"Heman", cat:"priest", w:7,
  clash:"Heman", clashtag:"The Levite musician, grandson of Samuel, whom David set over the temple music.",
  dates:"c. 10th c. BC",
  desc:`"Heman, the musician, the son of Joel, the son of Samuel," a Kohathite, one of the three Levites David set over the music "in the house of the LORD." He sounds the bronze cymbals when the ark comes up, and is called "the king's seer"; "God gave Heman fourteen sons and three daughters," whose divisions prophesied with harps, lyres and cymbals.`,
  notconfused:`Heman son of Zerah in Judah's genealogy (1 Chronicles 2:6), and Heman the Ezrahite of Psalm 88, a wise man to whom Solomon is compared (1 Kings 4:31); Scripture does not say whether any of these are the same man.`,
  refs:["1 Chronicles 6:33","1 Chronicles 15:17–19","1 Chronicles 16:41–42","1 Chronicles 25:1–6","2 Chronicles 5:12"]},

 {id:"asaph", name:"Asaph son of Berekiah", short:"Asaph", cat:"priest", w:7,
  dates:"c. 10th c. BC",
  desc:`A Gershonite Levite, "Heman's associate… who served at his right hand." When the ark is set in its tent, "Asaph was the chief" of those appointed "to extol, thank, and praise the LORD," and that day David "first appointed Asaph and his associates" to sing a psalm of thanks. His sons "prophesied under the king's supervision"; later generations sang "with the words of David and of Asaph the seer." Twelve psalms are headed with his name (Psalms 50 and 73–83).`,
  notconfused:`Asaph the father of Joah, Hezekiah's recorder (2 Kings 18:18); the text does not say they are the same man.`,
  refs:["1 Chronicles 6:39–43","1 Chronicles 15:17–19","1 Chronicles 16:4–7","1 Chronicles 16:37","1 Chronicles 25:1–2","2 Chronicles 29:30","Psalm 50","Psalms 73–83"]},

 {id:"jeduthun", name:"Jeduthun", short:"Jeduthun", cat:"priest", w:6,
  dates:"c. 10th c. BC",
  desc:`With Heman, stationed before the tabernacle at Gibeon "to give thanks to the LORD, 'for his love endures forever.'" His six sons served "under the supervision of their father Jeduthun, who prophesied, using the harp." He is called "the king's seer." Psalms 39, 62 and 77 are marked "For Jeduthun."`,
  refs:["1 Chronicles 16:41–42","1 Chronicles 25:1–3","2 Chronicles 5:12","2 Chronicles 35:15","Psalm 39","Psalm 62","Psalm 77"]},

 {id:"ethan_m", name:"Ethan the Merarite", short:"Ethan (musician)", cat:"priest", w:4,
  clash:"Ethan", clashtag:"The Merarite musician who sounded the cymbals when the ark came up.",
  dates:"c. 10th c. BC",
  desc:`The Merarite musician "at his left hand" — "Ethan son of Kishi" (also "son of Kushaiah") — who with Heman and Asaph sounded the bronze cymbals when the ark was brought up.`,
  notconfused:`Ethan son of Zerah in Judah's genealogy (1 Chronicles 2:6), and Ethan the Ezrahite of Psalm 89, to whom Solomon's wisdom is compared (1 Kings 4:31); Scripture does not say whether any of these are the same man.`,
  refs:["1 Chronicles 6:44–47","1 Chronicles 15:17–19"]},

 {id:"jehoiada_b", name:"Jehoiada father of Benaiah", short:"Jehoiada (Benaiah's father)", cat:"priest", w:4,
  clash:"Jehoiada", clashtag:"Leader of the family of Aaron who came to David at Hebron; father of Benaiah.",
  dates:"c. 11th–10th c. BC",
  desc:`"Jehoiada, leader of the family of Aaron, with 3,700 men," who came to David at Hebron. Benaiah, David's commander, is called "son of Jehoiada the priest"; the text does not say outright that this priest and the leader at Hebron are one man.`,
  notconfused:`Jehoiada the priest who crowned Joash a century and a half later (2 Kings 11).`,
  refs:["1 Chronicles 12:27","1 Chronicles 27:5"]},

 {id:"ahimelek_a", name:"Ahimelek son of Abiathar", short:"Ahimelek (Abiathar's son)", cat:"priest", w:4,
  clash:"Ahimelek", clashtag:"Priest under David alongside Zadok; 'a descendant of Ithamar.'",
  dates:"c. 10th c. BC",
  desc:`Listed with Zadok as priest under David — "Zadok son of Ahitub and Ahimelek son of Abiathar." He helps David divide the priests into divisions as "a descendant of Ithamar."`,
  notconfused:`Ahimelek son of Ahitub, the priest of Nob and father of Abiathar, killed on Saul's orders (1 Samuel 22).`,
  refs:["2 Samuel 8:17","1 Chronicles 18:16","1 Chronicles 24:3","1 Chronicles 24:6","1 Chronicles 24:31"]},

 {id:"amariah_cp", name:"Amariah the chief priest", short:"Amariah", cat:"priest", w:4,
  clash:"Amariah", clashtag:"The chief priest set over the judges by Jehoshaphat.",
  dates:"c. 9th c. BC",
  desc:`Set by Jehoshaphat over the judges in Jerusalem "in any matter concerning the LORD."`,
  notconfused:`Amariah, great-grandfather of the prophet Zephaniah (Zephaniah 1:1).`,
  refs:["2 Chronicles 19:11"]},

 {id:"azariah_cp", name:"Azariah the chief priest (Uzziah's day)", short:"Azariah (priest, Uzziah)", cat:"priest", w:5,
  clash:"Azariah", clashtag:"The chief priest who, with eighty priests, confronted King Uzziah in the temple.",
  dates:"c. 8th c. BC",
  desc:`With "eighty other courageous priests of the LORD" he follows Uzziah into the temple: "It is not right for you, Uzziah, to burn incense to the LORD." When leprosy breaks out on the king's forehead, "they hurried him out."`,
  refs:["2 Chronicles 26:17–20"]},

 {id:"azariah_h", name:"Azariah the chief priest (Hezekiah's day)", short:"Azariah (priest, Hezekiah)", cat:"priest", w:4,
  clash:"Azariah", clashtag:"Chief priest 'from the family of Zadok' under Hezekiah.",
  dates:"c. 8th–7th c. BC",
  desc:`"Azariah the chief priest, from the family of Zadok," who tells Hezekiah that since the people began bringing their contributions "we have had enough to eat and plenty to spare." The text does not say whether he is the Azariah of Uzziah's day.`,
  refs:["2 Chronicles 31:10–13"]},

 {id:"jozadak", name:"Jozadak son of Seraiah", short:"Jozadak", cat:"priest", w:4,
  dates:"c. 586 BC",
  desc:`Last in the high-priestly line of 1 Chronicles 6 — "Seraiah the father of Jozadak. Jozadak was deported when the LORD sent Judah and Jerusalem into exile by the hand of Nebuchadnezzar." His son "Joshua son of Jozadak" was the priest who returned with Zerubbabel. Haggai and Zechariah also name "Joshua son of Jozadak" (NIV footnote: "Hebrew Jehozadak, a variant of Jozadak").`,
  refs:["1 Chronicles 6:14–15","Ezra 3:2","Nehemiah 12:26","Haggai 1:1","Zechariah 6:11"]},

 // --- prophets and seers ---
 {id:"iddo", name:"Iddo the seer", short:"Iddo", cat:"proph", w:5,
  clash:"Iddo", clashtag:"The seer whose records Chronicles cites for Rehoboam and Abijah.",
  dates:"c. 10th c. BC",
  desc:`A seer whose writings Chronicles cites as sources: "the visions of Iddo the seer concerning Jeroboam son of Nebat," his records "that deal with genealogies" for Rehoboam, and "the annotations of the prophet Iddo" on Abijah's reign.`,
  notconfused:`Iddo, grandfather (or ancestor) of the prophet Zechariah (Zechariah 1:1; Ezra 5:1), and Iddo the leader at Kasiphia (Ezra 8:17).`,
  refs:["2 Chronicles 9:29","2 Chronicles 12:15","2 Chronicles 13:22"]},

 {id:"azariah_o", name:"Azariah son of Oded", short:"Azariah (prophet)", cat:"proph", w:5,
  clash:"Azariah", clashtag:"The prophet whose word moved Asa to purge idols and renew the covenant.",
  dates:"c. 10th–9th c. BC",
  desc:`"The Spirit of God came on Azariah son of Oded." He meets Asa after the victory over Zerah: "The LORD is with you when you are with him. If you seek him, he will be found by you… be strong and do not give up." Asa "took courage," removes the idols and leads Judah in a covenant to seek the LORD.`,
  refs:["2 Chronicles 15:1–8"]},

 {id:"hanani", name:"Hanani the seer", short:"Hanani", cat:"proph", w:5,
  clash:"Hanani", clashtag:"The seer who rebuked King Asa and was imprisoned; father of the prophet Jehu.",
  dates:"c. 9th c. BC",
  desc:`Rebukes Asa for relying on Aram: "the eyes of the LORD range throughout the earth to strengthen those whose hearts are fully committed to him. You have done a foolish thing." Asa, enraged, puts him in prison. Father of the prophet Jehu.`,
  notconfused:`Hanani, the brother of Nehemiah (Nehemiah 1:2).`,
  refs:["2 Chronicles 16:7–10","2 Chronicles 19:2","1 Kings 16:1"]},

 {id:"jahaziel", name:"Jahaziel the Levite", short:"Jahaziel", cat:"proph", w:5,
  dates:"c. 9th c. BC",
  desc:`"A Levite and descendant of Asaph," on whom "the Spirit of the LORD came" in the assembly as Moab, Ammon and Edom advanced: "Do not be afraid or discouraged because of this vast army. For the battle is not yours, but God's… stand firm and see the deliverance the LORD will give you."`,
  refs:["2 Chronicles 20:14–17"]},

 {id:"eliezer_d", name:"Eliezer son of Dodavahu", short:"Eliezer (prophet)", cat:"proph", w:4,
  clash:"Eliezer", clashtag:"The prophet of Mareshah who foretold the wreck of Jehoshaphat's fleet.",
  dates:"c. 9th c. BC",
  desc:`"Eliezer son of Dodavahu of Mareshah prophesied against Jehoshaphat, saying, 'Because you have made an alliance with Ahaziah, the LORD will destroy what you have made.' The ships were wrecked."`,
  refs:["2 Chronicles 20:35–37"]},

 {id:"zechariah_j", name:"Zechariah son of Jehoiada", short:"Zechariah (Jehoiada's son)", cat:"proph", w:6,
  clash:"Zechariah", clashtag:"Son of the priest Jehoiada, stoned in the temple court on King Joash's order.",
  dates:"c. 9th–8th c. BC",
  desc:`After Jehoiada's death, "the Spirit of God came on Zechariah son of Jehoiada the priest": "Because you have forsaken the LORD, he has forsaken you." By order of King Joash he is stoned "in the courtyard of the LORD's temple," saying as he dies, "May the LORD see this and call you to account."`,
  notconfused:`Zechariah the post-exilic prophet, and Zechariah king of Israel.`,
  refs:["2 Chronicles 24:20–22","2 Chronicles 24:25"]},

 {id:"zechariah_u", name:"Zechariah, Uzziah's instructor", short:"Zechariah (Uzziah's teacher)", cat:"proph", w:4,
  clash:"Zechariah", clashtag:"The man 'who instructed' King Uzziah 'in the fear of God.'",
  dates:"c. 8th c. BC",
  desc:`Uzziah "sought God during the days of Zechariah, who instructed him in the fear of God. As long as he sought the LORD, God gave him success."`,
  refs:["2 Chronicles 26:5"]},

 {id:"oded", name:"Oded the prophet", short:"Oded", cat:"proph", w:5,
  dates:"c. 8th c. BC (Israel)",
  desc:`"A prophet of the LORD named Oded" in Samaria, who meets the army returning with 200,000 captives from Judah in Ahaz's day: "aren't you also guilty of sins against the LORD your God? … Send back your fellow Israelites." Leaders of Ephraim agree; the captives are clothed, fed and returned to Jericho.`,
  notconfused:`Oded the father of the prophet Azariah in Asa's day (2 Chronicles 15:1); the text does not connect them.`,
  refs:["2 Chronicles 28:9–15"]},


 // ================= EZRA · NEHEMIAH · ESTHER =================
 {id:"sheshbazzar", name:"Sheshbazzar the prince of Judah", short:"Sheshbazzar", cat:"exile", w:6,
  dates:"c. 538 BC",
  desc:`"Sheshbazzar the prince of Judah," to whom Cyrus's treasurer counts out the 5,400 gold and silver temple articles that Nebuchadnezzar had taken; he brings them up from Babylon with the exiles. Ezra 5 says Cyrus "appointed" him governor and that he "laid the foundations of the house of God in Jerusalem." The text does not say how he relates to Zerubbabel, who is also credited with the foundation (Ezra 3).`,
  refs:["Ezra 1:8–11","Ezra 5:14–16"]},

 {id:"hanani_n", name:"Hanani brother of Nehemiah", short:"Hanani (Nehemiah's brother)", cat:"exile", w:4,
  clash:"Hanani", clashtag:"Nehemiah's brother, who brought word of Jerusalem's broken walls and was later put in charge of the city.",
  dates:"c. 445 BC",
  desc:`"One of my brothers," who comes from Judah to Susa with news that "the wall of Jerusalem is broken down, and its gates have been burned with fire." After the wall is finished Nehemiah puts him in charge of Jerusalem with Hananiah the commander of the citadel.`,
  notconfused:`Hanani the seer, imprisoned by King Asa (2 Chronicles 16).`,
  refs:["Nehemiah 1:2–3","Nehemiah 7:2"]},

 {id:"shekaniah_e", name:"Shekaniah son of Jehiel", short:"Shekaniah", cat:"exile", w:4,
  dates:"c. 458 BC",
  desc:`"One of the descendants of Elam," who answers Ezra's prayer of confession: "We have been unfaithful to our God by marrying foreign women… But in spite of this, there is still hope for Israel." He proposes a covenant to send the foreign wives away: "Rise up; this matter is in your hands. We will support you."`,
  refs:["Ezra 10:2–4"]},

 {id:"abihail_e", name:"Abihail father of Esther", short:"Abihail (Esther's father)", cat:"exile", w:3,
  dates:"5th c. BC",
  desc:`Esther's father and Mordecai's uncle — "the daughter of his uncle Abihail." Esther was raised by Mordecai "because she had neither father nor mother."`,
  refs:["Esther 2:7","Esther 2:15","Esther 9:29"]},

 {id:"joiakim", name:"Joiakim son of Joshua", short:"Joiakim", cat:"priest", w:4,
  dates:"5th c. BC",
  desc:`High priest after his father Joshua: "Joshua was the father of Joiakim, Joiakim the father of Eliashib." The heads of the priestly families "in the days of Joiakim" are listed in Nehemiah 12.`,
  refs:["Nehemiah 12:10","Nehemiah 12:12–26"]},

 {id:"eliashib", name:"Eliashib the high priest", short:"Eliashib", cat:"priest", w:6,
  dates:"c. 445 BC",
  desc:`Son of Joiakim. He and his fellow priests rebuild and dedicate the Sheep Gate. Later, as the priest "in charge of the storerooms," he gives Tobiah the Ammonite "a large room" in the temple courts while Nehemiah is away; Nehemiah throws Tobiah's goods out. One of his grandsons became son-in-law to Sanballat.`,
  refs:["Nehemiah 3:1","Nehemiah 3:20–21","Nehemiah 12:10","Nehemiah 13:4–9","Nehemiah 13:28"]},

 {id:"joiada_e", name:"Joiada son of Eliashib", short:"Joiada", cat:"priest", w:3,
  dates:"5th c. BC",
  desc:`Son of the high priest Eliashib and father of Jonathan. "One of the sons of Joiada son of Eliashib the high priest was son-in-law to Sanballat the Horonite," and Nehemiah drove him away.`,
  refs:["Nehemiah 12:10–11","Nehemiah 13:28"]},

 {id:"meremoth", name:"Meremoth son of Uriah", short:"Meremoth", cat:"priest", w:4,
  dates:"c. 458 – 445 BC",
  desc:`The priest into whose hands Ezra's company weighs out the silver, gold and sacred articles in the temple. As "Meremoth son of Uriah, the son of Hakkoz," he repairs two sections of the wall, one reaching to the house of Eliashib the high priest.`,
  refs:["Ezra 8:33","Nehemiah 3:4","Nehemiah 3:21"]},

 {id:"shemaiah_d", name:"Shemaiah son of Delaiah", short:"Shemaiah (hired prophet)", cat:"proph", w:4,
  clash:"Shemaiah", clashtag:"A prophet hired by Tobiah and Sanballat to frighten Nehemiah into hiding in the temple.",
  dates:"c. 445 BC",
  desc:`Shut in at his home, he urges Nehemiah, "Let us meet in the house of God… because men are coming to kill you." Nehemiah answers, "Should a man like me run away?" and realizes "that God had not sent him, but that he had prophesied against me because Tobiah and Sanballat had hired him."`,
  notconfused:`Shemaiah the man of God who stopped Rehoboam's war (1 Kings 12).`,
  refs:["Nehemiah 6:10–13"]},

 {id:"noadiah", name:"Noadiah the prophet", short:"Noadiah", cat:"proph", w:4,
  dates:"c. 445 BC",
  desc:`A prophet whom Nehemiah names among his intimidators: "remember also the prophet Noadiah and how she and the rest of the prophets have been trying to intimidate me."`,
  notconfused:`Noadiah son of Binnui, a Levite in Ezra's day (Ezra 8:33).`,
  refs:["Nehemiah 6:14"]},


 // ----- Wisdom & Poetry (Job, Psalms, Proverbs, Ecclesiastes, Song of Songs) -----
 {id:"job_wife", name:"Job's wife", short:"Job's wife", cat:"wis", w:5,
  dates:"undated",
  desc:`Unnamed. When Job sits among the ashes scraping his sores, she asks him, "Are you still maintaining your integrity? Curse God and die!" He answers, "You are talking like a foolish woman. Shall we accept good from God, and not trouble?" Later Job laments, "My breath is offensive to my wife."`,
  refs:["Job 2:9–10","Job 19:17"]},

 {id:"jemimah", name:"Jemimah daughter of Job", short:"Jemimah", cat:"wis", w:3,
  dates:"undated",
  desc:`The first of the three daughters born to Job after the LORD restored his fortunes. "Nowhere in all the land were there found women as beautiful as Job's daughters, and their father granted them an inheritance along with their brothers."`,
  refs:["Job 42:13–15"]},

 {id:"keziah", name:"Keziah daughter of Job", short:"Keziah", cat:"wis", w:3,
  dates:"undated",
  desc:`The second of Job's three daughters born after his restoration; with her sisters she was given an inheritance "along with their brothers."`,
  refs:["Job 42:13–15"]},

 {id:"kerenhappuch", name:"Keren-Happuch daughter of Job", short:"Keren-Happuch", cat:"wis", w:3,
  dates:"undated",
  desc:`The third of Job's three daughters born after his restoration; with her sisters she was given an inheritance "along with their brothers."`,
  refs:["Job 42:13–15"]},

 {id:"eliphaz_t", name:"Eliphaz the Temanite", short:"Eliphaz", cat:"wis", w:7,
  dates:"undated",
  desc:`The first of Job's three friends, who come "to sympathize with him and comfort him" and sit silent with him for seven days. He opens the debate — "Who, being innocent, has ever perished? … those who plow evil and those who sow trouble reap it" — and in his third speech accuses Job outright: "Is not your wickedness great? Are not your sins endless?" urging, "Submit to God and be at peace with him." At the end the LORD addresses him: "I am angry with you and your two friends, because you have not spoken the truth about me, as my servant Job has"; the three offer seven bulls and seven rams, and the LORD accepts Job's prayer for them.`,
  notconfused:`Eliphaz the firstborn of Esau, whose son was named Teman (Genesis 36:10–11); the book of Job does not connect them.`,
  refs:["Job 2:11–13","Job 4–5","Job 15","Job 22","Job 42:7–9"]},

 {id:"bildad", name:"Bildad the Shuhite", short:"Bildad", cat:"wis", w:6,
  dates:"undated",
  desc:`The second of Job's three friends. "Does God pervert justice? Does the Almighty pervert what is right?" he asks, and tells Job, "When your children sinned against him, he gave them over to the penalty of their sin"; "Surely God does not reject one who is blameless." His third, short speech begins, "Dominion and awe belong to God." With the others he is rebuked by the LORD and accepted through Job's prayer.`,
  notconfused:`Shuah, a son of Abraham by Keturah (Genesis 25:2); the book does not explain "Shuhite."`,
  refs:["Job 2:11","Job 8","Job 18","Job 25","Job 42:9"]},

 {id:"zophar", name:"Zophar the Naamathite", short:"Zophar", cat:"wis", w:6,
  dates:"undated",
  desc:`The third of Job's friends, who speaks twice. He tells Job, "Know this: God has even forgotten some of your sin," and promises restoration "if you devote your heart to him … if you put away the sin that is in your hand"; his second speech insists "that the mirth of the wicked is brief." With the others he is rebuked by the LORD and accepted through Job's prayer.`,
  refs:["Job 2:11","Job 11","Job 20","Job 42:9"]},

 {id:"elihu_b", name:"Elihu son of Barakel", short:"Elihu", cat:"wis", w:6,
  aliases:"Elihu the Buzite",
  dates:"undated",
  desc:`"Elihu son of Barakel the Buzite, of the family of Ram," a younger man who had waited to speak "because they were older than he." Angry with Job "for justifying himself rather than God," and with the three friends "because they had found no way to refute Job, and yet had condemned him," he speaks at length: "God is greater than any mortal"; "God is mighty, but despises no one." He is not mentioned again after his speeches, when the LORD answers Job out of the storm.`,
  notconfused:`The Elihu among Samuel's ancestors (1 Samuel 1:1). Buz was a brother of Uz among Nahor's sons (Genesis 22:21), and Ram is a name in Judah's line; the book does not explain "Buzite" or "the family of Ram."`,
  refs:["Job 32–37"]},

 {id:"heman_ez", name:"Heman the Ezrahite", short:"Heman the Ezrahite", cat:"wis", w:5,
  clash:"Heman", clashtag:"The wise man of Psalm 88 and 1 Kings 4:31, whom Solomon surpassed in wisdom.",
  dates:"before or in Solomon's day (undated)",
  desc:`Psalm 88 — "A song. A psalm of the Sons of Korah… A maskil of Heman the Ezrahite" — is a lament that ends, "darkness is my closest friend." 1 Kings 4:31 says Solomon "was wiser than anyone else, including Ethan the Ezrahite — wiser than Heman, Kalkol and Darda, the sons of Mahol"; 1 Chronicles 2:6 lists Ethan, Heman, Kalkol and Darda among the sons of Zerah.`,
  notconfused:`Heman the Levite musician, grandson of Samuel, whom David set over the temple music (1 Chronicles 6:33; 25:1); Scripture does not say whether they are the same man.`,
  refs:["Psalm 88","1 Kings 4:31","1 Chronicles 2:6"]},

 {id:"ethan_ez", name:"Ethan the Ezrahite", short:"Ethan the Ezrahite", cat:"wis", w:5,
  clash:"Ethan", clashtag:"The wise man of Psalm 89 and 1 Kings 4:31, whom Solomon surpassed in wisdom.",
  dates:"before or in Solomon's day (undated)",
  desc:`Psalm 89 is "A maskil of Ethan the Ezrahite": "I will sing of the LORD's great love forever." It rehearses the covenant with David — "I will establish your line forever and make your throne firm through all generations" — and then laments, "You have renounced the covenant with your servant and have defiled his crown in the dust." 1 Kings 4:31 names "Ethan the Ezrahite" among the wise men whom Solomon surpassed.`,
  notconfused:`Ethan the Merarite musician who sounded the cymbals with Heman and Asaph (1 Chronicles 15:17–19), and Ethan son of Zerah (1 Chronicles 2:6); Scripture does not say whether any of these are the same man.`,
  refs:["Psalm 89","1 Kings 4:31"]},

 {id:"agur", name:"Agur son of Jakeh", short:"Agur", cat:"wis", w:5,
  dates:"undated",
  desc:`"The sayings of Agur son of Jakeh — an inspired utterance. This man's utterance to Ithiel" (Proverbs 30). He calls himself "only a brute, not a man," asks, "Who has gone up to heaven and come down? … What is his name, and what is the name of his son?" and prays, "give me neither poverty nor riches, but give me only my daily bread." Nothing more is told of him, of Jakeh, or of Ithiel.`,
  refs:["Proverbs 30"]},

 {id:"lemuel", name:"King Lemuel", short:"Lemuel", cat:"wis", w:5,
  dates:"undated",
  desc:`"The sayings of King Lemuel — an inspired utterance his mother taught him" (Proverbs 31:1–9): "It is not for kings, Lemuel — it is not for kings to drink wine"; "Speak up for those who cannot speak for themselves, for the rights of all who are destitute." His kingdom is not named.`,
  refs:["Proverbs 31:1–9"]},

 {id:"lemuel_mother", name:"Lemuel's mother", short:"Lemuel's mother", cat:"wis", w:4,
  dates:"undated",
  desc:`Unnamed; she taught her son the "inspired utterance" of Proverbs 31:1–9: "Listen, my son! Listen, son of my womb! … Do not spend your strength on women, your vigor on those who ruin kings." The text does not say whether the poem of "a wife of noble character" that follows (31:10–31) is also hers.`,
  refs:["Proverbs 31:1–9"]},

 {id:"teacher_ecc", name:"The Teacher (Ecclesiastes)", short:"The Teacher", cat:"wis", w:8,
  aliases:"son of David, king in Jerusalem",
  dates:"undated",
  desc:`"The words of the Teacher, son of David, king in Jerusalem": "Meaningless! Meaningless! … Everything is meaningless." As "king over Israel in Jerusalem" he tests wisdom, pleasure and great works — houses, vineyards, gardens, reservoirs, "silver and gold … and a harem as well" — becoming "greater by far than anyone in Jerusalem before me," yet finds it all "a chasing after the wind." Still, "a person can do nothing better than to eat and drink and find satisfaction in their own toil. This too, I see, is from the hand of God." He "set in order many proverbs," and the book concludes: "Fear God and keep his commandments, for this is the duty of all mankind."`,
  notconfused:`The book never names him. He is traditionally identified with Solomon, David's son and king in Jerusalem, but the text itself only calls him "son of David."`,
  refs:["Ecclesiastes 1–2","Ecclesiastes 12:8–14"]},

 {id:"shulammite", name:"The Shulammite", short:"Shulammite", cat:"wis", w:6,
  aliases:"the beloved (Song of Songs)",
  dates:"undated",
  desc:`The woman whose voice leads "Solomon's Song of Songs." "Dark am I, yet lovely, daughters of Jerusalem," she says; "my mother's sons were angry with me and made me take care of the vineyards." She and her beloved praise one another in a series of love poems; she charges the daughters of Jerusalem, "Do not arouse or awaken love until it so desires," and the friends call, "Come back, come back, O Shulammite." She asks, "Place me like a seal over your heart … for love is as strong as death," and "Many waters cannot quench love."`,
  notconfused:`The Song never names her beloved. It mentions King Solomon's carriage and wedding day (3:6–11) and his vineyard (8:11–12), but whether Solomon is her beloved is disputed.`,
  refs:["Song of Songs 1:1–7","Song of Songs 2:7","Song of Songs 6:13","Song of Songs 8:6–12"]},

 {id:"cush_b", name:"Cush the Benjamite", short:"Cush", cat:"king", w:4,
  dates:"c. 10th c. BC (David's day)",
  desc:`Named only in the title of Psalm 7: "A shiggaion of David, which he sang to the LORD concerning Cush, a Benjamite." The psalm asks, "save and deliver me from all who pursue me"; nothing more is told of him.`,
  notconfused:`Cush son of Ham (Genesis 10:6), and the land of Cush.`,
  refs:["Psalm 7"]},


 {id:"nathan", name:"Nathan the prophet", short:"Nathan", cat:"proph", w:9,
  clash:"Nathan", clashtag:"The prophet who gave David the covenant promise and confronted him over Bathsheba.",
  dates:"c. 10th c. BC",
  desc:`David's prophet. When David wishes to build a house for the ark, the LORD sends Nathan to promise instead that the LORD will build David a house: "Your house and your kingdom will endure forever before me." After David takes Bathsheba, Nathan tells him the parable of the rich man and the poor man's ewe lamb — "You are the man!" — and announces that "the sword will never depart from your house." He conveys the LORD's name for Solomon, Jedidiah. Chronicles cites "the records of Nathan the prophet" for the reigns of David and Solomon. Psalm 51 is headed, "When the prophet Nathan came to him after David had committed adultery with Bathsheba."`,
  notconfused:`Nathan son of David, born in Jerusalem (2 Samuel 5:14).`,
  refs:["2 Samuel 7","2 Samuel 12:1–25","1 Kings 1","1 Chronicles 17","1 Chronicles 29:29","2 Chronicles 9:29","2 Chronicles 29:25","Psalm 51"]},

 {id:"elijah", name:"Elijah the Tishbite", short:"Elijah", cat:"proph", w:14, halo:1,
  aliases:"the Tishbite · from Tishbe in Gilead",
  dates:"c. 9th c. BC (days of Ahab and Ahaziah)",
  desc:`"Elijah the Tishbite, from Tishbe in Gilead," tells Ahab there will be "neither dew nor rain in the next few years except at my word." Fed by ravens at the Kerith Ravine and by a widow at Zarephath, whose son he raises, he faces the prophets of Baal on Mount Carmel — "How long will you waver between two opinions?" — and the fire of the LORD falls: "The LORD—he is God!" Fleeing Jezebel to Horeb, he hears "a gentle whisper" and is sent to anoint Hazael, Jehu and Elisha. He condemns Ahab over Naboth's vineyard, foretells Ahaziah's death and calls down fire on two companies of fifty. At the Jordan he parts the water with his cloak, and "a chariot of fire and horses of fire" appear as he goes "up to heaven in a whirlwind." Malachi promises his return. 2 Chronicles 21 records a letter from him to Jehoram of Judah, foretelling a lingering disease for murdering his brothers. Malachi 4:5–6: "See, I will send the prophet Elijah to you before that great and dreadful day of the LORD comes. He will turn the hearts of the parents to their children, and the hearts of the children to their parents."`,
  refs:["1 Kings 17–19","1 Kings 21:17–29","2 Kings 1–2","Malachi 4:5","2 Chronicles 21:12–15","Malachi 4:6"]},

 {id:"elisha", name:"Elisha son of Shaphat", short:"Elisha", cat:"proph", w:12,
  aliases:"the man of God",
  dates:"c. 9th c. BC (from Ahab's day to Jehoash's)",
  desc:`Plowing "with twelve yoke of oxen" when Elijah throws his cloak around him, he leaves to become Elijah's servant. Asking for "a double portion of your spirit," he sees Elijah taken up, takes his cloak and parts the Jordan. His ministry is full of signs: healing Jericho's water, cursing the jeering boys of Bethel, multiplying a widow's oil, raising the Shunammite's son, healing Naaman's leprosy, making an axhead float, blinding an Aramean army, and foretelling the end of Samaria's famine. He tells Hazael he will be king of Aram and sends a young prophet to anoint Jehu. King Jehoash weeps at his deathbed; after his burial a dead man thrown into his tomb "came to life and stood up on his feet."`,
  notconfused:`Elijah, his master and predecessor. His father Shaphat of Abel Meholah is not Shaphat son of Hori, the Simeonite spy (Numbers 13:5).`,
  refs:["1 Kings 19:16–21","2 Kings 2–9","2 Kings 13:14–21"]},

 {id:"isaiah", name:"Isaiah son of Amoz", short:"Isaiah", cat:"proph", w:14, halo:1,
  dates:"prophesied c. 740 – 686 BC, from Uzziah's death into Hezekiah's reign — dates approximate",
  desc:`"The vision concerning Judah and Jerusalem that Isaiah son of Amoz saw during the reigns of Uzziah, Jotham, Ahaz and Hezekiah, kings of Judah." "In the year that King Uzziah died" he sees the Lord enthroned in the temple with seraphim calling, "Holy, holy, holy is the LORD Almighty"; a live coal touches his lips and he answers, "Here am I. Send me!" With his son Shear-Jashub he meets Ahaz, threatened by Rezin and Pekah, and gives him the sign of Immanuel. His wife, "the prophetess," bears Maher-Shalal-Hash-Baz: "Here am I, and the children the LORD has given me. We are signs and symbols in Israel." For three years he goes "stripped and barefoot" as a sign against Egypt and Cush. He foretells Shebna's fall and Eliakim's rise, answers Hezekiah's prayer against Sennacherib, tells him to "put your house in order," then that fifteen years are added to his life, and warns that his treasures will be "carried off to Babylon." The book names Cyrus as the LORD's "shepherd" and "anointed," and speaks of a servant who "was pierced for our transgressions" and "will bear their iniquities." 2 Chronicles says he recorded the events of Uzziah's and Hezekiah's reigns and cried out in prayer with Hezekiah.`,
  notconfused:`The prophet Amos — Isaiah's father is Amoz, a different name.`,
  refs:["Isaiah 1:1","Isaiah 6","Isaiah 7–8","Isaiah 20","Isaiah 22:15–25","Isaiah 36–39","Isaiah 44:28–45:1","Isaiah 52:13–53:12","2 Kings 19–20","2 Chronicles 26:22","2 Chronicles 32:20","2 Chronicles 32:32"]},

 {id:"jeremiah", name:"Jeremiah son of Hilkiah", short:"Jeremiah", cat:"proph", w:14, halo:1,
  aliases:"the weeping prophet (traditional)",
  dates:"prophesied c. 627 – after 586 BC, from 'the thirteenth year of the reign of Josiah' into the exile — dates approximate",
  desc:`"One of the priests at Anathoth in the territory of Benjamin," called in Josiah's thirteenth year: "Before I formed you in the womb I knew you." "I am too young," he protests, but the LORD touches his mouth. He is told, "You must not marry," is threatened by the men of Anathoth, beaten and put in the stocks by the priest Pashhur, and nearly sentenced to death early in Jehoiakim's reign until Ahikam son of Shaphan protects him. He dictates his prophecies to Baruch; Jehoiakim cuts up the scroll and burns it, and Jeremiah dictates it again. He wears a yoke against Hananiah's promise of peace, writes to the exiles in Babylon to "build houses and settle down" for seventy years, and while Jerusalem is besieged buys his cousin Hanamel's field at Anathoth as a sign that "houses, fields and vineyards will again be bought in this land." Arrested as a deserter, thrown into a muddy cistern and rescued by Ebed-Melek, he stays in the courtyard of the guard until the city falls. Nebuzaradan frees him; he stays with Gedaliah, and after Gedaliah's murder is taken to Egypt against his own warning. He promises "a new covenant," with the law written "on their hearts." 2 Chronicles says he "composed laments for Josiah" and that the exile's seventy years fulfilled "the word of the LORD spoken by Jeremiah"; Daniel 9:2 reads his prophecy of seventy years. Lamentations does not name its author; tradition attributes it to him.`,
  notconfused:`Jeremiah of Libnah, father of Hamutal the queen mother (2 Kings 23:31), and Jeremiah the Rekabite, father of Jaazaniah (Jeremiah 35:3) — Scripture does not identify either with the prophet. His father Hilkiah, a priest of Anathoth, is not said to be Hilkiah the high priest of Josiah's day.`,
  refs:["Jeremiah 1","Jeremiah 16:1–2","Jeremiah 20","Jeremiah 26","Jeremiah 28–29","Jeremiah 31:31–34","Jeremiah 32","Jeremiah 36–43","Lamentations 1","2 Chronicles 35:25","2 Chronicles 36:12","2 Chronicles 36:21–22","Daniel 9:2"]},

 {id:"ezekiel", name:"Ezekiel son of Buzi", short:"Ezekiel", cat:"proph", w:13, halo:1,
  dates:"prophesied c. 593 – 571 BC in Babylon, from 'the fifth year of the exile of King Jehoiachin' to the twenty-seventh year — dates approximate",
  desc:`"Ezekiel the priest, the son of Buzi," among the exiles "by the Kebar River in the land of the Babylonians." In the fifth year of Jehoiachin's exile he sees the living creatures, the wheels and the glory of the LORD, and is made "a watchman for the people of Israel." He acts out the siege of Jerusalem on a block of clay. Carried in visions to the temple, he sees seventy elders with censers before "all the idols of Israel," Jaazaniah son of Shaphan among them, and women "mourning the god Tammuz"; as he prophesies against the city's leaders, Pelatiah son of Benaiah dies. He names Noah, Daniel and Job as men whose righteousness could save "only themselves." On the day the siege of Jerusalem begins, his wife — "the delight of your eyes" — dies, and he is told not to mourn, as a sign. When a fugitive brings the news, "The city has fallen!", his mouth is opened. He prophesies against Tyre, Egypt and Gog of Magog, sees a valley of dry bones come to life, promises "my servant David" as shepherd, and in the twenty-fifth year of the exile is shown a new temple where only "the descendants of Zadok" may come near to minister.`,
  refs:["Ezekiel 1–4","Ezekiel 8–11","Ezekiel 14:14","Ezekiel 24:15–27","Ezekiel 33:21–22","Ezekiel 34:23–24","Ezekiel 37","Ezekiel 40–48"]},

 {id:"daniel", name:"Daniel", short:"Daniel", cat:"proph", w:14, halo:1,
  aliases:"Belteshazzar",
  dates:"in Babylon from 'the third year of the reign of Jehoiakim' to 'the third year of Cyrus' — c. 605 – 536 BC, approximate",
  desc:`One of the young men "from the royal family and the nobility" brought to Babylon, given the name Belteshazzar by the chief official. He resolves "not to defile himself with the royal food and wine," and with Hananiah, Mishael and Azariah is found "ten times better" than all the king's magicians. He tells and interprets Nebuchadnezzar's dream of a statue — "You are that head of gold" — and is made ruler over the province of Babylon; interpreting the dream of the great tree, he urges the king, "Renounce your sins by doing what is right." Called before Belshazzar on the queen's advice, he reads the writing on the wall — "You have been weighed on the scales and found wanting" — and that night Belshazzar is slain. Under Darius the Mede he is one of three administrators; when he keeps praying three times a day toward Jerusalem he is thrown to the lions: "My God sent his angel, and he shut the mouths of the lions." His visions — four beasts, a ram and a goat, seventy "sevens," the kings of the North and the South — are explained to him by the angel Gabriel, and Michael is "the great prince who protects your people." From Jeremiah's prophecy he understands that the desolation of Jerusalem "would last seventy years." "Daniel prospered during the reign of Darius and the reign of Cyrus the Persian."`,
  notconfused:`The "Daniel" Ezekiel names with Noah and Job (Ezekiel 14:14, 20; 28:3) — the NIV footnote reads "Or Danel, a man of renown in ancient literature," so that may be another figure. Also Daniel son of David by Abigail (1 Chronicles 3:1) and Daniel of Ithamar's line who came back with Ezra (Ezra 8:2).`,
  refs:["Daniel 1–2","Daniel 4–6","Daniel 7–12"]},

 // ----- Major Prophets (Isaiah, Jeremiah, Lamentations, Ezekiel, Daniel) -----
 {id:"isaiah_wife", name:"The prophetess, Isaiah's wife", short:"Isaiah's wife", cat:"proph", w:4,
  dates:"c. 8th c. BC",
  desc:`Unnamed. Isaiah writes, "Then I made love to the prophetess, and she conceived and gave birth to a son," and the LORD tells him to name the boy Maher-Shalal-Hash-Baz.`,
  notconfused:`The "virgin" of the Immanuel sign (Isaiah 7:14) — Isaiah does not say whether they are the same woman.`,
  refs:["Isaiah 8:3"]},

 {id:"shear_jashub", name:"Shear-Jashub son of Isaiah", short:"Shear-Jashub", cat:"proph", w:4,
  dates:"c. 735 BC",
  desc:`Isaiah's son, whose name the NIV footnote explains as "a remnant will return." The LORD tells Isaiah, "Go out, you and your son Shear-Jashub, to meet Ahaz at the end of the aqueduct of the Upper Pool."`,
  refs:["Isaiah 7:3"]},

 {id:"maher_shalal", name:"Maher-Shalal-Hash-Baz son of Isaiah", short:"Maher-Shalal-Hash-Baz", cat:"proph", w:4,
  dates:"c. 734 BC",
  desc:`Before he is born Isaiah writes his name on "a large scroll" in front of witnesses; the NIV footnote explains it as "quick to the plunder, swift to the spoil." "Before the boy knows how to say 'My father' or 'My mother,' the wealth of Damascus and the plunder of Samaria will be carried off by the king of Assyria."`,
  refs:["Isaiah 8:1–4","Isaiah 8:18"]},

 {id:"immanuel", name:"Immanuel", short:"Immanuel", cat:"proph", w:6,
  dates:"sign given in Ahaz's reign, c. 735 BC",
  desc:`The sign the LORD gives Ahaz: "The virgin will conceive and give birth to a son, and will call him Immanuel" (NIV footnotes: "Or young woman"; "Immanuel means God with us"). "Before the boy knows enough to reject the wrong and choose the right, the land of the two kings you dread will be laid waste." Isaiah 8:8 cries out over Judah, "your land, Immanuel!" Isaiah does not name the mother or say who the child is.`,
  notconfused:`Matthew 1:23 quotes this prophecy at the birth of Jesus: "The virgin will conceive and give birth to a son, and they will call him Immanuel."`,
  refs:["Isaiah 7:10–16","Isaiah 8:8–10","Matthew 1:23"]},

 {id:"zechariah_jb", name:"Zechariah son of Jeberekiah", short:"Zechariah (Isaiah's witness)", cat:"king", w:3,
  clash:"Zechariah", clashtag:"One of Isaiah's two 'reliable witnesses' in Ahaz's reign.",
  dates:"c. 734 BC",
  desc:`Called by Isaiah, with Uriah the priest, as one of two "reliable witnesses" when he writes "Maher-Shalal-Hash-Baz" on a large scroll.`,
  notconfused:`Zechariah the prophet of the return (Zechariah 1:1), and Abijah's father Zechariah, grandfather of Hezekiah (2 Kings 18:2) — neither is said to be this man.`,
  refs:["Isaiah 8:2"]},

 {id:"sargon", name:"Sargon king of Assyria", short:"Sargon", cat:"natn", w:4,
  dates:"late 8th c. BC (Assyria)",
  desc:`Named once: "In the year that the supreme commander, sent by Sargon king of Assyria, came to Ashdod and attacked and captured it," the LORD tells Isaiah to take off his sackcloth and sandals, and he goes "stripped and barefoot" for three years as a sign against Egypt and Cush.`,
  refs:["Isaiah 20:1–6"]},

 {id:"hilkiah_a", name:"Hilkiah of Anathoth, father of Jeremiah", short:"Hilkiah (Jeremiah's father)", cat:"priest", w:3,
  clash:"Hilkiah", clashtag:"Jeremiah's father, 'one of the priests at Anathoth.'",
  dates:"c. 7th c. BC",
  desc:`Known only from the opening line of Jeremiah: "The words of Jeremiah son of Hilkiah, one of the priests at Anathoth in the territory of Benjamin."`,
  notconfused:`Hilkiah the high priest who found the Book of the Law in Josiah's day — the text does not say they are the same man.`,
  refs:["Jeremiah 1:1"]},

 {id:"hanamel", name:"Hanamel son of Shallum", short:"Hanamel", cat:"proph", w:4,
  dates:"c. 587 BC",
  desc:`Jeremiah's cousin, son of his uncle Shallum. As the LORD foretold, he comes to Jeremiah in the courtyard of the guard during the siege: "Buy my field at Anathoth… Since it is your right to redeem it and possess it, buy it for yourself." Jeremiah weighs out seventeen shekels of silver and has the deed sealed and witnessed.`,
  notconfused:`His father Shallum, Jeremiah's uncle, is not Shallum son of Josiah (Jehoahaz) or Shallum husband of Huldah.`,
  refs:["Jeremiah 32:6–15"]},

 {id:"baruch", name:"Baruch son of Neriah", short:"Baruch", cat:"proph", w:8,
  dates:"c. 605 – after 586 BC",
  desc:`"Baruch son of Neriah, the son of Mahseiah," Jeremiah's scribe. Jeremiah gives him the deed of the Anathoth field to keep in a clay jar. In Jehoiakim's fourth year Jeremiah dictates his prophecies to him, and he reads the scroll at the temple from Gemariah's room, then to the officials, who tell him, "You and Jeremiah, go and hide." After the king burns it, he writes it all again at Jeremiah's dictation. The LORD tells him through Jeremiah, "Should you then seek great things for yourself? Do not seek them… wherever you go I will let you escape with your life." Johanan's party accuses him of "inciting" Jeremiah against them and takes him with Jeremiah to Egypt.`,
  notconfused:`Baruch son of Zabbai, who repaired the wall (Nehemiah 3:20), and the Baruch who sealed Nehemiah's covenant (Nehemiah 10:6).`,
  refs:["Jeremiah 32:12–16","Jeremiah 36","Jeremiah 43:3–6","Jeremiah 45"]},

 {id:"seraiah_n", name:"Seraiah son of Neriah", short:"Seraiah (staff officer)", cat:"king", w:4,
  clash:"Seraiah", clashtag:"Zedekiah's staff officer, who threw Jeremiah's scroll against Babylon into the Euphrates.",
  dates:"c. 594 BC",
  desc:`"The staff officer Seraiah son of Neriah, the son of Mahseiah" — the same father and grandfather given for Baruch. He goes to Babylon with Zedekiah in his fourth year, carrying Jeremiah's scroll of disasters against Babylon, with orders to read it aloud, tie a stone to it and throw it into the Euphrates: "So will Babylon sink to rise no more."`,
  refs:["Jeremiah 51:59–64"]},

 {id:"ebed_melek", name:"Ebed-Melek the Cushite", short:"Ebed-Melek", cat:"king", w:6,
  dates:"c. 587 BC",
  desc:`"A Cushite, an official in the royal palace." When Jeremiah is left to sink in the mud of a cistern, he goes to the king at the Benjamin Gate: "These men have acted wickedly." With thirty men he lowers old rags and worn-out clothes on ropes — "Put these… under your arms to pad the ropes" — and lifts Jeremiah out. The LORD promises him, "I will rescue you on that day… because you trust in me."`,
  refs:["Jeremiah 38:7–13","Jeremiah 39:15–18"]},

 {id:"pashhur_i", name:"Pashhur son of Immer", short:"Pashhur (priest)", cat:"priest", w:5,
  clash:"Pashhur", clashtag:"The priest in charge of the temple who beat Jeremiah and put him in the stocks.",
  dates:"c. 600 BC",
  desc:`"The priest Pashhur son of Immer, the official in charge of the temple of the LORD," who has Jeremiah beaten and put in the stocks at the Upper Gate of Benjamin. Released the next day, Jeremiah tells him, "The LORD's name for you is not Pashhur, but Terror on Every Side," and that he and his household will die in exile in Babylon.`,
  notconfused:`Pashhur son of Malkijah, Zedekiah's official.`,
  refs:["Jeremiah 20:1–6"]},

 {id:"pashhur_m", name:"Pashhur son of Malkijah", short:"Pashhur (official)", cat:"king", w:4,
  clash:"Pashhur", clashtag:"Zedekiah's official, sent to Jeremiah and later among those who had him put in the cistern.",
  dates:"c. 588 BC",
  desc:`Sent by Zedekiah with the priest Zephaniah to ask Jeremiah, "Inquire now of the LORD for us." Later, with Shephatiah, Gedaliah son of Pashhur and Jehukal, he hears Jeremiah urging surrender and the officials tell the king, "This man should be put to death"; Jeremiah is lowered into "the cistern of Malkijah, the king's son."`,
  notconfused:`Pashhur son of Immer, the priest who put Jeremiah in the stocks. Whether his father is "Malkijah, the king's son," owner of the cistern, the text does not say.`,
  refs:["Jeremiah 21:1–2","Jeremiah 38:1–6"]},

 {id:"uriah_s", name:"Uriah son of Shemaiah", short:"Uriah (prophet)", cat:"proph", w:4,
  clash:"Uriah", clashtag:"The prophet from Kiriath Jearim whom Jehoiakim brought back from Egypt and killed.",
  dates:"c. 608 BC",
  desc:`"Uriah son of Shemaiah from Kiriath Jearim was another man who prophesied in the name of the LORD; he prophesied the same things… as Jeremiah did." When King Jehoiakim determines to kill him he flees to Egypt, but Elnathan son of Akbor brings him back and the king has him "struck down with a sword and his body thrown into the burial place of the common people."`,
  refs:["Jeremiah 26:20–23"]},

 {id:"elnathan", name:"Elnathan son of Akbor", short:"Elnathan", cat:"king", w:4,
  dates:"c. 608 – 604 BC",
  desc:`Sent by Jehoiakim to Egypt to bring back the prophet Uriah son of Shemaiah, who is then executed. Later, among the officials who hear Baruch read Jeremiah's scroll, he, Delaiah and Gemariah "urged the king not to burn the scroll."`,
  notconfused:`Elnathan father of Nehushta, King Jehoiachin's mother (2 Kings 24:8) — the text does not say they are the same man.`,
  refs:["Jeremiah 26:22","Jeremiah 36:12","Jeremiah 36:25"]},

 {id:"hananiah_a", name:"Hananiah son of Azzur", short:"Hananiah (false prophet)", cat:"proph", w:5,
  clash:"Hananiah", clashtag:"The prophet from Gibeon who broke Jeremiah's yoke and died that same year.",
  dates:"c. 594 BC",
  desc:`"The prophet Hananiah son of Azzur, who was from Gibeon," announces in the temple that within two years the LORD will break Babylon's yoke and bring back Jehoiachin, the exiles and the temple articles. He takes the yoke off Jeremiah's neck and breaks it. Jeremiah answers, "You have broken a wooden yoke, but in its place you will get a yoke of iron… This very year you are going to die." "In the seventh month of that same year, Hananiah the prophet died."`,
  notconfused:`Hananiah renamed Shadrach, Daniel's friend.`,
  refs:["Jeremiah 28"]},

 {id:"ahab_k", name:"Ahab son of Kolaiah", short:"Ahab (false prophet)", cat:"proph", w:3,
  clash:"Ahab", clashtag:"A lying prophet among the exiles in Babylon, burned by the king of Babylon.",
  dates:"c. 595 BC (Babylon)",
  desc:`With Zedekiah son of Maaseiah, "prophesying lies to you in my name" among the exiles in Babylon; they "committed adultery with their neighbors' wives." Jeremiah foretells that Nebuchadnezzar will put them to death, so that the exiles will curse, "May the LORD treat you like Zedekiah and Ahab, whom the king of Babylon burned in the fire."`,
  notconfused:`Ahab son of Omri, king of Israel.`,
  refs:["Jeremiah 29:21–23"]},

 {id:"zedekiah_m", name:"Zedekiah son of Maaseiah", short:"Zedekiah (false prophet)", cat:"proph", w:3,
  clash:"Zedekiah", clashtag:"A lying prophet among the exiles in Babylon, burned by the king of Babylon.",
  dates:"c. 595 BC (Babylon)",
  desc:`With Ahab son of Kolaiah, "prophesying lies to you in my name" among the exiles in Babylon; Jeremiah foretells that Nebuchadnezzar will burn them in the fire.`,
  notconfused:`King Zedekiah of Judah; Zedekiah son of Kenaanah, the prophet of Ahab's day; and Zedekiah son of Hananiah, Jehoiakim's official.`,
  refs:["Jeremiah 29:21–23"]},

 {id:"shemaiah_n", name:"Shemaiah the Nehelamite", short:"Shemaiah (Nehelamite)", cat:"proph", w:4,
  clash:"Shemaiah", clashtag:"The exile in Babylon who wrote demanding that Jeremiah be put in the stocks.",
  dates:"c. 595 BC (Babylon)",
  desc:`From Babylon he sends letters "in your own name" to the priest Zephaniah and the other priests: "why have you not reprimanded Jeremiah from Anathoth, who poses as a prophet among you?" Zephaniah reads the letter to Jeremiah, and the LORD answers that Shemaiah "has prophesied to you, even though I did not send him," and "will have no one left among this people."`,
  refs:["Jeremiah 29:24–32"]},

 {id:"elasah", name:"Elasah son of Shaphan", short:"Elasah", cat:"king", w:3,
  dates:"c. 597 BC",
  desc:`With Gemariah son of Hilkiah, sent by Zedekiah to Nebuchadnezzar in Babylon; Jeremiah entrusts them with his letter to the exiles.`,
  notconfused:`His father is not said outright to be Shaphan the secretary of Josiah's day, though that Shaphan's sons served in the same years.`,
  refs:["Jeremiah 29:3"]},

 {id:"gemariah_h", name:"Gemariah son of Hilkiah", short:"Gemariah (envoy)", cat:"king", w:3,
  clash:"Gemariah", clashtag:"Zedekiah's envoy to Babylon who carried Jeremiah's letter to the exiles.",
  dates:"c. 597 BC",
  desc:`With Elasah son of Shaphan, sent by Zedekiah to Nebuchadnezzar in Babylon; Jeremiah entrusts them with his letter to the exiles.`,
  notconfused:`Gemariah son of Shaphan, Jehoiakim's official. His father Hilkiah is not said to be the high priest or Jeremiah's father.`,
  refs:["Jeremiah 29:3"]},

 {id:"gemariah_s", name:"Gemariah son of Shaphan", short:"Gemariah (official)", cat:"king", w:4,
  clash:"Gemariah", clashtag:"Jehoiakim's official, from whose room Baruch read Jeremiah's scroll.",
  dates:"c. 604 BC",
  desc:`Baruch reads Jeremiah's scroll to the people "from the room of Gemariah son of Shaphan the secretary" by the New Gate of the temple. He is among the officials who hear it read, and with Elnathan and Delaiah "urged the king not to burn the scroll."`,
  notconfused:`Gemariah son of Hilkiah, who carried Jeremiah's letter to Babylon.`,
  refs:["Jeremiah 36:10–12","Jeremiah 36:25"]},

 {id:"micaiah_g", name:"Micaiah son of Gemariah", short:"Micaiah (Gemariah's son)", cat:"king", w:3,
  clash:"Micaiah", clashtag:"Grandson of Shaphan, who reported Baruch's reading of the scroll to the officials.",
  dates:"c. 604 BC",
  desc:`"Micaiah son of Gemariah, the son of Shaphan," hears Baruch read Jeremiah's scroll and goes down to the secretary's room in the palace to tell the officials "everything he had heard."`,
  notconfused:`Micaiah son of Imlah, the prophet of Ahab's day, and Micaiah father of Akbor (2 Kings 22:12).`,
  refs:["Jeremiah 36:11–13"]},

 {id:"elishama_s", name:"Elishama the secretary", short:"Elishama (secretary)", cat:"king", w:3,
  clash:"Elishama", clashtag:"Jehoiakim's secretary, in whose room Jeremiah's scroll was kept before it was burned.",
  dates:"c. 604 BC",
  desc:`Royal secretary under Jehoiakim. The officials are sitting in his room when Micaiah reports Baruch's reading; they put the scroll there, and Jehudi fetches it "from the room of Elishama the secretary" to read to the king.`,
  notconfused:`Elishama son of Ammihud, leader of Ephraim in the wilderness, and Elishama grandfather of Ishmael son of Nethaniah (Jeremiah 41:1).`,
  refs:["Jeremiah 36:12","Jeremiah 36:20–21"]},

 {id:"delaiah_s", name:"Delaiah son of Shemaiah", short:"Delaiah", cat:"king", w:3,
  dates:"c. 604 BC",
  desc:`One of Jehoiakim's officials who hear Baruch read Jeremiah's scroll; with Elnathan and Gemariah he "urged the king not to burn the scroll."`,
  notconfused:`Shemaiah son of Delaiah, the hired prophet of Nehemiah's day.`,
  refs:["Jeremiah 36:12","Jeremiah 36:25"]},

 {id:"zedekiah_h", name:"Zedekiah son of Hananiah", short:"Zedekiah (official)", cat:"king", w:3,
  clash:"Zedekiah", clashtag:"One of Jehoiakim's officials present when Baruch's scroll was reported.",
  dates:"c. 604 BC",
  desc:`Named among the officials sitting in the secretary's room when Micaiah reports Baruch's reading of Jeremiah's scroll.`,
  notconfused:`King Zedekiah, and the lying prophet Zedekiah son of Maaseiah.`,
  refs:["Jeremiah 36:12"]},

 {id:"jehudi", name:"Jehudi son of Nethaniah", short:"Jehudi", cat:"king", w:3,
  dates:"c. 604 BC",
  desc:`"Jehudi son of Nethaniah, the son of Shelemiah, the son of Cushi." Sent by the officials to bring Baruch and the scroll, he later fetches it for Jehoiakim and reads it to him; "whenever Jehudi had read three or four columns of the scroll, the king cut them off" and threw them into the firepot.`,
  notconfused:`His father Nethaniah is not said to be the father of Ishmael son of Nethaniah, Gedaliah's killer.`,
  refs:["Jeremiah 36:14","Jeremiah 36:21–23"]},

 {id:"jerahmeel_k", name:"Jerahmeel, a son of the king", short:"Jerahmeel", cat:"king", w:3,
  dates:"c. 604 BC",
  desc:`Ordered by Jehoiakim, with Seraiah son of Azriel and Shelemiah son of Abdeel, "to arrest Baruch the scribe and Jeremiah the prophet. But the LORD had hidden them."`,
  notconfused:`Jerahmeel son of Hezron of 1 Chronicles 2.`,
  refs:["Jeremiah 36:26"]},

 {id:"seraiah_a", name:"Seraiah son of Azriel", short:"Seraiah (Azriel's son)", cat:"king", w:3,
  clash:"Seraiah", clashtag:"Sent by Jehoiakim to arrest Baruch and Jeremiah.",
  dates:"c. 604 BC",
  desc:`Ordered by Jehoiakim, with Jerahmeel and Shelemiah son of Abdeel, to arrest Baruch and Jeremiah, "but the LORD had hidden them."`,
  refs:["Jeremiah 36:26"]},

 {id:"shelemiah_a", name:"Shelemiah son of Abdeel", short:"Shelemiah", cat:"king", w:3,
  dates:"c. 604 BC",
  desc:`Ordered by Jehoiakim, with Jerahmeel and Seraiah son of Azriel, to arrest Baruch and Jeremiah, "but the LORD had hidden them."`,
  refs:["Jeremiah 36:26"]},

 {id:"irijah", name:"Irijah son of Shelemiah", short:"Irijah", cat:"king", w:3,
  dates:"c. 588 BC",
  desc:`"The captain of the guard, whose name was Irijah son of Shelemiah, the son of Hananiah." When Jeremiah sets out for Benjamin during a lull in the siege, Irijah arrests him at the Benjamin Gate — "You are deserting to the Babylonians!" — and brings him to the officials, who beat and imprison him.`,
  refs:["Jeremiah 37:11–15"]},

 {id:"jonathan_sec", name:"Jonathan the secretary", short:"Jonathan (secretary)", cat:"king", w:3,
  clash:"Jonathan", clashtag:"The secretary whose house became Jeremiah's prison.",
  dates:"c. 588 BC",
  desc:`Jeremiah is beaten and "imprisoned in the house of Jonathan the secretary, which they had made into a prison," in a vaulted cell. He begs Zedekiah, "Do not send me back to the house of Jonathan the secretary, or I will die there."`,
  refs:["Jeremiah 37:15–20","Jeremiah 38:26"]},

 {id:"jehukal", name:"Jehukal son of Shelemiah", short:"Jehukal", cat:"king", w:3,
  dates:"c. 588 BC",
  desc:`Sent by Zedekiah with the priest Zephaniah to ask Jeremiah, "Please pray to the LORD our God for us." Later he is one of the four officials who hear Jeremiah urging surrender and demand his death.`,
  refs:["Jeremiah 37:3","Jeremiah 38:1–4"]},

 {id:"shephatiah_m", name:"Shephatiah son of Mattan", short:"Shephatiah", cat:"king", w:3,
  dates:"c. 588 BC",
  desc:`One of the four officials who hear Jeremiah telling the people to go over to the Babylonians and tell the king, "This man should be put to death."`,
  refs:["Jeremiah 38:1–4"]},

 {id:"gedaliah_p", name:"Gedaliah son of Pashhur", short:"Gedaliah (Pashhur's son)", cat:"king", w:3,
  clash:"Gedaliah", clashtag:"One of the officials who demanded Jeremiah's death during the siege.",
  dates:"c. 588 BC",
  desc:`One of the four officials who hear Jeremiah urging surrender and tell the king, "This man should be put to death."`,
  notconfused:`Gedaliah son of Ahikam, the governor at Mizpah. His father Pashhur is not said to be either Pashhur son of Immer or Pashhur son of Malkijah.`,
  refs:["Jeremiah 38:1–4"]},

 {id:"jaazaniah_r", name:"Jaazaniah son of Jeremiah, the Rekabite", short:"Jaazaniah (Rekabite)", cat:"king", w:3,
  clash:"Jaazaniah", clashtag:"Head of the Rekabite family whom Jeremiah tested with wine.",
  dates:"c. 600 BC",
  desc:`"Jaazaniah son of Jeremiah, the son of Habazziniah," brought with "the whole family of the Rekabites" into a side room of the temple. When Jeremiah sets out wine, they answer, "We do not drink wine, because our forefather Jehonadab son of Rekab gave us this command."`,
  notconfused:`His father Jeremiah is not the prophet. The other Jaazaniahs: the son of the Maakathite (Jeremiah 40:8), the son of Shaphan and the son of Azzur in Ezekiel.`,
  refs:["Jeremiah 35:3–11"]},

 {id:"jonathan_k", name:"Jonathan son of Kareah", short:"Jonathan (Kareah's son)", cat:"exile", w:3,
  clash:"Jonathan", clashtag:"Brother of Johanan, one of the army officers who came to Gedaliah at Mizpah.",
  dates:"c. 586 BC",
  desc:`"Johanan and Jonathan the sons of Kareah" are among the army officers who come with their men to Gedaliah at Mizpah.`,
  refs:["Jeremiah 40:8"]},

 {id:"seraiah_t", name:"Seraiah son of Tanhumeth", short:"Seraiah (Tanhumeth's son)", cat:"exile", w:3,
  clash:"Seraiah", clashtag:"One of the army officers who came to Gedaliah at Mizpah.",
  dates:"c. 586 BC",
  desc:`One of the army officers who come with their men to Gedaliah at Mizpah.`,
  refs:["2 Kings 25:23","Jeremiah 40:8"]},

 {id:"jaazaniah_m", name:"Jaazaniah son of the Maakathite", short:"Jaazaniah (officer)", cat:"exile", w:3,
  clash:"Jaazaniah", clashtag:"An army officer who came to Gedaliah at Mizpah.",
  dates:"c. 586 BC",
  desc:`"Jaazaniah the son of the Maakathite," one of the army officers who come with their men to Gedaliah at Mizpah.`,
  refs:["2 Kings 25:23","Jeremiah 40:8"]},

 {id:"jezaniah_h", name:"Jezaniah son of Hoshaiah", short:"Jezaniah", cat:"exile", w:3,
  dates:"c. 586 BC",
  desc:`Named with Johanan among the army officers who ask Jeremiah, "Pray that the LORD your God will tell us where we should go and what we should do."`,
  notconfused:`Azariah son of Hoshaiah (Jeremiah 43:2) — the text does not say whether they are brothers or the same man.`,
  refs:["Jeremiah 42:1–6"]},

 {id:"azariah_hs", name:"Azariah son of Hoshaiah", short:"Azariah (Hoshaiah's son)", cat:"exile", w:4,
  clash:"Azariah", clashtag:"The officer who told Jeremiah 'You are lying!' and led the flight to Egypt.",
  dates:"c. 586 BC",
  desc:`When Jeremiah tells the remnant not to go to Egypt, "Azariah son of Hoshaiah and Johanan son of Kareah and all the arrogant men said to Jeremiah, 'You are lying!'" and blame Baruch for "inciting" him.`,
  notconfused:`Jezaniah son of Hoshaiah (Jeremiah 42:1) — the text does not say whether they are brothers or the same man.`,
  refs:["Jeremiah 43:1–3"]},

 {id:"baalis", name:"Baalis king of the Ammonites", short:"Baalis", cat:"natn", w:4,
  dates:"c. 586 BC (Ammon)",
  desc:`Johanan warns Gedaliah, "Don't you know that Baalis king of the Ammonites has sent Ishmael son of Nethaniah to take your life?" After the murder Ishmael escapes "to the Ammonites."`,
  refs:["Jeremiah 40:14","Jeremiah 41:15"]},

 {id:"hophra", name:"Pharaoh Hophra king of Egypt", short:"Pharaoh Hophra", cat:"natn", w:4,
  clash:"Pharaoh", clashtag:"Pharaoh Hophra, whose fall Jeremiah foretold to the Judeans in Egypt.",
  dates:"early 6th c. BC (Egypt)",
  desc:`Named once, in Jeremiah's word to the Judeans in Egypt: "I am going to deliver Pharaoh Hophra king of Egypt into the hands of his enemies who want to kill him, just as I gave Zedekiah king of Judah into the hands of Nebuchadnezzar."`,
  notconfused:`The unnamed Pharaoh whose army marched out during the siege (Jeremiah 37:5) and the Pharaoh of Ezekiel 29–32 — the text does not name either as Hophra.`,
  refs:["Jeremiah 44:30"]},

 {id:"nergal_sharezer", name:"Nergal-Sharezer", short:"Nergal-Sharezer", cat:"natn", w:4,
  dates:"c. 586 BC (Babylon)",
  desc:`When the wall is breached, "all the officials of the king of Babylon came and took seats in the Middle Gate: Nergal-Sharezer of Samgar, Nebo-Sarsekim a chief officer, Nergal-Sharezer a high official." Nergal-Sharezer "a high official" is among those who have Jeremiah taken out of the courtyard of the guard and handed to Gedaliah. The list may name two men called Nergal-Sharezer or one man twice; the text does not say.`,
  notconfused:`Sharezer son of Sennacherib, who killed his father.`,
  refs:["Jeremiah 39:3","Jeremiah 39:13–14"]},

 {id:"nebo_sarsekim", name:"Nebo-Sarsekim", short:"Nebo-Sarsekim", cat:"natn", w:3,
  dates:"c. 586 BC (Babylon)",
  desc:`"A chief officer" of the king of Babylon, among the officials who take their seats in the Middle Gate when Jerusalem's wall is broken through.`,
  refs:["Jeremiah 39:3"]},

 {id:"nebushazban", name:"Nebushazban", short:"Nebushazban", cat:"natn", w:3,
  dates:"c. 586 BC (Babylon)",
  desc:`"A chief officer" who, with Nebuzaradan and Nergal-Sharezer, sends to have Jeremiah taken out of the courtyard of the guard and handed over to Gedaliah.`,
  refs:["Jeremiah 39:13–14"]},

 {id:"ezekiel_wife", name:"Ezekiel's wife", short:"Ezekiel's wife", cat:"proph", w:4,
  dates:"c. 588 BC (Babylon)",
  desc:`Unnamed. "Son of man, with one blow I am about to take away from you the delight of your eyes. Yet do not lament or weep." "So I spoke to the people in the morning, and in the evening my wife died." Ezekiel's silence is a sign that the people will not mourn when the temple, "the delight of your eyes," is taken.`,
  refs:["Ezekiel 24:15–27"]},

 {id:"jaazaniah_s", name:"Jaazaniah son of Shaphan", short:"Jaazaniah (Shaphan's son)", cat:"king", w:3,
  clash:"Jaazaniah", clashtag:"Standing among the seventy elders burning incense to idols in Ezekiel's vision.",
  dates:"c. 592 BC",
  desc:`In Ezekiel's vision of the temple, the walls are covered with "all the idols of Israel," and in front of them stand seventy elders of Israel, "and Jaazaniah son of Shaphan was standing among them," each with a censer: "The LORD does not see us."`,
  notconfused:`His father Shaphan is not said to be Shaphan the secretary, whose family supported Jeremiah.`,
  refs:["Ezekiel 8:10–12"]},

 {id:"jaazaniah_a", name:"Jaazaniah son of Azzur", short:"Jaazaniah (Azzur's son)", cat:"king", w:3,
  clash:"Jaazaniah", clashtag:"One of the twenty-five leaders at the temple's east gate in Ezekiel's vision.",
  dates:"c. 592 BC",
  desc:`One of the twenty-five men at the east gate of the temple, "leaders of the people," who are "plotting evil and giving wicked advice in this city."`,
  notconfused:`His father Azzur is not said to be the father of Hananiah son of Azzur, the false prophet.`,
  refs:["Ezekiel 11:1–4"]},

 {id:"pelatiah", name:"Pelatiah son of Benaiah", short:"Pelatiah", cat:"king", w:3,
  dates:"c. 592 BC",
  desc:`One of the twenty-five leaders at the east gate in Ezekiel's vision. "Now as I was prophesying, Pelatiah son of Benaiah died," and Ezekiel falls facedown: "Will you completely destroy the remnant of Israel?"`,
  notconfused:`His father Benaiah is not Benaiah son of Jehoiada, David's commander.`,
  refs:["Ezekiel 11:1–13"]},

 {id:"gog", name:"Gog of Magog", short:"Gog", cat:"natn", w:5,
  dates:"'in days to come' (Ezekiel 38:16)",
  desc:`"Gog, of the land of Magog, the chief prince of Meshek and Tubal" (NIV footnote: "Or the prince of Rosh"). "In days to come," when Israel is living in safety, the LORD will bring him against the land with many nations, then bring him down: "On the mountains of Israel you will fall" and give him a burial place in "the Valley of Hamon Gog."`,
  notconfused:`Gog son of Shemaiah, a Reubenite in the genealogy of 1 Chronicles 5:4.`,
  refs:["Ezekiel 38–39"]},

 {id:"shadrach", name:"Shadrach (Hananiah)", short:"Shadrach", cat:"exile", w:8,
  aliases:"Hananiah",
  clash:"Hananiah", clashtag:"Daniel's friend, renamed Shadrach, who survived the blazing furnace.",
  dates:"c. 605 BC onward (Babylon)",
  desc:`One of the young men from Judah chosen with Daniel; the chief official renames Hananiah "Shadrach." With Meshach and Abednego he is made an administrator over the province of Babylon. Refusing to worship Nebuchadnezzar's image of gold — "even if he does not, we want you to know, Your Majesty, that we will not serve your gods" — the three are thrown into the blazing furnace, where the king sees "four men walking around in the fire, unbound and unharmed." They come out with "no smell of fire on them," and the king promotes them.`,
  notconfused:`Hananiah son of Azzur, the false prophet who broke Jeremiah's yoke.`,
  refs:["Daniel 1","Daniel 2:17–18","Daniel 2:49","Daniel 3"]},

 {id:"meshach", name:"Meshach (Mishael)", short:"Meshach", cat:"exile", w:8,
  aliases:"Mishael",
  clash:"Mishael", clashtag:"Daniel's friend, renamed Meshach, who survived the blazing furnace.",
  dates:"c. 605 BC onward (Babylon)",
  desc:`One of the young men from Judah chosen with Daniel; the chief official renames Mishael "Meshach." With Shadrach and Abednego he is made an administrator over the province of Babylon, refuses to worship the image of gold, and is thrown into the blazing furnace and brought out unharmed.`,
  notconfused:`Mishael son of Uzziel, Aaron's cousin, who carried Nadab and Abihu's bodies out of the camp.`,
  refs:["Daniel 1","Daniel 2:17–18","Daniel 2:49","Daniel 3"]},

 {id:"abednego", name:"Abednego (Azariah)", short:"Abednego", cat:"exile", w:8,
  aliases:"Azariah",
  clash:"Azariah", clashtag:"Daniel's friend, renamed Abednego, who survived the blazing furnace.",
  dates:"c. 605 BC onward (Babylon)",
  desc:`One of the young men from Judah chosen with Daniel; the chief official renames Azariah "Abednego." With Shadrach and Meshach he is made an administrator over the province of Babylon, refuses to worship the image of gold, and is thrown into the blazing furnace and brought out unharmed; Nebuchadnezzar praises "the God of Shadrach, Meshach and Abednego, who has sent his angel and rescued his servants."`,
  notconfused:`The many other Azariahs — among them King Azariah (Uzziah) and Azariah son of Hoshaiah, who opposed Jeremiah.`,
  refs:["Daniel 1","Daniel 2:17–18","Daniel 2:49","Daniel 3"]},

 {id:"ashpenaz", name:"Ashpenaz chief of the court officials", short:"Ashpenaz", cat:"natn", w:4,
  dates:"c. 605 BC (Babylon)",
  desc:`"Chief of his court officials," ordered by Nebuchadnezzar to bring young men from Judah's royal family and nobility to be trained for three years. "The chief official gave them new names." God causes him "to show favor and compassion to Daniel," though he fears for his head if Daniel refuses the royal food; at the end of the training he presents them to the king.`,
  refs:["Daniel 1:3–18"]},

 {id:"arioch", name:"Arioch commander of the king's guard", short:"Arioch", cat:"natn", w:4,
  dates:"c. 603 BC (Babylon)",
  desc:`"The commander of the king's guard," sent to put to death the wise men of Babylon when none can tell Nebuchadnezzar his dream. Daniel speaks to him "with wisdom and tact," and Arioch takes him to the king: "I have found a man among the exiles from Judah who can tell the king what his dream means."`,
  notconfused:`Arioch king of Ellasar, one of the four kings in Abraham's day (Genesis 14:1).`,
  refs:["Daniel 2:14–25"]},

 {id:"babylon_queen", name:"The queen at Belshazzar's banquet", short:"The queen (Daniel 5)", cat:"natn", w:4,
  dates:"c. 539 BC (Babylon)",
  desc:`Hearing the uproar over the writing on the wall, she comes into the banquet hall: "Don't be alarmed! Don't look so pale! There is a man in your kingdom who has the spirit of the holy gods in him… Call for Daniel, and he will tell you what the writing means." The text does not name her or say whose wife or mother she is.`,
  refs:["Daniel 5:10–12"]},


 {id:"hosea", name:"Hosea son of Beeri", short:"Hosea", cat:"proph", w:11,
  dates:"prophesied from Jeroboam II's reign into Hezekiah's — c. 755 – after 715 BC, approximate",
  desc:`"The word of the LORD that came to Hosea son of Beeri during the reigns of Uzziah, Jotham, Ahaz and Hezekiah, kings of Judah, and during the reign of Jeroboam son of Jehoash king of Israel." He is told, "Go, marry a promiscuous woman and have children with her, for like an adulterous wife this land is guilty of unfaithfulness to the LORD," and marries Gomer daughter of Diblaim. Their children are named as signs: Jezreel, "because I will soon punish the house of Jehu for the massacre at Jezreel"; Lo-Ruhamah, "not loved"; and Lo-Ammi, "not my people" — yet "they will be called 'children of the living God.'" Told to "show your love to your wife again, though she is loved by another man," he buys her back "for fifteen shekels of silver and about a homer and a lethek of barley." His oracles charge Ephraim and Judah with Baal worship, the calf-idol of Samaria and Ephraim "now calling to Egypt, now turning to Assyria": "For I desire mercy, not sacrifice," "They sow the wind and reap the whirlwind," and "When Israel was a child, I loved him, and out of Egypt I called my son… How can I give you up, Ephraim?" He recalls Jacob, who "in the womb… grasped his brother's heel" and "struggled with the angel," and warns of destruction "as Shalman devastated Beth Arbel." The book ends, "Return, Israel, to the LORD your God."`,
  notconfused:`Hoshea son of Elah, the last king of Israel — a different spelling in the NIV. His father Beeri is not Beeri the Hittite, father of Esau's wife Judith (Genesis 26:34).`,
  refs:["Hosea 1–3","Hosea 6:6","Hosea 8:7","Hosea 10:14","Hosea 11:1–9","Hosea 12:3–4","Hosea 14"]},

 {id:"joel", name:"Joel son of Pethuel", short:"Joel", cat:"proph", w:8,
  clash:"Joel", clashtag:"The prophet of the locust plague and the outpouring of the Spirit.",
  dates:"undated — the book names no king; estimates range from the 9th to the 5th c. BC",
  desc:`"The word of the LORD that came to Joel son of Pethuel." A locust swarm has stripped Judah — "What the locust swarm has left the great locusts have eaten" — and he calls the priests to put on sackcloth and "declare a holy fast," for "the day of the LORD is near." He describes the locusts as an army with "the LORD… at the head": "Rend your heart and not your garments. Return to the LORD your God, for he is gracious and compassionate." The LORD answers, "I will repay you for the years the locusts have eaten," and promises, "I will pour out my Spirit on all people. Your sons and daughters will prophesy, your old men will dream dreams, your young men will see visions… everyone who calls on the name of the LORD will be saved." The nations are summoned to "the Valley of Jehoshaphat," the "valley of decision," for judgment — "Beat your plowshares into swords." Peter quotes the outpouring of the Spirit at Pentecost (Acts 2).`,
  notconfused:`Joel son of Samuel, who took bribes at Beersheba (1 Samuel 8:2). The "Valley of Jehoshaphat" is a place name; the text does not connect it to King Jehoshaphat.`,
  refs:["Joel 1–3","Acts 2:16–21"]},

 {id:"amos", name:"Amos of Tekoa", short:"Amos", cat:"proph", w:10,
  dates:"prophesied 'two years before the earthquake,' when Uzziah and Jeroboam II reigned — c. 760 BC, approximate",
  desc:`"The words of Amos, one of the shepherds of Tekoa — the vision he saw concerning Israel two years before the earthquake, when Uzziah was king of Judah and Jeroboam son of Jehoash was king of Israel." He pronounces "For three sins… even for four" on Damascus, Gaza, Tyre, Edom, Ammon and Moab, then on Judah and Israel, who "sell the innocent for silver, and the needy for a pair of sandals." He calls the wealthy women of Samaria "cows of Bashan" and warns: "prepare to meet your God," "That day will be darkness, not light," "But let justice roll on like a river, righteousness like a never-failing stream!" Twice shown locusts and fire, he pleads, "How can Jacob survive? He is so small!" and the LORD relents; then he is shown a plumb line — "I will spare them no longer." Amaziah the priest of Bethel reports him to Jeroboam and tells him, "Get out, you seer! Go back to the land of Judah." Amos answers, "I was neither a prophet nor the son of a prophet, but I was a shepherd, and I also took care of sycamore-fig trees. But the LORD took me." The book closes with a promise: "I will restore David's fallen shelter."`,
  notconfused:`Amoz, the father of Isaiah — a different name.`,
  refs:["Amos 1–2","Amos 4:1","Amos 4:12","Amos 5:18–24","Amos 7","Amos 8:1–2","Amos 9:11–15"]},

 {id:"obadiah", name:"Obadiah the prophet", short:"Obadiah", cat:"proph", w:6,
  clash:"Obadiah", clashtag:"The prophet whose one-chapter vision condemns Edom.",
  dates:"undated in the text; often placed after Jerusalem's fall in 586 BC (verses 11–14), but disputed",
  desc:`"The vision of Obadiah. This is what the Sovereign LORD says about Edom." Edom lives "in the clefts of the rocks" and says, "Who can bring me down to the ground?" — "Though you soar like the eagle and make your nest among the stars, from there I will bring you down." Because of "the violence against your brother Jacob" — standing aloof while foreigners "cast lots for Jerusalem," gloating "in the day of their destruction," and handing over survivors — "As you have done, it will be done to you." "Jacob will be a fire and Joseph a flame; Esau will be stubble," and "the kingdom will be the LORD's." Nothing else is said about him; his book is the shortest in the Old Testament.`,
  notconfused:`Obadiah, Ahab's palace administrator who hid a hundred prophets (1 Kings 18), and the other Obadiahs of Chronicles, Ezra and Nehemiah — Scripture does not identify any of them with the prophet.`,
  refs:["Obadiah 1"]},

 {id:"jonah", name:"Jonah son of Amittai", short:"Jonah", cat:"proph", w:10,
  dates:"8th c. BC — 2 Kings 14:25 places him in Jeroboam II's reign (c. 793 – 753 BC)",
  desc:`"The prophet from Gath Hepher," through whom the LORD promised that Jeroboam II would restore Israel's borders "from Lebo Hamath to the Dead Sea." Told, "Go to the great city of Nineveh and preach against it," he heads for Tarshish from Joppa instead. In the storm the captain wakes him — "How can you sleep? Get up and call on your god!" — the lot falls on him, and he tells the sailors, "I am a Hebrew and I worship the LORD, the God of heaven… Pick me up and throw me into the sea." "The LORD provided a huge fish to swallow Jonah, and Jonah was in the belly of the fish three days and three nights." He prays — "Salvation comes from the LORD" — and the fish vomits him onto dry land. Sent "a second time," he proclaims, "Forty more days and Nineveh will be overthrown." The Ninevites and their king fast in sackcloth, and God relents. Jonah is angry: "I knew that you are a gracious and compassionate God… Now, LORD, take away my life." God provides a leafy plant, a worm and a scorching east wind, and asks, "Should I not have concern for the great city of Nineveh?" The book ends on that question.`,
  refs:["Jonah 1–4","2 Kings 14:25"]},

 {id:"beeri_h", name:"Beeri, father of Hosea", short:"Beeri", cat:"proph", w:3,
  dates:"8th c. BC",
  desc:`Named only as the father of the prophet: "Hosea son of Beeri."`,
  notconfused:`Beeri the Hittite, father of Esau's wife Judith (Genesis 26:34).`,
  refs:["Hosea 1:1"]},

 {id:"gomer", name:"Gomer daughter of Diblaim", short:"Gomer", cat:"proph", w:6,
  dates:"8th c. BC",
  desc:`The wife Hosea is commanded to marry — "a promiscuous woman" — as a sign that "like an adulterous wife this land is guilty of unfaithfulness to the LORD." She bears a son, Jezreel; a daughter, Lo-Ruhamah; and, after weaning her daughter, another son, Lo-Ammi. The text says she bore the first son "to him" (Hosea); it does not say so of the other two. In chapter 3 the LORD tells Hosea, "Go, show your love to your wife again, though she is loved by another man and is an adulteress," and he buys her back and tells her, "You are to live with me many days." Chapter 3 does not name her; that she is Gomer is the natural reading but is not stated.`,
  notconfused:`Gomer son of Japheth, ancestor of a people in the Table of Nations (Genesis 10:2) and among Gog's allies (Ezekiel 38:6).`,
  refs:["Hosea 1:2–9","Hosea 3:1–3"]},

 {id:"diblaim", name:"Diblaim, father of Gomer", short:"Diblaim", cat:"proph", w:3,
  dates:"8th c. BC",
  desc:`Named only as the father of Hosea's wife: "Gomer daughter of Diblaim."`,
  refs:["Hosea 1:3"]},

 {id:"jezreel_h", name:"Jezreel son of Hosea", short:"Jezreel", cat:"proph", w:4,
  dates:"8th c. BC",
  desc:`Hosea and Gomer's first son. "Call him Jezreel, because I will soon punish the house of Jehu for the massacre at Jezreel, and I will put an end to the kingdom of Israel. In that day I will break Israel's bow in the Valley of Jezreel." The name returns as a promise: "great will be the day of Jezreel."`,
  notconfused:`Jezreel the town and valley, where Jehu killed Joram and Jezebel (2 Kings 9–10) — the son is named after the place.`,
  refs:["Hosea 1:3–5","Hosea 1:11","Hosea 2:22"]},

 {id:"lo_ruhamah", name:"Lo-Ruhamah", short:"Lo-Ruhamah", cat:"proph", w:4,
  dates:"8th c. BC",
  desc:`Gomer's daughter. "Call her Lo-Ruhamah (which means 'not loved'), for I will no longer show love to Israel." The reversal is promised: "I will show my love to the one I called 'Not my loved one.'" The text does not say she was Hosea's child.`,
  refs:["Hosea 1:6–8","Hosea 2:1","Hosea 2:23"]},

 {id:"lo_ammi", name:"Lo-Ammi", short:"Lo-Ammi", cat:"proph", w:4,
  dates:"8th c. BC",
  desc:`Gomer's second son, born after she weaned Lo-Ruhamah. "Call him Lo-Ammi (which means 'not my people'), for you are not my people, and I am not your God." Yet "in the place where it was said to them, 'You are not my people,' they will be called 'children of the living God.'" The text does not say he was Hosea's child.`,
  refs:["Hosea 1:8–10","Hosea 2:23"]},

 {id:"shalman", name:"Shalman", short:"Shalman", cat:"natn", w:3,
  dates:"before c. 725 BC",
  desc:`Named once by Hosea as a warning to Israel: "all your fortresses will be devastated — as Shalman devastated Beth Arbel on the day of battle, when mothers were dashed to the ground with their children." The text does not say who he was.`,
  notconfused:`Shalmaneser king of Assyria (2 Kings 17–18) — the name is similar, but Scripture does not identify them.`,
  refs:["Hosea 10:14"]},

 {id:"pethuel", name:"Pethuel, father of Joel", short:"Pethuel", cat:"proph", w:3,
  dates:"undated",
  desc:`Named only as the father of the prophet: "Joel son of Pethuel."`,
  refs:["Joel 1:1"]},

 {id:"amaziah_b", name:"Amaziah the priest of Bethel", short:"Amaziah (priest of Bethel)", cat:"priest", w:5,
  clash:"Amaziah", clashtag:"The priest of Bethel who reported Amos to Jeroboam II and told him to go home to Judah.",
  dates:"c. 760 BC",
  desc:`"Amaziah the priest of Bethel sent a message to Jeroboam king of Israel: 'Amos is raising a conspiracy against you in the very heart of Israel. The land cannot bear all his words.'" To Amos he says, "Get out, you seer! Go back to the land of Judah. Earn your bread there and do your prophesying there. Don't prophesy anymore at Bethel, because this is the king's sanctuary and the temple of the kingdom." Amos answers with a word against him: his wife, sons and daughters, his land, and "you yourself will die in a pagan country." The text does not record what happened to him.`,
  notconfused:`Amaziah son of Joash, king of Judah and father of Uzziah (2 Kings 14) — a different man; Bethel was the northern sanctuary of Jeroboam's calf (1 Kings 12:29).`,
  refs:["Amos 7:10–17"]},

 {id:"amittai", name:"Amittai, father of Jonah", short:"Amittai", cat:"proph", w:3,
  dates:"8th c. BC",
  desc:`Named only as the father of the prophet: "Jonah son of Amittai."`,
  refs:["Jonah 1:1","2 Kings 14:25"]},

 {id:"nineveh_king", name:"The king of Nineveh", short:"King of Nineveh", cat:"natn", w:5,
  dates:"8th c. BC, if Jonah's time — the book does not name him or give a year",
  desc:`"When Jonah's warning reached the king of Nineveh, he rose from his throne, took off his royal robes, covered himself with sackcloth and sat down in the dust." He decrees, with his nobles, that neither people nor animals eat or drink, that all be covered with sackcloth, and "Let everyone call urgently on God. Let them give up their evil ways and their violence. Who knows? God may yet relent." God sees "how they turned from their evil ways" and relents. Scripture does not give his name.`,
  notconfused:`The named kings of Assyria in Kings and Isaiah (Tiglath-Pileser, Shalmaneser, Sennacherib, Esarhaddon) — the book of Jonah does not identify him with any of them.`,
  refs:["Jonah 3:6–10"]},

 {id:"micah", name:"Micah of Moresheth", short:"Micah", cat:"proph", w:10,
  clash:"Micah", clashtag:"Micah of Moresheth, the prophet in the reigns of Jotham, Ahaz and Hezekiah.",
  dates:"prophesied in the reigns of Jotham, Ahaz and Hezekiah — c. 740 – 700 BC, approximate",
  desc:`"The word of the LORD that came to Micah of Moresheth during the reigns of Jotham, Ahaz and Hezekiah, kings of Judah — the vision he saw concerning Samaria and Jerusalem." He foretells that Samaria will become "a heap of rubble" and mourns, "I will go about barefoot and naked." He condemns those who "covet fields and seize them," the rulers who "tear the skin from my people," and prophets who "proclaim 'peace' if they have something to eat": "But as for me, I am filled with power, with the Spirit of the LORD." "Zion will be plowed like a field." He also sees the nations streaming to "the mountain of the LORD," where "they will beat their swords into plowshares," and a ruler from "Bethlehem Ephrathah, though you are small among the clans of Judah… whose origins are from of old, from ancient times." The LORD recalls sending "Moses to lead you, also Aaron and Miriam," and what "Balak king of Moab plotted and what Balaam son of Beor answered," and asks only "To act justly and to love mercy and to walk humbly with your God." The people have kept "the statutes of Omri and all the practices of Ahab's house." He ends, "Who is a God like you, who pardons sin…?" A century later elders defending Jeremiah recall that "Micah of Moresheth prophesied in the days of Hezekiah" and Hezekiah did not put him to death.`,
  notconfused:`Micah of Ephraim, whose household idol and Levite priest were taken by the Danites (Judges 17–18), and Micaiah son of Imlah, Ahab's prophet (1 Kings 22).`,
  refs:["Micah 1:1–9","Micah 2:1–2","Micah 3","Micah 4:1–5","Micah 5:2–5","Micah 6:4–8","Micah 6:16","Micah 7:18–20","Jeremiah 26:17–19"]},

 {id:"nahum", name:"Nahum the Elkoshite", short:"Nahum", cat:"proph", w:7,
  dates:"between the fall of Thebes (663 BC, which he recalls) and the fall of Nineveh (612 BC, which he foretells) — historical record",
  desc:`"A prophecy concerning Nineveh. The book of the vision of Nahum the Elkoshite." "The LORD is slow to anger but great in power; the LORD will not leave the guilty unpunished… The LORD is good, a refuge in times of trouble," but "with an overwhelming flood he will make an end of Nineveh." To Judah he brings "the feet of one who brings good news, who proclaims peace!" He describes the attack — chariots storming "through the streets," "the river gates are thrown open and the palace collapses" — and pronounces, "Woe to the city of blood, full of lies." "Are you better than Thebes?" which also went into exile. He closes addressing the unnamed "King of Assyria": "your shepherds slumber… Nothing can heal you; your wound is fatal." Nothing else is told of him.`,
  refs:["Nahum 1–3"]},

 {id:"habakkuk", name:"Habakkuk the prophet", short:"Habakkuk", cat:"proph", w:8,
  dates:"as the Babylonians rose to power — late 7th c. BC, approximate (the book names no king)",
  desc:`"The prophecy that Habakkuk the prophet received." "How long, LORD, must I call for help, but you do not listen?" The LORD answers, "I am raising up the Babylonians, that ruthless and impetuous people." Habakkuk asks again, "Your eyes are too pure to look on evil… Why then do you tolerate the treacherous?" and stands "at my watch… on the ramparts" to wait. He is told, "Write down the revelation and make it plain on tablets… Though it linger, wait for it… but the righteous person will live by his faithfulness." Five woes follow against the plunderer, and "the earth will be filled with the knowledge of the glory of the LORD as the waters cover the sea… The LORD is in his holy temple; let all the earth be silent before him." The book ends with "a prayer of Habakkuk the prophet": "in wrath remember mercy… Though the fig tree does not bud… yet I will rejoice in the LORD, I will be joyful in God my Savior."`,
  refs:["Habakkuk 1–3","Habakkuk 2:4"]},

 {id:"zephaniah", name:"Zephaniah son of Cushi", short:"Zephaniah", cat:"proph", w:7,
  clash:"Zephaniah", clashtag:"The prophet of Josiah's day who warned of the day of the LORD.",
  dates:"prophesied in Josiah's reign (c. 640 – 609 BC) — the year is not given",
  desc:`"The word of the LORD that came to Zephaniah son of Cushi, the son of Gedaliah, the son of Amariah, the son of Hezekiah, during the reign of Josiah son of Amon king of Judah." The text does not say whether this Hezekiah is the king. He announces, "I will sweep away everything from the face of the earth," and against Judah those who "swear by the LORD and who also swear by Molek": "The great day of the LORD is near… a day of wrath… a day of darkness and gloom." "Seek the LORD, all you humble of the land… perhaps you will be sheltered." He pronounces judgment on Philistia, Moab and Ammon, Cush, and Assyria — "leaving Nineveh utterly desolate" — then on Jerusalem, "the city of oppressors." It ends in joy: "Sing, Daughter Zion… The LORD your God is with you, the Mighty Warrior who saves. He will take great delight in you… but will rejoice over you with singing."`,
  notconfused:`Zephaniah the priest, son of Maaseiah, of Zedekiah's day (Jeremiah 21:1; 2 Kings 25:18), and Zephaniah the father of Josiah and Hen (Zechariah 6:10, 14).`,
  refs:["Zephaniah 1:1","Zephaniah 1–3","Zephaniah 3:14–17"]},

 {id:"haggai", name:"Haggai the prophet", short:"Haggai", cat:"proph", w:9,
  dates:"'in the second year of King Darius,' sixth to ninth month — 520 BC (historical record)",
  desc:`"In the second year of King Darius… the word of the LORD came through the prophet Haggai to Zerubbabel son of Shealtiel, governor of Judah, and to Joshua son of Jozadak, the high priest." The people say, "The time has not yet come to rebuild the LORD's house." "Is it a time for you yourselves to be living in your paneled houses, while this house remains a ruin?… Give careful thought to your ways." Zerubbabel, Joshua "and the whole remnant of the people obeyed," and Haggai, "the LORD's messenger," tells them, "I am with you." They begin work in the sixth month. In the seventh he encourages them — "be strong… and work. For I am with you… The glory of this present house will be greater than the glory of the former house." In the ninth he asks the priests about consecrated meat and defilement, and promises, "From this day on I will bless you." His last word is to Zerubbabel: "I will make you like my signet ring, for I have chosen you." Ezra records that he and Zechariah prophesied and that the elders "continued to build and prosper under the preaching of Haggai."`,
  refs:["Haggai 1–2","Ezra 5:1","Ezra 6:14"]},

 {id:"zechariah_p", name:"Zechariah son of Berekiah", short:"Zechariah (Prophet)", cat:"proph", w:11,
  clash:"Zechariah", clashtag:"Post-exilic prophet of visions who, with Haggai, urged on the rebuilding of the Temple.",
  dates:"from the second to the fourth year of Darius — 520 – 518 BC (historical record); the later chapters are undated",
  desc:`"The prophet Zechariah son of Berekiah, the son of Iddo"; Ezra calls him "a descendant of Iddo." His message opens, "'Return to me,' declares the LORD Almighty, 'and I will return to you.'" Beginning "during the night," he sees a series of visions, explained by "the angel who was talking with me": a man on a red horse among myrtle trees, four horns and four craftsmen, a man with a measuring line, Joshua the high priest before the angel of the LORD with Satan accusing him — "Is not this man a burning stick snatched from the fire?" — and given clean garments, a gold lampstand and two olive trees with the word to Zerubbabel, "'Not by might nor by power, but by my Spirit,'" a flying scroll, a woman in a basket, and four chariots. He makes a crown of silver and gold from the exiles Heldai, Tobijah and Jedaiah for Joshua: "Here is the man whose name is the Branch." When Bethel sends Sharezer and Regem-Melek to ask about fasting, he answers, "Administer true justice; show mercy and compassion." Later oracles foretell a king "lowly and riding on a donkey," a shepherd paid "thirty pieces of silver" thrown "to the potter," "the one they have pierced," "Strike the shepherd, and the sheep will be scattered," and a day when the LORD's feet "will stand on the Mount of Olives" and "the LORD will be king over the whole earth." Nehemiah 12:16 lists a Zechariah as head of Iddo's priestly family in Joiakim's day; the text does not say this is the prophet.`,
  notconfused:`Zechariah son of Jeberekiah, Isaiah's witness (Isaiah 8:2) — a similar father's name, two centuries earlier; King Zechariah of Israel; and Zechariah the father of John the Baptist in the New Testament.`,
  refs:["Zechariah 1–6","Zechariah 7–8","Zechariah 9:9","Zechariah 11:12–13","Zechariah 12:10","Zechariah 13:7","Zechariah 14:4–9","Ezra 5:1","Ezra 6:14","Nehemiah 12:16"]},

 {id:"cushi_z", name:"Cushi, father of Zephaniah", short:"Cushi", cat:"line", w:3,
  dates:"7th c. BC",
  desc:`Named only in Zephaniah's family line: "Zephaniah son of Cushi, the son of Gedaliah, the son of Amariah, the son of Hezekiah."`,
  notconfused:`Cushi, great-grandfather of Jehudi (Jeremiah 36:14), and the Cushites, the people of Cush — the text connects none of them to him.`,
  refs:["Zephaniah 1:1"]},

 {id:"gedaliah_z", name:"Gedaliah, Zephaniah's grandfather", short:"Gedaliah (Zephaniah's line)", cat:"line", w:3,
  clash:"Gedaliah", clashtag:"Grandfather of the prophet Zephaniah, named only in his family line.",
  dates:"7th c. BC",
  desc:`Named only in Zephaniah's family line, as son of Amariah and father of Cushi.`,
  notconfused:`Gedaliah son of Ahikam, the governor murdered at Mizpah, and Gedaliah son of Pashhur, who demanded Jeremiah's death.`,
  refs:["Zephaniah 1:1"]},

 {id:"amariah_z", name:"Amariah, Zephaniah's great-grandfather", short:"Amariah (Zephaniah's line)", cat:"line", w:3,
  clash:"Amariah", clashtag:"Great-grandfather of the prophet Zephaniah, named as 'son of Hezekiah.'",
  dates:"7th c. BC",
  desc:`Named only in Zephaniah's family line, as son of Hezekiah and father of Gedaliah. The text does not say whether this Hezekiah is the king of Judah; 2 Kings and Chronicles name no son of King Hezekiah called Amariah — the only son they name is Manasseh.`,
  notconfused:`Amariah the chief priest of Jehoshaphat's day (2 Chronicles 19:11).`,
  refs:["Zephaniah 1:1"]},

 {id:"berekiah_z", name:"Berekiah, father of Zechariah", short:"Berekiah", cat:"line", w:3,
  dates:"6th c. BC",
  desc:`Named only as the father of the prophet: "Zechariah son of Berekiah, the son of Iddo." Ezra calls Zechariah "a descendant of Iddo" without naming Berekiah.`,
  notconfused:`Berekiah the father of Asaph the musician (1 Chronicles 6:39), and Jeberekiah, father of the Zechariah who witnessed for Isaiah (Isaiah 8:2).`,
  refs:["Zechariah 1:1","Zechariah 1:7"]},

 {id:"iddo_z", name:"Iddo, grandfather of Zechariah", short:"Iddo (Zechariah's grandfather)", cat:"line", w:3,
  clash:"Iddo", clashtag:"Grandfather (or ancestor) of the prophet Zechariah.",
  dates:"6th c. BC",
  desc:`"The prophet Zechariah son of Berekiah, the son of Iddo"; Ezra calls Zechariah "a descendant of Iddo." Nehemiah 12:4 lists an Iddo among the priests who returned with Zerubbabel, and 12:16 a Zechariah as head of Iddo's family; the text does not say outright that these are the prophet's family.`,
  notconfused:`Iddo the seer of Rehoboam's and Abijah's day (2 Chronicles 9:29; 12:15; 13:22), and Iddo the leader at Kasiphia (Ezra 8:17).`,
  refs:["Zechariah 1:1","Ezra 5:1","Ezra 6:14","Nehemiah 12:4","Nehemiah 12:16"]},

 {id:"heldai_z", name:"Heldai the exile", short:"Heldai", cat:"exile", w:3,
  aliases:"Helem (Hebrew text of Zechariah 6:14)",
  dates:"c. 520 BC",
  desc:`One of three exiles "who have arrived from Babylon," from whom Zechariah is told to take silver and gold to make a crown for Joshua the high priest; the crown is then "given to Heldai, Tobijah, Jedaiah and Hen son of Zephaniah as a memorial in the temple of the LORD." The NIV footnote on 6:14 reads "Syriac; Hebrew Helem."`,
  notconfused:`Heldai the Netophathite, one of David's army commanders (1 Chronicles 27:15).`,
  refs:["Zechariah 6:10–14"]},

 {id:"tobijah_z", name:"Tobijah the exile", short:"Tobijah", cat:"exile", w:3,
  dates:"c. 520 BC",
  desc:`One of three exiles from Babylon whose silver and gold Zechariah uses to make the crown for Joshua the high priest; the crown is kept "as a memorial in the temple of the LORD."`,
  notconfused:`Tobiah the Ammonite official who opposed Nehemiah.`,
  refs:["Zechariah 6:10–14"]},

 {id:"jedaiah_z", name:"Jedaiah the exile", short:"Jedaiah", cat:"exile", w:3,
  dates:"c. 520 BC",
  desc:`One of three exiles from Babylon whose silver and gold Zechariah uses to make the crown for Joshua the high priest; the crown is kept "as a memorial in the temple of the LORD."`,
  notconfused:`The priestly family of Jedaiah listed among the returned exiles (Ezra 2:36; Nehemiah 12) — the text does not connect them.`,
  refs:["Zechariah 6:10–14"]},

 {id:"josiah_z", name:"Josiah son of Zephaniah", short:"Josiah (Zechariah 6)", cat:"exile", w:3,
  clash:"Josiah", clashtag:"Son of Zephaniah, at whose house in Jerusalem the crown for Joshua was made.",
  aliases:"possibly 'Hen son of Zephaniah' (Zechariah 6:14)",
  dates:"c. 520 BC",
  desc:`Zechariah is told to take the exiles' silver and gold and "go the same day to the house of Josiah son of Zephaniah." In 6:14 the crown is given to "Heldai, Tobijah, Jedaiah and Hen son of Zephaniah"; the NIV footnote gives "Or and the gracious one, the" for "Hen," so Hen may not be a personal name and may refer to Josiah. The text does not settle it.`,
  notconfused:`Josiah son of Amon, king of Judah — and the prophet Zephaniah of Josiah's reign is not said to be this Josiah's father.`,
  refs:["Zechariah 6:10","Zechariah 6:14"]},

 {id:"sharezer_b", name:"Sharezer of Bethel", short:"Sharezer (Bethel)", cat:"exile", w:3,
  clash:"Sharezer", clashtag:"Sent by the people of Bethel to ask the priests about fasting (Zechariah 7).",
  dates:"'in the fourth year of King Darius' — 518 BC",
  desc:`"The people of Bethel had sent Sharezer and Regem-Melek, together with their men, to entreat the LORD by asking the priests… and the prophets, 'Should I mourn and fast in the fifth month, as I have done for so many years?'" The LORD's answer through Zechariah: "When you fasted… was it really for me that you fasted?… Administer true justice; show mercy and compassion to one another," and the fasts "will become joyful and glad occasions."`,
  notconfused:`Sharezer son of Sennacherib, who with Adrammelek killed his father (2 Kings 19:37), and Nergal-Sharezer of Babylon (Jeremiah 39).`,
  refs:["Zechariah 7:1–7","Zechariah 8:19"]},

 {id:"regem_melek", name:"Regem-Melek", short:"Regem-Melek", cat:"exile", w:3,
  dates:"'in the fourth year of King Darius' — 518 BC",
  desc:`Sent with Sharezer by "the people of Bethel" to ask the priests and prophets whether they should still "mourn and fast in the fifth month." Zechariah's answer follows in chapters 7–8.`,
  refs:["Zechariah 7:2–3"]},

 {id:"malachi", name:"Malachi", short:"Malachi", cat:"proph", w:9,
  dates:"undated; after the temple was rebuilt, when Judah had a 'governor' — usually placed in the 5th c. BC",
  desc:`"A prophecy: The word of the LORD to Israel through Malachi" (NIV footnote: "Malachi means my messenger"). "'I have loved you,' says the LORD. 'But you ask, How have you loved us?' 'Was not Esau Jacob's brother?… Yet I have loved Jacob.'" He rebukes the priests for offering blind, lame and diseased animals — "Try offering them to your governor!" — and recalls "my covenant with Levi… True instruction was in his mouth." He condemns marrying "women who worship a foreign god" and being "unfaithful to the wife of your youth," and asks, "Will a mere mortal rob God?… Bring the whole tithe into the storehouse." "I will send my messenger, who will prepare the way before me. Then suddenly the Lord you are seeking will come to his temple… he will be like a refiner's fire." "A scroll of remembrance was written in his presence concerning those who feared the LORD": "for you who revere my name, the sun of righteousness will rise with healing in its rays." The book — the last of the Old Testament in the Christian order — ends: "Remember the law of my servant Moses… See, I will send the prophet Elijah to you before that great and dreadful day of the LORD comes."`,
  refs:["Malachi 1–4","Malachi 3:1","Malachi 4:4–6"]},

 {id:"huldah", name:"Huldah the prophet", short:"Huldah", cat:"proph", w:6,
  dates:"c. 622 BC (Judah)",
  desc:`"The prophet Huldah, who was the wife of Shallum son of Tikvah… keeper of the wardrobe," living in Jerusalem's New Quarter. Hilkiah, Ahikam, Akbor, Shaphan and Asaiah consult her for King Josiah about the newly found Book of the Law. She declares that disaster will come on Jerusalem as the book says, but because the king "humbled himself" he "will be buried in peace" and not see it.`,
  refs:["2 Kings 22:14–20"]},

 // ---------------- EXILE & RETURN ----------------
 {id:"zerubbabel", name:"Zerubbabel son of Shealtiel", short:"Zerubbabel", cat:"exile", w:9,
  dates:"c. 538 – 515 BC (post-exile)",
  desc:`Listed first among those who returned from Babylon. With "Joshua son of Jozadak" he rebuilds the altar, keeps the Festival of Tabernacles, and in the second year begins the temple; at the laying of its foundation the people shout for joy while the old men weep. He refuses the help of "the enemies of Judah and Benjamin" — "You have no part with us" — and when work restarts under Darius, urged on by Haggai and Zechariah, the temple is finished. Ezra calls him "son of Shealtiel"; 1 Chronicles 3:19 lists him among "the sons of Pedaiah," Shealtiel's brother. Haggai addresses him as "governor of Judah": the LORD "stirred up the spirit of Zerubbabel," he and the people begin work on the house of the LORD, and the last word of the book is to him — "I will take you, my servant Zerubbabel son of Shealtiel… and I will make you like my signet ring, for I have chosen you." Zechariah receives "the word of the LORD to Zerubbabel: 'Not by might nor by power, but by my Spirit'… The hands of Zerubbabel have laid the foundation of this temple; his hands will also complete it."`,
  refs:["Ezra 2:2","Ezra 3","Ezra 4:1–3","Ezra 5:1–2","Nehemiah 12:1","1 Chronicles 3:19","Haggai 2:23","Haggai 1:1","Haggai 1:12–14","Haggai 2:2–4","Haggai 2:20–23","Zechariah 4:6–10"]},

 {id:"jeshua_hp", name:"Joshua son of Jozadak", short:"Joshua (High Priest)", cat:"exile", w:7,
  aliases:"Jeshua the high priest",
  clash:"Joshua", clashtag:"The high priest who, with Zerubbabel, rebuilt the altar and Temple after the return from exile.",
  dates:"c. 538 – 515 BC (post-exile)",
  desc:`"Joshua son of Jozadak," the priest who returns with Zerubbabel; with his fellow priests he rebuilds the altar and, with his sons and the Levites, supervises the temple work, restarting it under Darius with the prophets' support. He is the father of Joiakim, the next high priest; some of his descendants had married foreign women in Ezra's day. The prophet Zechariah sees him cleansed and re-clothed in a vision. Haggai tells him, "Be strong, Joshua son of Jozadak, the high priest… and work." In Zechariah's vision he stands "before the angel of the LORD, and Satan standing at his right side to accuse him"; the LORD rebukes Satan — "Is not this man a burning stick snatched from the fire?" — and his filthy clothes are replaced: "See, I have taken away your sin." Zechariah later sets a crown of silver and gold on his head: "Here is the man whose name is the Branch."`,
  notconfused:`Joshua son of Nun, who conquered Canaan nearly a thousand years earlier.`,
  refs:["Ezra 2:2","Ezra 3:2–9","Ezra 5:2","Ezra 10:18","Nehemiah 12:1","Nehemiah 12:10","Zechariah 3","Haggai 1:1","Haggai 1:12–14","Haggai 2:4","Zechariah 6:9–15"]},

 {id:"ezra", name:"Ezra the priest and teacher of the Law", short:"Ezra", cat:"exile", w:11,
  aliases:"the scribe · teacher of the Law",
  dates:"arrived c. 458 BC (7th year of Artaxerxes; date disputed)",
  desc:`"Ezra son of Seraiah," whose line runs back through Hilkiah and Zadok to "Aaron the chief priest" — "a teacher well versed in the Law of Moses," who "had devoted himself to the study and observance of the Law of the LORD, and to teaching its decrees and laws in Israel." With a letter from Artaxerxes and gifts for the temple he leads a company from Babylon; ashamed to ask for soldiers, he proclaims a fast at the Ahava Canal, and "the hand of our God was on us." Told that many, priests included, have married foreign women, he tears his clothes and prays, "our guilt has reached to the heavens," and the people covenant to send the foreign wives away. In Nehemiah he reads the Book of the Law aloud from daybreak till noon, the Levites "giving the meaning," and leads the celebration of the Festival of Tabernacles and the dedication of the wall.`,
  refs:["Ezra 7–10","Nehemiah 8","Nehemiah 12:26","Nehemiah 12:36"]},

 {id:"nehemiah", name:"Nehemiah son of Hakaliah", short:"Nehemiah", cat:"exile", w:11,
  aliases:"cupbearer to the king · the governor",
  dates:"governor c. 445 – 433 BC (20th to 32nd year of Artaxerxes)",
  desc:`Cupbearer to Artaxerxes in Susa. Hearing that Jerusalem's wall is broken down, he weeps, fasts and prays; when the king asks why his face is sad, he prays "to the God of heaven" and asks to be sent to rebuild the city. Inspecting the walls by night, he rallies the people — "Let us start rebuilding" — and, against the mockery, plots and threats of Sanballat, Tobiah and Geshem, the builders work with a weapon in one hand: "Our God will fight for us!" The wall is completed "in fifty-two days." As governor he refuses the governor's food allowance, makes the nobles stop charging interest, and stands beside Ezra at the reading of the Law: "the joy of the LORD is your strength." Returning after a time away, he throws Tobiah out of the temple storeroom, restores the Levites' portions, enforces the Sabbath and confronts mixed marriages, praying, "Remember me with favor, my God."`,
  refs:["Nehemiah 1–2","Nehemiah 4–6","Nehemiah 8:9–10","Nehemiah 12:31–43","Nehemiah 13"]},

 {id:"esther", name:"Esther", short:"Esther", cat:"exile", w:11,
  aliases:"Hadassah",
  dates:"made queen c. 479 BC (7th year of Xerxes)",
  desc:`"Hadassah… also known as Esther," daughter of Abihail, raised by her cousin Mordecai "because she had neither father nor mother." Taken into the king's harem, she wins Hegai's favor and then the king's: Xerxes "set a royal crown on her head and made her queen instead of Vashti." Keeping her nationality secret at Mordecai's word, she reports his discovery of a plot against the king. When Haman's edict condemns the Jews, Mordecai tells her, "who knows but that you have come to your royal position for such a time as this?" She asks the Jews of Susa to fast and goes to the king unsummoned — "If I perish, I perish." At her second banquet she exposes "this vile Haman!" and pleads for her people; with Mordecai she writes to confirm the days of Purim.`,
  refs:["Esther 2","Esther 4–5","Esther 7–9"]},

 {id:"mordecai", name:"Mordecai son of Jair", short:"Mordecai", cat:"exile", w:9,
  aliases:"Mordecai the Jew",
  dates:"5th c. BC (Persia)",
  desc:`"A Jew of the tribe of Benjamin, named Mordecai son of Jair, the son of Shimei, the son of Kish," of the family carried into exile with Jehoiachin. He raises his orphaned cousin Esther and, sitting at the king's gate, uncovers Bigthana and Teresh's plot. He will not kneel to Haman, which provokes the edict against the Jews; he urges Esther to act "for such a time as this." Honored by the sleepless king through Haman himself, he receives the king's signet ring, writes the counter-edict, establishes Purim, and becomes "second in rank to King Xerxes… because he worked for the good of his people."`,
  notconfused:`The Mordecai named among those who returned with Zerubbabel (Ezra 2:2); his ancestor Kish is not Kish the father of King Saul.`,
  refs:["Esther 2:5–7","Esther 2:19–23","Esther 3:2–6","Esther 4","Esther 6","Esther 8–10"]},

 // ---------------- FOREIGN NATIONS ----------------
 // Genesis
 {id:"pharaoh_abr", name:"Pharaoh in Abram's day", short:"Pharaoh (Abram)", cat:"natn", w:6,
  clash:"Pharaoh", clashtag:"The king of Egypt who took Sarai into his palace, until the LORD struck his household with serious diseases.",
  dates:"c. 2000 BC (traditional; unnamed)",
  desc:`The unnamed king of Egypt when Abram went down during a famine. Told Sarai is Abram's sister, he takes her into his palace and treats Abram well — until "the LORD inflicted serious diseases on Pharaoh and his household." He sends them away: "Why didn't you tell me she was your wife?"`,
  notconfused:`The pharaoh of Joseph's day and the pharaoh of the Exodus — "Pharaoh" is a royal title, and Scripture names none of the three.`,
  refs:["Genesis 12:10–20"]},

 {id:"pharaoh_jos", name:"Pharaoh in Joseph's day", short:"Pharaoh (Joseph)", cat:"natn", w:9,
  clash:"Pharaoh", clashtag:"The king of Egypt whose dreams Joseph interpreted; he put Joseph in charge of Egypt and settled Jacob's family in Goshen.",
  dates:"c. 18th c. BC (traditional; unnamed)",
  desc:`The unnamed king who imprisons his chief cupbearer and baker, then dreams of seven fat and seven gaunt cows. When Joseph interprets, he asks, "Can we find anyone like this man, one in whom is the spirit of God?" and puts him in charge of the whole land of Egypt, giving him his signet ring, the name Zaphenath-Paneah and a wife, Asenath. He welcomes Jacob's family to Goshen, and Jacob blesses him.`,
  notconfused:`The pharaoh of Abram's day and the pharaoh of the Exodus, a "new king, to whom Joseph meant nothing" (Exodus 1:8).`,
  refs:["Genesis 40–41","Genesis 45:16–20","Genesis 47:1–10","Genesis 50:4–6"]},

 {id:"melchizedek", name:"Melchizedek", short:"Melchizedek", cat:"natn", w:8,
  aliases:"king of Salem · priest of God Most High",
  dates:"c. 2000 BC (traditional)",
  desc:`King of Salem and "priest of God Most High," who brings out bread and wine to Abram after his victory over the four kings and blesses him: "Blessed be Abram by God Most High, Creator of heaven and earth." Abram gives him a tenth of everything. Psalm 110:4 declares, "You are a priest forever, in the order of Melchizedek."`,
  refs:["Genesis 14:18–20","Psalm 110:4","Hebrews 7"]},

 {id:"kedorlaomer", name:"Kedorlaomer", short:"Kedorlaomer", cat:"natn", w:6,
  aliases:"king of Elam",
  dates:"c. 2000 BC (traditional)",
  desc:`King of Elam, to whom the kings of Sodom, Gomorrah and the other cities of the plain were subject for twelve years. When they rebel, he and his allies — Amraphel of Shinar, Arioch of Ellasar and Tidal of Goyim — defeat them in the Valley of Siddim and carry off Lot, until Abram routs them by night with 318 trained men.`,
  refs:["Genesis 14:1–17"]},

 {id:"bera", name:"Bera king of Sodom", short:"King of Sodom", cat:"natn", w:5,
  dates:"c. 2000 BC (traditional)",
  desc:`King of Sodom when the four kings attacked. After Abram's victory he offers, "Give me the people and keep the goods for yourself," but Abram will accept "nothing belonging to you, not even a thread or the strap of a sandal."`,
  refs:["Genesis 14:2","Genesis 14:17–24"]},

 {id:"abimelek", name:"Abimelek king of Gerar", short:"Abimelek", cat:"natn", w:8,
  clash:"Abimelek", clashtag:"King of Gerar who took Sarah and later made treaties with Abraham and Isaac.",
  dates:"c. 20th–19th c. BC (traditional)",
  desc:`King of Gerar who takes Sarah after Abraham calls her his sister, is warned by God in a dream, and returns her with gifts; he and his commander Phicol later make a treaty with Abraham at Beersheba. In Isaac's time "Abimelek king of the Philistines" sees Isaac caressing Rebekah, sends him away as "too powerful for us," then makes a sworn treaty with him. Genesis does not say whether this is the same king.`,
  notconfused:`Abimelek son of Gideon (Jerub-Baal), crowned king by the citizens of Shechem (Judges 9).`,
  refs:["Genesis 20","Genesis 21:22–34","Genesis 26"]},

 {id:"phicol", name:"Phicol", short:"Phicol", cat:"natn", w:5,
  dates:"c. 20th–19th c. BC (traditional)",
  desc:`"The commander of his forces" — Abimelek's — present at the treaty with Abraham at Beersheba and again, with the adviser Ahuzzath, at the treaty with Isaac.`,
  refs:["Genesis 21:22–32","Genesis 26:26–31"]},

 {id:"ephron", name:"Ephron the Hittite", short:"Ephron", cat:"natn", w:5,
  dates:"c. 1900 BC (traditional)",
  desc:`Son of Zohar, a Hittite who sells Abraham the field and cave of Machpelah near Mamre for four hundred shekels of silver as a burial site for Sarah. Abraham, Isaac, Rebekah, Leah and Jacob are later buried there.`,
  refs:["Genesis 23","Genesis 25:9–10","Genesis 49:29–32","Genesis 50:13"]},

 {id:"hamor", name:"Hamor the Hivite", short:"Hamor", cat:"natn", w:6,
  dates:"c. 18th c. BC (traditional)",
  desc:`"The ruler of that area" around Shechem and father of Shechem; Jacob buys land from his sons. After Shechem takes Dinah, Hamor proposes intermarriage with Jacob's family and persuades the men of his city to be circumcised — and is killed with his son by Simeon and Levi.`,
  refs:["Genesis 33:19","Genesis 34"]},

 {id:"shechem_p", name:"Shechem son of Hamor", short:"Shechem", cat:"natn", w:6,
  dates:"c. 18th c. BC (traditional)",
  desc:`Son of Hamor and "the most honored of all his father's family." He takes and rapes Dinah, then, his heart drawn to her, asks to marry her and agrees to the circumcision of every male in the city. Simeon and Levi kill him and take Dinah from his house.`,
  notconfused:`The city of Shechem, where Abram built his first altar in Canaan (12:6–7) and where these events take place.`,
  refs:["Genesis 34"]},

 {id:"potiphar", name:"Potiphar", short:"Potiphar", cat:"natn", w:8,
  dates:"c. 18th c. BC (traditional)",
  desc:`"One of Pharaoh's officials, the captain of the guard," who buys Joseph from the Ishmaelites and puts him in charge of his household — and the LORD blesses his house because of Joseph. When his wife accuses Joseph, "he burned with anger" and puts him in prison.`,
  notconfused:`Potiphera, priest of On, the father of Joseph's wife Asenath (41:45).`,
  refs:["Genesis 37:36","Genesis 39"]},

 {id:"potiphar_wife", name:"Potiphar's wife", short:"Potiphar's wife", cat:"natn", w:6,
  dates:"c. 18th c. BC (traditional)",
  desc:`Unnamed in Scripture. Day after day she urges Joseph, "Come to bed with me!" When he runs out leaving his cloak in her hand, she claims he tried to sleep with her, and her husband has him imprisoned.`,
  refs:["Genesis 39:7–20"]},

 {id:"cupbearer", name:"Pharaoh's chief cupbearer", short:"Chief cupbearer", cat:"natn", w:6,
  dates:"c. 18th c. BC (traditional)",
  desc:`Imprisoned with the chief baker, he dreams of a vine with three branches; Joseph foretells his restoration within three days. Restored, he "did not remember Joseph; he forgot him" — until two full years later, when Pharaoh's dreams remind him.`,
  refs:["Genesis 40","Genesis 41:9–13"]},

 {id:"baker", name:"Pharaoh's chief baker", short:"Chief baker", cat:"natn", w:5,
  dates:"c. 18th c. BC (traditional)",
  desc:`Imprisoned with the chief cupbearer, he dreams of three baskets of bread on his head and birds eating from the top one. As Joseph foretold, within three days Pharaoh impales him.`,
  refs:["Genesis 40"]},

 {id:"asenath", name:"Asenath", short:"Asenath", cat:"natn", w:6,
  dates:"c. 18th c. BC (traditional)",
  desc:`Daughter of Potiphera, priest of On, given by Pharaoh to Joseph as his wife; mother of Manasseh and Ephraim, born before the years of famine.`,
  refs:["Genesis 41:45","Genesis 41:50–52","Genesis 46:20"]},

 {id:"potiphera", name:"Potiphera", short:"Potiphera", cat:"natn", w:4,
  aliases:"priest of On",
  dates:"c. 18th c. BC (traditional)",
  desc:`Priest of On and father of Asenath, Joseph's wife.`,
  notconfused:`Potiphar, the captain of the guard who bought Joseph (39:1).`,
  refs:["Genesis 41:45","Genesis 41:50","Genesis 46:20"]},

 {id:"hirah", name:"Hirah the Adullamite", short:"Hirah", cat:"natn", w:4,
  dates:"c. 18th c. BC (traditional)",
  desc:`Judah's friend from Adullam, with whom Judah went to stay. Judah sends him with a young goat to recover his pledge from the woman at Enaim, but he cannot find her.`,
  refs:["Genesis 38:1","Genesis 38:12","Genesis 38:20–23"]},

 // Exodus
 {id:"pharaoh_opp", name:"Pharaoh of the oppression", short:"Pharaoh (oppression)", cat:"natn", w:8,
  clash:"Pharaoh", clashtag:"The 'new king, to whom Joseph meant nothing,' who enslaved Israel and ordered the Hebrew boys thrown into the Nile.",
  dates:"c. 16th–15th or 14th–13th c. BC (disputed; unnamed)",
  desc:`"A new king, to whom Joseph meant nothing," who fears Israel's growing numbers, puts slave masters over them to build the store cities Pithom and Rameses, orders the Hebrew midwives to kill the newborn boys, and then commands, "Every Hebrew boy that is born you must throw into the Nile." When Moses kills an Egyptian, Pharaoh tries to kill him. "During that long period, the king of Egypt died." Exodus does not say whether every mention in chapters 1–2 is the same king.`,
  notconfused:`The pharaoh of the plagues and the Exodus, who reigns after "the king of Egypt died" (Exodus 2:23; 4:19) — and the pharaohs of Abram's and Joseph's day in Genesis.`,
  refs:["Exodus 1:8–22","Exodus 2:15","Exodus 2:23","Exodus 4:19"]},

 {id:"pharaoh_daughter", name:"Pharaoh's daughter", short:"Pharaoh's daughter", cat:"natn", w:7,
  dates:"c. 16th c. BC (traditional; unnamed)",
  desc:`Coming down to bathe in the Nile, she finds the basket among the reeds: "This is one of the Hebrew babies." She pays the baby's own mother to nurse him, and when the child grows older "he became her son. She named him Moses, saying, 'I drew him out of the water.'" Exodus does not give her name.`,
  refs:["Exodus 2:5–10"]},

 // Exodus onward
 {id:"pharaoh_ex", name:"Pharaoh of the Exodus", short:"Pharaoh (Exodus)", cat:"natn", w:9,
  clash:"Pharaoh", clashtag:"The king of the plagues, who refused to let Israel go until the death of the firstborn, then pursued them to the sea.",
  dates:"c. 15th or 13th c. BC (disputed; unnamed)",
  desc:`The king Moses and Aaron confront after the death of the earlier king: "Who is the LORD, that I should obey him and let Israel go?" He makes the Israelites gather their own straw for bricks, and through blood, frogs, gnats, flies, the plague on livestock, boils, hail, locusts and darkness his heart is hardened — by himself and by the LORD. Twice he says "I have sinned," then refuses again. After his own firstborn son dies he summons Moses and Aaron in the night: "Up! Leave my people … And also bless me." Then he changes his mind and pursues with six hundred chariots; the sea flows back over his army, and "not one of them survived." Exodus does not name him or say plainly whether he himself died; scholars who try to identify him propose Amenhotep II or Rameses II, depending on the Exodus date.`,
  notconfused:`The pharaoh of the oppression earlier in Exodus, who "died" during Moses' years in Midian (Exodus 2:23), and the pharaohs of Genesis — the one who took Sarai into his palace (Genesis 12) and the one who raised Joseph to power (Genesis 41).`,
  refs:["Exodus 5","Exodus 7–12","Exodus 14","Psalm 136:15"]},

 {id:"sihon", name:"Sihon king of the Amorites", short:"Sihon", cat:"natn", w:7,
  dates:"c. 15th c. BC (traditional)",
  desc:`The Amorite king "who reigned in Heshbon," who had taken Moab's land as far as the Arnon. When Israel asks to pass along the King's Highway he refuses and marches out to fight at Jahaz; Israel puts him to the sword and takes his land from the Arnon to the Jabbok. Deuteronomy says "the LORD your God had made his spirit stubborn and his heart obstinate."`,
  refs:["Numbers 21:21–31","Deuteronomy 2:24–37","Deuteronomy 29:7","Joshua 12:2–3","Joshua 13:21","Psalm 135:11","Psalm 136:19"]},

 {id:"og", name:"Og king of Bashan", short:"Og", cat:"natn", w:7,
  dates:"c. 15th c. BC (traditional)",
  desc:`King of Bashan, who marches out against Israel at Edrei and is struck down with his sons and his army; his sixty fortified cities in Argob are taken. "Og king of Bashan was the last of the Rephaites. His bed was decorated with iron and was more than nine cubits long and four cubits wide." His land goes to the half-tribe of Manasseh.`,
  refs:["Numbers 21:33–35","Numbers 32:33","Deuteronomy 3:1–13","Joshua 12:4–5","Joshua 13:12","Psalm 135:11","Psalm 136:20"]},

 {id:"zur_m", name:"Zur", short:"Zur", cat:"natn", w:5,
  dates:"c. 15th c. BC (traditional)",
  desc:`"A tribal chief of a Midianite family," father of Kozbi. Numbers 31:8 names a Zur among "the five kings of Midian" — Evi, Rekem, Zur, Hur and Reba — killed in Israel's war on Midian; the text does not say outright that he is the same man. Joshua 13:21 lists the same five as "Midianite chiefs … princes allied with Sihon."`,
  refs:["Numbers 25:15","Numbers 25:18","Numbers 31:8","Joshua 13:21"]},

 {id:"kozbi", name:"Kozbi", short:"Kozbi", cat:"natn", w:5,
  dates:"c. 15th c. BC (traditional)",
  desc:`"Kozbi daughter of Zur, a tribal chief of a Midianite family," brought into the camp by Zimri during the Peor apostasy and killed with him by Phinehas. The LORD later says the Midianites "deceived you in the Peor incident involving their sister Kozbi."`,
  refs:["Numbers 25:6–18"]},

 {id:"balaam", name:"Balaam son of Beor", short:"Balaam", cat:"natn", w:8,
  dates:"c. 15th c. BC (traditional)",
  desc:`A diviner "at Pethor, near the Euphrates River," hired by Balak king of Moab to curse Israel. God first forbids him, then lets him go — "but do only what I tell you." On the road his donkey sees the angel of the LORD and speaks to him. From Bamoth Baal, Pisgah and Peor he blesses Israel instead of cursing them: "How can I curse those whom God has not cursed?" and "A star will come out of Jacob; a scepter will rise out of Israel." Numbers 31 says the Midianite women "followed Balaam's advice" at Peor, and he is killed with the sword in the war on Midian. Deuteronomy 23:5: "the LORD your God … turned the curse into a blessing for you."`,
  refs:["Numbers 22–24","Numbers 31:8","Numbers 31:16","Deuteronomy 23:4–5","Joshua 13:22","Joshua 24:9–10","Micah 6:5"]},

 {id:"balak", name:"Balak son of Zippor", short:"Balak", cat:"natn", w:6,
  aliases:"king of Moab",
  dates:"c. 15th c. BC (traditional)",
  desc:`"Balak son of Zippor, who was king of Moab at that time," terrified by Israel's numbers, sends twice for Balaam to curse them and builds seven altars on three heights. Each time Balaam blesses Israel; finally "Balak's anger burned against Balaam. He struck his hands together" and sent him home. Micah 6:5: "Remember what Balak king of Moab plotted and what Balaam son of Beor answered."`,
  refs:["Numbers 22–24","Micah 6:5"]},

 // Joshua
 {id:"adonizedek", name:"Adoni-Zedek king of Jerusalem", short:"Adoni-Zedek", cat:"natn", w:6,
  dates:"c. 1400 BC (early-date tradition; disputed)",
  desc:`King of Jerusalem who, alarmed that Gibeon had made peace with Israel, summons the kings of Hebron, Jarmuth, Lachish and Eglon: "Come up and help me attack Gibeon." Joshua marches all night from Gilgal; the LORD hurls hailstones on the fleeing Amorites and "the sun stood still." The five kings hide in the cave at Makkedah, and Joshua has his commanders put their feet on their necks before putting them to death.`,
  refs:["Joshua 10:1–27","Joshua 12:10"]},

 {id:"hoham", name:"Hoham king of Hebron", short:"Hoham", cat:"natn", w:4,
  dates:"c. 1400 BC (early-date tradition; disputed)",
  desc:`One of the five Amorite kings summoned by Adoni-Zedek against Gibeon; captured in the cave at Makkedah and put to death by Joshua.`,
  refs:["Joshua 10:3–27"]},

 {id:"piram", name:"Piram king of Jarmuth", short:"Piram", cat:"natn", w:4,
  dates:"c. 1400 BC (early-date tradition; disputed)",
  desc:`One of the five Amorite kings summoned by Adoni-Zedek against Gibeon; captured in the cave at Makkedah and put to death by Joshua.`,
  refs:["Joshua 10:3–27"]},

 {id:"japhia", name:"Japhia king of Lachish", short:"Japhia", cat:"natn", w:4,
  dates:"c. 1400 BC (early-date tradition; disputed)",
  desc:`One of the five Amorite kings summoned by Adoni-Zedek against Gibeon; captured in the cave at Makkedah and put to death by Joshua.`,
  notconfused:`Japhia, a town on Zebulun's boundary (Joshua 19:12).`,
  refs:["Joshua 10:3–27"]},

 {id:"debir_k", name:"Debir king of Eglon", short:"Debir (king)", cat:"natn", w:4,
  dates:"c. 1400 BC (early-date tradition; disputed)",
  desc:`One of the five Amorite kings summoned by Adoni-Zedek against Gibeon; captured in the cave at Makkedah and put to death by Joshua.`,
  notconfused:`The city of Debir (formerly Kiriath Sepher), which Joshua took and Othniel later captured (Joshua 10:38; 15:15).`,
  refs:["Joshua 10:3–27"]},

 {id:"horam", name:"Horam king of Gezer", short:"Horam", cat:"natn", w:4,
  dates:"c. 1400 BC (early-date tradition; disputed)",
  desc:`"Horam king of Gezer had come up to help Lachish, but Joshua defeated him and his army — until no survivors were left."`,
  refs:["Joshua 10:33"]},

 {id:"jabin_h", name:"Jabin king of Hazor", short:"Jabin (Joshua)", cat:"natn", w:6,
  clash:"Jabin", clashtag:"King of Hazor, 'the head of all these kingdoms,' defeated by Joshua at the Waters of Merom.",
  dates:"c. 1400 BC (early-date tradition; disputed)",
  desc:`King of Hazor — "the head of all these kingdoms" — who gathers the northern kings with "a large number of horses and chariots" at the Waters of Merom. Joshua attacks suddenly, hamstrings their horses and burns their chariots, then captures Hazor, puts its king to the sword and burns the city.`,
  notconfused:`Jabin king of Canaan, who reigned in Hazor in the time of Deborah (Judges 4).`,
  refs:["Joshua 11:1–13"]},

 {id:"jobab_m", name:"Jobab king of Madon", short:"Jobab", cat:"natn", w:4,
  dates:"c. 1400 BC (early-date tradition; disputed)",
  desc:`One of the northern kings Jabin of Hazor summoned to fight Israel at the Waters of Merom; the king of Madon is listed among the thirty-one kings Joshua defeated.`,
  notconfused:`Jobab son of Joktan (Genesis 10:29) and Jobab son of Zerah, an early king of Edom (Genesis 36:33).`,
  refs:["Joshua 11:1–12","Joshua 12:19"]},

 {id:"anak", name:"Anak", short:"Anak", cat:"natn", w:5,
  dates:"before the conquest (undated)",
  desc:`Ancestor of the Anakites, the people of great size whom the spies saw at Hebron — "the descendants of Anak come from the Nephilim" (Numbers 13:33). His forefather was Arba. Joshua destroyed the Anakites from the hill country; "only in Gaza, Gath and Ashdod did any survive."`,
  refs:["Numbers 13:22","Numbers 13:28–33","Deuteronomy 9:2","Joshua 11:21–22","Joshua 15:13–14"]},

 {id:"sheshai", name:"Sheshai", short:"Sheshai", cat:"natn", w:4,
  dates:"c. 15th c. BC (traditional)",
  desc:`One of "the three Anakites — Sheshai, Ahiman and Talmai, the sons of Anak," living at Hebron when the spies came, and later driven out by Caleb.`,
  refs:["Numbers 13:22","Joshua 15:14"]},

 {id:"ahiman", name:"Ahiman", short:"Ahiman", cat:"natn", w:4,
  dates:"c. 15th c. BC (traditional)",
  desc:`One of the three sons of Anak at Hebron whom the spies saw and Caleb later drove out.`,
  refs:["Numbers 13:22","Joshua 15:14"]},

 {id:"talmai", name:"Talmai son of Anak", short:"Talmai", cat:"natn", w:4,
  clash:"Talmai", clashtag:"A son of Anak at Hebron, driven out by Caleb.",
  dates:"c. 15th c. BC (traditional)",
  desc:`One of the three sons of Anak at Hebron whom the spies saw and Caleb later drove out.`,
  notconfused:`Talmai king of Geshur, the father of David's wife Maakah (2 Samuel 3:3).`,
  refs:["Numbers 13:22","Joshua 15:14"]},

 // Judges
 {id:"adonibezek", name:"Adoni-Bezek", short:"Adoni-Bezek", cat:"natn", w:5,
  dates:"c. 14th c. BC (traditional; disputed)",
  desc:`A Canaanite ruler defeated by Judah at Bezek; they cut off his thumbs and big toes, and he says, "Seventy kings with their thumbs and big toes cut off have picked up scraps under my table. Now God has paid me back for what I did to them." He dies in Jerusalem.`,
  refs:["Judges 1:4–7"]},

 {id:"cushan", name:"Cushan-Rishathaim", short:"Cushan-Rishathaim", cat:"natn", w:5,
  dates:"c. 14th c. BC (traditional; disputed)",
  desc:`"King of Aram Naharaim," to whom the Israelites were subject for eight years until the LORD gave him "into the hands of Othniel."`,
  refs:["Judges 3:8–10"]},

 {id:"eglon", name:"Eglon king of Moab", short:"Eglon", cat:"natn", w:6,
  dates:"c. 14th–13th c. BC (traditional; disputed)",
  desc:`King of Moab, "a very fat man," who with the Ammonites and Amalekites takes the City of Palms and rules Israel eighteen years. Ehud, bringing tribute, kills him in his upper room with a hidden sword.`,
  notconfused:`Eglon, the Amorite city whose king Debir was defeated by Joshua (Joshua 10:3).`,
  refs:["Judges 3:12–25"]},

 {id:"jabin_c", name:"Jabin king of Canaan", short:"Jabin (Judges)", cat:"natn", w:6,
  clash:"Jabin", clashtag:"'Jabin king of Canaan, who reigned in Hazor,' whose commander Sisera oppressed Israel for twenty years.",
  dates:"c. 12th c. BC (traditional; disputed)",
  desc:`"Jabin king of Canaan, who reigned in Hazor," with nine hundred iron chariots under his commander Sisera, who "cruelly oppressed the Israelites for twenty years." After Sisera's defeat "the hand of the Israelites pressed harder and harder against Jabin king of Canaan until they destroyed him."`,
  notconfused:`Jabin king of Hazor, defeated by Joshua at the Waters of Merom (Joshua 11).`,
  refs:["Judges 4:2–3","Judges 4:23–24","Psalm 83:9"]},

 {id:"sisera", name:"Sisera", short:"Sisera", cat:"natn", w:7,
  dates:"c. 12th c. BC (traditional; disputed)",
  desc:`"The commander of Jabin's army," based in Harosheth Haggoyim. Routed by Barak at the Kishon, he flees on foot to the tent of Jael, who kills him in his sleep with a tent peg. "From the heavens the stars fought … against Sisera." Psalm 83 prays, "Do to them as you did to Midian, as you did to Sisera and Jabin at the river Kishon."`,
  refs:["Judges 4","Judges 5:20–30","Psalm 83:9–10"]},

 {id:"sisera_mother", name:"Sisera's mother", short:"Sisera's mother", cat:"natn", w:4,
  dates:"c. 12th c. BC (traditional; disputed)",
  desc:`In Deborah's song she peers through the window — "Why is his chariot so long in coming?" — imagining her son dividing the plunder. Unnamed in Scripture.`,
  refs:["Judges 5:28–30"]},

 {id:"oreb", name:"Oreb", short:"Oreb", cat:"natn", w:4,
  dates:"c. 12th c. BC (traditional; disputed)",
  desc:`A Midianite leader captured by the men of Ephraim and killed "at the rock of Oreb"; his head was brought to Gideon.`,
  refs:["Judges 7:24–25","Judges 8:3","Psalm 83:11"]},

 {id:"zeeb", name:"Zeeb", short:"Zeeb", cat:"natn", w:4,
  dates:"c. 12th c. BC (traditional; disputed)",
  desc:`A Midianite leader captured by the men of Ephraim and killed "at the winepress of Zeeb"; his head was brought to Gideon.`,
  refs:["Judges 7:24–25","Judges 8:3","Psalm 83:11"]},

 {id:"zebah", name:"Zebah", short:"Zebah", cat:"natn", w:5,
  dates:"c. 12th c. BC (traditional; disputed)",
  desc:`One of "the two kings of Midian," pursued across the Jordan and captured by Gideon. Because they had killed Gideon's brothers at Tabor, Gideon kills them himself.`,
  refs:["Judges 8:4–21","Psalm 83:11"]},

 {id:"zalmunna", name:"Zalmunna", short:"Zalmunna", cat:"natn", w:5,
  dates:"c. 12th c. BC (traditional; disputed)",
  desc:`With Zebah, one of the two kings of Midian captured by Gideon; when Jether is afraid, they say, "Come, do it yourself. 'As is the man, so is his strength.'"`,
  refs:["Judges 8:4–21","Psalm 83:11"]},

 // 1 Samuel
 {id:"nahash", name:"Nahash the Ammonite", short:"Nahash", cat:"natn", w:6,
  dates:"c. 11th c. BC (traditional)",
  desc:`An Ammonite who besieges Jabesh Gilead and offers a treaty "only on the condition that I gouge out the right eye of every one of you." Saul rallies Israel and routs the Ammonites. Samuel later calls him "Nahash king of the Ammonites."`,
  refs:["1 Samuel 11:1–11","1 Samuel 12:12"]},

 {id:"agag", name:"Agag king of the Amalekites", short:"Agag", cat:"natn", w:6,
  dates:"c. 11th c. BC (traditional)",
  desc:`King of the Amalekites whom Saul spares against the LORD's command. Brought in chains, he thinks, "Surely the bitterness of death is past," but Samuel says, "As your sword has made women childless, so will your mother be childless among women," and puts him to death at Gilgal.`,
  notconfused:`Haman is called "the Agagite" in Esther; the text does not explain the term.`,
  refs:["1 Samuel 15:8–33"]},

 {id:"achish", name:"Achish son of Maok", short:"Achish", cat:"natn", w:7,
  aliases:"king of Gath",
  dates:"c. 11th c. BC (traditional)",
  desc:`King of Gath. David first flees to him and feigns madness — "Am I so short of madmen?" Later Achish takes in David and his six hundred men, gives him Ziklag, and trusts him — "you have been as pleasing in my eyes as an angel of God" — until the Philistine commanders refuse to let David fight with them at Gilboa. Psalm 34's title says David "pretended to be insane before Abimelek, who drove him away"; 1 Samuel 21 names the king of Gath as Achish, and the text does not explain the difference.`,
  refs:["1 Samuel 21:10–15","1 Samuel 27","1 Samuel 28:1–2","1 Samuel 29","Psalm 34"]},

 {id:"doeg", name:"Doeg the Edomite", short:"Doeg", cat:"natn", w:6,
  dates:"c. 11th c. BC (traditional)",
  desc:`"Saul's chief shepherd," who sees David at Nob and reports Ahimelek to Saul. When Saul's guards refuse to strike the priests, Doeg kills eighty-five of them and puts the town of Nob to the sword. Psalm 52 is headed, "When Doeg the Edomite had gone to Saul and told him: 'David has gone to the house of Ahimelek.'"`,
  refs:["1 Samuel 21:7","1 Samuel 22:9–19","Psalm 52"]},

 {id:"goliath", name:"Goliath of Gath", short:"Goliath", cat:"natn", w:8,
  dates:"c. 11th c. BC (traditional)",
  desc:`"A champion named Goliath, who was from Gath," whose "height was six cubits and a span," armed in bronze with an iron-pointed spear. For forty days he defies the ranks of Israel; David, coming "in the name of the LORD Almighty," fells him with a sling and a stone and cuts off his head with his own sword. His sword is later kept at Nob and given to David. 1 Chronicles 20:5 names his brother, Lahmi, killed by Elhanan son of Jair (compare 2 Samuel 21:19).`,
  refs:["1 Samuel 17","1 Samuel 21:9","1 Samuel 22:10","1 Chronicles 20:5"]},

 // 2 Samuel
 {id:"amalekite_msg", name:"The Amalekite messenger", short:"Amalekite messenger", cat:"natn", w:5,
  dates:"c. 1010 BC (traditional)",
  desc:`"The son of a foreigner, an Amalekite," who brings David Saul's crown and armband and claims, "I stood beside him and killed him." David has him struck down: "Your own mouth testified against you." (1 Samuel 31 says Saul fell on his own sword.) Unnamed in Scripture.`,
  refs:["2 Samuel 1:1–16","1 Samuel 31:4"]},

 {id:"rekab", name:"Rekab son of Rimmon", short:"Rekab", cat:"king", w:5,
  dates:"c. 1010 BC (traditional)",
  desc:`With his brother Baanah, a Benjamite raiding leader under Ish-Bosheth, who murders Ish-Bosheth in his bed and brings his head to David at Hebron; David has them killed.`,
  refs:["2 Samuel 4:2–12"]},

 {id:"baanah", name:"Baanah son of Rimmon", short:"Baanah", cat:"king", w:5,
  dates:"c. 1010 BC (traditional)",
  desc:`Rekab's brother and accomplice in the murder of Ish-Bosheth; executed on David's order.`,
  refs:["2 Samuel 4:2–12"]},

 {id:"hiram", name:"Hiram king of Tyre", short:"Hiram", cat:"natn", w:7,
  dates:"c. 10th c. BC (traditional)",
  desc:`King of Tyre, who "sent envoys to David, along with cedar logs and carpenters and stonemasons, and they built a palace for David." He sends cedar and craftsmen to Solomon for the temple in return for wheat, barley, wine and oil — "Because the LORD loves his people, he has made you their king" — sends Huram-Abi, and supplies sailors for Solomon's ships to Ophir.`,
  refs:["2 Samuel 5:11","1 Kings 5","1 Chronicles 14:1","2 Chronicles 2","2 Chronicles 8:18","2 Chronicles 9:10"]},

 {id:"hadadezer", name:"Hadadezer son of Rehob", short:"Hadadezer", cat:"natn", w:6,
  aliases:"king of Zobah",
  dates:"c. 10th c. BC (traditional)",
  desc:`King of Zobah, defeated by David when he went to restore his monument at the Euphrates; David took his gold shields to Jerusalem. He later sends Arameans under his commander Shobak to help the Ammonites, and is routed again at Helam.`,
  refs:["2 Samuel 8:3–12","2 Samuel 10:16–19"]},

 {id:"tou", name:"Tou king of Hamath", short:"Tou", cat:"natn", w:4,
  dates:"c. 10th c. BC (traditional)",
  desc:`King of Hamath, who had been at war with Hadadezer; he sends his son Joram to congratulate David with articles of silver, gold and bronze.`,
  refs:["2 Samuel 8:9–10"]},

 {id:"joram_t", name:"Joram son of Tou", short:"Joram (Tou's son)", cat:"natn", w:4,
  aliases:"Hadoram (1 Chronicles 18:10)",
  clash:"Joram", clashtag:"Son of Tou king of Hamath, sent to congratulate David.",
  dates:"c. 10th c. BC (traditional)",
  desc:`Sent by his father Tou king of Hamath to greet David after his victory over Hadadezer, bringing gifts that David dedicated to the LORD. 1 Chronicles 18:10 calls him Hadoram.`,
  refs:["2 Samuel 8:10","1 Chronicles 18:10"]},

 {id:"hanun", name:"Hanun son of Nahash", short:"Hanun", cat:"natn", w:5,
  dates:"c. 10th c. BC (traditional)",
  desc:`King of the Ammonites after his father. Suspecting David's envoys of spying, he shaves off half of each man's beard and cuts off their garments, provoking war with Israel.`,
  refs:["2 Samuel 10:1–14"]},

 {id:"shobak", name:"Shobak", short:"Shobak", cat:"natn", w:4,
  dates:"c. 10th c. BC (traditional)",
  desc:`"The commander of Hadadezer's army," struck down by David at Helam.`,
  refs:["2 Samuel 10:16–18"]},

 {id:"talmai_g", name:"Talmai king of Geshur", short:"Talmai (Geshur)", cat:"natn", w:5,
  clash:"Talmai", clashtag:"King of Geshur, Absalom's grandfather, with whom Absalom took refuge.",
  dates:"c. 10th c. BC (traditional)",
  desc:`"Talmai son of Ammihud, the king of Geshur," father of David's wife Maakah. Absalom flees to him after killing Amnon and stays three years.`,
  notconfused:`Talmai son of Anak, driven out of Hebron by Caleb (Joshua 15:14).`,
  refs:["2 Samuel 3:3","2 Samuel 13:37–38"]},

 {id:"araunah", name:"Araunah the Jebusite", short:"Araunah", cat:"natn", w:5,
  dates:"c. 10th c. BC (traditional)",
  desc:`Owner of the threshing floor where the angel of the LORD stops the plague. He offers it free, but David insists on paying — "I will not sacrifice to the LORD my God burnt offerings that cost me nothing" — and builds an altar there. 1 Chronicles 21:25 says David paid "six hundred shekels of gold for the site" (2 Samuel 24:24: fifty shekels of silver for the threshing floor and oxen). The LORD answered "with fire from heaven," David declared, "The house of the LORD God is to be here," and Solomon built the temple on that site.`,
  refs:["2 Samuel 24:16–25","1 Chronicles 21:15–22:1","2 Chronicles 3:1"]},

 // 1 Kings
 {id:"pharaoh_sol", name:"Pharaoh in Solomon's day", short:"Pharaoh (Solomon)", cat:"natn", w:5,
  clash:"Pharaoh", clashtag:"The king of Egypt whose daughter Solomon married, and who gave Gezer as her dowry.",
  dates:"c. 10th c. BC (unnamed)",
  desc:`The unnamed king of Egypt with whom Solomon "made an alliance… and married his daughter." He had captured and burned Gezer "and then gave it as a wedding gift to his daughter, Solomon's wife."`,
  refs:["1 Kings 3:1","1 Kings 7:8","1 Kings 9:16","1 Kings 9:24"]},

 {id:"sheba_queen", name:"The queen of Sheba", short:"Queen of Sheba", cat:"natn", w:7,
  dates:"c. 10th c. BC (unnamed)",
  desc:`Hearing of Solomon's fame "and his relationship to the LORD," she comes "to test Solomon with hard questions," with a great caravan of spices, gold and precious stones. Overwhelmed, she says, "not even half was told me," praises the LORD "who has delighted in you," and gives Solomon 120 talents of gold.`,
  refs:["1 Kings 10:1–13"]},

 {id:"huram", name:"Huram of Tyre", short:"Huram", cat:"natn", w:5,
  aliases:"Huram-Abi",
  dates:"c. 10th c. BC",
  desc:`A bronze craftsman "whose mother was a widow from the tribe of Naphtali and whose father was from Tyre," brought by Solomon to cast the temple's bronze pillars Jakin and Boaz, the Sea on twelve bulls, the stands and basins. 2 Chronicles calls him Huram-Abi, sent by Hiram, "whose mother was from Dan and whose father was from Tyre" (1 Kings names her tribe as Naphtali).`,
  notconfused:`Hiram king of Tyre, who supplied Solomon's cedar (1 Kings 5).`,
  refs:["1 Kings 7:13–47","2 Chronicles 2:13–14","2 Chronicles 4:11–16"]},

 {id:"hadad_e", name:"Hadad the Edomite", short:"Hadad", cat:"natn", w:5,
  dates:"c. 10th c. BC",
  desc:`"From the royal line of Edom," he fled to Egypt as a boy when Joab struck down Edom's men; Pharaoh gave him the sister of Queen Tahpenes as his wife. After David and Joab die he returns, and "the LORD raised up against Solomon an adversary."`,
  refs:["1 Kings 11:14–22"]},

 {id:"rezon", name:"Rezon son of Eliada", short:"Rezon", cat:"natn", w:5,
  dates:"c. 10th c. BC",
  desc:`A fugitive from Hadadezer king of Zobah who gathers a band, takes control in Damascus, and "was Israel's adversary as long as Solomon lived."`,
  refs:["1 Kings 11:23–25"]},

 {id:"shishak", name:"Shishak king of Egypt", short:"Shishak", cat:"natn", w:6,
  dates:"c. 10th c. BC (Egypt)",
  desc:`The king of Egypt with whom Jeroboam took refuge from Solomon. "In the fifth year of King Rehoboam, Shishak king of Egypt attacked Jerusalem" and carried off the treasures of the temple and palace, including Solomon's gold shields.`,
  refs:["1 Kings 11:40","1 Kings 14:25–26"]},

 {id:"benhadad_t", name:"Ben-Hadad son of Tabrimmon", short:"Ben-Hadad (Asa's day)", cat:"natn", w:5,
  clash:"Ben-Hadad", clashtag:"The king of Aram in Damascus paid by Asa to break his treaty with Baasha.",
  dates:"c. 9th c. BC (Aram)",
  desc:`"Ben-Hadad son of Tabrimmon, the son of Hezion, the king of Aram, who was ruling in Damascus." Bribed with the temple's silver and gold by Asa, he breaks his treaty with Baasha and conquers towns in northern Israel.`,
  refs:["1 Kings 15:18–20"]},

 {id:"benhadad_a", name:"Ben-Hadad king of Aram", short:"Ben-Hadad (Ahab's day)", cat:"natn", w:7,
  clash:"Ben-Hadad", clashtag:"The king of Aram who besieged Samaria in the days of Ahab.",
  dates:"c. 9th c. BC (Aram)",
  desc:`King of Aram who besieges Samaria with thirty-two kings and demands Ahab's silver, gold, wives and children. Defeated at Samaria and again at Aphek — where his officials think Israel's gods are "gods of the hills" — he is spared by Ahab: "He is my brother." 1 Kings does not say whether he is the Ben-Hadad of Asa's day.`,
  refs:["1 Kings 20","1 Kings 22:1–4"]},

 {id:"ethbaal", name:"Ethbaal king of the Sidonians", short:"Ethbaal", cat:"natn", w:5,
  dates:"c. 9th c. BC (Sidon)",
  desc:`Father of Jezebel, whom Ahab married — "Jezebel daughter of Ethbaal king of the Sidonians."`,
  refs:["1 Kings 16:31"]},

 // 2 Kings
 {id:"mesha", name:"Mesha king of Moab", short:"Mesha", cat:"natn", w:6,
  dates:"c. 9th c. BC (Moab)",
  desc:`A sheep-raising king who paid Israel "a hundred thousand lambs and the wool of a hundred thousand rams," and rebelled after Ahab died. Facing Joram, Jehoshaphat and the king of Edom, he is driven back to Kir Hareseth, where he offers his firstborn son "as a sacrifice on the city wall," and Israel withdraws. A Moabite inscription (the Mesha Stele) also names him.`,
  refs:["2 Kings 1:1","2 Kings 3:4–27"]},

 {id:"naaman", name:"Naaman the Aramean", short:"Naaman", cat:"natn", w:8,
  dates:"c. 9th c. BC (Aram)",
  desc:`"Commander of the army of the king of Aram… a valiant soldier, but he had leprosy." Sent by his king to the king of Israel, he comes to Elisha's door and is told to wash seven times in the Jordan; angry at first — "Are not Abana and Pharpar, the rivers of Damascus, better?" — he obeys, and his flesh becomes "clean like that of a young boy." "Now I know that there is no God in all the world except in Israel." He takes home earth to worship the LORD, asking pardon for bowing in the temple of Rimmon.`,
  refs:["2 Kings 5"]},

 {id:"hazael", name:"Hazael king of Aram", short:"Hazael", cat:"natn", w:8,
  dates:"c. 842 – c. 800 BC (Aram)",
  desc:`An official of Ben-Hadad sent to ask Elisha whether the king will recover. Elisha weeps, foretelling "the harm you will do to the Israelites," and says, "The LORD has shown me that you will become king of Aram." The next day Hazael smothers Ben-Hadad with a wet cloth and takes the throne. He wounds Joram at Ramoth Gilead, seizes Israel's land east of the Jordan in Jehu's day, takes Gath and is bought off from Jerusalem by Joash, and oppresses Israel "throughout the reign of Jehoahaz." Elijah had been told to anoint him (1 Kings 19:15). Amos 1:4: "I will send fire on the house of Hazael that will consume the fortresses of Ben-Hadad."`,
  refs:["1 Kings 19:15","2 Kings 8:7–15","2 Kings 8:28–29","2 Kings 10:32–33","2 Kings 12:17–18","2 Kings 13:3","2 Kings 13:22–25","Amos 1:3–5"]},

 {id:"benhadad_e", name:"Ben-Hadad king of Aram (Elisha's day)", short:"Ben-Hadad (Elisha's day)", cat:"natn", w:6,
  clash:"Ben-Hadad", clashtag:"The king of Aram who besieged Samaria in Elisha's day and was smothered by Hazael.",
  dates:"c. 9th c. BC (Aram)",
  desc:`"Ben-Hadad king of Aram mobilized his entire army" and besieges Samaria until famine grips the city; the LORD makes the Arameans hear "the sound of chariots and horses" and they flee. Later, ill in Damascus, he sends Hazael with forty camel-loads of gifts to ask Elisha, "Will I recover?" — and Hazael smothers him. 2 Kings does not say whether he is the Ben-Hadad of Ahab's day.`,
  refs:["2 Kings 6:24–7:16","2 Kings 8:7–15"]},

 {id:"benhadad_h", name:"Ben-Hadad son of Hazael", short:"Ben-Hadad (Hazael's son)", cat:"natn", w:5,
  clash:"Ben-Hadad", clashtag:"Hazael's son and successor, three times defeated by Jehoash of Israel.",
  dates:"c. 8th c. BC (Aram)",
  desc:`Son of Hazael, who keeps Israel under Aram's power in Jehoahaz's day and succeeds his father. "Three times Jehoash defeated him," recovering the towns taken from Jehoahaz — as Elisha's three arrow-strikes foretold.`,
  refs:["2 Kings 13:3","2 Kings 13:18–19","2 Kings 13:24–25"]},

 {id:"rezin", name:"Rezin king of Aram", short:"Rezin", cat:"natn", w:6,
  dates:"c. 8th c. BC (Aram)",
  desc:`King of Aram sent with Pekah of Israel against Judah in Jotham's day. Together they besiege Ahaz in Jerusalem but "could not overpower him"; Rezin recovers Elath for Aram. At Ahaz's request Tiglath-Pileser captures Damascus, deports its people to Kir "and put Rezin to death." Isaiah calls Rezin and "the son of Remaliah" "two smoldering stubs of firewood": "the head of Damascus is only Rezin."`,
  refs:["2 Kings 15:37","2 Kings 16:5–9","Isaiah 7:1–9","Isaiah 8:6"]},

 {id:"tiglath", name:"Tiglath-Pileser king of Assyria", short:"Tiglath-Pileser", cat:"natn", w:7,
  aliases:"Pul",
  dates:"reigned 745 – 727 BC (Assyria)",
  desc:`In Pekah's reign he takes Ijon, Abel Beth Maakah, Kedesh, Hazor, Gilead and Galilee, "including all the land of Naphtali," and deports the people to Assyria. Paid by Ahaz with temple treasure, he captures Damascus and kills Rezin; Ahaz meets him there and copies an altar he sees. 1 Chronicles 5:26 identifies the two: "Pul king of Assyria (that is, Tiglath-Pileser king of Assyria)." As Pul he invaded Israel in Menahem's reign and took a thousand talents of silver; he also exiled Reuben, Gad and the half-tribe of Manasseh to Halah, Habor, Hara and the river of Gozan.`,
  notconfused:`Shalmaneser, the next Assyrian king, who took Samaria (2 Kings 17).`,
  refs:["2 Kings 15:29","2 Kings 16:7–10","2 Kings 15:19–20","1 Chronicles 5:6","1 Chronicles 5:26","2 Chronicles 28:20–21"]},

 {id:"shalmaneser", name:"Shalmaneser king of Assyria", short:"Shalmaneser", cat:"natn", w:6,
  dates:"reigned 727 – 722 BC (Assyria)",
  desc:`Overlord of Hoshea, whom he imprisons as a traitor for sending envoys to Egypt and withholding tribute. He besieges Samaria for three years; "in the ninth year of Hoshea, the king of Assyria captured Samaria and deported the Israelites to Assyria."`,
  notconfused:`Shalman, who "devastated Beth Arbel" (Hosea 10:14) — the name is similar, but Scripture does not identify them.`,
  refs:["2 Kings 17:3–6","2 Kings 18:9–11"]},

 {id:"so_egypt", name:"So king of Egypt", short:"So", cat:"natn", w:4,
  dates:"c. 725 BC (Egypt) — identity uncertain",
  desc:`The king of Egypt to whom Hoshea "had sent envoys," which Assyria treated as treason. He is not securely identified in Egyptian records.`,
  refs:["2 Kings 17:4"]},

 {id:"field_cmdr", name:"The Assyrian field commander", short:"Field commander", cat:"natn", w:6,
  dates:"c. 701 BC (Assyria)",
  desc:`Sent by Sennacherib from Lachish with "his supreme commander, his chief officer and his field commander," he stands by the aqueduct of the Upper Pool and taunts Jerusalem in Hebrew so the people on the wall can hear: Egypt is "that splintered reed of a staff," and "Has the god of any nation ever delivered his land from the hand of the king of Assyria?"`,
  refs:["2 Kings 18:17–37","2 Kings 19:4","2 Kings 19:8","Isaiah 36–37"]},

 {id:"tirhakah", name:"Tirhakah king of Cush", short:"Tirhakah", cat:"natn", w:4,
  dates:"c. 701 BC (Cush / Egypt)",
  desc:`Sennacherib receives "a report that Tirhakah, the king of Cush, was marching out to fight against him," and sends Hezekiah a second threatening message.`,
  refs:["2 Kings 19:9","Isaiah 37:9"]},

 {id:"adrammelek", name:"Adrammelek son of Sennacherib", short:"Adrammelek", cat:"natn", w:4,
  dates:"c. 681 BC (Assyria)",
  desc:`With his brother Sharezer he kills their father Sennacherib "while he was worshiping in the temple of his god Nisrok," and escapes to the land of Ararat.`,
  notconfused:`Adrammelek, a god of the Sepharvites to whom children were burned (2 Kings 17:31).`,
  refs:["2 Kings 19:37","Isaiah 37:38"]},

 {id:"sharezer", name:"Sharezer son of Sennacherib", short:"Sharezer", cat:"natn", w:4,
  clash:"Sharezer", clashtag:"Son of Sennacherib, who with Adrammelek killed his father.",
  dates:"c. 681 BC (Assyria)",
  desc:`With his brother Adrammelek he kills Sennacherib with the sword and flees to Ararat.`,
  notconfused:`Sharezer of Bethel, sent to ask the priests about fasting (Zechariah 7:2), and Nergal-Sharezer of Babylon (Jeremiah 39).`,
  refs:["2 Kings 19:37","Isaiah 37:38"]},

 {id:"esarhaddon", name:"Esarhaddon king of Assyria", short:"Esarhaddon", cat:"natn", w:4,
  dates:"reigned 681 – 669 BC (Assyria)",
  desc:`Son of Sennacherib, who "succeeded him as king" after his brothers murdered their father. Ezra 4:2 has the opponents of the rebuilding say he "brought us here."`,
  refs:["2 Kings 19:37","Ezra 4:2","Isaiah 37:38"]},

 {id:"merodach", name:"Marduk-Baladan son of Baladan", short:"Marduk-Baladan", cat:"natn", w:5,
  dates:"c. late 8th c. BC (Babylon)",
  desc:`King of Babylon who sends Hezekiah letters and a gift on hearing of his illness. Hezekiah shows the envoys everything in his storehouses, and Isaiah foretells that all of it will be "carried off to Babylon."`,
  refs:["2 Kings 20:12–19","Isaiah 39"]},

 {id:"necho", name:"Pharaoh Necho king of Egypt", short:"Pharaoh Necho", cat:"natn", w:6,
  clash:"Pharaoh", clashtag:"Pharaoh Necho, who killed Josiah at Megiddo and made Jehoiakim king.",
  dates:"c. 609 BC (Egypt)",
  desc:`Going up to the Euphrates "to help the king of Assyria," he kills King Josiah at Megiddo. He puts Jehoahaz in chains at Riblah and takes him to Egypt, levies silver and gold on Judah, and makes Eliakim son of Josiah king, renaming him Jehoiakim. Afterward "the king of Egypt did not march out from his own country again," for Babylon had taken his territory. 2 Chronicles has him marching to Carchemish and warning Josiah, "God has told me to hurry; so stop opposing God." Jeremiah 46 is "against the army of Pharaoh Necho king of Egypt, which was defeated at Carchemish on the Euphrates River by Nebuchadnezzar king of Babylon in the fourth year of Jehoiakim."`,
  refs:["2 Kings 23:29–35","2 Kings 24:7","2 Chronicles 35:20–22","2 Chronicles 36:3–4","Jeremiah 46:2"]},

 {id:"nebuzaradan", name:"Nebuzaradan commander of the guard", short:"Nebuzaradan", cat:"natn", w:6,
  dates:"c. 586 BC (Babylon)",
  desc:`"Commander of the imperial guard, an official of the king of Babylon." In Nebuchadnezzar's nineteenth year he burns the temple, the royal palace and Jerusalem's houses, breaks down the walls, carries the people into exile leaving "some of the poorest people of the land," and takes Seraiah, Zephaniah and others to Riblah to be executed. Jeremiah adds that he gave the poor left in Judah vineyards and fields, found Jeremiah in chains at Ramah and freed him — "The LORD your God decreed this disaster for this place" — leaving him free to go to Babylon or stay with Gedaliah, and that in Nebuchadnezzar's twenty-third year he took 745 more Jews into exile.`,
  refs:["2 Kings 25:8–21","Jeremiah 39:9–14","Jeremiah 40:1–6","Jeremiah 52:12–30"]},

 {id:"awel_marduk", name:"Awel-Marduk king of Babylon", short:"Awel-Marduk", cat:"natn", w:5,
  dates:"reigned c. 562 – 560 BC (Babylon)",
  desc:`In the year he becomes king — the thirty-seventh year of Jehoiachin's exile — he releases Jehoiachin from prison, "spoke kindly to him," gives him a seat of honor above the other captive kings and a regular allowance for life.`,
  refs:["2 Kings 25:27–30","Jeremiah 52:31–34"]},


 // 1–2 Chronicles
 {id:"zerah_c", name:"Zerah the Cushite", short:"Zerah (Cushite)", cat:"natn", w:6,
  clash:"Zerah", clashtag:"The Cushite whose great army Asa routed after prayer.",
  dates:"c. 10th–9th c. BC",
  desc:`Marches against Asa "with an army of thousands upon thousands and three hundred chariots." Asa prays, "Help us, LORD our God, for we rely on you," and "the LORD struck down the Cushites before Asa and Judah"; they are pursued as far as Gerar.`,
  notconfused:`Zerah son of Judah and Tamar (Genesis 38:30).`,
  refs:["2 Chronicles 14:9–15","2 Chronicles 16:8"]},


 // Ezra · Nehemiah · Esther
 {id:"darius_p", name:"Darius king of Persia", short:"Darius (Persia)", cat:"natn", w:7,
  clash:"Darius", clashtag:"The Persian king under whom the second temple was finished (Ezra 4–6).",
  dates:"reigned 522 – 486 BC (Persia; historical record)",
  desc:`Work on the temple stops "until the second year of the reign of Darius king of Persia." When Tattenai writes to ask who authorized the rebuilding, Darius has the archives searched; Cyrus's decree is found at Ecbatana, and Darius orders the costs paid "out of the royal treasury" and warns, "Do not interfere with the work on this temple of God." "The temple was completed… in the sixth year of the reign of King Darius." Nehemiah 12:22 also mentions "Darius the Persian"; the text does not say whether he is the same king.`,
  notconfused:`"Darius the Mede" of Daniel 5–6, who cast Daniel into the lions' den.`,
  refs:["Ezra 4:5","Ezra 4:24","Ezra 5–6","Nehemiah 12:22","Haggai 1:1","Zechariah 1:1","Haggai 2:10","Zechariah 1:7","Zechariah 7:1"]},

 {id:"mithredath", name:"Mithredath the treasurer", short:"Mithredath", cat:"natn", w:3,
  dates:"c. 538 BC (Persia)",
  desc:`Cyrus's treasurer, who brings out the temple articles Nebuchadnezzar had taken "and counted them out to Sheshbazzar the prince of Judah."`,
  notconfused:`The Mithredath who joined in writing to Artaxerxes against Jerusalem (Ezra 4:7).`,
  refs:["Ezra 1:8"]},

 {id:"rehum_c", name:"Rehum the commanding officer", short:"Rehum", cat:"natn", w:4,
  dates:"5th c. BC (Persian province)",
  desc:`With Shimshai the secretary he writes to Artaxerxes that Jerusalem is "that rebellious and wicked city," and that if its walls are restored "no more taxes, tribute or duty will be paid." When the king's reply comes, they go "to the Jews in Jerusalem and compelled them by force to stop."`,
  refs:["Ezra 4:8–23"]},

 {id:"shimshai", name:"Shimshai the secretary", short:"Shimshai", cat:"natn", w:4,
  dates:"5th c. BC (Persian province)",
  desc:`Co-author with Rehum of the letter to Artaxerxes against Jerusalem's rebuilding, and one of those who stopped the work by force.`,
  refs:["Ezra 4:8–23"]},

 {id:"tattenai", name:"Tattenai governor of Trans-Euphrates", short:"Tattenai", cat:"natn", w:5,
  dates:"c. 520 BC (Persia)",
  desc:`Governor of the province west of the Euphrates, who asks the builders, "Who authorized you to rebuild this temple?" and writes to Darius. "The eye of their God was watching over the elders," and they are not stopped; when Darius confirms Cyrus's decree, Tattenai carries it out "with diligence."`,
  refs:["Ezra 5:3–17","Ezra 6:6–13"]},

 {id:"shetharbozenai", name:"Shethar-Bozenai", short:"Shethar-Bozenai", cat:"natn", w:3,
  dates:"c. 520 BC (Persia)",
  desc:`An associate of Tattenai who questioned the temple builders and joined in the report to Darius.`,
  refs:["Ezra 5:3–6","Ezra 6:6","Ezra 6:13"]},

 {id:"ashurbanipal", name:"Ashurbanipal", short:"Ashurbanipal", cat:"natn", w:4,
  dates:"reigned c. 668 – 627 BC (Assyria; historical record)",
  desc:`Named in the opponents' letter as "the great and honorable Ashurbanipal," who "deported and settled" peoples "in the city of Samaria and elsewhere in Trans-Euphrates." The opponents of Ezra 4:2 likewise say Esarhaddon king of Assyria "brought us here."`,
  refs:["Ezra 4:2","Ezra 4:10"]},

 {id:"sanballat", name:"Sanballat the Horonite", short:"Sanballat", cat:"natn", w:7,
  dates:"c. 445 BC",
  desc:`Nehemiah's chief opponent. He mocks the builders before "the army of Samaria" — "What are those feeble Jews doing?" — plots an attack, repeatedly invites Nehemiah to meet "on the plain of Ono" to harm him, sends an open letter accusing him of planning to be king, and with Tobiah hires Shemaiah to frighten him. A grandson of Eliashib the high priest became his son-in-law. Extra-biblical papyri from Elephantine name a Sanballat as governor of Samaria.`,
  refs:["Nehemiah 2:10","Nehemiah 2:19","Nehemiah 4:1–8","Nehemiah 6:1–14","Nehemiah 13:28"]},

 {id:"tobiah", name:"Tobiah the Ammonite official", short:"Tobiah", cat:"natn", w:7,
  dates:"c. 445 BC",
  desc:`With Sanballat he opposes the wall — "even a fox climbing up on it would break down their wall of stones!" — and sends letters to intimidate Nehemiah. Many nobles of Judah are "under oath to him," since he is son-in-law to Shekaniah son of Arah. While Nehemiah is away, Eliashib gives him a room in the temple courts; Nehemiah throws out "all Tobiah's household goods."`,
  refs:["Nehemiah 2:10","Nehemiah 4:3","Nehemiah 6:1–19","Nehemiah 13:4–9"]},

 {id:"geshem", name:"Geshem the Arab", short:"Geshem", cat:"natn", w:5,
  dates:"c. 445 BC",
  desc:`With Sanballat and Tobiah he mocks the rebuilding — "Are you rebelling against the king?" — and joins the scheme to lure Nehemiah to Ono. Sanballat's letter claims, "Geshem says it is true" that the Jews are plotting revolt.`,
  refs:["Nehemiah 2:19","Nehemiah 6:1–6"]},

 {id:"vashti", name:"Queen Vashti", short:"Vashti", cat:"natn", w:6,
  dates:"c. 483 BC (Persia)",
  desc:`Xerxes' queen, who gives a banquet for the women of the palace. Summoned on the seventh day of the king's feast "in order to display her beauty to the people and nobles," she refuses to come. On Memukan's advice a decree is issued "that Vashti is never again to enter the presence of King Xerxes," and her royal position is given to another — Esther.`,
  refs:["Esther 1:9–22","Esther 2:1–4","Esther 2:17"]},

 {id:"memukan", name:"Memukan", short:"Memukan", cat:"natn", w:4,
  dates:"c. 483 BC (Persia)",
  desc:`One of "the seven nobles of Persia and Media who had special access to the king." He advises that Vashti be deposed, so that "all the women will respect their husbands."`,
  refs:["Esther 1:14–21"]},

 {id:"hegai", name:"Hegai the king's eunuch", short:"Hegai", cat:"natn", w:4,
  dates:"5th c. BC (Persia)",
  desc:`The eunuch "in charge of the women" of the harem. Esther "pleased him and won his favor"; he gives her beauty treatments, seven attendants and the best place in the harem, and when her turn comes she asks only for what Hegai suggests.`,
  refs:["Esther 2:3","Esther 2:8–9","Esther 2:15"]},

 {id:"bigthana", name:"Bigthana", short:"Bigthana", cat:"natn", w:3,
  dates:"5th c. BC (Persia)",
  desc:`One of two officers "who guarded the doorway" and conspired to assassinate Xerxes. Mordecai exposes the plot and both are impaled; the record of it, read to the sleepless king, leads to Mordecai's honor.`,
  refs:["Esther 2:21–23","Esther 6:2"]},

 {id:"teresh", name:"Teresh", short:"Teresh", cat:"natn", w:3,
  dates:"5th c. BC (Persia)",
  desc:`Bigthana's fellow conspirator against King Xerxes, impaled when Mordecai's report proved true.`,
  refs:["Esther 2:21–23","Esther 6:2"]},

 {id:"haman", name:"Haman son of Hammedatha", short:"Haman", cat:"natn", w:8,
  aliases:"the Agagite · \"the enemy of the Jews\"",
  dates:"c. 474 BC (Persia)",
  desc:`Raised by Xerxes "higher than that of all the other nobles." When Mordecai will not kneel to him, he sets out "to destroy all Mordecai's people, the Jews," casts the pur to choose the day, and offers the king ten thousand talents of silver. Invited to Esther's banquets, he builds a pole fifty cubits high for Mordecai — only to be made to lead Mordecai through the streets in royal honor. Exposed by Esther as "this vile Haman!", he is impaled on his own pole, and his ten sons are later killed. His wife was Zeresh.`,
  notconfused:`"Agagite" is not explained in the text; Agag was the Amalekite king spared by Saul (1 Samuel 15).`,
  refs:["Esther 3","Esther 5:9–14","Esther 6–7","Esther 9:7–14","Esther 9:24–25"]},

 {id:"zeresh", name:"Zeresh wife of Haman", short:"Zeresh", cat:"natn", w:4,
  dates:"c. 474 BC (Persia)",
  desc:`With Haman's friends she advises him to set up a pole fifty cubits high for Mordecai. When Mordecai is honored instead, she warns: "Since Mordecai, before whom your downfall has started, is of Jewish origin, you cannot stand against him — you will surely come to ruin!"`,
  refs:["Esther 5:10–14","Esther 6:13"]},

 {id:"hathak", name:"Hathak", short:"Hathak", cat:"natn", w:3,
  dates:"5th c. BC (Persia)",
  desc:`One of the king's eunuchs "assigned to attend" Esther, who carries messages between her and Mordecai — including the copy of Haman's edict and Mordecai's charge to plead with the king.`,
  refs:["Esther 4:5–10"]},

 {id:"harbona", name:"Harbona", short:"Harbona", cat:"natn", w:3,
  dates:"5th c. BC (Persia)",
  desc:`One of the seven eunuchs who served Xerxes. At Esther's second banquet he points out the pole "reaching to a height of fifty cubits" that Haman had set up for Mordecai, and the king says, "Impale him on it!"`,
  refs:["Esther 1:10","Esther 7:9"]},


 {id:"sennacherib", name:"Sennacherib king of Assyria", short:"Sennacherib", cat:"natn", w:8,
  dates:"reigned 705 – 681 BC (Assyria)",
  desc:`"In the fourteenth year of King Hezekiah's reign" he captures Judah's fortified cities and exacts three hundred talents of silver and thirty of gold. From Lachish he sends his commanders to demand Jerusalem's surrender and writes that its God will not save it. Isaiah answers, "I will put my hook in your nose." That night the angel of the LORD strikes 185,000 in the Assyrian camp. He returns to Nineveh, where his sons Adrammelek and Sharezer kill him in the temple of Nisrok, and Esarhaddon succeeds him.`,
  refs:["2 Kings 18:13–19:37","Isaiah 36–37"]},

 {id:"nebuchadnezzar", name:"Nebuchadnezzar king of Babylon", short:"Nebuchadnezzar", cat:"natn", w:12,
  dates:"reigned 605 – 562 BC (Babylon; historical record)",
  desc:`He invades Judah and makes Jehoiakim his vassal. In his eighth year he besieges Jerusalem, takes Jehoiachin captive to Babylon with ten thousand of its people and the temple treasures, and makes Zedekiah king. When Zedekiah rebels he besieges the city again; in his nineteenth year his commander Nebuzaradan burns the temple and Jerusalem, and he appoints Gedaliah governor. Jeremiah calls him "my servant Nebuchadnezzar king of Babylon," records his defeat of Pharaoh Necho's army at Carchemish "in the fourth year of Jehoiakim," his order about Jeremiah — "don't harm him but do for him whatever he asks" — and lists those he carried into exile in his seventh, eighteenth and twenty-third years, "4,600 people in all." Ezekiel says he and his army "got no reward" from their hard campaign against Tyre, so Egypt is given to him as pay. In Daniel he takes Daniel and his friends to Babylon, dreams of a statue whose head of gold is himself, throws Shadrach, Meshach and Abednego into the blazing furnace and then praises their God. Boasting of "the great Babylon I have built," he is driven away to eat "grass like the ox" until his sanity is restored and he praises "the King of heaven."`,
  refs:["2 Kings 24–25","Jeremiah 25:1–11","Jeremiah 39:11–12","Jeremiah 46:2","Jeremiah 52:28–30","Ezekiel 26:7","Ezekiel 29:17–20","Daniel 1–4"]},

 {id:"belshazzar", name:"Belshazzar king of Babylon", short:"Belshazzar", cat:"natn", w:8,
  dates:"6th c. BC; Babylon fell to the Medes and Persians in 539 BC (historical record)",
  desc:`"King Belshazzar gave a great banquet for a thousand of his nobles" and drank from the gold and silver goblets "that Nebuchadnezzar his father had taken from the temple in Jerusalem" (NIV footnote: "Or ancestor; or predecessor"). "Suddenly the fingers of a human hand appeared and wrote on the plaster of the wall." On the queen's advice he calls Daniel, who reminds him how Nebuchadnezzar was humbled — "But you, Belshazzar, his son, have not humbled yourself" — and reads "mene, mene, tekel, parsin": "You have been weighed on the scales and found wanting… Your kingdom is divided and given to the Medes and Persians." He has Daniel proclaimed third highest ruler in the kingdom. "That very night Belshazzar, king of the Babylonians, was slain." Daniel's visions of the four beasts and of the ram and the goat are dated to his first and third years.`,
  refs:["Daniel 5","Daniel 7:1","Daniel 8:1"]},

 {id:"cyrus", name:"Cyrus the Great", short:"Cyrus", cat:"natn", w:10,
  dates:"reigned 559 – 530 BC (Persia)",
  desc:`The Persian conqueror of Babylon whose decree in 538 BC frees the exiles to return home and rebuild the Temple. Isaiah names him God's "anointed" and "shepherd" long in advance. 2 Chronicles closes with his proclamation: "Any of his people among you may go up." Ezra 1 repeats the decree, and Cyrus returns the temple articles to Sheshbazzar; the decree is later found in the archives at Ecbatana. Isaiah 45:13: "He will rebuild my city and set my exiles free." Daniel "remained there until the first year of King Cyrus," "prospered during the reign of Darius and the reign of Cyrus the Persian," and received a revelation "in the third year of Cyrus king of Persia."`,
  refs:["2 Chronicles 36:22–23","Ezra 1","Isaiah 45:1","Ezra 1:7–11","Ezra 5:13–15","Ezra 6:3–5","Isaiah 44:28","Isaiah 45:13","Daniel 1:21","Daniel 6:28","Daniel 10:1"]},

 {id:"darius", name:"Darius the Mede", short:"Darius the Mede", cat:"natn", w:8,
  aliases:"Darius son of Xerxes",
  clash:"Darius", clashtag:"'Darius the Mede' of Daniel, who cast Daniel into the lions' den.",
  dates:"6th c. BC (identity in historical records debated)",
  desc:`"Darius the Mede took over the kingdom, at the age of sixty-two," the night Belshazzar was slain. He appoints 120 satraps with three administrators over them, one of them Daniel, and plans "to set him over the whole kingdom." His officials persuade him to decree that anyone who prays "to any god or human being during the next thirty days, except to you" be thrown to the lions; bound by his own decree, he has Daniel thrown in — "May your God, whom you serve continually, rescue you!" At first light he hurries to the den, rejoices at Daniel's rescue, has the accusers thrown to the lions, and decrees that people "must fear and reverence the God of Daniel." Daniel 9:1 calls him "Darius son of Xerxes (a Mede by descent), who was made ruler over the Babylonian kingdom."`,
  notconfused:`Darius king of Persia, under whom the second temple was finished (Ezra 4–6). The Xerxes named as his father is not said to be Xerxes king of Persia in Esther.`,
  refs:["Daniel 5:30–31","Daniel 6","Daniel 9:1","Daniel 11:1"]},

 {id:"xerxes", name:"Xerxes king of Persia", short:"Xerxes", cat:"natn", w:8,
  aliases:"Ahasuerus",
  dates:"reigned 486 – 465 BC (Persia; historical record)",
  desc:`"The Xerxes who ruled over 127 provinces stretching from India to Cush," reigning from Susa. At a great banquet he orders Queen Vashti to display her beauty; when she refuses he deposes her and later makes Esther queen. He raises Haman, hands him his signet ring to destroy the Jews, then — after a sleepless night and Esther's plea — has Haman impaled, gives his ring to Mordecai and lets the Jews defend themselves. Ezra 4:6 records an accusation against Judah "at the beginning of the reign of Xerxes."`,
  refs:["Ezra 4:6","Esther 1–3","Esther 5–8","Esther 10"]},

 {id:"artaxerxes", name:"Artaxerxes king of Persia", short:"Artaxerxes", cat:"natn", w:7,
  dates:"reigned 465 – 424 BC (Persia; historical record)",
  desc:`On the letter of Rehum and Shimshai he orders work on Jerusalem stopped. In his seventh year he sends Ezra with a decree — "Artaxerxes, king of kings, To Ezra the priest, teacher of the Law of the God of heaven" — and silver and gold for the temple. In his twentieth year he notices his cupbearer Nehemiah's sad face and, "with the queen sitting beside him," sends him to rebuild the city with letters and an escort; Nehemiah returns to him in his thirty-second year. The text does not say whether the Artaxerxes of Ezra 4 is the same king.`,
  refs:["Ezra 4:7–23","Ezra 6:14","Ezra 7","Nehemiah 2:1–9","Nehemiah 5:14","Nehemiah 13:6"]},

 // ---------------- ANGELS & SATAN ----------------
 {id:"angel_lord", name:"The angel of the LORD", short:"Angel of the LORD", cat:"angels", w:12,
  aliases:"the angel of God (in some of the same accounts)",
  dates:"—",
  desc:`"The angel of the LORD found Hagar near a spring in the desert" (Genesis 16:7); "called out to him from heaven, 'Abraham! Abraham!'" (22:11); appeared to Moses "in flames of fire from within a bush" (Exodus 3:2); "stood in the road to oppose" Balaam (Numbers 22:22); said to Gideon, "The LORD is with you, mighty warrior" (Judges 6:12); announced Samson's birth to Manoah's wife and "ascended in the flame" (13:3, 20); stood "between heaven and earth, with a drawn sword" over Jerusalem in David's day (1 Chronicles 21:16); fed Elijah — "Get up and eat, for the journey is too much for you" (1 Kings 19:7); "put to death a hundred and eighty-five thousand in the Assyrian camp" (2 Kings 19:35); and stood by Joshua the high priest (Zechariah 3). In several accounts the one who speaks is then called the LORD or God: Hagar named "the LORD who spoke to her" "the God who sees me" (Genesis 16:13); "God called to him from within the bush" (Exodus 3:4); Manoah said, "We have seen God!" (Judges 13:22). Scripture does not explain this, nor say whether every appearance is the same angel; they are gathered in one circle here because the text uses the one title.`,
  notconfused:`The unnamed "angels of God" (Lot's two visitors, Jacob's angels, the angel in Daniel's lions' den); Gabriel and Michael, who are named; and the "commander of the army of the LORD" who met Joshua (Joshua 5:14), whom the text does not call an angel.`,
  refs:["Genesis 16:7–13","Genesis 22:11–18","Exodus 3:2–6","Numbers 22:22–35","Judges 2:1–4","Judges 5:23","Judges 6:11–22","Judges 13:3–23","2 Samuel 24:16–17","1 Kings 19:5–7","2 Kings 1:3, 15","2 Kings 19:35","1 Chronicles 21:12–30","Isaiah 37:36","Zechariah 1:11–12","Zechariah 3:1–6"]},

 {id:"angels_ot", name:"Angels of God (unnamed)", short:"Angels of God", cat:"angels", w:9,
  aliases:"the angel of God · \"the angel who talked with me\" (Zechariah)",
  dates:"—",
  desc:`One circle for the angels the Old Testament does not name, other than "the angel of the LORD" — each sent from God, grouped only for the map; the text does not say whether any two are the same. "The two angels arrived at Sodom" and urged Lot, "Hurry! Take your wife and your two daughters" (Genesis 19:1, 15). "The angel of God called to Hagar from heaven" (21:17). Jacob dreamed of "the angels of God… ascending and descending" (28:12); "the angels of God met him" (32:1); and he blessed Joseph's sons by "the Angel who has delivered me from all harm" (48:16). Nebuchadnezzar praised the God "who has sent his angel and rescued his servants" Shadrach, Meshach and Abednego (Daniel 3:28); Daniel told Darius, "My God sent his angel, and he shut the mouths of the lions" (6:22). Through Zechariah's night visions "the angel who talked with me" explained what he saw (Zechariah 1:9 – 6:5).`,
  notconfused:`The angel of the LORD (a separate circle); Gabriel; Michael.`,
  refs:["Genesis 19:1–22","Genesis 21:17–19","Genesis 28:12","Genesis 31:11","Genesis 32:1","Genesis 48:16","Hosea 12:4","Daniel 3:28","Daniel 6:22","Zechariah 1:9–6:5"]},

 {id:"gabriel_ot", name:"Gabriel", short:"Gabriel", cat:"angels", w:9,
  dates:"—",
  desc:`One of only two angels the Old Testament names. In Daniel's vision by the Ulai, "I heard a man's voice from the Ulai calling, 'Gabriel, tell this man the meaning of the vision'"; Daniel "was terrified and fell prostrate" (Daniel 8:16–17). Later, while Daniel prayed, "Gabriel, the man I had seen in the earlier vision, came to me in swift flight about the time of the evening sacrifice" and said, "Daniel, I have now come to give you insight and understanding" (9:21–22). In the New Testament he is sent to Zechariah and to Mary (Luke 1; New Testament map).`,
  notconfused:`Michael (Daniel 10; 12); and "a man dressed in linen" who speaks to Daniel in chapter 10, whom the text does not name.`,
  refs:["Daniel 8:15–27","Daniel 9:20–27"]},

 {id:"michael_ot", name:"Michael", short:"Michael (angel)", cat:"angels", w:8,
  dates:"—",
  desc:`Named only in Daniel, and never shown meeting a person. The one who speaks to Daniel says, "the prince of the Persian kingdom resisted me twenty-one days. Then Michael, one of the chief princes, came to help me" and "No one supports me against them except Michael, your prince" (Daniel 10:13, 21). "At that time Michael, the great prince who protects your people, will arise" (12:1). The New Testament calls him "the archangel Michael" (Jude 9) and shows him fighting the dragon (Revelation 12:7; New Testament map).`,
  notconfused:`The men named Michael in the genealogies, such as the father of Sethur (Numbers 13:13); and Gabriel.`,
  refs:["Daniel 10:13, 21","Daniel 12:1"]},

 {id:"satan_ot", name:"Satan", short:"Satan", cat:"devil", w:9,
  aliases:"the adversary (NIV footnote: \"Hebrew satan means adversary\")",
  dates:"—",
  desc:`"One day the angels came to present themselves before the LORD, and Satan also came with them" (Job 1:6; NIV footnotes: "Hebrew the sons of God" and "Hebrew satan means adversary"). Asking "Does Job fear God for nothing?" he took Job's possessions and children, then "afflicted Job with painful sores" (1:9; 2:7). "Satan rose up against Israel and incited David to take a census of Israel" (1 Chronicles 21:1); the parallel account says the anger of the LORD "incited David" (2 Samuel 24:1) — Scripture gives both. Zechariah saw "Joshua the high priest standing before the angel of the LORD, and Satan standing at his right side to accuse him," and the LORD said, "The LORD rebuke you, Satan!" (Zechariah 3:1–2). He comes among the angels in Job; the Old Testament does not call him an angel.`,
  notconfused:`The serpent of Genesis 3, whom Genesis does not call Satan; Revelation 12:9 later speaks of "that ancient serpent called the devil, or Satan" (New Testament map), so the tie to Eve is drawn as possible.`,
  refs:["Job 1:6–12","Job 2:1–7","1 Chronicles 21:1","Zechariah 3:1–2","Genesis 3:1–15 (the serpent; cf. Revelation 12:9)"]},
];

