  tlTitle:"A rough chronology, from Creation to Malachi",
  tlCaption:"* Estimate. Before Abraham, years are a straight count of the ages in Genesis 5 and 11 (the Hebrew numbers the NIV follows), taking Terah as 130 at Abram's birth and assuming no gaps in the lists. The chart uses three scales — compressed before Abraham, widened from Saul on, where the kings crowd together — so compare bar lengths only within a stretch. From Abraham to Solomon the dates follow Scripture's own figures on the early-date reckoning (Exodus 12:40; 1 Kings 6:1: the Exodus c. 1446 BC — many place it c. 1250 BC instead). The judges' dates are especially disputed. Kings follow the widely used Thiele reckoning; foreign rulers follow the historical record. Dashed ends mark greater uncertainty. Hover a bar for its caveat.",
